INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ar4mirez/samuel/cuda-guide', 'community', 'ar4mirez', 'samuel', 'ar4mirez/samuel', 'cuda-guide', 0, 0, 50, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:17.260Z', '33f8d70986fcf190cd36242d1c5032db166503e51160db1ed2d5794a17a2d6df', '{"id":"ar4mirez/samuel/cuda-guide","name":"cuda-guide","description":{"en":"The cuda-guide skill provides a minimalist yet powerful AI-assisted development framework for GPU computing, deep learning, and scientific computing. It benefits developers working with CUDA 11+, TypeScript, Python, Go, and Rust.","zh":"CUDA Guide 是一个用于并行计算和内存优化的开发框架，提供 Minimalist 且强大的 AI 辅助开发功能","ja":"CUDA Guide は、パラレルプログラミングとメモリ最適化のための開発フレームワークで、最小限の強力な AI エージェント機能を提供します","ko":"CUDA Guide 는 병렬 컴퓨팅과 메모리 최적화를 위한 개발 프레임워크로 최소한의 강력한 AI 에이전트 기능을 제공합니다","es":"Nuestra guía de CUDA proporciona un framework de desarrollo asistido por AI para producción, con 35+ guardrails y metodología 4D para TypeScript, Python, Go y Rust","fr":"Notre guide CUDA offre un framework de développement assisté par l''IA pour la production, avec 35+ garde-fous et une méthodologie 4D pour TypeScript, Python, Go et Rust","de":"Unsere CUDA-Anleitung bietet ein AI-gestütztes Entwicklungsframework für die Produktion, mit 35+ Schutzvorkehrungen und 4D-Methode für TypeScript, Python, Go und Rust","pt":"O guia de CUDA é um framework de desenvolvimento de AI minimalista, mas poderoso, com 35+ guardrails e suporte a linguagens como TypeScript, Python, Go e Rust","ru":"CUDA-руководство - это минималистичный, но мощный фреймворк для разработки ИИ с 35+ guardrails и поддержкой языков như TypeScript, Python, Go и Rust","ar":"دليل CUDA هو إطار عمل تطوير الذكاء الاصطناعي المحدود، ولكن القوي، مع 35+ حواجز أمان ودعم للغات مثل TypeScript، Python، Go وRust"},"seo":{"title":{"en":"cuda-guide: Setup Guide for AI Agents | AI Agent Skill","zh":"CUDA Guide 最佳实践：并行计算和内存优化","ja":"CUDA Guide セットアップガイド：パラレルプログラミングとメモリ最適化","ko":"CUDA Guide 설정 가이드: 병렬 컴퓨팅과 메모리 최적화","es":"Guía de Configuración CUDA para Desarrolladores de AI","fr":"Guide de Mise en Route CUDA pour les Développeurs d''IA","de":"CUDA-Setup-Leitfaden für KI-Entwickler","pt":"Guia de Configuração CUDA: Desenvolvimento de AI com Ferr...","ru":"CUDA Руководство: ИИ Агенты для Высокопроизводительных Вы...","ar":"دليل CUDA: تطبيق أدوات الذكاء الاصطناعي للكمبيوتر الفائق"},"description":{"en":"Unlock the full potential of CUDA 11+ with cuda-guide. Learn how to optimize GPU performance and get started with our expert setup guide and tutorials.","zh":"CUDA Guide 是一个 Minimalist 且强大的 AI 辅助开发框架，提供 35+ 个守护线程，4D 方法论和自动加载语言指南，用于 TypeScript、Python、Go 和 Rust","ja":"CUDA Guide は、35 個以上のガードレール、4D メソッド論、TypeScript、Python、Go、Rust 用の自動ロード言語ガイドを備えた、最小限の強力な AI エージェント開発フレームワークです","ko":"CUDA Guide 는 35 개 이상의 가드레일, 4D 방법론 및 TypeScript, Python, Go, Rust 용 자동 로드 언어 가이드를 제공하는 최소한의 강력한 AI 에이전트 개발 프레임워크입니다","es":"Aprende a aprovechar al máximo el rendimiento de GPU con nuestra guía de CUDA, incluyendo principios de paralelismo y jerarquía de memoria","fr":"Découvrez comment optimiser les performances GPU avec notre guide CUDA, y compris les principes de parallélisme et de hiérarchie de mémoire","de":"Erfahren Sie, wie Sie die GPU-Leistung mit unserer CUDA-Anleitung maximieren, einschließlich Prinzipien von Parallelität und Speicherhierarchie","pt":"Aprenda a configurar o framework CUDA para desenvolvimento de AI com guardrails, metodologia 4D e guias de linguagem para TypeScript, Python, Go e Rust","ru":"Узнайте, как настроить фреймворк CUDA для разработки ИИ с помощью guardrails, 4D-методологии и языковых руководств для TypeScript, Python, Go и Rust","ar":"تعلم كيفية تكوين إطار العمل CUDA لتطوير الذكاء الاصطناعي مع حواجز الأمان، منهجية 4D ودلائل اللغة لTypeScript، Python، Go وRust"},"definition":{"en":"cuda-guide is a production-ready CLAUDE.md & AGENTS.md system with 35+ guardrails, 4D methodology, and auto-loading language guides for various programming languages.","zh":"CUDA Guide 是一个用于 GPU 计算和深度学习的 AI 辅助开发框架","ja":"CUDA Guide は、GPU コンピューティングとディープラーニングのための AI エージェント開発フレームワークです","ko":"CUDA Guide 는 GPU 컴퓨팅과 딥러닝을 위한 AI 에이전트 개발 프레임워크입니다","es":"La guía de CUDA es un framework de desarrollo asistido por AI que aplica principios de paralelismo y jerarquía de memoria para optimizar el rendimiento de GPU","fr":"Le guide CUDA est un framework de développement assisté par l''IA qui applique des principes de parallélisme et de hiérarchie de mémoire pour optimiser les performances GPU","de":"Die CUDA-Anleitung ist ein AI-gestütztes Entwicklungsframework, das Prinzipien von Parallelität und Speicherhierarchie anwendet, um die GPU-Leistung zu optimieren","pt":"O que é o guia de CUDA? Um framework de desenvolvimento de AI que aplica princípios de parallelismo, hierarquia de memória e acesso coalescido","ru":"Что такое CUDA-руководство? Фреймворк для разработки ИИ, который применяет принципы параллелизма, иерархии памяти и коалицированного доступа","ar":"ما هو دليل CUDA؟ إطار عمل لتطوير الذكاء الاصطناعي الذي يطبق مبادئ التزامن، هرمية الذاكرة والوصول المتوازي"},"features":{"en":["Applies Parallelism First principle for designing algorithms with thousands of concurrent threads","Optimizes memory access with Memory Hierarchy Awareness and Coalesced Access","Supports CUDA 11+ for GPU computing and deep learning applications","Includes auto-loading language guides for TypeScript, Python, Go, and Rust","Utilizes 4D methodology for efficient system design"],"zh":["并行计算支持","内存优化技术","35+ 个守护线程","4D 方法论","自动加载语言指南（TypeScript、Python、Go、Rust）"],"ja":["パラレルプログラミングサポート","メモリ最適化技術","35 個以上のガードレール","4D メソッド論","自動ロード言語ガイド（TypeScript、Python、Go、Rust）"],"ko":["병렬 컴퓨팅 지원","메모리 최적화 기술","35 개 이상의 가드레일","4D 방법론","자동 로드 언어 가이드（TypeScript、Python、Go、Rust）"],"es":["Diseño de algoritmos para miles de hilos concurrentes","Planificación de acceso a memoria global y compartida","Acceso coalescido para optimizar el rendimiento de GPU","Soporte para TypeScript, Python, Go y Rust","Metodología 4D para desarrollo de aplicaciones de AI","35+ guardrails para garantizar la calidad del código"],"fr":["Conception d''algorithmes pour des milliers de threads concurrents","Planification d''accès à la mémoire globale et partagée","Accès coalescé pour optimiser les performances GPU","Prise en charge de TypeScript, Python, Go et Rust","Méthodologie 4D pour le développement d''applications d''IA","35+ garde-fous pour garantir la qualité du code"],"de":["Entwurf von Algorithmen für Tausende von konkurrierenden Threads","Planung des Zugriffs auf globale und gemeinsame Speicher","Koaleszierter Zugriff zur Optimierung der GPU-Leistung","Unterstützung für TypeScript, Python, Go und Rust","4D-Methode für die Entwicklung von KI-Anwendungen","35+ Schutzvorkehrungen zur Gewährleistung der Codequalität"],"pt":["Suporte a linguagens como TypeScript, Python, Go e Rust","35+ guardrails para garantir a segurança e a estabilidade do código","Metodologia 4D para desenvolvimento de AI","Acesso coalescido para melhorar o desempenho do GPU"],"ru":["Поддержка языков как TypeScript, Python, Go и Rust","35+ guardrails для обеспечения безопасности и стабильности кода","4D-методология для разработки ИИ","Коалицированный доступ для улучшения производительности GPU"],"ar":["دعم للغات مثل TypeScript، Python، Go وRust","35+ حواجز أمان لضمان سلامة وثبات الكود","منهجية 4D لتطوير الذكاء الاصطناعي","الوصول المتوازي لتحسين أداء وحدة معالجة الرسومات"]},"keywords":{"en":["how to use cuda-guide","cuda-guide setup guide","cuda-guide vs CUDA Toolkit","cuda-guide install for GPU computing","what is cuda-guide","cuda-guide alternative for deep learning","cuda-guide tutorial for scientific computing","cuda-guide documentation for TypeScript developers","cuda-guide best practices for Python developers"],"zh":["CUDA Guide","AI 辅助开发","并行计算","内存优化","GPU 计算","深度学习","TypeScript","Python","Go","Rust"],"ja":["CUDA Guide","AI エージェント","パラレルプログラミング","メモリ最適化","GPU コンピューティング","ディープラーニング","TypeScript","Python","Go","Rust"],"ko":["CUDA Guide","AI 에이전트","병렬 컴퓨팅","메모리 최적화","GPU 컴퓨팅","딥러닝","TypeScript","Python","Go","Rust"],"es":["guía de CUDA","desarrollo de AI","paralelismo","jerarquía de memoria","GPU","TypeScript","Python","Go","Rust","metodología 4D"],"fr":["guide CUDA","développement d''IA","parallélisme","hiérarchie de mémoire","GPU","TypeScript","Python","Go","Rust","méthodologie 4D"],"de":["CUDA-Anleitung","KI-Entwicklung","Parallelität","Speicherhierarchie","GPU","TypeScript","Python","Go","Rust","4D-Methode"],"pt":["desenvolvimento de AI","ferramentas de alta performance","CUDA","TypeScript","Python","Go","Rust","guardrails","metodologia 4D"],"ru":["разработка ИИ","инструменты высокой производительности","CUDA","TypeScript","Python","Go","Rust","guardrails","4D-методология"],"ar":["تطوير الذكاء الاصطناعي","أدوات الكمبيوتر الفائق","CUDA","TypeScript","Python","Go","Rust","حواجز الأمان","منهجية 4D"]}},"owner":"ar4mirez","repo":"samuel","repoPath":"ar4mirez/samuel","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"cuda-guide","description":"|","version":"1.0","bodyPreview":"# CUDA Guide\n\n> Applies to: CUDA 11+, GPU Computing, Deep Learning, Scientific Computing, HPC\n\n## Core Principles\n\n1. **Parallelism First**: Design algorithms for thousands of concurrent threads; serial thinking is the primary enemy of GPU performance\n2. **Memory Hierarchy Awareness**: Global memory is 100x slower than shared memory and 1000x slower than registers; every kernel design starts with memory access planning\n3. **Coalesced Access**: Adjacent threads must access adjacent memory address","body":"# CUDA Guide\n\n> Applies to: CUDA 11+, GPU Computing, Deep Learning, Scientific Computing, HPC\n\n## Core Principles\n\n1. **Parallelism First**: Design algorithms for thousands of concurrent threads; serial thinking is the primary enemy of GPU performance\n2. **Memory Hierarchy Awareness**: Global memory is 100x slower than shared memory and 1000x slower than registers; every kernel design starts with memory access planning\n3. **Coalesced Access**: Adjacent threads must access adjacent memory addresses; a single misaligned access pattern can reduce bandwidth by 32x\n4. **Occupancy Over Cleverness**: Maximize active warps per SM by managing register count, shared memory usage, and block dimensions together\n5. **Minimize Host-Device Transfers**: PCIe bandwidth is the bottleneck; overlap transfers with computation using streams and pinned memory\n\n## Guardrails\n\n### Error Checking\n\n- ALWAYS check CUDA API return values with a macro wrapper\n- ALWAYS call `cudaGetLastError()` after every kernel launch\n- ALWAYS call `cudaDeviceSynchronize()` before reading kernel results on the host\n- Use `compute-sanitizer` (successor to `cuda-memcheck`) in development builds\n- Handle `cudaErrorMemoryAllocation` gracefully; never assume GPU memory is infinite\n\n```cuda\n#define CUDA_CHECK(call)                                                    \\\n    do {                                                                    \\\n        cudaError_t err = call;                                            \\\n        if (err != cudaSuccess) {                                          \\\n            fprintf(stderr, \"CUDA error at %s:%d: %s\\n\",                   \\\n                    __FILE__, __LINE__, cudaGetErrorString(err));           \\\n            exit(EXIT_FAILURE);                                            \\\n        }                                                                   \\\n    } while (0)\n\n#define CUDA_CHECK_KERNEL()                                                 \\\n    do {                                                                    \\\n        cudaError_t err = cudaGetLastError();                              \\\n        if (err != cudaSuccess) {                                          \\\n            fprintf(stderr, \"Kernel launch error at %s:%d: %s\\n\",          \\\n                    __FILE__, __LINE__, cudaGetErrorString(err));           \\\n            exit(EXIT_FAILURE);                                            \\\n        }                                                                   \\\n    } while (0)\n```\n\n### Memory Management\n\n- Pair every `cudaMalloc` with a `cudaFree`; prefer RAII wrappers in C++ host code\n- Use `cudaMallocManaged` (Unified Memory) for prototyping; switch to explicit transfers for production\n- Use `cudaMallocHost` (pinned memory) when streaming data to the GPU; pageable memory cannot overlap with compute\n- Prefer `cudaMemcpyAsync` with streams over synchronous `cudaMemcpy`\n- Never access device pointers from host code or host pointers from device code (except Unified Memory)\n- Call `cudaMemset` or `cudaMemsetAsync` to zero-initialize device buffers\n\n### Kernel Design\n\n- Block size must be a multiple of warp size (32); prefer 128, 256, or 512\n- Calculate grid size as `(n + block_size - 1) / block_size`\n- Always include bounds checking: `if (idx < n)` at the top of every kernel\n- Use grid-stride loops for kernels that must handle arbitrary data sizes\n- Document thread mapping: which dimension maps to which data axis\n- Mark device-only helpers as `__device__`, host+device as `__host__ __device__`\n\n```cuda\n// Grid-stride loop: works with any grid size, any data size\n__global__ void saxpy(float a, const float* x, float* y, int n) {\n    for (int i = blockIdx.x * blockDim.x + threadIdx.x;\n         i < n;\n         i += blockDim.x * gridDim.x) {\n        y[i] = a * x[i] + y[i];\n    }\n}\n```\n\n### Synchronization\n\n- Use `__syncthreads()` after every shared memory write before any thread reads another thread''s value\n- Never place `__syncthreads()` inside a conditional branch that not all threads in a block will reach (deadlock)\n- Use `__syncwarp()` (CUDA 9+) for warp-level synchronization instead of relying on implicit warp-synchronous execution\n- Use `cudaDeviceSynchronize()` sparingly in production; prefer stream synchronization with `cudaStreamSynchronize()`\n- Use CUDA events (`cudaEventRecord` / `cudaEventSynchronize`) for fine-grained inter-stream ordering\n\n### Performance\n\n- Profile before optimizing: use Nsight Compute for kernel analysis, Nsight Systems for system-level view\n- Target >50% theoretical occupancy; use the CUDA Occupancy Calculator to tune block dimensions\n- Aim for >60% of peak memory bandwidth in memory-bound kernels\n- Avoid warp divergence: ensure threads within a warp take the same branch when possible\n- Prefer `float` over `double` on consumer GPUs (2x throughput difference)\n- Minimize atomic operations on global memory; use shared memory atomics with a final reduction\n\n## Memory Hierarchy\n\nUnderstanding the memory hierarchy is the single most important factor in CUDA performance.\n\n| Memory Type | Scope | Latency (cycles) | Size | Cached | Read/Write |\n|-------------|-------|-------------------|------|--------|------------|\n| Registers | Thread | 1 | ~255 per thread | N/A | R/W |\n| Shared | Block | ~5 | 48-164 KB per SM | N/A | R/W |\n| L1 Cache | SM | ~28 | 48-192 KB per SM | Auto | R |\n| L2 Cache | Device | ~200 | 4-40 MB | Auto | R/W |\n| Global | Device | ~400-600 | 4-80 GB (HBM/GDDR) | Yes | R/W |\n| Constant | Device | ~5 (cached) | 64 KB | Yes (broadcast) | R |\n| Texture | Device | ~400 (cached) | Global pool | Yes (spatial) | R |\n\n**Decision guide:**\n- Data reused within a thread -> registers (automatic via local variables)\n- Data shared across threads in a block -> `__shared__` memory\n- Read-only data broadcast to all threads -> `__constant__` memory\n- Large read-only data with spatial locality -> texture memory\n- Everything else -> global memory with coalesced access patterns\n\n## Key Patterns\n\n### Kernel Launch Configuration\n\n```cuda\n// Query device for optimal configuration\nvoid launch_optimized(const float* input, float* output, int n) {\n    int block_size;\n    int min_grid_size;\n\n    // Let the runtime suggest optimal block size for maximum occupancy\n    cudaOccupancyMaxPotentialBlockSize(\n        &min_grid_size, &block_size, my_kernel, 0, n);\n\n    int grid_size = (n + block_size - 1) / block_size;\n    my_kernel<<<grid_size, block_size>>>(input, output, n);\n    CUDA_CHECK_KERNEL();\n}\n```\n\n### Coalesced Memory Access\n\n```cuda\n// BAD: Strided access -- adjacent threads access non-adjacent memory\n// Each warp issues 32 separate memory transactions\n__global__ void transpose_naive(const float* in, float* out, int W, int H) {\n    int x = blockIdx.x * blockDim.x + threadIdx.x;\n    int y = blockIdx.y * blockDim.y + threadIdx.y;\n    if (x < W && y < H) {\n        out[x * H + y] = in[y * W + x];  // Write is strided\n    }\n}\n\n// GOOD: Use shared memory to coalesce both reads and writes\n__global__ void transpose_coalesced(\n    const float* in, float* out, int W, int H\n) {\n    __shared__ float tile[32][33]; // +1 padding avoids bank conflicts\n\n    int x = blockIdx.x * 32 + threadIdx.x;\n    int y = blockIdx.y * 32 + threadIdx.y;\n\n    if (x < W && y < H) {\n        tile[threadIdx.y][threadIdx.x] = in[y * W + x]; // Coalesced read\n    }\n    __syncthreads();\n\n    x = blockIdx.y * 32 + threadIdx.x;\n    y = blockIdx.x * 32 + threadIdx.y;\n\n    if (x < H && y < W) {\n        out[y * H + x] = tile[threadIdx.x][threadIdx.y]; // Coalesced write\n    }\n}\n```\n\n### Shared Memory Tiling\n\n```cuda\n// Dot product of two vectors using shared memory reduction\n__global__ void dot_product(\n    const float* a, const float* b, float* result, int n\n) {\n    __shared__ float cache[256];\n\n    int tid = threadIdx.x;\n    int idx = blockIdx.x * blockDim.x + threadIdx.x;\n\n    // Each thread computes its partial sum via grid-stride\n    float partial = 0.0f;\n    for (int i = idx; i < n; i += blockDim.x * gridDim.x) {\n        partial += a[i] * b[i];\n    }\n    cache[tid] = partial;\n    __syncthreads();\n\n    // Tree reduction in shared memory\n    for (int s = blockDim.x / 2; s > 0; s >>= 1) {\n        if (tid < s) {\n            cache[tid] += cache[tid + s];\n        }\n        __syncthreads();\n    }\n\n    if (tid == 0) {\n        atomicAdd(result, cache[0]);\n    }\n}\n```\n\n### Warp-Level Primitives (CUDA 9+)\n\n```cuda\n// Warp-level reduction using shuffle instructions -- no shared memory needed\n__device__ float warp_reduce_sum(float val) {\n    for (int offset = warpSize / 2; offset > 0; offset /= 2) {\n        val += __shfl_down_sync(0xFFFFFFFF, val, offset);\n    }\n    return val;\n}\n\n// Block-level reduction combining warp shuffles and shared memory\n__device__ float block_reduce_sum(float val) {\n    __shared__ float warp_sums[32]; // One slot per warp (max 32 warps/block)\n\n    int lane = threadIdx.x % warpSize;\n    int warp_id = threadIdx.x / warpSize;\n\n    val = warp_reduce_sum(val);\n\n    if (lane == 0) {\n        warp_sums[warp_id] = val;\n    }\n    __syncthreads();\n\n    // First warp reduces the warp sums\n    int num_warps = (blockDim.x + warpSize - 1) / warpSize;\n    val = (threadIdx.x < num_warps) ? warp_sums[threadIdx.x] : 0.0f;\n    if (warp_id == 0) {\n        val = warp_reduce_sum(val);\n    }\n\n    return val;\n}\n```\n\n## Performance\n\n### Occupancy Calculator\n\n```cuda\n// Query occupancy at compile time for tuning\nvoid report_occupancy() {\n    int block_size = 256;\n    int num_blocks;\n\n    cudaOccupancyMaxActiveBlocksPerMultiprocessor(\n        &num_blocks, my_kernel, block_size, 0);\n\n    cudaDeviceProp prop;\n    cudaGetDeviceProperties(&prop, 0);\n\n    int active_warps = num_blocks * (block_size / prop.warpSize);\n    int max_warps = prop.maxThreadsPerMultiProcessor / prop.warpSize;\n    float occupancy = (float)active_warps / max_warps;\n\n    printf(\"Occupancy: %.1f%% (%d/%d warps)\\n\",\n           occupancy * 100, active_warps, max_warps);\n}\n```\n\n### Nsight Profiling Workflow\n\n```bash\n# System-level trace: find CPU/GPU idle gaps, stream concurrency\nnsys profile -o trace ./program\nnsys stats trace.nsys-rep\n\n# Kernel-level analysis: roofline, memory throughput, occupancy\nncu --set full -o kernel_report ./program\nncu -i kernel_report.ncu-rep    # Open in Nsight Compute GUI\n\n# Quick single-metric check\nncu --metrics sm__throughput.avg.pct_of_peak_sustained_elapsed ./program\n```\n\n### Memory Bandwidth Measurement\n\n```cuda\n// Measure effective bandwidth of a kernel\nvoid measure_bandwidth(int n) {\n    size_t bytes = 2 * n * sizeof(float); // Read A + Write B\n\n    cudaEvent_t start, stop;\n    CUDA_CHECK(cudaEventCreate(&start));\n    CUDA_CHECK(cudaEventCreate(&stop));\n\n    CUDA_CHECK(cudaEventRecord(start));\n    copy_kernel<<<grid, block>>>(d_in, d_out, n);\n    CUDA_CHECK(cudaEventRecord(stop));\n    CUDA_CHECK(cudaEventSynchronize(stop));\n\n    float ms = 0;\n    CUDA_CHECK(cudaEventElapsedTime(&ms, start, stop));\n\n    float gb_per_sec = bytes / (ms * 1e6);\n    printf(\"Effective bandwidth: %.2f GB/s\\n\", gb_per_sec);\n\n    CUDA_CHECK(cudaEventDestroy(start));\n    CUDA_CHECK(cudaEventDestroy(stop));\n}\n```\n\n## Tooling\n\n### Essential Commands\n\n```bash\n# Compile CUDA code\nnvcc -arch=sm_80 -O3 -o program main.cu         # Single file\nnvcc -arch=native -lineinfo -o program main.cu   # With debug line info\n\n# CMake build\ncmake -B build -DCMAKE_CUDA_ARCHITECTURES=\"70;80;86\"\ncmake --build build -j$(nproc)\n\n# Runtime debugging\ncompute-sanitizer ./program                      # Memory errors (replaces cuda-memcheck)\ncompute-sanitizer --tool racecheck ./program     # Shared memory race conditions\ncompute-sanitizer --tool initcheck ./program     # Uninitialized device memory reads\ncompute-sanitizer --tool synccheck ./program     # Synchronization errors\n\n# Profiling\nnsys profile ./program                           # System-level timeline\nncu ./program                                    # Kernel-level metrics\nncu --kernel-name my_kernel --launch-skip 2 --launch-count 1 ./program\n\n# Device info\nnvidia-smi                                       # GPU status and memory usage\nnvcc --version                                   # CUDA compiler version\n```\n\n### CMakeLists.txt Template\n\n```cmake\ncmake_minimum_required(VERSION 3.18)\nproject(myproject LANGUAGES CXX CUDA)\n\nset(CMAKE_CXX_STANDARD 17)\nset(CMAKE_CUDA_STANDARD 17)\nset(CMAKE_CUDA_ARCHITECTURES 70 80 86)\nset(CMAKE_CUDA_SEPARABLE_COMPILATION ON)\n\nfind_package(CUDAToolkit REQUIRED)\n\nadd_library(kernels src/kernels.cu)\ntarget_include_directories(kernels PUBLIC include)\n\nadd_executable(main src/main.cpp)\ntarget_link_libraries(main kernels CUDA::cudart)\n\nenable_testing()\nadd_executable(tests tests/test_kernels.cu)\ntarget_link_libraries(tests kernels CUDA::cudart)\nadd_test(NAME gpu_tests COMMAND tests)\n```\n\n## References\n\nFor detailed patterns and examples, see:\n\n- [references/patterns.md](references/patterns.md) -- Tiled matrix multiply, parallel reduction tree, stream overlap pipeline\n\n## External References\n\n- [CUDA C++ Programming Guide](https://docs.nvidia.com/cuda/cuda-c-programming-guide/)\n- [CUDA C++ Best Practices Guide](https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/)\n- [Nsight Compute Documentation](https://docs.nvidia.com/nsight-compute/)\n- [Nsight Systems Documentation](https://docs.nvidia.com/nsight-systems/)\n- [Thrust Documentation](https://nvidia.github.io/cccl/thrust/)\n- [CUDA Samples](https://github.com/NVIDIA/cuda-samples)\n- [NVIDIA Occupancy Calculator](https://docs.nvidia.com/cuda/cuda-occupancy-calculator/)\n- [GPU Memory Hierarchy (GTC talk)](https://developer.nvidia.com/blog/tag/cuda/)\n"},"lastSynced":"2026-03-08T02:01:17.260Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents focused on GPU-accelerated computing, needing expertise in CUDA 11+ for deep learning and scientific computing applications.","zh":"非常适合专注于GPU加速计算的AI代理，需要在深度学习和科学计算应用中使用CUDA 11+的专业知识。","ja":"GPUアクセラレーションコンピューティングに焦点を当てたAIエージェントに最適で、深層学習と科学計算アプリケーションでCUDA 11+の専門知識を必要とします。","ko":"GPU 가속 컴퓨팅에 집중하는 AI 에이전트에게 적합하며, 심층 학습 및 과학 컴퓨팅 애플리케이션에서 CUDA 11+를 전문으로 하는 데 적합합니다.","es":"Perfecto para agentes de IA centrados en computación acelerada por GPU, que necesitan experiencia en CUDA 11+ para aplicaciones de aprendizaje profundo y computación científica.","fr":"Parfait pour les agents IA axés sur le calcul accéléré par GPU, nécessitant une expertise en CUDA 11+ pour les applications de deep learning et de calcul scientifique.","de":"Perfekt für KI-Agents, die auf GPU-beschleunigtes Rechnen spezialisiert sind und Expertenwissen in CUDA 11+ für Deep-Learning- und wissenschaftliche Rechenanwendungen benötigen.","pt":"Perfeito para Agentes de IA focados em computação acelerada por GPU, necessitando de especialização em CUDA 11+ para aplicações de aprendizado profundo e computação científica.","ru":"Идеально подходит для агентов ИИ, ориентированных на ускоренную вычисления на GPU, требующих экспертизы в CUDA 11+ для приложений глубокого обучения и научных вычислений.","ar":"مثالي لعميل الذكاء الاصطناعي الذين يركزون على الحوسبة المعززة بواسطة وحدة معالجة الرسومات، وحاجة إلى الخبرة في CUDA 11+ لتطبيقات التعلم العميق والحوسبة العلمية."},"recommendation":{"en":"Empowers agents to design high-performance algorithms with parallelism first principles, leveraging memory hierarchy awareness and coalesced access for optimal GPU utilization, supporting development in TypeScript, Python, Go, and Rust.","zh":"赋予代理设计高性能算法的能力，遵循并行性第一原则，利用内存层次结构感知和联合访问以实现最佳的GPU利用，支持TypeScript、Python、Go和Rust的开发。","ja":"エージェントが並列性を第一に考えた高性能アルゴリズムを設計できるようにし、メモリ階層構造の認識と結合されたアクセスを利用して最適なGPU利用を実現し、TypeScript、Python、Go、Rustの開発をサポートします。","ko":"에이전트가 병렬성 우선 원칙에 따라 고성능 알고리즘을 설계할 수 있도록 하며, 메모리 계층 구조 인식 및 집합 접근을 활용하여 최적의 GPU 사용을 달성하며, TypeScript, Python, Go 및 Rust 개발을 지원합니다.","es":"Habilita a los agentes a diseñar algoritmos de alto rendimiento con principios de paralelismo, aprovechando la conciencia de la jerarquía de memoria y el acceso coalescido para una utilización óptima de la GPU, y admitiendo el desarrollo en TypeScript, Python, Go y Rust.","fr":"Permet aux agents de concevoir des algorithmes haute performance avec des principes de parallélisme, en exploitant la conscience de la hiérarchie de mémoire et l''accès coalescé pour une utilisation optimale de la GPU, et en supportant le développement en TypeScript, Python, Go et Rust.","de":"Ermöglich es Agents, hochleistungsstarke Algorithmen mit Parallelsismus-First-Prinzipien zu entwerfen, die die Speicherhierarchie-Awareness und den koaleszierten Zugriff für eine optimale GPU-Ausnutzung nutzen, und die Entwicklung in TypeScript, Python, Go und Rust unterstützen.","pt":"Habilita os agentes a projetar algoritmos de alto desempenho com princípios de paralelismo em primeiro lugar, aproveitando a consciência da hierarquia de memória e o acesso coalescido para uma utilização ótima da GPU, suportando o desenvolvimento em TypeScript, Python, Go e Rust.","ru":"Наделяет агентов возможностью проектировать высокопроизводительные алгоритмы с параллелизмом в качестве первого принципа, используя осведомленность о иерархии памяти и коалированный доступ для оптимального использования GPU, поддерживая разработку на TypeScript, Python, Go и Rust.","ar":"تمكين الوكلاء من تصميم خوارزميات أداء عالية مع مبادئ متوازي أولاً، والاستفادة من الوعي بالهرمية الذاكرة والوصول المتوازي للحصول على استخدام مثالي للوحدة المعززة بواسطة وحدة معالجة الرسومات، ودعم التطوير بلغة TypeScript و Python و Go و Rust."},"useCases":{"en":["Optimizing deep learning models for GPU acceleration","Developing high-performance scientific computing applications with CUDA 11+","Debugging memory access patterns for improved GPU performance"],"zh":["为GPU加速优化深度学习模型","使用CUDA 11+开发高性能科学计算应用","调试内存访问模式以提高GPU性能"],"ja":["GPUアクセラレーションを使用した深層学習モデルの最適化","CUDA 11+を使用した高性能科学計算アプリケーションの開発","GPUパフォーマンスの向上のためのメモリアクセスパターンのデバッグ"],"ko":["GPU 가속을 사용한 심층 학습 모델 최적화","CUDA 11+를 사용한 고성능 과학 컴퓨팅 애플리케이션 개발","GPU 성능 개선을 위한 메모리 접근 패턴 디버깅"],"es":["Optimizar modelos de aprendizaje profundo para la aceleración por GPU","Desarrollar aplicaciones de computación científica de alto rendimiento con CUDA 11+","Depurar patrones de acceso a memoria para mejorar el rendimiento de la GPU"],"fr":["Optimiser les modèles de deep learning pour l''accélération par GPU","Développer des applications de calcul scientifique haute performance avec CUDA 11+","Déboguer les modèles d''accès à la mémoire pour améliorer les performances de la GPU"],"de":["Optimieren von Deep-Learning-Modellen für die GPU-Beschleunigung","Entwicklung von hochleistungsstarken wissenschaftlichen Rechenanwendungen mit CUDA 11+","Fehlersuche bei den Speicherzugriffsmustern zur Verbesserung der GPU-Leistung"],"pt":["Otimizar modelos de aprendizado profundo para aceleração por GPU","Desenvolver aplicações de computação científica de alto desempenho com CUDA 11+","Depurar padrões de acesso à memória para melhorar o desempenho da GPU"],"ru":["Оптимизация моделей глубокого обучения для ускорения на GPU","Разработка высокопроизводительных научных вычислительных приложений с CUDA 11+","Отладка моделей доступа к памяти для улучшения производительности GPU"],"ar":["تحسين نماذج التعلم العميق لتسريع وحدة معالجة الرسومات","تطوير تطبيقات الحوسبة العلمية عالية الأداء مع CUDA 11+","تصحيح أخطاء أنماط الوصول إلى الذاكرة لتحسين أداء وحدة معالجة الرسومات"]},"limitations":{"en":["Requires CUDA 11+ compatible hardware","Limited to GPU computing, deep learning, and scientific computing applications","Development restricted to TypeScript, Python, Go, and Rust"],"zh":["需要兼容CUDA 11+的硬件","仅限GPU计算、深度学习和科学计算应用","开发仅限于TypeScript、Python、Go和Rust"],"ja":["CUDA 11+と互換性のあるハードウェアが必要","GPUコンピューティング、深層学習、科学計算アプリケーションに限定","開発はTypeScript、Python、Go、Rustに制限"],"ko":["CUDA 11+와 호환되는 하드웨어 필요","GPU 컴퓨팅, 심층 학습 및 과학 컴퓨팅 애플리케이션에만 제한","개발은 TypeScript, Python, Go 및 Rust로 제한"],"es":["Requiere hardware compatible con CUDA 11+","Limitado a aplicaciones de computación por GPU, aprendizaje profundo y computación científica","Desarrollo restringido a TypeScript, Python, Go y Rust"],"fr":["Nécessite un matériel compatible CUDA 11+","Limité aux applications de calcul par GPU, de deep learning et de calcul scientifique","Développement restreint à TypeScript, Python, Go et Rust"],"de":["Benötigt CUDA-11+-kompatibles Hardware","Begrenzt auf GPU-Rechen-, Deep-Learning- und wissenschaftliche Rechenanwendungen","Entwicklung auf TypeScript, Python, Go und Rust beschränkt"],"pt":["Exige hardware compatível com CUDA 11+","Limitado a aplicações de computação por GPU, aprendizado profundo e computação científica","Desenvolvimento restrito a TypeScript, Python, Go e Rust"],"ru":["Требует совместимого с CUDA 11+ оборудования","Ограничен приложениями для вычислений на GPU, глубокого обучения и научных вычислений","Разработка ограничена TypeScript, Python, Go и Rust"],"ar":["يتطلب الأجهزة المتوافقة مع CUDA 11+","محدود لتطبيقات الحوسبة بواسطة وحدة معالجة الرسومات، والتعلم العميق، والحوسبة العلمية","التطوير مقيد بلغة TypeScript و Python و Go و Rust"]},"version":4},"contentHash":"33f8d70986fcf190cd36242d1c5032db166503e51160db1ed2d5794a17a2d6df","qualityScore":50}');
