INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jk278/veld/product-manager', 'product-manager', 'jk278', 'veld', 'community', 'product-manager jk278 veld community The product-manager skill assists developers with core product management workflows, including research synthesis and feature prioritization. It benefits developers working on AI-powered projects. Veld AI Toolkit帮助开发者快速访问AI助手，进行产品管理核心工作流，包括研究合成、需求文档和功能优先级 Veld AIエージェントは、開発者が製品管理の核心ワークフロー、包括研究合成、要件ドキュメント、機能優先順位を実行できるようにします Veld AI 도구는 개발자가 제품 관리 핵심 워크플로를 수행할 수 있도록 도와줍니다. 연구 합성, 요구 사항 문서화, 기능 우선순위를 포함하여 La habilidad product-manager de Veld es una herramienta de AI que ayuda a los desarrolladores a gestionar productos de manera más eficiente, con funcionalidades como síntesis de investigación y priorización de características La compétence product-manager de Veld est un outil d''IA qui aide les développeurs à gérer les produits de manière plus efficace, avec des fonctionnalités telles que la synthèse de recherche et la priorisation des fonctionnalités Die Fähigkeit product-manager von Veld ist ein KI-Tool, das Entwicklern hilft, Produkte effizienter zu verwalten, mit Funktionen wie Recherchesynthese und Funktionspriorisierung O Product Manager é uma ferramenta de IA que ajuda nos fluxos de trabalho de gestão de produtos, incluindo síntese de pesquisa e priorização de recursos ИИ Агент Product Manager - это инструмент, который помогает в потоке работы управления продуктами, включая синтез исследования и приоритизацию функций مساعد إدارة المنتج بالذكاء الاصطناعي هو أداة تساعد في تدفق العمل لإدارة المنتجات، بما في ذلك تحليل البحث وتحديد الأولويات للميزات how to use product-manager product-manager setup guide what is product-manager product-manager alternative product-manager vs competing tools installing product-manager for AI agents product-manager for developers product-manager workflow optimization product-manager for AI-powered projects 产品经理AI工具 AI助手 产品管理 研究合成 需求文档 功能优先级 Veld AI Toolkit Assists with research synthesis, requirement documentation, and feature prioritization Enables real-time AI interaction for stakeholder updates and presentations Supports analyzing user interviews, surveys, or feedback for data-driven decisions Facilitates interpreting product metrics and analytics for informed decision-making Conducts competitive analysis for strategic product planning product-manager is a cross-platform system tray tool for quick AI assistant access, facilitating workflows such as user research, requirement documentation, and strategic communication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('overtimepog/AgentTheo/Global Validation', 'community', 'overtimepog', 'AgentTheo', 'overtimepog/AgentTheo', 'Global Validation', 0, 0, 50, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:44.029Z', 'c84a19a2505351aea39ad07171e5de6392c6dec256ac28716eb6b93a92b81770', '{"id":"overtimepog/AgentTheo/Global Validation","name":"Global Validation","description":{"en":"Global Validation provides specific guidance on coding standards for handling global validation, benefiting developers implementing server-side and client-side validation for API endpoints and forms.","zh":"全局验证是一种基本的聊天机器人代理，提供如何处理全局验证的指导，适用于服务器端和客户端验证","ja":"グローバルバリデーションは基本的なチャットボットエージェントであり、サーバーサイドとクライアントサイドのバリデーションを処理する方法に関するガイダンスを提供する","ko":"전역 유효성 검사는 기본적인聊天机器人 에이전트로서 서버 측 및 클라이언트 측 유효성 검사를 처리하는 방법에 대한 가이드를 제공합니다","es":"La Validación Global es una habilidad fundamental para los agentes de inteligencia artificial, que proporciona orientación sobre cómo adherirse a los estándares de codificación para la validación de datos","fr":"La Validation Globale est une compétence essentielle pour les outils d''IA, qui fournit des conseils sur la façon de respecter les normes de codage pour la validation des données","de":"Die globale Validierung ist eine grundlegende Fähigkeit für KI-Agents, die eine Orientierung darüber bietet, wie die Codierungsstandards für die Datenvalidierung eingehalten werden können","pt":"A Validação Global é uma habilidade de agente de chatbot que fornece orientação sobre como seguir padrões de codificação para validação de servidor e cliente.","ru":"Глобальная Валидация - это навык чат-бота, который предоставляет руководство по соблюдению стандартов кодирования для валидации на стороне сервера и клиента.","ar":"التحقق العالمي هي ميزة لعميل الدردشة توفر إرشادات حول كيفية اتباع معايير البرمجة للتحقق من الجانب الخلفي والجانب الأمامي"},"seo":{"title":{"en":"Global Validation: Setup Guide for AI Agents","zh":"全局验证 Setup Guide - AIエージェント开发最佳实践","ja":"グローバルバリデーション入門 - AIエージェントのための開発ガイド","ko":"전역 유효성 검사 설정 가이드 - AI 에이전트 개발자를 위한 최고의 관행","es":"Guía de configuración de Validación Global para agentes d...","fr":"Guide de mise en place de la Validation Globale pour les ...","de":"Einrichtungsleitfaden für globale Validierung in KI-Agents","pt":"Guia de Configuração de Validação Global para Desenvolved...","ru":"Настройка Глобальной Валидации для ИИ Агентов: Лучшие Пра...","ar":"دليل تنفيذ التحقق العالمي لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement server-side and client-side validation with Global Validation. Learn how to handle API endpoints, forms, and data processing with e...","zh":"了解全局验证的基础知识，学习如何在API端点、表单和数据处理中实现服务器端和客户端验证","ja":"グローバルバリデーションの基本を学び、APIエンドポイント、フォーム、データ処理でのサーバーサイドとクライアントサイドのバリデーションを実装する方法を発見","ko":"전역 유효성 검사의 기본을 배우고 API 엔드포인트, 양식 및 데이터 처리에서 서버 측 및 클라이언트 측 유효성 검사를 구현하는 방법을 알아보세요","es":"Aprende a implementar la validación global en tus proyectos de desarrollo con este enfoque práctico y escalable para agentes de inteligencia artificial","fr":"Découvrez comment mettre en œuvre la validation globale dans vos projets de développement avec cette approche pratique et évolutuve pour les outils d''IA","de":"Erfahren Sie, wie Sie die globale Validierung in Ihren Entwicklungsprojekten implementieren können, mit diesem praxisorientierten und skalierbaren Ansatz für...","pt":"Aprenda a implementar a validação global em seus projetos com essa habilidade de agente de chatbot, incluindo validação de servidor e cliente","ru":"Узнайте, как реализовать глобальную валидацию в ваших проектах с помощью этого навыка чат-бота, включая валидацию на стороне сервера и клиента","ar":"تعرف على كيفية تنفيذ التحقق العالمي في مشاريعك باستخدام هذه المهارة لعميل الدردشة، بما في ذلك التحقق من الجانب الخلفي والجانب الأمامي"},"definition":{"en":"Global Validation is a basic yet solid chatbot agent skill that provides guidance on adhering to coding standards for global validation in various applications.","zh":"全局验证是一种用于验证用户输入和数据处理的技术，确保数据的准确性和安全性","ja":"グローバルバリデーションは、ユーザーの入力とデータ処理を検証する技術であり、データの正確性とセキュリティを確保する","ko":"전역 유효성 검사는 사용자 입력 및 데이터 처리를 검증하는 기술로서 데이터의 정확성 및 보안을 보장합니다","es":"La Validación Global es una técnica de validación de datos que se utiliza para garantizar la consistencia y la exactitud de los datos en aplicaciones y API","fr":"La Validation Globale est une technique de validation de données qui est utilisée pour garantir la cohérence et l''exactitude des données dans les applications et les API","de":"Die globale Validierung ist eine Technik zur Überprüfung von Daten, die dazu dient, die Konsistenz und Genauigkeit von Daten in Anwendungen und APIs zu gewährleisten","pt":"Validação Global é uma técnica de verificação de dados que garante a consistência dos dados em todo o sistema","ru":"Глобальная Валидация - это техника проверки данных, обеспечивающая согласованность данных во всем системе","ar":"التحقق العالمي هو تقنية للتحقق من البيانات التي تضمن الاتساق في جميع أنحاء النظام"},"features":{"en":["Provides guidance on server-side validation for API endpoints and forms","Supports client-side validation for immediate user feedback","Handles validation of user inputs in forms, search fields, and text inputs","Processes API request payloads for secure data processing"],"zh":["服务器端验证","客户端验证","API端点验证","表单验证","数据处理验证","React和Python集成"],"ja":["サーバーサイドバリデーション","クライアントサイドバリデーション","APIエンドポイントバリデーション","フォームバリデーション","データ処理バリデーション","ReactとPythonの統合"],"ko":["서버 측 유효성 검사","클라이언트 측 유효성 검사","API 엔드포인트 유효성 검사","양식 유효성 검사","데이터 처리 유효성 검사","React 및 Python 통합"],"es":["Validación de datos en el servidor para API y formularios","Validación de datos en el cliente para retroalimentación inmediata","Procesamiento de payloads de solicitudes de API","Validación de entradas de usuario en formularios y campos de texto","Implementación de estándares de codificación para la validación de datos"],"fr":["Validation des données sur le serveur pour les API et les formulaires","Validation des données sur le client pour une rétroaction immédiate","Traitement des charges utiles des requêtes d''API","Validation des entrées utilisateur dans les formulaires et les champs de texte","Mise en œuvre des normes de codage pour la validation des données"],"de":["Datenvalidierung auf dem Server für APIs und Formulare","Datenvalidierung auf dem Client für sofortige Rückmeldung","Verarbeitung von API-Anforderungspayloads","Validierung von Benutzereingaben in Formularen und Textfeldern","Implementierung von Codierungsstandards für die Datenvalidierung"],"pt":["Validação de servidor para pontos de extremidade de API","Validação de cliente para feedback imediato do usuário","Suporte à validação de formulários e campos de texto","Processamento de payloads de solicitação de API"],"ru":["Валидация на стороне сервера для конечных точек API","Валидация на стороне клиента для немедленной обратной связи пользователя","Поддержка валидации форм и текстовых полей","Обработка полезных нагрузок запросов API"],"ar":["التحقق من الجانب الخلفي لنقاط النهاية API","التحقق من الجانب الأمامي للرد الفوري للمستخدم","دعم التحقق من النماذج وحقول النص","معالجة حمولات الطلبات API"]},"keywords":{"en":["how to use Global Validation","what is Global Validation","Global Validation alternative","Global Validation vs other validation tools","Global Validation install","Global Validation setup guide","API endpoint validation","client-side validation best practices"],"zh":["全局验证","AIエージェント","服务器端验证","客户端验证","API端点验证","表单验证","数据处理验证","React","Python","聊天机器人开发"],"ja":["グローバルバリデーション","AIエージェント","サーバーサイドバリデーション","クライアントサイドバリデーション","APIエンドポイントバリデーション","フォームバリデーション","データ処理バリデーション","React","Python","チャットボット開発"],"ko":["전역 유효성 검사","AI 에이전트","서버 측 유효성 검사","클라이언트 측 유효성 검사","API 엔드포인트 유효성 검사","양식 유효성 검사","데이터 처리 유효성 검사","React","Python","챗봇 개발"],"es":["validación global","agentes de inteligencia artificial","desarrollo de software","validación de datos","estándares de codificación","API","formularios","validación de servidor","validación de cliente"],"fr":["validation globale","outils d''IA","développement de logiciels","validation de données","normes de codage","API","formulaires","validation de serveur","validation de client"],"de":["globale Validierung","KI-Agents","Softwareentwicklung","Datenvalidierung","Codierungsstandards","API","Formulare","Server-Validierung","Client-Validierung"],"pt":["validação global","agente de chatbot","desenvolvimento de software","padrões de codificação","validação de servidor","validação de cliente","API","formulários","campos de texto"],"ru":["глобальная валидация","чат-бот","разработка программного обеспечения","стандарты кодирования","валидация на стороне сервера","валидация на стороне клиента","ИИ Агенты","API","формы","текстовые поля"],"ar":["التحقق العالمي","أدوات الذكاء الاصطناعي","تطوير البرمجيات","معايير البرمجة","التحقق من الجانب الخلفي","التحقق من الجانب الأمامي","نقاط النهاية API","النماذج","حقول النص"]}},"owner":"overtimepog","repo":"AgentTheo","repoPath":"overtimepog/AgentTheo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"Global Validation","description":"Implement comprehensive input validation on server-side with complementary client-side validation for user experience, using allowlists, type checking, and sanitization to prevent injection attacks. Use this skill when validating user inputs, form data, API requests, file uploads, query parameters, or any external data entering the application. Apply this skill when implementing server-side validation as the primary security layer, adding client-side validation for immediate user feedback, validating data types and formats, checking ranges and required fields, sanitizing inputs to prevent SQL injection and XSS attacks, using allowlists over blocklists, providing field-specific error messages, or enforcing business rules at appropriate application layers. This skill ensures validation happens at all entry points consistently, security is never dependent on client-side checks alone, users receive helpful immediate feedback, and data integrity is maintained through multiple layers of validation.","bodyPreview":"# Global Validation\n\nThis Skill provides Claude Code with specific guidance on how to adhere to coding standards as they relate to how it should handle global validation.\n\n## When to use this skill\n\n- When implementing server-side validation for API endpoints, forms, or data processing\n- When adding client-side validation for immediate user feedback (but always duplicating server-side)\n- When validating user inputs in forms, search fields, or text inputs\n- When processing API request payloads, q","body":"# Global Validation\n\nThis Skill provides Claude Code with specific guidance on how to adhere to coding standards as they relate to how it should handle global validation.\n\n## When to use this skill\n\n- When implementing server-side validation for API endpoints, forms, or data processing\n- When adding client-side validation for immediate user feedback (but always duplicating server-side)\n- When validating user inputs in forms, search fields, or text inputs\n- When processing API request payloads, query parameters, or file uploads\n- When sanitizing inputs to prevent SQL injection, XSS, or command injection attacks\n- When validating data types, formats (email, phone, date), required fields, and ranges\n- When providing specific, helpful error messages for each validation failure\n- When using allowlists (defining what''s allowed) rather than blocklists (blocking bad patterns)\n- When implementing business rule validation (sufficient balance, valid dates, inventory checks)\n- When ensuring validation is applied consistently across all entry points (web, API, background jobs)\n- When failing early by rejecting invalid data before processing or storing it\n- When working with form validation libraries or schema validation tools (Yup, Zod, Joi, Pydantic)\n- When adding validation error handling in UI components or API error responses\n- When testing validation logic to ensure security and data integrity\n\n## Instructions\n\nFor details, refer to the information provided in this file:\n[global validation](../../../agent-os/standards/global/validation.md)\n"},"lastSynced":"2026-03-08T02:01:44.029Z","agentAnalysis":{"suitability":{"en":"Perfect for API-focused Agents needing robust server-side and client-side validation capabilities for handling global validation.","zh":"非常适合需要强大的服务器端和客户端验证能力的API专注代理，用于处理全局验证。","ja":"API中心のエージェントに適しています。グローバルな検証のための強力なサーバーサイドとクライアントサイドの検証機能が必要です。","ko":"전역 검증을 처리하는 데 강력한 서버 측 및 클라이언트 측 검증 기능이 필요한 API 중심 에이전트에 적합합니다.","es":"Perfecto para Agentes centrados en API que necesitan capacidades de validación robustas en el servidor y en el cliente para el manejo de la validación global.","fr":"Parfait pour les Agents axés sur l''API nécessitant des capacités de validation robustes côté serveur et côté client pour la gestion de la validation globale.","de":"Perfekt für API-fokussierte Agenten, die robuste Server- und Client-Seitige Validierungsfunktionen für die globale Validierung benötigen.","pt":"Perfeito para Agentes focados em API que necessitam de capacidades de validação robustas de servidor e cliente para lidar com validação global.","ru":"Идеально для агентов, ориентированных на API, которым необходимы мощные возможности валидации на стороне сервера и клиента для обработки глобальной валидации.","ar":"مثالي للوكلاء الذين يركزون على واجهات برمجة التطبيقات التي تحتاج إلى قدرات التحقق القوية على جانب الخادم والعميل لمعالجة التحقق العالمي."},"recommendation":{"en":"Empowers agents to adhere to coding standards for global validation, providing specific guidance on handling API endpoint and form validation using protocols like HTTP and HTTPS, and supporting libraries for immediate user feedback and data processing.","zh":"赋予代理人遵循编码标准以进行全局验证的能力，提供有关使用HTTP和HTTPS等协议处理API端点和表单验证的具体指导，并支持提供立即用户反馈和数据处理的库。","ja":"エージェントに、HTTPやHTTPSなどのプロトコルを使用したAPIエンドポイントやフォームの検証を処理するためのコーディング規範に従う能力を付与し、即時のユーザーフィードバックやデータ処理を提供するライブラリをサポートします。","ko":"에이전트에게 전역 검증을 위한 코딩 표준을 준수할 수 있는 능력을 부여하며, HTTP 및 HTTPS와 같은 프로토콜을 사용하여 API 엔드포인트 및 양식 검증을 처리하는 데 대한 구체적인 지침을 제공하고, 즉각적인 사용자 피드백 및 데이터 처리를 제공하는 라이브러리를 지원합니다.","es":"Permite a los agentes adherirse a los estándares de codificación para la validación global, proporcionando orientación específica sobre el manejo de la validación de puntos finales de API y formularios utilizando protocolos como HTTP y HTTPS, y bibliotecas de soporte para la retroalimentación inmediata del usuario y el procesamiento de datos.","fr":"Permet aux agents de se conformer aux normes de codage pour la validation globale, en fournissant des conseils spécifiques sur la gestion de la validation des points de terminaison d''API et des formulaires en utilisant des protocoles tels que HTTP et HTTPS, et des bibliothèques de support pour la rétroaction immédiate de l''utilisateur et le traitement des données.","de":"Ermächtigt die Agenten, sich an die Kodierungsstandards für die globale Validierung zu halten und bietet spezifische Anleitung zur Handhabung der API-Endpunkt- und Formularvalidierung unter Verwendung von Protokollen wie HTTP und HTTPS sowie unterstützende Bibliotheken für sofortige Benutzerfeedback und Datenverarbeitung.","pt":"Habilita os agentes a aderir aos padrões de codificação para validação global, fornecendo orientação específica sobre como lidar com a validação de pontos de extremidade de API e formulários usando protocolos como HTTP e HTTPS, e bibliotecas de suporte para feedback imediato do usuário e processamento de dados.","ru":"Наделяет агентов возможностью соблюдать стандарты кодирования для глобальной валидации, предоставляя конкретные рекомендации по обработке валидации конечных точек API и форм с использованием протоколов như HTTP и HTTPS, а также поддерживающие библиотеки для немедленной обратной связи пользователя и обработки данных.","ar":"يتمكّن الوكلاء من الالتزام بمعايير البرمجة للتحقق العالمي، مع توفير إرشادات محددة حول كيفية التعامل مع التحقق من نقاط النهاية لواجهة برمجة التطبيقات والاستمارات باستخدام بروتوكولات مثل HTTP وHTTPS، ودعم المكتبات للتعليقات الفورية للمستخدم ومعالجة البيانات."},"useCases":{"en":["Implementing server-side validation for API endpoints and forms","Adding client-side validation for immediate user feedback","Validating user inputs in forms, search fields, or text inputs","Processing API request payloads"],"zh":["为API端点和表单实现服务器端验证","为即时用户反馈添加客户端验证","验证表单、搜索字段或文本输入中的用户输入","处理API请求有效载荷"],"ja":["APIエンドポイントとフォームのサーバーサイド検証を実装する","即時のユーザーフィードバックのためにクライアントサイド検証を追加する","フォーム、検索フィールド、またはテキスト入力内のユーザー入力を検証する","APIリクエストペイロードを処理する"],"ko":["API 엔드포인트 및 양식에 대한 서버 측 검증을 구현합니다.","즉각적인 사용자 피드백을 위해 클라이언트 측 검증을 추가합니다.","양식, 검색 필드 또는 텍스트 입력에서 사용자 입력을 검증합니다.","API 요청 페이로드를 처리합니다."],"es":["Implementar la validación en el servidor para puntos finales de API y formularios","Agregar validación en el cliente para una retroalimentación inmediata del usuario","Validar las entradas de usuario en formularios, campos de búsqueda o campos de texto","Procesar las cargas de solicitudes de API"],"fr":["Mettre en œuvre la validation côté serveur pour les points de terminaison d''API et les formulaires","Ajouter la validation côté client pour une rétroaction immédiate de l''utilisateur","Valider les entrées utilisateur dans les formulaires, les champs de recherche ou les champs de texte","Traiter les charges de requêtes d''API"],"de":["Implementierung der Server-Seitigen Validierung für API-Endpunkte und Formulare","Hinzufügen der Client-Seitigen Validierung für sofortige Benutzerfeedback","Validieren von Benutzereingaben in Formularen, Suchfeldern oder Texteingabefeldern","Verarbeiten von API-Anforderungsnutzlasten"],"pt":["Implementar validação de servidor para pontos de extremidade de API e formulários","Adicionar validação de cliente para feedback imediato do usuário","Validar entradas de usuário em formulários, campos de pesquisa ou entradas de texto","Processar payloads de solicitações de API"],"ru":["Реализовать валидацию на стороне сервера для конечных точек API и форм","Добавить валидацию на стороне клиента для немедленной обратной связи пользователя","Валидировать ввод пользователя в формах, полях поиска или текстовых полях","Обрабатывать payload запросов API"],"ar":["تنفيذ التحقق من جانب الخادم لنقاط النهاية لواجهة برمجة التطبيقات والاستمارات","إضافة التحقق من جانب العميل للتعليقات الفورية للمستخدم","التحقق من إدخال المستخدم في الاستمارات أو حقول البحث أو إدخال النص","معالجة حمولات طلبات واجهة برمجة التطبيقات"]},"limitations":{"en":["Requires duplicated server-side validation for security","Limited to handling global validation for API endpoints and forms"],"zh":["需要为安全性而进行重复的服务器端验证","仅限于处理API端点和表单的全局验证"],"ja":["セキュリティのためにサーバーサイド検証を複製する必要がある","APIエンドポイントとフォームのグローバルな検証のみを処理することができる"],"ko":["보안을 위해 서버 측 검증을 중복해야 합니다.","API 엔드포인트 및 양식의 전역 검증만 처리할 수 있습니다."],"es":["Requiere validación duplicada en el servidor para la seguridad","Limitado a la gestión de la validación global para puntos finales de API y formularios"],"fr":["Nécessite une validation dupliquée côté serveur pour la sécurité","Limité à la gestion de la validation globale pour les points de terminaison d''API et les formulaires"],"de":["Erfordert doppelte Server-Seitige Validierung für die Sicherheit","Begrenzt auf die Handhabung der globalen Validierung für API-Endpunkte und Formulare"],"pt":["Exige validação de servidor duplicada para segurança","Limitado ao manuseio de validação global para pontos de extremidade de API e formulários"],"ru":["Требует дублированной валидации на стороне сервера для безопасности","Ограничен обработкой глобальной валидации для конечных точек API и форм"],"ar":["يتطلب التحقق المكرر من جانب الخادم للأمان","محدود بمعالجة التحقق العالمي لنقاط النهاية لواجهة برمجة التطبيقات والاستمارات"]},"version":4},"contentHash":"c84a19a2505351aea39ad07171e5de6392c6dec256ac28716eb6b93a92b81770","qualityScore":50}');
