INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('overtimepog/AgentTheo/Global Validation', 'Global Validation', 'overtimepog', 'AgentTheo', 'community', 'Global Validation overtimepog AgentTheo community Global Validation provides specific guidance on coding standards for handling global validation, benefiting developers implementing server-side and client-side validation for API endpoints and forms. 全局验证是一种基本的聊天机器人代理，提供如何处理全局验证的指导，适用于服务器端和客户端验证 グローバルバリデーションは基本的なチャットボットエージェントであり、サーバーサイドとクライアントサイドのバリデーションを処理する方法に関するガイダンスを提供する 전역 유효성 검사는 기본적인聊天机器人 에이전트로서 서버 측 및 클라이언트 측 유효성 검사를 처리하는 방법에 대한 가이드를 제공합니다 La Validación Global es una habilidad fundamental para los agentes de inteligencia artificial, que proporciona orientación sobre cómo adherirse a los estándares de codificación para la validación de datos La Validation Globale est une compétence essentielle pour les outils d''IA, qui fournit des conseils sur la façon de respecter les normes de codage pour la validation des données Die globale Validierung ist eine grundlegende Fähigkeit für KI-Agents, die eine Orientierung darüber bietet, wie die Codierungsstandards für die Datenvalidierung eingehalten werden können A Validação Global é uma habilidade de agente de chatbot que fornece orientação sobre como seguir padrões de codificação para validação de servidor e cliente. Глобальная Валидация - это навык чат-бота, который предоставляет руководство по соблюдению стандартов кодирования для валидации на стороне сервера и клиента. التحقق العالمي هي ميزة لعميل الدردشة توفر إرشادات حول كيفية اتباع معايير البرمجة للتحقق من الجانب الخلفي والجانب الأمامي how to use Global Validation what is Global Validation Global Validation alternative Global Validation vs other validation tools Global Validation install Global Validation setup guide API endpoint validation client-side validation best practices 全局验证 AIエージェント 服务器端验证 客户端验证 API端点验证 表单验证 数据处理验证 React Python 聊天机器人开发 Provides guidance on server-side validation for API endpoints and forms Supports client-side validation for immediate user feedback Handles validation of user inputs in forms, search fields, and text inputs Processes API request payloads for secure data processing Global Validation is a basic yet solid chatbot agent skill that provides guidance on adhering to coding standards for global validation in various applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ruan-cat/monorepo/openspec-continue-change', 'community', 'ruan-cat', 'monorepo', 'ruan-cat/monorepo', 'openspec-continue-change', 0, 0, 50, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:35.777Z', 'd0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d', '{"id":"ruan-cat/monorepo/openspec-continue-change","name":"openspec-continue-change","description":{"en":"openspec-continue-change is a skill that allows AI agents to continue working on changes by creating the next artifact. It benefits developers by streamlining their workflow.","zh":"openspec-continue-change 是一个用于继续更改的 AIエージェント，通过创建下一个工件来实现自动化流程","ja":"openspec-continue-change は変更を続けるための AIエージェントであり、次のアーティファクトを作成することで自動化プロセスを実現します","ko":"openspec-continue-change 는 변경을 계속하기 위한 AI 에이전트로 다음 아티팩트를 생성하여 자동화 프로세스를 구현합니다","es":"openspec-continue-change es una herramienta que permite continuar trabajando en un cambio mediante la creación del próximo artifact. Utiliza npm y CLI para gestionar los cambios.","fr":"openspec-continue-change est un outil qui permet de continuer à travailler sur un changement en créant le prochain artifact. Il utilise npm et CLI pour gérer les changements.","de":"openspec-continue-change ist ein Tool, das es ermöglicht, an einem Change weiterzuarbeiten, indem das nächste Artifact erstellt wird. Es verwendet npm und CLI, um die Änderungen zu verwalten.","pt":"O openspec-continue-change é uma ferramenta que permite criar o próximo artifact de alteração usando o npm @ruan-cat/*. Ele lista as alterações disponíveis e permite ao usuário selecionar qual alteração trabalhar.","ru":"openspec-continue-change - это инструмент, который позволяет создать следующий артефакт изменений, используя npm @ruan-cat/*. Он список доступных изменений и позволяет пользователю выбрать, над какой изменением работать.","ar":"openspec-continue-change هو أداة تمكن من إنشاء التالي artifact لتغيير باستخدام npm @ruan-cat/*. يقوم بlisting التغييرات المتاحة ويمكن للمستخدم اختيار التغيير الذي يريد العمل عليه."},"seo":{"title":{"en":"openspec-continue-change: Setup Guide for AI Agents","zh":"openspec-continue-change Setup Guide - AIエージェント","ja":"openspec-continue-change Setup Guide - AIエージェント","ko":"openspec-continue-change Setup Guide - AI 에이전트","es":"Guía de configuración de openspec-continue-change para ag...","fr":"Guide de démarrage rapide pour openspec-continue-change a...","de":"Einrichtungsanleitung für openspec-continue-change mit KI...","pt":"Guia de Configuração do openspec-continue-change para Des...","ru":"Настройка openspec-continue-change: Руководство для Разра...","ar":"دليل إعداد openspec-continue-change لمنصة أدوات الذكاء ال..."},"description":{"en":"Discover how to continue working on changes with openspec-continue-change. Learn how to create the next artifact and manage changes with ease. Get started now!","zh":"使用 openspec-continue-change 实现自动化流程，提高开发效率，了解更多关于 AIエージェント 的信息","ja":"openspec-continue-change を使用して自動化プロセスを実現し、開発効率を向上させます。AIエージェント の詳細についてはこちら","ko":"openspec-continue-change 를 사용하여 자동화 프로세스를 구현하고 개발 효율을 향상시키세요. AI 에이전트에 대한 자세한 정보","es":"Aprende a utilizar openspec-continue-change con npm y CLI para crear el próximo artifact en tu proyecto de desarrollo","fr":"Découvrez comment utiliser openspec-continue-change avec npm et CLI pour créer le prochain artifact dans votre projet de développement","de":"Erfahren Sie, wie Sie openspec-continue-change mit npm und CLI verwenden, um das nächste Artifact in Ihrem Entwicklungsprojekt zu erstellen","pt":"Aprenda a usar o openspec-continue-change com o npm @ruan-cat/* para criar o próximo artifact de alteração","ru":"Используйте openspec-continue-change с npm @ruan-cat/* для создания следующего артефакта изменений в ваших ИИ Агентах","ar":"تعلم كيفية استخدام openspec-continue-change مع npm @ruan-cat/* لإنشاء التالي artifact لتغيير في أدوات الذكاء الاصطناعي"},"definition":{"en":"openspec-continue-change is a skill that enables AI agents to continue working on changes by creating the next artifact, using commands like `openspec list --json`.","zh":"openspec-continue-change 是一种 AIエージェント，用于继续更改和创建下一个工件","ja":"openspec-continue-change は、変更を続けて次のアーティファクトを作成する AIエージェントです","ko":"openspec-continue-change 는 변경을 계속하고 다음 아티팩트를 생성하는 AI 에이전트입니다","es":"openspec-continue-change es una herramienta de desarrollo que permite continuar trabajando en un cambio mediante la creación del próximo artifact","fr":"openspec-continue-change est un outil de développement qui permet de continuer à travailler sur un changement en créant le prochain artifact","de":"openspec-continue-change ist ein Entwicklungstool, das es ermöglicht, an einem Change weiterzuarbeiten, indem das nächste Artifact erstellt wird","pt":"O openspec-continue-change é uma ferramenta de linha de comando que permite continuar trabalhando em uma alteração","ru":"openspec-continue-change - это командная утилита, которая позволяет продолжить работу над изменением","ar":"openspec-continue-change هو أداة سطر أوامر تمكن من الاستمرار في العمل على تغيير"},"features":{"en":["Runs `openspec list --json` to get available changes sorted by most recently modified","Uses the AskUserQuestion tool to let users select which change to work on","Presents the top 3-5 available changes for user selection","Creates the next artifact based on user input or conversation context","Infers change name from conversation context if not explicitly provided","Prompts for selection if change name is vague or ambiguous"],"zh":["支持创建下一个工件","可选指定更改名称","如果省略，更改名称可以从对话上下文中推断","如果不明确或模糊，则必须提示用户选择可用的更改","使用 AskUserQuestion 工具让用户选择要处理的更改","运行 openspec list --json 获取可用的更改，按最近修改时间排序"],"ja":["次のアーティファクトを作成する機能","変更名の指定が可能","省略した場合は、変更名を会話のコンテキストから推測する","不明確または曖昧な場合は、利用可能な変更の選択をユーザーに促す","AskUserQuestion ツールを使用してユーザーがどの変更を処理するか選択できる","openspec list --json を実行して利用可能な変更を取得し、最近変更された順に並べ替える"],"ko":["다음 아티팩트를 생성하는 기능","변경 이름을 지정할 수 있습니다","省略한 경우 변경 이름을 대화의 컨텍스트에서 추론","불분명 또는 모호한 경우 사용 가능한 변경 사항을 선택하도록 사용자를 제안","AskUserQuestion 도구를 사용하여 사용자가 처리할 변경 사항을 선택","openspec list --json을 실행하여 사용 가능한 변경 사항을 가져오고 최근 수정된 순으로 정렬"],"es":["Utiliza npm para gestionar los cambios","Permite crear el próximo artifact mediante CLI","Incluye la herramienta AskUserQuestion para seleccionar el cambio a trabajar","Ordena los cambios por fecha de modificación","Presenta los 3 cambios más recientes","Soporta la inferencia de contexto de conversación"],"fr":["Utilise npm pour gérer les changements","Permet de créer le prochain artifact via CLI","Inclut l''outil AskUserQuestion pour sélectionner le changement à travailler","Trie les changements par date de modification","Présente les 3 changements les plus récents","Prend en charge l''inférence de contexte de conversation"],"de":["Verwendet npm, um die Änderungen zu verwalten","Ermöglicht die Erstellung des nächsten Artifacts über CLI","Enthält das Tool AskUserQuestion, um den Change auszuwählen","Sortiert die Änderungen nach Änderungsdatum","Präsentiert die 3 zuletzt geänderten Änderungen","Unterstützt die Kontextinferenz"],"pt":["Cria o próximo artifact de alteração","Lista as alterações disponíveis usando `openspec list --json`","Permite ao usuário selecionar qual alteração trabalhar","Usa o AskUserQuestion tool para obter a seleção do usuário","Executa `openspec list --json` para obter as alterações mais recentes"],"ru":["Создаёт следующий артефакт изменений","Список доступных изменений с помощью `openspec list --json`","Позволяет пользователю выбрать, над какой изменением работать","Использует AskUserQuestion tool для получения выбора пользователя","Выполняет `openspec list --json` для получения последних изменений"],"ar":["ينشئ التالي artifact لتغيير","يقوم بlisting التغييرات المتاحة باستخدام `openspec list --json`","يمكن للمستخدم اختيار التغيير الذي يريد العمل عليه","يستخدم أداة AskUserQuestion لاستلام اختيار المستخدم","ينفذ `openspec list --json` لاستلام التغييرات الأخيرة"]},"keywords":{"en":["how to use openspec-continue-change","openspec-continue-change setup guide","openspec-continue-change alternative","openspec-continue-change vs other AI skills","openspec-continue-change install","what is openspec-continue-change","openspec-continue-change documentation","openspec-continue-change tutorial","openspec-continue-change for AI agents","openspec-continue-change workflow management"],"zh":["openspec-continue-change","AIエージェント","自动化流程","开发效率","AskUserQuestion","openspec list --json","npm","ruan-cat"],"ja":["openspec-continue-change","AIエージェント","自動化プロセス","開発効率","AskUserQuestion","openspec list --json","npm","ruan-cat"],"ko":["openspec-continue-change","AI 에이전트","자동화 프로세스","개발 효율","AskUserQuestion","openspec list --json","npm","ruan-cat"],"es":["openspec-continue-change","agentes de IA","desarrollo de software","npm","CLI","AskUserQuestion","inferencia de contexto","gestión de cambios"],"fr":["openspec-continue-change","outils d''IA","développement de logiciels","npm","CLI","AskUserQuestion","inférence de contexte","gestion de changements"],"de":["openspec-continue-change","KI-Tools","Softwareentwicklung","npm","CLI","AskUserQuestion","Kontextinferenz","Änderungsverwaltung"],"pt":["openspec-continue-change","npm @ruan-cat/*","ferramenta de linha de comando","alteração","artifact","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["openspec-continue-change","npm @ruan-cat/*","командная утилита","изменение","артефакт","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["openspec-continue-change","npm @ruan-cat/*","أداة سطر أوامر","تغيير","artifact","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"ruan-cat","repo":"monorepo","repoPath":"ruan-cat/monorepo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"openspec-continue-change","description":"Continue working on an OpenSpec change by creating the next artifact. Use when the user wants to progress their change, create the next artifact, or continue their workflow.","version":"1.0","bodyPreview":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-","body":"Continue working on a change by creating the next artifact.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **If no change name provided, prompt for selection**\n\n   Run `openspec list --json` to get available changes sorted by most recently modified. Then use the **AskUserQuestion tool** to let the user select which change to work on.\n\n   Present the top 3-4 most recently modified changes as options, showing:\n   - Change name\n   - Schema (from `schema` field if present, otherwise \"spec-driven\")\n   - Status (e.g., \"0/5 tasks\", \"complete\", \"no tasks\")\n   - How recently it was modified (from `lastModified` field)\n\n   Mark the most recently modified change as \"(Recommended)\" since it''s likely what the user wants to continue.\n\n   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.\n\n2. **Check current status**\n\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n\n   Parse the JSON to understand current state. The response includes:\n   - `schemaName`: The workflow schema being used (e.g., \"spec-driven\")\n   - `artifacts`: Array of artifacts with their status (\"done\", \"ready\", \"blocked\")\n   - `isComplete`: Boolean indicating if all artifacts are complete\n\n3. **Act based on status**:\n\n   ***\n\n   **If all artifacts are complete (`isComplete: true`)**:\n   - Congratulate the user\n   - Show final status including the schema used\n   - Suggest: \"All artifacts created! You can now implement this change or archive it.\"\n   - STOP\n\n   ***\n\n   **If artifacts are ready to create** (status shows artifacts with `status: \"ready\"`):\n   - Pick the FIRST artifact with `status: \"ready\"` from the status output\n   - Get its instructions:\n     ```bash\n     openspec instructions <artifact-id> --change \"<name>\" --json\n     ```\n   - Parse the JSON. The key fields are:\n     - `context`: Project background (constraints for you - do NOT include in output)\n     - `rules`: Artifact-specific rules (constraints for you - do NOT include in output)\n     - `template`: The structure to use for your output file\n     - `instruction`: Schema-specific guidance\n     - `outputPath`: Where to write the artifact\n     - `dependencies`: Completed artifacts to read for context\n   - **Create the artifact file**:\n     - Read any completed dependency files for context\n     - Use `template` as the structure - fill in its sections\n     - Apply `context` and `rules` as constraints when writing - but do NOT copy them into the file\n     - Write to the output path specified in instructions\n   - Show what was created and what''s now unlocked\n   - STOP after creating ONE artifact\n\n   ***\n\n   **If no artifacts are ready (all blocked)**:\n   - This shouldn''t happen with a valid schema\n   - Show status and suggest checking for issues\n\n4. **After creating an artifact, show progress**\n   ```bash\n   openspec status --change \"<name>\"\n   ```\n\n**Output**\n\nAfter each invocation, show:\n\n- Which artifact was created\n- Schema workflow being used\n- Current progress (N/M complete)\n- What artifacts are now unlocked\n- Prompt: \"Want to continue? Just ask me to continue or tell me what to do next.\"\n\n**Artifact Creation Guidelines**\n\nThe artifact types and their purpose depend on the schema. Use the `instruction` field from the instructions output to understand what to create.\n\nCommon artifact patterns:\n\n**spec-driven schema** (proposal → specs → design → tasks):\n\n- **proposal.md**: Ask user about the change if not clear. Fill in Why, What Changes, Capabilities, Impact.\n  - The Capabilities section is critical - each capability listed will need a spec file.\n- **specs/<capability>/spec.md**: Create one spec per capability listed in the proposal''s Capabilities section (use the capability name, not the change name).\n- **design.md**: Document technical decisions, architecture, and implementation approach.\n- **tasks.md**: Break down implementation into checkboxed tasks.\n\nFor other schemas, follow the `instruction` field from the CLI output.\n\n**Guardrails**\n\n- Create ONE artifact per invocation\n- Always read dependency artifacts before creating a new one\n- Never skip artifacts or create out of order\n- If context is unclear, ask the user before creating\n- Verify the artifact file exists after writing before marking progress\n- Use the schema''s artifact sequence, don''t assume specific artifact names\n- **IMPORTANT**: `context` and `rules` are constraints for YOU, not content for the file\n  - Do NOT copy `<context>`, `<rules>`, `<project_context>` blocks into the artifact\n  - These guide what you write, but should never appear in the output\n"},"lastSynced":"2026-03-08T02:02:35.777Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined workflow automation through openspec integration.","zh":"非常适合需要通过openspec集成简化工作流自动化的开发代理","ja":"開発エージェントがopenspec統合を介してワークフローの自動化を簡素化する必要がある場合に最適","ko":"开发 에이전트가 openspec 통합을 통해 워크플로우 자동화를 간소화해야 하는 경우에 적합","es":"Perfecto para Agentes de Desarrollo que necesitan una automatización de flujo de trabajo simplificada a través de la integración de openspec.","fr":"Parfait pour les Agents de Développement ayant besoin d''une automatisation de workflow simplifiée via l''intégration openspec.","de":"Perfekt für Entwicklungsmittel, die eine vereinfachte Workflow-Automatisierung durch openspec-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de automação de fluxo de trabalho otimizada por meio da integração do openspec.","ru":"Идеально для агентов разработки, которым необходима автоматизация рабочего процесса с помощью интеграции openspec.","ar":"مثالي لعميل التطوير الذي يحتاج إلى تسهيل تدفق العمل من خلال التكامل مع openspec."},"recommendation":{"en":"Empowers agents to continue working on changes by creating the next artifact, leveraging openspec list and AskUserQuestion tool for seamless workflow management, and utilizing JSON data for efficient change tracking.","zh":"赋予代理继续处理更改的能力，通过创建下一个构件，利用openspec列表和AskUserQuestion工具进行无缝的工作流管理，并利用JSON数据进行高效的更改跟踪","ja":"エージェントが変更を続けて作業できるようにし、openspecリストとAskUserQuestionツールを使用してシームレスなワークフローマネジメントを行い、JSONデータを使用して効率的な変更追跡を行うことで、次のアーティファクトを作成する","ko":"에이전트가 변경 사항을 계속 작업할 수 있도록 하며, openspec 목록과 AskUserQuestion 도구를 사용하여 무결점의 워크플로우 관리를 수행하고, JSON 데이터를 사용하여 효율적인 변경 추적을 수행함으로써 다음 아티팩트를 생성","es":"Permite a los agentes continuar trabajando en los cambios creando el próximo artifacto, aprovechando la lista openspec y la herramienta AskUserQuestion para una gestión de flujo de trabajo sin problemas, y utilizando datos JSON para un seguimiento eficiente de cambios.","fr":"Permet aux agents de continuer à travailler sur les modifications en créant le prochain artifact, en exploitant la liste openspec et l''outil AskUserQuestion pour une gestion de workflow sans accroc, et en utilisant des données JSON pour un suivi efficace des modifications.","de":"Ermöglicht es den Agenten, weiter an Änderungen zu arbeiten, indem sie das nächste Artifact erstellen, die openspec-Liste und das Tool AskUserQuestion für eine nahtlose Workflow-Verwaltung nutzen und JSON-Daten für eine effiziente Änderungsverfolgung verwenden.","pt":"Permite que os agentes continuem trabalhando nas alterações, criando o próximo artefato, utilizando a lista do openspec e a ferramenta AskUserQuestion para gerenciamento de fluxo de trabalho sem interrupções e utilizando dados JSON para acompanhamento eficiente de alterações.","ru":"Позволяет агентам продолжать работать над изменениями, создавая следующий артефакт, используя список openspec и инструмент AskUserQuestion для бесшовного управления рабочим процессом, и используя данные JSON для эффективного отслеживания изменений.","ar":"يسمح للوكلاء بمواصلة العمل على التعديلات من خلال إنشاء الملف القابل للاستخدام التالي، واستخدام قائمة openspec وأداة AskUserQuestion لإدارة تدفق العمل دون انقطاع، واستخدام بيانات JSON لتتبع التعديلات بكفاءة."},"useCases":{"en":["Automating change management workflows","Generating next artifacts in a development pipeline","Selecting and continuing work on recently modified changes"],"zh":["自动化变更管理工作流","在开发管道中生成下一个构件","选择并继续处理最近修改的更改"],"ja":["変更管理ワークフローの自動化","開発パイプラインで次のアーティファクトを生成する","最近変更された変更を選択し続けて処理する"],"ko":["변경 관리 워크플로우의 자동화","개발 파이프라인에서 다음 아티팩트를 생성","최근 수정된 변경 사항을 선택하여 계속 작업"],"es":["Automatización de flujos de trabajo de gestión de cambios","Generación de los próximos artifactos en una canalización de desarrollo","Selección y continuación del trabajo en los cambios modificados recientemente"],"fr":["Automatisation des flux de travail de gestion de modifications","Génération des prochains artifactes dans une canalisation de développement","Sélection et poursuite du travail sur les modifications récemment modifiées"],"de":["Automatisierung von Änderungsmanagement-Workflows","Erstellung der nächsten Artefakte in einer Entwicklungspipeline","Auswahl und Fortsetzung der Arbeit an kürzlich geänderten Änderungen"],"pt":["Automatizar fluxos de trabalho de gerenciamento de alterações","Gerar os próximos artefatos em um pipeline de desenvolvimento","Selecionar e continuar trabalhando nas alterações modificadas recentemente"],"ru":["Автоматизировать рабочие процессы управления изменениями","Генерировать следующие артефакты в конвейере разработки","Выбирать и продолжать работу над недавно измененными изменениями"],"ar":["تأتمتة سير عمل إدارة التغييرات","генерировать الملفات القابلة للاستخدام التالية في خط أنابيب التطوير","اختيارและมتابعة العمل على التغييرات المعدلة مؤخرًا"]},"limitations":{"en":["Requires openspec installation and configuration","Dependent on conversation context for change name inference","Limited to top 3 changes for user selection prompt"],"zh":["需要openspec的安装和配置","依赖于对话上下文进行更改名称推理","用户选择提示仅限于前3个更改"],"ja":["openspecのインストールと構成が必要","変更名の推論に会話のコンテキストに依存","ユーザー選択プロンプトはトップ3の変更に限定"],"ko":["openspec의 설치 및 구성이 필요","변경 이름 추론에 대화 문맥에 의존","사용자 선택 프롬프트는 상위 3개의 변경 사항으로 제한"],"es":["Requiere instalación y configuración de openspec","Dependiente del contexto de conversación para la inferencia del nombre de cambio","Limitado a los 3 cambios superiores para la selección del usuario"],"fr":["Nécessite l''installation et la configuration d''openspec","Dépend du contexte de conversation pour l''inférence du nom de modification","Limité aux 3 modifications les plus récentes pour la invite de sélection de l''utilisateur"],"de":["Benötigt die Installation und Konfiguration von openspec","Abhängig vom Konversationskontext für die Ableitung des Änderungsnamens","Begrenzt auf die 3 besten Änderungen für die Benutzerauswahl"],"pt":["Exige instalação e configuração do openspec","Depende do contexto da conversa para inferência do nome da alteração","Limitado aos 3 principais alterações para prompt de seleção de usuário"],"ru":["Требует установки и конфигурации openspec","Зависит от контекста разговора для вывода имени изменения","Ограничен до 3 лучших изменений для приглашения выбора пользователя"],"ar":["يتطلب تثبيت وت 구성 openspec","يعتمد على سياق المحادثة لاستنتاج اسم التغيير","محدود بالتغييرات الثلاث الأولى لتحفيز اختيار المستخدم"]},"version":4},"contentHash":"d0fbc067936de6bea93e611b962d6fa0fd58bcd47b1fe8ee529fa0c97c1afd9d","qualityScore":50}');
