INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ruan-cat/monorepo/openspec-continue-change', 'openspec-continue-change', 'ruan-cat', 'monorepo', 'community', 'openspec-continue-change ruan-cat monorepo community openspec-continue-change is a skill that allows AI agents to continue working on changes by creating the next artifact. It benefits developers by streamlining their workflow. openspec-continue-change 是一个用于继续更改的 AIエージェント，通过创建下一个工件来实现自动化流程 openspec-continue-change は変更を続けるための AIエージェントであり、次のアーティファクトを作成することで自動化プロセスを実現します openspec-continue-change 는 변경을 계속하기 위한 AI 에이전트로 다음 아티팩트를 생성하여 자동화 프로세스를 구현합니다 openspec-continue-change es una herramienta que permite continuar trabajando en un cambio mediante la creación del próximo artifact. Utiliza npm y CLI para gestionar los cambios. openspec-continue-change est un outil qui permet de continuer à travailler sur un changement en créant le prochain artifact. Il utilise npm et CLI pour gérer les changements. openspec-continue-change ist ein Tool, das es ermöglicht, an einem Change weiterzuarbeiten, indem das nächste Artifact erstellt wird. Es verwendet npm und CLI, um die Änderungen zu verwalten. O openspec-continue-change é uma ferramenta que permite criar o próximo artifact de alteração usando o npm @ruan-cat/*. Ele lista as alterações disponíveis e permite ao usuário selecionar qual alteração trabalhar. openspec-continue-change - это инструмент, который позволяет создать следующий артефакт изменений, используя npm @ruan-cat/*. Он список доступных изменений и позволяет пользователю выбрать, над какой изменением работать. openspec-continue-change هو أداة تمكن من إنشاء التالي artifact لتغيير باستخدام npm @ruan-cat/*. يقوم بlisting التغييرات المتاحة ويمكن للمستخدم اختيار التغيير الذي يريد العمل عليه. how to use openspec-continue-change openspec-continue-change setup guide openspec-continue-change alternative openspec-continue-change vs other AI skills openspec-continue-change install what is openspec-continue-change openspec-continue-change documentation openspec-continue-change tutorial openspec-continue-change for AI agents openspec-continue-change workflow management openspec-continue-change AIエージェント 自动化流程 开发效率 AskUserQuestion openspec list --json npm ruan-cat Runs `openspec list --json` to get available changes sorted by most recently modified Uses the AskUserQuestion tool to let users select which change to work on Presents the top 3-5 available changes for user selection Creates the next artifact based on user input or conversation context Infers change name from conversation context if not explicitly provided Prompts for selection if change name is vague or ambiguous openspec-continue-change is a skill that enables AI agents to continue working on changes by creating the next artifact, using commands like `openspec list --json`.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SpillwaveSolutions/agent_rulez/architect-agent', 'community', 'SpillwaveSolutions', 'agent_rulez', 'SpillwaveSolutions/agent_rulez', 'architect-agent', 0, 0, 50, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:38.780Z', '3cb2e039d77927a4d2b0d7b8ea4d6ada58f099db0139ba368748909d0dae7e1f', '{"id":"SpillwaveSolutions/agent_rulez/architect-agent","name":"architect-agent","description":{"en":"Architect-Agent coordinates planning, delegation, and evaluation across architect and code agent workspaces, benefiting developers and architects. It streamlines workflow with features like intent classification and decision trees.","zh":"Architect Agent 是一种代码协作工具，能够自动化代码管理和工作流","ja":"Architect Agent は、AIエージェントによるコード管理を自動化するツールです","ko":"Architect Agent는 자동화된 코드 에이전트 워크플로를 제공하는 도구입니다","es":"El agente de arquitectura es una habilidad que coordina la planificación, delegación y evaluación en el espacio de trabajo de código","fr":"L''agent d''architecture est une compétence qui coordonne la planification, la délégation et l''évaluation dans l''espace de travail de code","de":"Der Architekturagent ist eine Fähigkeit, die die Planung, Delegation und Bewertung im Code-Arbeitsbereich koordiniert","pt":"O Architect-Agent é um skill que coordena planejamento, delegação e avaliação entre os ambientes de trabalho do arquiteto e do agente de código","ru":"Архитектор-агент - это навык, который координирует планирование, делегирование и оценку между рабочими пространствами архитектора и кодировочного агента","ar":"وكيل المعماري هو مهارة تنسق التخطيط والتفويض والتقييم بين بيئات العمل المعمارية ووكيل الكود"},"seo":{"title":{"en":"Architect-Agent: Setup Guide for AI Agents","zh":"Architect Agent 设置指南：自动化代码协作","ja":"Architect Agent のベストプラクティス：AIエージェントによるコード管理","ko":"Architect Agent 사용 가이드: 자동화된 코드 에이전트 워크플로","es":"Guía de configuración de Archi