INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SpillwaveSolutions/agent_rulez/architect-agent', 'architect-agent', 'SpillwaveSolutions', 'agent_rulez', 'community', 'architect-agent SpillwaveSolutions agent_rulez community Architect-Agent coordinates planning, delegation, and evaluation across architect and code agent workspaces, benefiting developers and architects. It streamlines workflow with features like intent classification and decision trees. Architect Agent 是一种代码协作工具，能够自动化代码管理和工作流 Architect Agent は、AIエージェントによるコード管理を自動化するツールです Architect Agent는 자동화된 코드 에이전트 워크플로를 제공하는 도구입니다 El agente de arquitectura es una habilidad que coordina la planificación, delegación y evaluación en el espacio de trabajo de código L''agent d''architecture est une compétence qui coordonne la planification, la délégation et l''évaluation dans l''espace de travail de code Der Architekturagent ist eine Fähigkeit, die die Planung, Delegation und Bewertung im Code-Arbeitsbereich koordiniert O Architect-Agent é um skill que coordena planejamento, delegação e avaliação entre os ambientes de trabalho do arquiteto e do agente de código Архитектор-агент - это навык, который координирует планирование, делегирование и оценку между рабочими пространствами архитектора и кодировочного агента وكيل المعماري هو مهارة تنسق التخطيط والتفويض والتقييم بين بيئات العمل المعمارية ووكيل الكود how to use architect-agent architect-agent setup guide architect-agent alternative architect-agent vs competitor architect-agent install what is architect-agent architect-agent workflow management intent classification in architect-agent decision trees in architect-agent Architect Agent 代码协作工具 AI代码管理 自动化代码管理 代码工作流 Intent Classification Decision Tree Resource Loading Policy Coordinates planning, delegation, and evaluation across architect and code agent workspaces Supports quick start commands like ''write instructions for code agent'' and ''initialize workspace'' Utilizes intent classification for efficient workflow management Employs decision trees for automated evaluation and grading Allows for resource loading policy customization Follows critical protocol for secure and reliable workflow setup Architect-agent is a workflow skill that coordinates planning, delegation, and evaluation across architect and code agent workspaces, utilizing technologies like intent classification and decision trees.');
