INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IsKenKenYa/Open1PanelApp/ui-visual-validator', 'ui-visual-validator', 'IsKenKenYa', 'Open1PanelApp', 'community', 'ui-visual-validator IsKenKenYa Open1PanelApp community The ui-visual-validator skill provides guidance and best practices for ui visual validator tasks, helping developers work efficiently with the 1Panel Open API. UI视觉验证器技能是一种基于1Panel Open API的移动应用，用于验证UI视觉效果 UIビジュアルバリデータースキルは、1Panel Open APIを基盤とするモバイルアプリで、UIの視覚効果を検証する UI 시각적 검증기 스킬은 1Panel Open API를 기반으로 하는 모바일 앱으로 UI 시각적 효과를 검증합니다 ui-visual-validator es una herramienta de validación visual para aplicaciones móviles basada en la API de 1Panel ui-visual-validator est un outil de validation visuelle pour les applications mobiles basé sur l''API de 1Panel ui-visual-validator ist ein Tool für die visuelle Validierung von mobilen Anwendungen basierend auf der 1Panel-API O ui-visual-validator é uma ferramenta baseada na 1Panel Open API para validar interfaces de usuário em aplicações móveis ui-visual-validator - это инструмент, основанный на 1Panel Open API, для валидации пользовательских интерфейсов в мобильных приложениях, разработанный для ИИ Агентов ui-visual-validator هو أداة قائمة على 1Panel Open API لتحقق من صحة واجهات المستخدم في التطبيقات المتنقلة، مصممة لأدوات الذكاء الاصطناعي how to use ui-visual-validator ui-visual-validator setup guide ui-visual-validator alternative ui-visual-validator vs other validators what is ui-visual-validator ui-visual-validator install ui-visual-validator for mobile app development 1Panel Open API integration ui visual validation best practices UI视觉验证器 1Panel Open API 移动应用开发 UI视觉效果验证 最佳实践 AIエージェント Applies relevant best practices for ui visual validator tasks Validates outcomes and provides actionable steps Clarifies goals, constraints, and required inputs for workflows Supports detailed examples and verification for complex tasks Utilizes the 1Panel Open API for seamless integration ui-visual-validator is a mobile app-based skill that utilizes the 1Panel Open API for ui visual validation tasks and workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gursheyss/styx/turborepo', 'community', 'gursheyss', 'styx', 'gursheyss/styx', 'turborepo', 0, 0, 50, '2026-03-08T01:57:15.329Z', '2026-03-08T02:03:10.270Z', '4282dd2f1ec1b912660be61f38858ff05053e94903af9771a5361058c47bb9c4', '{"id":"gursheyss/styx/turborepo","name":"turborepo","description":{"en":"Turborepo is a build system for JavaScript and TypeScript monorepos, caching task outputs and running tasks in parallel based on dependency graphs. It benefits developers working on large-scale projects.","zh":"Turborepo 是一个用于 JavaScript/TypeScript monorepo 的构建系统，通过缓存任务输出和并行运行任务来提高性能","ja":"Turborepo は JavaScript/TypeScript モノレポ用のビルドシステムで、タスクの出力をキャッシュし、依存関係に基づいてタスクを並列実行することでパフォーマンスを向上させる","ko":"Turborepo는 JavaScript/TypeScript 모노레포를 위한 빌드 시스템으로, 태스크 출력을 캐싱하고 의존성 그래프를 기반으로 태스크를 병렬적으로 실행하여 성능을 향상시킵니다","es":"Turborepo es un sistema de compilación para monorepos JavaScript/TypeScript que almacena en caché las salidas de las tareas y ejecuta tareas en paralelo según el grafo de dependencias.","fr":"Turborepo est un système de construction pour les monorepos JavaScript/TypeScript qui met en cache les sorties des tâches et exécute les tâches en parallèle en fonction du graphe de dépendances.","de":"Turborepo ist ein Build-System für JavaScript/TypeScript-Monorepos, das Task-Ausgaben zwischenspeichert und Tasks parallel basierend auf der Abhängigkeitsgrafik ausführt.","pt":"Turborepo é um sistema de compilação para monorepos JavaScript e TypeScript que melhora a eficiência do desenvolvimento","ru":"Turborepo — это система сборки для монорепозиториев JavaScript и TypeScript, повышающая эффективность разработки","ar":"Turborepo هو نظام بناء لمونوريبو جافاسكريبت و타입스크립트 الذي يحسن كفاءة التطوير"},"seo":{"title":{"en":"Turborepo: Build System for JavaScript/TypeScript Monorep...","zh":"Turborepo_SETUP_GUIDE：JavaScript/TypeScript monorepo 优化","ja":"Turborepo ベストプラクティス：JavaScript/TypeScript モノレポ高速化","ko":"Turborepo 설정 가이드: JavaScript/TypeScript 모노레포 최적화","es":"Guía de configuración de Turborepo para monorepos JavaScr...","fr":"Guide d''installation de Turborepo pour les monorepos Java...","de":"Einrichtungsleitfaden für Turborepo in JavaScript/TypeScr...","pt":"Guia de Configuração Turborepo: Otimização de Monorepos J...","ru":"ИИ Агенты: Turborepo Настройка для Монорепозиториев JavaS...","ar":"إعداد Turborepo: دليل لتحسين مونوريبو جافاسكريبت"},"description":{"en":"Unlock efficient monorepo management with Turborepo. Learn how to cache task outputs, run tasks in parallel, and optimize your workflow. Get started now!","zh":"了解 Turborepo 的工作原理，并掌握如何为 JavaScript/TypeScript 项目优化 monorepo 性能","ja":"Turborepo のしくみを理解し、JavaScript/TypeScript プロジェクトの monorepo パフォーマンスを最適化する","ko":"Turborepo의 동작 원리를 배우고 JavaScript/TypeScript 프로젝트의 모노레포 성능을 최적화하는 방법","es":"Aprende a configurar Turborepo para acelerar el desarrollo de monorepos JavaScript/TypeScript con caché de tareas y ejecución paralela","fr":"Découvrez comment configurer Turborepo pour accélérer le développement de monorepos JavaScript/TypeScript avec mise en cache des tâches et exécution parallèle","de":"Erfahren Sie, wie Sie Turborepo für die Beschleunigung der Entwicklung von JavaScript/TypeScript-Monorepos mit Aufgabencache und paralleler Ausführung einric...","pt":"Aprenda a configurar o Turborepo para otimizar seus monorepos JavaScript e TypeScript, melhorando a eficiência do desenvolvimento","ru":"Узнайте, как настроить Turborepo для оптимизации ваших монорепозиториев JavaScript и TypeScript, повышая эффективность разработки","ar":"تعلم كيفية تعيين Turborepo لتحسين مونوريبو جافاسكريبت و타입스크립트، وتحسين كفاءة التطوير"},"definition":{"en":"Turborepo is a build system for JavaScript and TypeScript monorepos that caches task outputs and runs tasks in parallel based on dependency graphs.","zh":"Turborepo 是一个用于优化 JavaScript/TypeScript 项目 monorepo 性能的构建系统","ja":"Turborepo は JavaScript/TypeScript プロジェクトの monorepo パフォーマンスを最適化するビルドシステム","ko":"Turborepo는 JavaScript/TypeScript 프로젝트의 모노레포 성능을 최적화하는 빌드 시스템","es":"Turborepo es un sistema de compilación que almacena en caché las salidas de las tareas y ejecuta tareas en paralelo","fr":"Turborepo est un système de construction qui met en cache les sorties des tâches et exécute les tâches en parallèle","de":"Turborepo ist ein Build-System, das Task-Ausgaben zwischenspeichert und Tasks parallel ausführt","pt":"Turborepo é um sistema de compilação que caches as saídas das tarefas e executa tarefas em paralelo com base no grafo de dependência","ru":"Turborepo — это система сборки, которая кэширует вывод задач и выполняет задачи параллельно на основе графа зависимостей","ar":"Turborepo هو نظام بناء يقوم بتخزين مؤقت للخروج من المهام وتنفيذ المهام بالتوازي بناءً على مخطط الاعتماد"},"features":{"en":["Caches task outputs to improve build performance","Runs tasks in parallel based on dependency graphs","Requires package tasks to be registered in root turbo.json","Supports task delegation via ''turbo run <task>'' in root package.json","Enforces package tasks over root tasks for efficient builds"],"zh":["缓存任务输出以减少重复计算","并行运行任务以提高构建速度","基于依存关系图的任务调度","支持 JavaScript/TypeScript 项目","通过 turbo.json 配置任务"],"ja":["タスクの出力をキャッシュして冗長な計算を減らす","タスクを並列実行してビルド速度を向上させる","依存関係グラフに基づいたタスクのスケジューリング","JavaScript/TypeScript プロジェクトをサポート","turbo.json でタスクを設定"],"ko":["태스크 출력을 캐싱하여 중복 계산을 줄임","태스크를 병렬적으로 실행하여 빌드 속도를 향상","의존성 그래프를 기반으로 태스크를 스케줄링","JavaScript/TypeScript 프로젝트 지원","turbo.json을 통해 태스크 설정"],"es":["Almacenamiento en caché de las salidas de las tareas","Ejecución paralela de tareas según el grafo de dependencias","Compatibilidad con monorepos JavaScript/TypeScript","Configuración a través de archivos `package.json` y `turbo.json`","Ejecución de tareas mediante el comando `turbo run`"],"fr":["Mise en cache des sorties des tâches","Exécution parallèle des tâches en fonction du graphe de dépendances","Compatibilité avec les monorepos JavaScript/TypeScript","Configuration via les fichiers `package.json` et `turbo.json`","Exécution des tâches via la commande `turbo run`"],"de":["Zwischenspeicherung von Task-Ausgaben","Parallele Ausführung von Tasks basierend auf der Abhängigkeitsgrafik","Kompatibilität mit JavaScript/TypeScript-Monorepos","Konfiguration über Dateien `package.json` und `turbo.json`","Ausführung von Tasks mittels Befehl `turbo run`"],"pt":["Cache de saídas de tarefas","Execução de tarefas em paralelo","Grafo de dependência para otimização","Integração com package.json","Suporte a monorepos JavaScript e TypeScript"],"ru":["Кэширование вывода задач","Параллельное выполнение задач","Граф зависимостей для оптимизации","Интеграция с package.json","Поддержка монорепозиториев JavaScript и TypeScript"],"ar":["مخزن مؤقت للخروج من المهام","تنفيذ المهام بالتوازي","مخطط الاعتماد لتحسين الأداء","التكامل مع package.json","دعم مونوريبو جافاسكريبت و타입스크립트"]},"keywords":{"en":["how to use turborepo","turborepo vs lerna","turborepo install","turborepo setup guide","what is turborepo","turborepo alternative","turborepo tutorial","turborepo monorepo management","turborepo dependency graph"],"zh":["Turborepo","JavaScript monorepo","TypeScript monorepo","构建系统","性能优化","缓存任务输出","并行运行任务"],"ja":["Turborepo","JavaScript モノレポ","TypeScript モノレポ","ビルドシステム","パフォーマンス最適化","タスクの出力をキャッシュ","タスクを並列実行"],"ko":["Turborepo","JavaScript 모노레포","TypeScript 모노레포","빌드 시스템","성능 최적화","태스크 출력 캐싱","태스크 병렬 실행"],"es":["turborepo","monorepos javascript","monorepos typescript","sistema de compilación","caché de tareas","ejecución paralela","grafo de dependencias","package.json","turbo.json"],"fr":["turborepo","monorepos javascript","monorepos typescript","système de construction","mise en cache des tâches","exécution parallèle","graphe de dépendances","package.json","turbo.json"],"de":["turborepo","javascript-monorepos","typescript-monorepos","build-system","task-cache","parallele ausführung","abhängigkeitsgrafik","package.json","turbo.json"],"pt":["turborepo","monorepo","javascript","typescript","sistema de compilação","otimização de desenvolvimento","cache de saídas de tarefas","execução de tarefas em paralelo"],"ru":["turborepo","монорепозиторий","javascript","typescript","система сборки","оптимизация разработки","кэширование вывода задач","параллельное выполнение задач"],"ar":["turborepo","مونوريبو","جافاسكريبت","타입스크립트","نظام بناء","تحسين التطوير","مخزن مؤقت للخروج من المهام","تنفيذ المهام بالتوازي"]}},"owner":"gursheyss","repo":"styx","repoPath":"gursheyss/styx","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.329Z","topics":[],"category":"community","skillMd":{"name":"turborepo","description":"|","version":"2.8.3-canary.11","bodyPreview":"# Turborepo Skill\n\nBuild system for JavaScript/TypeScript monorepos. Turborepo caches task outputs and runs tasks in parallel based on dependency graph.\n\n## IMPORTANT: Package Tasks, Not Root Tasks\n\n**DO NOT create Root Tasks. ALWAYS create package tasks.**\n\nWhen creating tasks/scripts/pipelines, you MUST:\n\n1. Add the script to each relevant package''s `package.json`\n2. Register the task in root `turbo.json`\n3. Root `package.json` only delegates via `turbo run <task>`\n\n**DO NOT** put task logic i","body":"# Turborepo Skill\n\nBuild system for JavaScript/TypeScript monorepos. Turborepo caches task outputs and runs tasks in parallel based on dependency graph.\n\n## IMPORTANT: Package Tasks, Not Root Tasks\n\n**DO NOT create Root Tasks. ALWAYS create package tasks.**\n\nWhen creating tasks/scripts/pipelines, you MUST:\n\n1. Add the script to each relevant package''s `package.json`\n2. Register the task in root `turbo.json`\n3. Root `package.json` only delegates via `turbo run <task>`\n\n**DO NOT** put task logic in root `package.json`. This defeats Turborepo''s parallelization.\n\n```json\n// DO THIS: Scripts in each package\n// apps/web/package.json\n{ \"scripts\": { \"build\": \"next build\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n\n// apps/api/package.json\n{ \"scripts\": { \"build\": \"tsc\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n\n// packages/ui/package.json\n{ \"scripts\": { \"build\": \"tsc\", \"lint\": \"eslint .\", \"test\": \"vitest\" } }\n```\n\n```json\n// turbo.json - register tasks\n{\n  \"tasks\": {\n    \"build\": { \"dependsOn\": [\"^build\"], \"outputs\": [\"dist/**\"] },\n    \"lint\": {},\n    \"test\": { \"dependsOn\": [\"build\"] }\n  }\n}\n```\n\n```json\n// Root package.json - ONLY delegates, no task logic\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"lint\": \"turbo run lint\",\n    \"test\": \"turbo run test\"\n  }\n}\n```\n\n```json\n// DO NOT DO THIS - defeats parallelization\n// Root package.json\n{\n  \"scripts\": {\n    \"build\": \"cd apps/web && next build && cd ../api && tsc\",\n    \"lint\": \"eslint apps/ packages/\",\n    \"test\": \"vitest\"\n  }\n}\n```\n\nRoot Tasks (`//#taskname`) are ONLY for tasks that truly cannot exist in packages (rare).\n\n## Secondary Rule: `turbo run` vs `turbo`\n\n**Always use `turbo run` when the command is written into code:**\n\n```json\n// package.json - ALWAYS \"turbo run\"\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\"\n  }\n}\n```\n\n```yaml\n# CI workflows - ALWAYS \"turbo run\"\n- run: turbo run build --affected\n```\n\n**The shorthand `turbo <tasks>` is ONLY for one-off terminal commands** typed directly by humans or agents. Never write `turbo build` into package.json, CI, or scripts.\n\n## Quick Decision Trees\n\n### \"I need to configure a task\"\n\n```\nConfigure a task?\n├─ Define task dependencies → references/configuration/tasks.md\n├─ Lint/check-types (parallel + caching) → Use Transit Nodes pattern (see below)\n├─ Specify build outputs → references/configuration/tasks.md#outputs\n├─ Handle environment variables → references/environment/RULE.md\n├─ Set up dev/watch tasks → references/configuration/tasks.md#persistent\n├─ Package-specific config → references/configuration/RULE.md#package-configurations\n└─ Global settings (cacheDir, daemon) → references/configuration/global-options.md\n```\n\n### \"My cache isn''t working\"\n\n```\nCache problems?\n├─ Tasks run but outputs not restored → Missing `outputs` key\n├─ Cache misses unexpectedly → references/caching/gotchas.md\n├─ Need to debug hash inputs → Use --summarize or --dry\n├─ Want to skip cache entirely → Use --force or cache: false\n├─ Remote cache not working → references/caching/remote-cache.md\n└─ Environment causing misses → references/environment/gotchas.md\n```\n\n### \"I want to run only changed packages\"\n\n```\nRun only what changed?\n├─ Changed packages + dependents (RECOMMENDED) → turbo run build --affected\n├─ Custom base branch → --affected --affected-base=origin/develop\n├─ Manual git comparison → --filter=...[origin/main]\n└─ See all filter options → references/filtering/RULE.md\n```\n\n**`--affected` is the primary way to run only changed packages.** It automatically compares against the default branch and includes dependents.\n\n### \"I want to filter packages\"\n\n```\nFilter packages?\n├─ Only changed packages → --affected (see above)\n├─ By package name → --filter=web\n├─ By directory → --filter=./apps/*\n├─ Package + dependencies → --filter=web...\n├─ Package + dependents → --filter=...web\n└─ Complex combinations → references/filtering/patterns.md\n```\n\n### \"Environment variables aren''t working\"\n\n```\nEnvironment issues?\n├─ Vars not available at runtime → Strict mode filtering (default)\n├─ Cache hits with wrong env → Var not in `env` key\n├─ .env changes not causing rebuilds → .env not in `inputs`\n├─ CI variables missing → references/environment/gotchas.md\n└─ Framework vars (NEXT_PUBLIC_*) → Auto-included via inference\n```\n\n### \"I need to set up CI\"\n\n```\nCI setup?\n├─ GitHub Actions → references/ci/github-actions.md\n├─ Vercel deployment → references/ci/vercel.md\n├─ Remote cache in CI → references/caching/remote-cache.md\n├─ Only build changed packages → --affected flag\n├─ Skip unnecessary builds → turbo-ignore (references/cli/commands.md)\n└─ Skip container setup when no changes → turbo-ignore\n```\n\n### \"I want to watch for changes during development\"\n\n```\nWatch mode?\n├─ Re-run tasks on change → turbo watch (references/watch/RULE.md)\n├─ Dev servers with dependencies → Use `with` key (references/configuration/tasks.md#with)\n├─ Restart dev server on dep change → Use `interruptible: true`\n└─ Persistent dev tasks → Use `persistent: true`\n```\n\n### \"I need to create/structure a package\"\n\n```\nPackage creation/structure?\n├─ Create an internal package → references/best-practices/packages.md\n├─ Repository structure → references/best-practices/structure.md\n├─ Dependency management → references/best-practices/dependencies.md\n├─ Best practices overview → references/best-practices/RULE.md\n├─ JIT vs Compiled packages → references/best-practices/packages.md#compilation-strategies\n└─ Sharing code between apps → references/best-practices/RULE.md#package-types\n```\n\n### \"How should I structure my monorepo?\"\n\n```\nMonorepo structure?\n├─ Standard layout (apps/, packages/) → references/best-practices/RULE.md\n├─ Package types (apps vs libraries) → references/best-practices/RULE.md#package-types\n├─ Creating internal packages → references/best-practices/packages.md\n├─ TypeScript configuration → references/best-practices/structure.md#typescript-configuration\n├─ ESLint configuration → references/best-practices/structure.md#eslint-configuration\n├─ Dependency management → references/best-practices/dependencies.md\n└─ Enforce package boundaries → references/boundaries/RULE.md\n```\n\n### \"I want to enforce architectural boundaries\"\n\n```\nEnforce boundaries?\n├─ Check for violations → turbo boundaries\n├─ Tag packages → references/boundaries/RULE.md#tags\n├─ Restrict which packages can import others → references/boundaries/RULE.md#rule-types\n└─ Prevent cross-package file imports → references/boundaries/RULE.md\n```\n\n## Critical Anti-Patterns\n\n### Using `turbo` Shorthand in Code\n\n**`turbo run` is recommended in package.json scripts and CI pipelines.** The shorthand `turbo <task>` is intended for interactive terminal use.\n\n```json\n// WRONG - using shorthand in package.json\n{\n  \"scripts\": {\n    \"build\": \"turbo build\",\n    \"dev\": \"turbo dev\"\n  }\n}\n\n// CORRECT\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"dev\": \"turbo run dev\"\n  }\n}\n```\n\n```yaml\n# WRONG - using shorthand in CI\n- run: turbo build --affected\n\n# CORRECT\n- run: turbo run build --affected\n```\n\n### Root Scripts Bypassing Turbo\n\nRoot `package.json` scripts MUST delegate to `turbo run`, not run tasks directly.\n\n```json\n// WRONG - bypasses turbo entirely\n{\n  \"scripts\": {\n    \"build\": \"bun build\",\n    \"dev\": \"bun dev\"\n  }\n}\n\n// CORRECT - delegates to turbo\n{\n  \"scripts\": {\n    \"build\": \"turbo run build\",\n    \"dev\": \"turbo run dev\"\n  }\n}\n```\n\n### Using `&&` to Chain Turbo Tasks\n\nDon''t chain turbo tasks with `&&`. Let turbo orchestrate.\n\n```json\n// WRONG - turbo task not using turbo run\n{\n  \"scripts\": {\n    \"changeset:publish\": \"bun build && changeset publish\"\n  }\n}\n\n// CORRECT\n{\n  \"scripts\": {\n    \"changeset:publish\": \"turbo run build && changeset publish\"\n  }\n}\n```\n\n### `prebuild` Scripts That Manually Build Dependencies\n\nScripts like `prebuild` that manually build other packages bypass Turborepo''s dependency graph.\n\n```json\n// WRONG - manually building dependencies\n{\n  \"scripts\": {\n    \"prebuild\": \"cd ../../packages/types && bun run build && cd ../utils && bun run build\",\n    \"build\": \"next build\"\n  }\n}\n```\n\n**However, the fix depends on whether workspace dependencies are declared:**\n\n1. **If dependencies ARE declared** (e.g., `\"@repo/types\": \"workspace:*\"` in package.json), remove the `prebuild` script. Turbo''s `dependsOn: [\"^build\"]` handles this automatically.\n\n2. **If dependencies are NOT declared**, the `prebuild` exists because `^build` won''t trigger without a dependency relationship. The fix is to:\n   - Add the dependency to package.json: `\"@repo/types\": \"workspace:*\"`\n   - Then remove the `prebuild` script\n\n```json\n// CORRECT - declare dependency, let turbo handle build order\n// package.json\n{\n  \"dependencies\": {\n    \"@repo/types\": \"workspace:*\",\n    \"@repo/utils\": \"workspace:*\"\n  },\n  \"scripts\": {\n    \"build\": \"next build\"\n  }\n}\n\n// turbo.json\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    }\n  }\n}\n```\n\n**Key insight:** `^build` only runs build in packages listed as dependencies. No dependency declaration = no automatic build ordering.\n\n### Overly Broad `globalDependencies`\n\n`globalDependencies` affects ALL tasks in ALL packages. Be specific.\n\n```json\n// WRONG - heavy hammer, affects all hashes\n{\n  \"globalDependencies\": [\"**/.env.*local\"]\n}\n\n// BETTER - move to task-level inputs\n{\n  \"globalDependencies\": [\".env\"],\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"],\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n```\n\n### Repetitive Task Configuration\n\nLook for repeated configuration across tasks that can be collapsed. Turborepo supports shared configuration patterns.\n\n```json\n// WRONG - repetitive env and inputs across tasks\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"]\n    },\n    \"test\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"]\n    },\n    \"dev\": {\n      \"env\": [\"API_URL\", \"DATABASE_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env*\"],\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n\n// BETTER - use globalEnv and globalDependencies for shared config\n{\n  \"globalEnv\": [\"API_URL\", \"DATABASE_URL\"],\n  \"globalDependencies\": [\".env*\"],\n  \"tasks\": {\n    \"build\": {},\n    \"test\": {},\n    \"dev\": {\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\n**When to use global vs task-level:**\n\n- `globalEnv` / `globalDependencies` - affects ALL tasks, use for truly shared config\n- Task-level `env` / `inputs` - use when only specific tasks need it\n\n### NOT an Anti-Pattern: Large `env` Arrays\n\nA large `env` array (even 50+ variables) is **not** a problem. It usually means the user was thorough about declaring their build''s environment dependencies. Do not flag this as an issue.\n\n### Using `--parallel` Flag\n\nThe `--parallel` flag bypasses Turborepo''s dependency graph. If tasks need parallel execution, configure `dependsOn` correctly instead.\n\n```bash\n# WRONG - bypasses dependency graph\nturbo run lint --parallel\n\n# CORRECT - configure tasks to allow parallel execution\n# In turbo.json, set dependsOn appropriately (or use transit nodes)\nturbo run lint\n```\n\n### Package-Specific Task Overrides in Root turbo.json\n\nWhen multiple packages need different task configurations, use **Package Configurations** (`turbo.json` in each package) instead of cluttering root `turbo.json` with `package#task` overrides.\n\n```json\n// WRONG - root turbo.json with many package-specific overrides\n{\n  \"tasks\": {\n    \"test\": { \"dependsOn\": [\"build\"] },\n    \"@repo/web#test\": { \"outputs\": [\"coverage/**\"] },\n    \"@repo/api#test\": { \"outputs\": [\"coverage/**\"] },\n    \"@repo/utils#test\": { \"outputs\": [] },\n    \"@repo/cli#test\": { \"outputs\": [] },\n    \"@repo/core#test\": { \"outputs\": [] }\n  }\n}\n\n// CORRECT - use Package Configurations\n// Root turbo.json - base config only\n{\n  \"tasks\": {\n    \"test\": { \"dependsOn\": [\"build\"] }\n  }\n}\n\n// packages/web/turbo.json - package-specific override\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"test\": { \"outputs\": [\"coverage/**\"] }\n  }\n}\n\n// packages/api/turbo.json\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"test\": { \"outputs\": [\"coverage/**\"] }\n  }\n}\n```\n\n**Benefits of Package Configurations:**\n\n- Keeps configuration close to the code it affects\n- Root turbo.json stays clean and focused on base patterns\n- Easier to understand what''s special about each package\n- Works with `$TURBO_EXTENDS$` to inherit + extend arrays\n\n**When to use `package#task` in root:**\n\n- Single package needs a unique dependency (e.g., `\"deploy\": { \"dependsOn\": [\"web#build\"] }`)\n- Temporary override while migrating\n\nSee `references/configuration/RULE.md#package-configurations` for full details.\n\n### Using `../` to Traverse Out of Package in `inputs`\n\nDon''t use relative paths like `../` to reference files outside the package. Use `$TURBO_ROOT$` instead.\n\n```json\n// WRONG - traversing out of package\n{\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \"../shared-config.json\"]\n    }\n  }\n}\n\n// CORRECT - use $TURBO_ROOT$ for repo root\n{\n  \"tasks\": {\n    \"build\": {\n      \"inputs\": [\"$TURBO_DEFAULT$\", \"$TURBO_ROOT$/shared-config.json\"]\n    }\n  }\n}\n```\n\n### Missing `outputs` for File-Producing Tasks\n\n**Before flagging missing `outputs`, check what the task actually produces:**\n\n1. Read the package''s script (e.g., `\"build\": \"tsc\"`, `\"test\": \"vitest\"`)\n2. Determine if it writes files to disk or only outputs to stdout\n3. Only flag if the task produces files that should be cached\n\n```json\n// WRONG: build produces files but they''re not cached\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    }\n  }\n}\n\n// CORRECT: build outputs are cached\n{\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n```\n\nCommon outputs by framework:\n\n- Next.js: `[\".next/**\", \"!.next/cache/**\"]`\n- Vite/Rollup: `[\"dist/**\"]`\n- tsc: `[\"dist/**\"]` or custom `outDir`\n\n**TypeScript `--noEmit` can still produce cache files:**\n\nWhen `incremental: true` in tsconfig.json, `tsc --noEmit` writes `.tsbuildinfo` files even without emitting JS. Check the tsconfig before assuming no outputs:\n\n```json\n// If tsconfig has incremental: true, tsc --noEmit produces cache files\n{\n  \"tasks\": {\n    \"typecheck\": {\n      \"outputs\": [\"node_modules/.cache/tsbuildinfo.json\"] // or wherever tsBuildInfoFile points\n    }\n  }\n}\n```\n\nTo determine correct outputs for TypeScript tasks:\n\n1. Check if `incremental` or `composite` is enabled in tsconfig\n2. Check `tsBuildInfoFile` for custom cache location (default: alongside `outDir` or in project root)\n3. If no incremental mode, `tsc --noEmit` produces no files\n\n### `^build` vs `build` Confusion\n\n```json\n{\n  \"tasks\": {\n    // ^build = run build in DEPENDENCIES first (other packages this one imports)\n    \"build\": {\n      \"dependsOn\": [\"^build\"]\n    },\n    // build (no ^) = run build in SAME PACKAGE first\n    \"test\": {\n      \"dependsOn\": [\"build\"]\n    },\n    // pkg#task = specific package''s task\n    \"deploy\": {\n      \"dependsOn\": [\"web#build\"]\n    }\n  }\n}\n```\n\n### Environment Variables Not Hashed\n\n```json\n// WRONG: API_URL changes won''t cause rebuilds\n{\n  \"tasks\": {\n    \"build\": {\n      \"outputs\": [\"dist/**\"]\n    }\n  }\n}\n\n// CORRECT: API_URL changes invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"outputs\": [\"dist/**\"],\n      \"env\": [\"API_URL\", \"API_KEY\"]\n    }\n  }\n}\n```\n\n### `.env` Files Not in Inputs\n\nTurbo does NOT load `.env` files - your framework does. But Turbo needs to know about changes:\n\n```json\n// WRONG: .env changes don''t invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\"]\n    }\n  }\n}\n\n// CORRECT: .env file changes invalidate cache\n{\n  \"tasks\": {\n    \"build\": {\n      \"env\": [\"API_URL\"],\n      \"inputs\": [\"$TURBO_DEFAULT$\", \".env\", \".env.*\"]\n    }\n  }\n}\n```\n\n### Root `.env` File in Monorepo\n\nA `.env` file at the repo root is an anti-pattern — even for small monorepos or starter templates. It creates implicit coupling between packages and makes it unclear which packages depend on which variables.\n\n```\n// WRONG - root .env affects all packages implicitly\nmy-monorepo/\n├── .env              # Which packages use this?\n├── apps/\n│   ├── web/\n│   └── api/\n└── packages/\n\n// CORRECT - .env files in packages that need them\nmy-monorepo/\n├── apps/\n│   ├── web/\n│   │   └── .env      # Clear: web needs DATABASE_URL\n│   └── api/\n│       └── .env      # Clear: api needs API_KEY\n└── packages/\n```\n\n**Problems with root `.env`:**\n\n- Unclear which packages consume which variables\n- All packages get all variables (even ones they don''t need)\n- Cache invalidation is coarse-grained (root .env change invalidates everything)\n- Security risk: packages may accidentally access sensitive vars meant for others\n- Bad habits start small — starter templates should model correct patterns\n\n**If you must share variables**, use `globalEnv` to be explicit about what''s shared, and document why.\n\n### Strict Mode Filtering CI Variables\n\nBy default, Turborepo filters environment variables to only those in `env`/`globalEnv`. CI variables may be missing:\n\n```json\n// If CI scripts need GITHUB_TOKEN but it''s not in env:\n{\n  \"globalPassThroughEnv\": [\"GITHUB_TOKEN\", \"CI\"],\n  \"tasks\": { ... }\n}\n```\n\nOr use `--env-mode=loose` (not recommended for production).\n\n### Shared Code in Apps (Should Be a Package)\n\n```\n// WRONG: Shared code inside an app\napps/\n  web/\n    shared/          # This breaks monorepo principles!\n      utils.ts\n\n// CORRECT: Extract to a package\npackages/\n  utils/\n    src/utils.ts\n```\n\n### Accessing Files Across Package Boundaries\n\n```typescript\n// WRONG: Reaching into another package''s internals\nimport { Button } from \"../../packages/ui/src/button\";\n\n// CORRECT: Install and import properly\nimport { Button } from \"@repo/ui/button\";\n```\n\n### Too Many Root Dependencies\n\n```json\n// WRONG: App dependencies in root\n{\n  \"dependencies\": {\n    \"react\": \"^18\",\n    \"next\": \"^14\"\n  }\n}\n\n// CORRECT: Only repo tools in root\n{\n  \"devDependencies\": {\n    \"turbo\": \"latest\"\n  }\n}\n```\n\n## Common Task Configurations\n\n### Standard Build Pipeline\n\n```json\n{\n  \"$schema\": \"https://turborepo.dev/schema.v2.json\",\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\", \".next/**\", \"!.next/cache/**\"]\n    },\n    \"dev\": {\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\nAdd a `transit` task if you have tasks that need parallel execution with cache invalidation (see below).\n\n### Dev Task with `^dev` Pattern (for `turbo watch`)\n\nA `dev` task with `dependsOn: [\"^dev\"]` and `persistent: false` in root turbo.json may look unusual but is **correct for `turbo watch` workflows**:\n\n```json\n// Root turbo.json\n{\n  \"tasks\": {\n    \"dev\": {\n      \"dependsOn\": [\"^dev\"],\n      \"cache\": false,\n      \"persistent\": false  // Packages have one-shot dev scripts\n    }\n  }\n}\n\n// Package turbo.json (apps/web/turbo.json)\n{\n  \"extends\": [\"//\"],\n  \"tasks\": {\n    \"dev\": {\n      \"persistent\": true  // Apps run long-running dev servers\n    }\n  }\n}\n```\n\n**Why this works:**\n\n- **Packages** (e.g., `@acme/db`, `@acme/validators`) have `\"dev\": \"tsc\"` — one-shot type generation that completes quickly\n- **Apps** override with `persistent: true` for actual dev servers (Next.js, etc.)\n- **`turbo watch`** re-runs the one-shot package `dev` scripts when source files change, keeping types in sync\n\n**Intended usage:** Run `turbo watch dev` (not `turbo run dev`). Watch mode re-executes one-shot tasks on file changes while keeping persistent tasks running.\n\n**Alternative pattern:** Use a separate task name like `prepare` or `generate` for one-shot dependency builds to make the intent clearer:\n\n```json\n{\n  \"tasks\": {\n    \"prepare\": {\n      \"dependsOn\": [\"^prepare\"],\n      \"outputs\": [\"dist/**\"]\n    },\n    \"dev\": {\n      \"dependsOn\": [\"prepare\"],\n      \"cache\": false,\n      \"persistent\": true\n    }\n  }\n}\n```\n\n### Transit Nodes for Parallel Tasks with Cache Invalidation\n\nSome tasks can run in parallel (don''t need built output from dependencies) but must invalidate cache when dependency source code changes.\n\n**The problem with `dependsOn: [\"^taskname\"]`:**\n\n- Forces sequential execution (slow)\n\n**The problem with `dependsOn: []` (no dependencies):**\n\n- Allows parallel execution (fast)\n- But cache is INCORRECT - changing dependency source won''t invalidate cache\n\n**Transit Nodes solve both:**\n\n```json\n{\n  \"tasks\": {\n    \"transit\": { \"dependsOn\": [\"^transit\"] },\n    \"my-task\": { \"dependsOn\": [\"transit\"] }\n  }\n}\n```\n\nThe `transit` task creates dependency relationships without matching any actual script, so tasks run in parallel with correct cache invalidation.\n\n**How to identify tasks that need this pattern:** Look for tasks that read source files from dependencies but don''t need their build outputs.\n\n### With Environment Variables\n\n```json\n{\n  \"globalEnv\": [\"NODE_ENV\"],\n  \"globalDependencies\": [\".env\"],\n  \"tasks\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"outputs\": [\"dist/**\"],\n      \"env\": [\"API_URL\", \"DATABASE_URL\"]\n    }\n  }\n}\n```\n\n## Reference Index\n\n### Configuration\n\n| File                                                                            | Purpose                                                  |\n| ------------------------------------------------------------------------------- | -------------------------------------------------------- |\n| [configuration/RULE.md](./references/configuration/RULE.md)                     | turbo.json overview, Package Configurations              |\n| [configuration/tasks.md](./references/configuration/tasks.md)                   | dependsOn, outputs, inputs, env, cache, persistent       |\n| [configuration/global-options.md](./references/configuration/global-options.md) | globalEnv, globalDependencies, cacheDir, daemon, envMode |\n| [configuration/gotchas.md](./references/configuration/gotchas.md)               | Common configuration mistakes                            |\n\n### Caching\n\n| File                                                            | Purpose                                      |\n| --------------------------------------------------------------- | -------------------------------------------- |\n| [caching/RULE.md](./references/caching/RULE.md)                 | How caching works, hash inputs               |\n| [caching/remote-cache.md](./references/caching/remote-cache.md) | Vercel Remote Cache, self-hosted, login/link |\n| [caching/gotchas.md](./references/caching/gotchas.md)           | Debugging cache misses, --summarize, --dry   |\n\n### Environment Variables\n\n| File                                                          | Purpose                                   |\n| ------------------------------------------------------------- | ----------------------------------------- |\n| [environment/RULE.md](./references/environment/RULE.md)       | env, globalEnv, passThroughEnv            |\n| [environment/modes.md](./references/environment/modes.md)     | Strict vs Loose mode, framework inference |\n| [environment/gotchas.md](./references/environment/gotchas.md) | .env files, CI issues                     |\n\n### Filtering\n\n| File                                                        | Purpose                  |\n| ----------------------------------------------------------- | ------------------------ |\n| [filtering/RULE.md](./references/filtering/RULE.md)         | --filter syntax overview |\n| [filtering/patterns.md](./references/filtering/patterns.md) | Common filter patterns   |\n\n### CI/CD\n\n| File                                                      | Purpose                         |\n| --------------------------------------------------------- | ------------------------------- |\n| [ci/RULE.md](./references/ci/RULE.md)                     | General CI principles           |\n| [ci/github-actions.md](./references/ci/github-actions.md) | Complete GitHub Actions setup   |\n| [ci/vercel.md](./references/ci/vercel.md)                 | Vercel deployment, turbo-ignore |\n| [ci/patterns.md](./references/ci/patterns.md)             | --affected, caching strategies  |\n\n### CLI\n\n| File                                            | Purpose                                       |\n| ----------------------------------------------- | --------------------------------------------- |\n| [cli/RULE.md](./references/cli/RULE.md)         | turbo run basics                              |\n| [cli/commands.md](./references/cli/commands.md) | turbo run flags, turbo-ignore, other commands |\n\n### Best Practices\n\n| File                                                                          | Purpose                                                         |\n| ----------------------------------------------------------------------------- | --------------------------------------------------------------- |\n| [best-practices/RULE.md](./references/best-practices/RULE.md)                 | Monorepo best practices overview                                |\n| [best-practices/structure.md](./references/best-practices/structure.md)       | Repository structure, workspace config, TypeScript/ESLint setup |\n| [best-practices/packages.md](./references/best-practices/packages.md)         | Creating internal packages, JIT vs Compiled, exports            |\n| [best-practices/dependencies.md](./references/best-practices/dependencies.md) | Dependency management, installing, version sync                 |\n\n### Watch Mode\n\n| File                                        | Purpose                                         |\n| ------------------------------------------- | ----------------------------------------------- |\n| [watch/RULE.md](./references/watch/RULE.md) | turbo watch, interruptible tasks, dev workflows |\n\n### Boundaries (Experimental)\n\n| File                                                  | Purpose                                               |\n| ----------------------------------------------------- | ----------------------------------------------------- |\n| [boundaries/RULE.md](./references/boundaries/RULE.md) | Enforce package isolation, tag-based dependency rules |\n\n## Source Documentation\n\nThis skill is based on the official Turborepo documentation at:\n\n- Source: `apps/docs/content/docs/` in the Turborepo repository\n- Live: https://turborepo.dev/docs\n"},"lastSynced":"2026-03-08T02:03:10.270Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript and TypeScript Agents managing large-scale monorepos and requiring efficient build systems.","zh":"适用于JavaScript和TypeScript代理管理大规模单体仓库并需要高效的构建系统。","ja":"JavaScriptとTypeScriptエージェントが大規模なモノリポを管理し、効率的なビルドシステムを必要とする場合に最適です。","ko":"JavaScript와 TypeScript 에이전트가 대규모 모노리포를 관리하고 효율적인 빌드 시스템을 필요로 할 때 적합합니다.","es":"Ideal para Agentes JavaScript y TypeScript que gestionan monorepos a gran escala y requieren sistemas de compilación eficientes.","fr":"Idéal pour les agents JavaScript et TypeScript gérant des monorepos à grande échelle et nécessitant des systèmes de construction efficaces.","de":"Ideal für JavaScript- und TypeScript-Agents, die große monorepos verwalten und effiziente Build-Systeme benötigen.","pt":"Ideal para Agentes JavaScript e TypeScript que gerenciam monorepos em larga escala e requerem sistemas de build eficientes.","ru":"Идеально подходит для агентов JavaScript и TypeScript, управляющих крупномасштабными монорепозиториями и требующих эффективных систем сборки.","ar":"مثالي لعميل JavaScript و TypeScript الذين يديرون مستودعات مونو كبيرة الحجم وتحتاج إلى أنظمة بناء فعالة."},"recommendation":{"en":"Empowers agents to cache task outputs and run tasks in parallel based on dependency graphs, leveraging turbo.json configurations and package.json scripts for optimized monorepo builds, utilizing dependency graphs for task management.","zh":"赋予代理缓存任务输出和基于依赖图并行运行任务的能力，利用turbo.json配置和package.json脚本实现优化的单体仓库构建，利用依赖图管理任务。","ja":"エージェントにタスク出力をキャッシュし、依存関係グラフに基づいてタスクを並列で実行する能力を与え、turbo.json構成とpackage.jsonスクリプトを使用してモノリポのビルドを最適化し、依存関係グラフを使用してタスクを管理します。","ko":"에이전트에 태스크 출력을 캐시하고 종속성 그래프를 기반으로 태스크를 병렬로 실행하는 기능을 부여하여 turbo.json 구성 및 package.json 스크립트를 사용하여 모노리포 빌드를 최적화하고 종속성 그래프를 사용하여 태스크를 관리합니다.","es":"Habilita a los agentes a almacenar en caché las salidas de las tareas y ejecutar tareas en paralelo en función de los gráficos de dependencias, aprovechando configuraciones turbo.json y scripts package.json para compilaciones de monorepo optimizadas, utilizando gráficos de dependencias para la gestión de tareas.","fr":"Permet aux agents de mettre en cache les sorties de tâches et d''exécuter des tâches en parallèle en fonction des graphiques de dépendances, en exploitant les configurations turbo.json et les scripts package.json pour des constructions de monorepo optimisées, en utilisant des graphiques de dépendances pour la gestion de tâches.","de":"Ermächtigt die Agents, Task-Ausgaben zu cachen und Tasks parallel basierend auf Abhängigkeitsgraphen auszuführen, indem turbo.json-Konfigurationen und package.json-Skripte für optimierte monorepo-Builds genutzt werden, wobei Abhängigkeitsgraphen für die Taskverwaltung verwendet werden.","pt":"Habilita os agentes a armazenar em cache as saídas das tarefas e executar tarefas em paralelo com base em gráficos de dependência, aproveitando configurações turbo.json e scripts package.json para compilações de monorepo otimizadas, utilizando gráficos de dependência para gerenciamento de tarefas.","ru":"Наделяет агентов возможностью кэшировать выходные данные задач и выполнять задачи параллельно на основе графов зависимостей, используя конфигурации turbo.json и скрипты package.json для оптимизированной сборки монорепозитория, используя графы зависимостей для управления задачами.","ar":"تمكين الوكلاء لتخزين مخرجات المهام في ذاكرة التخزين المؤقت وتشغيل المهام بالتوازي بناءً على رسوميات الاعتماد، واستخدام تكوينات turbo.json وبرامج نصية package.json لإنشاء مونو متوافق محسّن، واستخدام رسوميات الاعتماد لإدارة المهام."},"useCases":{"en":["Automating build processes for JavaScript and TypeScript monorepos","Optimizing task execution using parallel processing and caching","Managing dependencies and task graphs for efficient monorepo builds"],"zh":["为JavaScript和TypeScript单体仓库自动化构建过程","使用并行处理和缓存优化任务执行","管理依赖项和任务图以实现高效的单体仓库构建"],"ja":["JavaScriptとTypeScriptのモノリポのビルドプロセスを自動化する","並列処理とキャッシュを使用してタスクの実行を最適化する","依存関係とタスクグラフを管理してモノリポのビルドを効率化する"],"ko":["JavaScript와 TypeScript 모노리포의 빌드 프로세스를 자동화하는 것","병렬 처리와 캐싱을 사용하여 태스크 실행을 최적화하는 것","의존성과 태스크 그래프를 관리하여 모노리포 빌드를 효율화하는 것"],"es":["Automatizar procesos de compilación para monorepos JavaScript y TypeScript","Optimizar la ejecución de tareas utilizando procesamiento paralelo y caché","Gestionar dependencias y gráficos de tareas para compilaciones de monorepo eficientes"],"fr":["Automatiser les processus de construction pour les monorepos JavaScript et TypeScript","Optimiser l''exécution des tâches en utilisant le traitement parallèle et la mise en cache","Gérer les dépendances et les graphiques de tâches pour des constructions de monorepo efficaces"],"de":["Automatisieren von Build-Prozessen für JavaScript- und TypeScript-monorepos","Optimieren der Task-Ausführung unter Verwendung von parallelem Verarbeiten und Caching","Verwalten von Abhängigkeiten und Task-Graphen für effiziente monorepo-Builds"],"pt":["Automatizar processos de compilação para monorepos JavaScript e TypeScript","Otimizar a execução de tarefas usando processamento paralelo e cache","Gerenciar dependências e gráficos de tarefas para compilações de monorepo eficientes"],"ru":["Автоматизировать процессы сборки для монорепозиториев JavaScript и TypeScript","Оптимизировать выполнение задач с помощью параллельной обработки и кэширования","Управлять зависимостями и графами задач для эффективной сборки монорепозитория"],"ar":["توفير عمليات بناء آلية لمستودعات مونو JavaScript و TypeScript","تحسين تشغيل المهام باستخدام المعالجة الموازية والتخزين المؤقت","إدارة الإعتماد ورسوميات المهام لإنشاء مونو فعال"]},"limitations":{"en":["Requires JavaScript or TypeScript environment","Root tasks are not supported, only package tasks are allowed","turbo.json and package.json configuration needed"],"zh":["需要JavaScript或TypeScript环境","不支持根任务，只允许包任务","需要turbo.json和package.json配置"],"ja":["JavaScriptまたはTypeScript環境が必要","ルートタスクはサポートされていない、パッケージタスクのみが許可される","turbo.jsonとpackage.jsonの構成が必要"],"ko":["JavaScript 또는 TypeScript 환경이 필요합니다.","루트 태스크는 지원되지 않으며 패키지 태스크만 허용됩니다.","turbo.json 및 package.json 구성이 필요합니다."],"es":["Requiere entorno JavaScript o TypeScript","No se admiten tareas raíz, solo se permiten tareas de paquete","Se necesita configuración turbo.json y package.json"],"fr":["Nécessite un environnement JavaScript ou TypeScript","Les tâches racine ne sont pas prises en charge, seules les tâches de package sont autorisées","Configuration turbo.json et package.json requise"],"de":["Benötigt JavaScript- oder TypeScript-Umgebung","Root-Tasks werden nicht unterstützt, nur Package-Tasks sind erlaubt","turbo.json- und package.json-Konfiguration erforderlich"],"pt":["Requer ambiente JavaScript ou TypeScript","Tarefas raiz não são suportadas, apenas tarefas de pacote são permitidas","Configuração turbo.json e package.json necessária"],"ru":["Требуется среда JavaScript или TypeScript","Корневые задачи не поддерживаются, разрешены только задачи пакета","Необходима конфигурация turbo.json и package.json"],"ar":["يتطلب بيئة JavaScript أو TypeScript","المهام الجذرية غير مدعومة، فقط مهام الحزمة مسموح بها","التكوين turbo.json و package.json ضروري"]},"version":4},"contentHash":"4282dd2f1ec1b912660be61f38858ff05053e94903af9771a5361058c47bb9c4","qualityScore":50}');
