INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NextLogic2025/frontendCafrisales/react-native-best-practices', 'react-native-best-practices', 'NextLogic2025', 'frontendCafrisales', 'community', 'react-native-best-practices NextLogic2025 frontendCafrisales community The react-native-best-practices skill provides a comprehensive performance optimization guide for React Native applications, covering JavaScript, Native, and bundling optimizations. This skill is ideal for developers seeking to improve their React Native app''s performance. React Native 优化最佳实践指南，涵盖 JavaScript、React 和本地代码优化 React Native 最適化のベストプラクティスを紹介 React Native 성능 최적화를 위한最佳实践 가이드 Mejore el rendimiento de sus aplicaciones React Native con nuestra guía de mejores prácticas. Aprenda a optimizar JavaScript, React y Native Améliorez les performances de vos applications React Native avec notre guide de meilleures pratiques. Découvrez comment optimiser JavaScript, React et Native Optimieren Sie die Leistung Ihrer React Native-Anwendungen mit unserem Leitfaden für Best Practices. Erfahren Sie, wie Sie JavaScript, React und Native optimieren Otimização de desempenho para aplicativos React Native, cobrindo JavaScript/React, nativas (iOS/Android) e otimizações de bundling Оптимизация производительности для приложений React Native, охватывающая JavaScript/React, нативные (iOS/Android) и оптимизации пакетов تحسين الأداء لتطبيقات رياكت نيتيف، تغطية جافا سكريبت/رياكت والأصلية (iOS/Android) وتحسينات التجميع how to use react-native-best-practices react-native-best-practices setup guide react-native performance optimization react-native-best-practices alternative react-native-best-practices vs native code install react-native-best-practices react-native-best-practices tutorial react-native optimization techniques react-native-best-practices benefits react-native performance improvement React Native 优化 JavaScript 优化 React 最佳实践 本地代码优化 打包优化 React Native 性能 Provides Quick Pattern code snippets for immediate pattern matching Includes Quick Command shell commands for process measurement Covers JavaScript/React performance optimizations Covers Native (iOS/Android) performance optimizations Covers bundling optimizations for improved app performance Follows a hybrid format for fast lookup and deep understanding react-native-best-practices is a set of guidelines for optimizing React Native application performance, covering JavaScript, Native, and bundling optimizations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('emlopezr/TrackWatch/django-expert', 'community', 'emlopezr', 'TrackWatch', 'emlopezr/TrackWatch', 'django-expert', 0, 0, 50, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.787Z', 'a4919acb26157e182b2d5da524f85efa8c837eaeff3596cbeadf8ec6b61702bb', '{"id":"emlopezr/TrackWatch/django-expert","name":"django-expert","description":{"en":"The django-expert skill provides comprehensive guidance for Django backend development, covering models, views, Django REST Framework, and performance optimization. It helps developers build maintainable applications following official Django best practices.","zh":"Django Expert 提供了 Django 后端开发的全面指导，包括模型、视图、Django REST Framework、表单、身份验证、测试和性能优化","ja":"Django Expert は、モデル、ビュー、Django REST Framework、フォーム、認証、テスト、パフォーマンス最適化を含む Django バックエンド開発の総合ガイドを提供する","ko":"Django Expert는 모델, 뷰, Django REST Framework, 폼, 인증, 테스트 및 성능 최적화를 포함하는 Django 백엔드 개발에 대한 종합 가이드를 제공","es":"Django Expert es una herramienta para desarrollo backend que proporciona orientación experta en modelos, vistas, Django REST Framework y autenticación","fr":"Django Expert est un outil de développement backend qui offre une guidance experte sur les modèles, vues, Django REST Framework et l''authentification","de":"Django Expert ist ein Tool für die Backend-Entwicklung, das umfassende Anleitung zu Modellen, Views, Django REST Framework und Authentifizierung bietet","pt":"O Django Expert é uma ferramenta para desenvolvedores que fornece orientação especializada para desenvolvimento de backend com Django, incluindo modelos, views e otimização de desempenho","ru":"Django Expert - это инструмент для разработчиков, который предоставляет экспертные рекомендации по разработке бэкенда на Django, включая модели, представления и оптимизацию производительности","ar":"خبير Django هو أداة لل مطورين توفر إرشادات متخصصة لتحسين تطوير الخلفية مع Django ، بما في ذلك النماذج والوجهات وتحسين الأداء"},"seo":{"title":{"en":"django-expert: Expert Guidance for Django Backend Develop...","zh":"Django Expert 设置指南 - 高级后端开发最佳实践","ja":"Django Expert 導入ガイド - 最新のバックエンド開発ベストプラクティス","ko":"Django Expert 설정 가이드 - 고급 백엔드 개발 모범 사례","es":"Guía de configuración de Django Expert para desarrollo ba...","fr":"Guide de mise en place de Django Expert pour le développe...","de":"Einrichtungsleitfaden für Django Expert zur Backend-Entwi...","pt":"Guia de Configuração do Django Expert para Desenvolviment...","ru":"Руководство по настройке Django Expert для разработки бэк...","ar":"دليل إعداد خبير Django لتحسين تطوير الخلفية"},"description":{"en":"Unlock the full potential of Django with django-expert. Get expert guidance on models, views, and Django REST Framework. Learn how to build robust applicatio...","zh":"使用 Django Expert 构建强大、可维护的应用程序，遵循官方最佳实践和现代 Python 约定","ja":"Django Expert を使用して堅牢で保守可能なアプリケーションを構築し、公式のベストプラクティスと最新の Python 規約に従う","ko":"Django Expert를 사용하여 강력하고 유지 보수 가능한 애플리케이션을 구축하고 공식적인 모범 사례와 최신 Python 규약을 따름","es":"Aprende a utilizar Django Expert para crear aplicaciones backend robustas y escalables con ORM, vistas y autenticación","fr":"Découvrez comment utiliser Django Expert pour créer des applications backend robustes et évolutives avec ORM, vues et authentification","de":"Erfahren Sie, wie Sie Django Expert verwenden, um robuste und skalierbare Backend-Anwendungen mit ORM, Views und Authentifizierung zu erstellen","pt":"Aprenda a configurar o Django Expert para desenvolver aplicações robustas e escaláveis com o framework Django e Python","ru":"Узнайте, как настроить Django Expert для разработки надежных и масштабируемых приложений с использованием фреймворка Django и Python","ar":"تعلم كيفية إعداد خبير Django لتحسين تطوير التطبيقات القوية والموسعة باستخدام إطار عمل Django و Python"},"definition":{"en":"django-expert is a skill that provides expert guidance for Django backend development with comprehensive coverage of models, views, and Django REST Framework.","zh":"Django Expert 是一个提供 Django 后端开发专业指导的 AI 工具","ja":"Django Expert は、Django バックエンド開発の専門的なガイダンスを提供する AI エージェントです","ko":"Django Expert는 Django 백엔드 개발 전문 지침을 제공하는 AI 에이전트","es":"Django Expert es un conjunto de habilidades para desarrolladores que necesitan crear aplicaciones backend con Django","fr":"Django Expert est un ensemble de compétences pour les développeurs qui ont besoin de créer des applications backend avec Django","de":"Django Expert ist eine Sammlung von Fähigkeiten für Entwickler, die Backend-Anwendungen mit Django erstellen müssen","pt":"O Django Expert é uma ferramenta de desenvolvimento de backend que fornece orientação especializada para desenvolvedores que trabalham com Django","ru":"Django Expert - это инструмент для разработки бэкенда, который предоставляет экспертные рекомендации для разработчиков, работающих с Django","ar":"خبير Django هو أداة لتحسين تطوير الخلفية توفر إرشادات متخصصة للمطورين الذين يعملون مع Django"},"features":{"en":["Model design with optimal ORM patterns","View implementation using FBV, CBV, and DRF viewsets","Django REST Framework API development","Testing and performance optimization","Implementation of authentication and forms"],"zh":["模型设计与优化的 ORM 模式","视图实现（FBV、CBV、DRF 视图集）","Django REST Framework API 开发","表单处理与验证","身份验证与权限管理","测试与性能优化"],"ja":["モデル設計と最適化の ORM パターン","ビュー実装（FBV、CBV、DRF ビューセット）","Django REST Framework API 開発","フォーム処理と検証","認証と権限管理","テストとパフォーマンス最適化"],"ko":["모델 설계 및 최적화의 ORM 패턴","뷰 구현（FBV、CBV、DRF 뷰셋）","Django REST Framework API 개발","폼 처리 및 검증","인증 및 권한 관리","테스트 및 성능 최적화"],"es":["Diseño de modelos con patrones de ORM óptimos","Implementación de vistas con FBV, CBV y DRF viewsets","Desarrollo de API con Django REST Framework","Autenticación y autorización de usuarios","Optimización del rendimiento de la aplicación"],"fr":["Conception de modèles avec des patrons de ORM optimisés","Implémentation de vues avec FBV, CBV et DRF viewsets","Développement d''API avec Django REST Framework","Authentification et autorisation des utilisateurs","Optimisation des performances de l''application"],"de":["Modellentwurf mit optimalen ORM-Mustern","Implementierung von Views mit FBV, CBV und DRF-Viewsets","Entwicklung von APIs mit Django REST Framework","Authentifizierung und Autorisierung von Benutzern","Optimierung der Leistung der Anwendung"],"pt":["Projeto de modelo com padrões de ORM otimizados","Implementação de views (FBV, CBV, DRF viewsets)","Desenvolvimento de API com Django REST Framework","Otimização de desempenho com práticas recomendadas do Django","Autenticação e autorização com Django"],"ru":["Проектирование моделей с оптимальными шаблонами ORM","Реализация представлений (FBV, CBV, DRF viewsets)","Разработка API с использованием Django REST Framework","Оптимизация производительности с помощью рекомендаций по Django","Аутентификация и авторизация с помощью Django"],"ar":["تصميم نموذج مع أنماط ORM المثالية","تنفيذ وجهات (FBV، CBV، DRF viewsets)","تطوير واجهة برمجة التطبيقات مع إطار عمل Django REST","تحسين الأداء مع أفضل الممارسات من Django","التحقق والتحقق من صحة الهوية باستخدام Django"]},"keywords":{"en":["how to use django-expert","django-expert setup guide","django-expert alternative","django-expert vs flask","django-expert install","django-expert tutorial","what is django-expert","django-expert best practices","django-expert documentation"],"zh":["Django 后端开发","Django Expert","AI 工具","模型设计","视图实现","Django REST Framework","表单处理","身份验证","测试与性能优化"],"ja":["Django バックエンド開発","Django Expert","AI エージェント","モデル設計","ビュー実装","Django REST Framework","フォーム処理","認証","テストとパフォーマンス最適化"],"ko":["Django 백엔드 개발","Django Expert","AI 에이전트","모델 설계","뷰 구현","Django REST Framework","폼 처리","인증","테스트 및 성능 최적화"],"es":["Django Expert","desarrollo backend","ORM","vistas","Django REST Framework","autenticación","optimización del rendimiento","herramientas de desarrollo","framework de Python"],"fr":["Django Expert","développement backend","ORM","vues","Django REST Framework","authentification","optimisation des performances","outils de développement","framework Python"],"de":["Django Expert","Backend-Entwicklung","ORM","Views","Django REST Framework","Authentifizierung","Leistungsoptimierung","Entwicklungstools","Python-Framework"],"pt":["Django Expert","desenvolvimento de backend","Django REST Framework","modelos de dados","views em Django","otimização de desempenho","autenticação em Django","desenvolvimento de API"],"ru":["Django Expert","разработка бэкенда","Django REST Framework","модели данных","представления в Django","оптимизация производительности","аутентификация в Django","разработка API"],"ar":["خبير Django","تحسين تطوير الخلفية","إطار عمل Django REST","نماذج البيانات","الوجهات في Django","تحسين الأداء","التحقق من صحة الهوية في Django","تطوير واجهة برمجة التطبيقات"]}},"owner":"emlopezr","repo":"TrackWatch","repoPath":"emlopezr/TrackWatch","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"django-expert","description":"Expert Django backend development guidance. Use when creating Django models, views, serializers, or APIs; debugging ORM queries or migrations; optimizing database performance; implementing authentication; writing tests; or working with Django REST Framework. Follows Django best practices and modern patterns.","bodyPreview":"# Django Expert\n\n## Overview\n\nThis skill provides expert guidance for Django backend development with comprehensive coverage of models, views, Django REST Framework, forms, authentication, testing, and performance optimization. It follows official Django best practices and modern Python conventions to help you build robust, maintainable applications.\n\n**Key Capabilities:**\n- Model design with optimal ORM patterns\n- View implementation (FBV, CBV, DRF viewsets)\n- Django REST Framework API developm","body":"# Django Expert\n\n## Overview\n\nThis skill provides expert guidance for Django backend development with comprehensive coverage of models, views, Django REST Framework, forms, authentication, testing, and performance optimization. It follows official Django best practices and modern Python conventions to help you build robust, maintainable applications.\n\n**Key Capabilities:**\n- Model design with optimal ORM patterns\n- View implementation (FBV, CBV, DRF viewsets)\n- Django REST Framework API development\n- Query optimization and performance tuning\n- Authentication and permissions\n- Testing strategies and patterns\n- Security best practices\n\n## When to Use\n\nInvoke this skill when you encounter these triggers:\n\n**Model & Database Work:**\n- \"Create a Django model for...\"\n- \"Optimize this queryset/database query\"\n- \"Generate migrations for...\"\n- \"Design database schema for...\"\n- \"Fix N+1 query problem\"\n\n**View & API Development:**\n- \"Create an API endpoint for...\"\n- \"Build a Django view that...\"\n- \"Implement DRF serializer/viewset\"\n- \"Add filtering/pagination to API\"\n\n**Authentication & Security:**\n- \"Implement authentication/permissions\"\n- \"Create custom user model\"\n- \"Secure this endpoint/view\"\n\n**Testing & Quality:**\n- \"Write tests for this Django app\"\n- \"Debug this Django error/issue\"\n- \"Review Django code for issues\"\n\n**Performance & Optimization:**\n- \"This Django view is slow\"\n- \"Optimize database queries\"\n- \"Add caching to...\"\n\n**Production Deployment:**\n- \"Deploy Django to production\"\n- \"Configure Django for production\"\n- \"Set up HTTPS/SSL for Django\"\n- \"Production settings checklist\"\n- \"Configure production database/cache\"\n\n## Instructions\n\nFollow this workflow when handling Django development requests:\n\n### 1. Analyze the Request and Gather Context\n\n**Identify the task type:**\n- Model design (database schema, relationships, migrations)\n- View/API development (FBV, CBV, DRF viewsets, serializers)\n- Query optimization (N+1 problems, database performance)\n- Authentication/permissions (user models, access control)\n- Testing (unit tests, integration tests, fixtures)\n- Security review (CSRF, XSS, SQL injection, permissions)\n- Production deployment (settings, HTTPS, database, caching, monitoring)\n- Template rendering (Django templates, context processors)\n\n**Leverage available context:**\n- If `django-ai-boost` MCP server is available, use it to understand project structure and existing patterns\n- Read relevant existing code to understand conventions\n- Check Django version for compatibility considerations\n\n### 2. Load Relevant Reference Documentation\n\nBased on the task type, reference the appropriate bundled documentation:\n\n- **Models/ORM work** -> `references/models-and-orm.md`\n  - Model design patterns and field choices\n  - Relationship configurations (ForeignKey, ManyToMany)\n  - Custom managers and QuerySet methods\n  - Migration strategies\n\n- **View/API development** -> `references/views-and-urls.md` + `references/drf-guidelines.md`\n  - FBV vs CBV decision criteria\n  - DRF serializers, viewsets, and routers\n  - URL configuration patterns\n  - Middleware and request/response handling\n\n- **Performance issues** -> `references/performance-optimization.md`\n  - Query optimization techniques (select_related, prefetch_related)\n  - Caching strategies (Redis, Memcached, database caching)\n  - Database indexing and query profiling\n  - Connection pooling and async patterns\n\n- **Production deployment** -> `references/production-deployment.md`\n  - Critical settings (DEBUG, SECRET_KEY, ALLOWED_HOSTS)\n  - HTTPS and SSL/TLS configuration\n  - Database and cache configuration\n  - Static/media file serving\n  - Error monitoring and logging\n  - Deployment process and health checks\n\n- **Security concerns** -> `references/security-checklist.md`\n  - CSRF/XSS/SQL injection prevention\n  - Authentication and authorization patterns\n  - Secure configuration practices\n  - Input validation and sanitization\n\n- **Testing tasks** -> `references/testing-strategies.md`\n  - Test structure and organization\n  - Fixtures and factories\n  - Mocking external dependencies\n  - Coverage and CI/CD integration\n\n### 3. Implement Following Django Best Practices\n\n**Code quality standards:**\n- Follow PEP 8 and Django coding style\n- Use Django built-ins over third-party packages when possible\n- Keep views thin, use services/managers for business logic\n- Write descriptive variable names and add docstrings for complex logic\n- Handle errors gracefully with appropriate exceptions\n\n**Django-specific patterns:**\n- Use `select_related()` for FK/OneToOne, `prefetch_related()` for reverse FK/M2M\n- Leverage class-based views and mixins for code reuse\n- Use Django forms/serializers for validation\n- Follow Django''s migration workflow (never edit applied migrations)\n- Use Django''s built-in security features (CSRF tokens, auth decorators)\n\n**API development (DRF):**\n- Use ModelSerializer for standard CRUD operations\n- Implement proper pagination and filtering\n- Use appropriate permission classes\n- Follow RESTful conventions for endpoints\n- Version APIs when making breaking changes\n\n### 4. Validate and Test\n\nBefore presenting the solution:\n\n**Code review:**\n- Check for N+1 query problems (use Django Debug Toolbar mentally)\n- Verify proper error handling and edge cases\n- Ensure security best practices are followed\n- Confirm migrations are clean and reversible\n\n**Testing considerations:**\n- Suggest or write appropriate tests for new functionality\n- Verify test coverage for critical paths\n- Check that fixtures/factories are maintainable\n\n**Performance check:**\n- Review database queries for efficiency\n- Consider caching opportunities\n- Verify proper use of database indexes\n\n## Bundled Resources\n\n**references/** - Comprehensive Django documentation loaded into context as needed\n\nThese reference files provide detailed guidance beyond this SKILL.md overview:\n\n- **`references/models-and-orm.md`** (~11k words)\n  - Model field types and best practices\n  - Relationship configurations (ForeignKey, OneToOne, ManyToMany)\n  - Custom managers and QuerySet methods\n  - Migration patterns and common pitfalls\n  - Database-level constraints and indexes\n\n- **`references/views-and-urls.md`** (~17k words)\n  - Function-based vs class-based view trade-offs\n  - CBV mixins and inheritance patterns\n  - URL routing and reverse resolution\n  - Middleware implementation\n  - Request/response lifecycle\n\n- **`references/drf-guidelines.md`** (~18k words)\n  - Serializer patterns (ModelSerializer, nested serializers)\n  - ViewSet and router configurations\n  - Pagination, filtering, and search\n  - Authentication and permission classes\n  - API versioning strategies\n  - Performance optimization for APIs\n\n- **`references/testing-strategies.md`** (~18k words)\n  - Test organization and structure\n  - Factory patterns vs fixtures\n  - Testing views, models, and serializers\n  - Mocking external services\n  - Test database optimization\n  - CI/CD integration\n\n- **`references/security-checklist.md`** (~12k words)\n  - CSRF protection implementation\n  - XSS prevention techniques\n  - SQL injection defense\n  - Authentication best practices\n  - Permission and authorization patterns\n  - Secure settings configuration\n\n- **`references/performance-optimization.md`** (~14k words)\n  - Query optimization (select_related, prefetch_related, only, defer)\n  - Database indexing strategies\n  - Caching layers (Redis, Memcached, database cache)\n  - Database connection pooling\n  - Profiling and monitoring tools\n  - Async views and background tasks\n\n- **`references/production-deployment.md`** (~20k words)\n  - Critical settings (DEBUG, SECRET_KEY, ALLOWED_HOSTS)\n  - Database configuration and connection pooling\n  - HTTPS/SSL configuration and security headers\n  - Static and media file serving\n  - Caching with Redis/Memcached\n  - Email configuration for production\n  - Error monitoring with Sentry\n  - Logging and health checks\n  - Zero-downtime deployment strategies\n\n- **`references/examples.md`** - Practical implementation examples\n  - Model design with custom managers\n  - N+1 query optimization\n  - DRF API endpoint implementation\n  - Writing Django tests\n\n## Additional Notes\n\n**Django Version Compatibility:**\n- Consider LTS releases (4.2, 5.2) for production\n- Check deprecation warnings when upgrading\n- Use `django-upgrade` tool for automated migration\n\n**Common Pitfalls to Avoid:**\n- Circular imports (use lazy references)\n- Missing `related_name` on relationships\n- Forgetting database indexes on frequently queried fields\n- Using `get()` without exception handling\n- N+1 queries in templates and serializers\n"},"lastSynced":"2026-03-08T02:03:21.787Z","agentAnalysis":{"suitability":{"en":"Ideal for Python-based AI Agents requiring expert-level Django backend development capabilities","zh":"适用于需要高级Django后端开发能力的Python-based AI Agents","ja":"PythonベースのAIエージェントがDjangoバックエンド開発のエキスパートレベルの機能を必要とする場合に最適","ko":"Python 기반 AI 에이전트가 전문가 수준의 Django 백엔드 개발 기능을 필요로 할 때 적합","es":"Ideal para agentes de IA basados en Python que requieren capacidades de desarrollo de backend de nivel experto en Django","fr":"Idéal pour les agents d''IA basés sur Python nécessitant des capacités de développement de backend Django de niveau expert","de":"Ideal für Python-basierte KI-Agents, die Experten-Level-Backend-Entwicklungsfähigkeiten für Django erfordern","pt":"Ideal para agentes de IA baseados em Python que exigem capacidades de desenvolvimento de backend de nível expert em Django","ru":"Идеально подходит для агентов ИИ на основе Python, требующих экспертных возможностей по разработке бэкенда на Django","ar":"مثالي لعمليات الوكيل الذكي التي تعتمد على بايثون وتتطلب إمكانيات تطوير خلفية خبير في دجنجو"},"recommendation":{"en":"Empowers agents to design optimal Django models using ORM patterns, implement scalable views with FBV, CBV, and DRF viewsets, and develop high-performance REST APIs with Django REST Framework, following official Django best practices and modern Python conventions","zh":"赋予代理设计最优Django模型，使用ORM模式，实现可扩展的视图，使用FBV，CBV和DRF视图集，并使用Django REST Framework开发高性能REST API，遵循官方Django最佳实践和现代Python约定","ja":"エージェントに最適なDjangoモデルを設計する権限を与え、ORMパターンを使用し、FBV、CBV、DRFビューセットを使用して拡張可能なビューを実装し、Django REST Frameworkを使用して高パフォーマンスのREST APIを開発し、公式のDjangoベストプラクティスとモダンPython規約に従う","ko":"에이전트가 최적의 Django 모델을 설계하고 ORM 패턴을 사용하고 FBV, CBV 및 DRF 뷰셋을 사용하여 확장 가능한 뷰를 구현하고 Django REST Framework를 사용하여 고성능 REST API를 개발하며 공식 Django 최고 실践 및 현대 Python 규약을 따름","es":"Habilita a los agentes a diseñar modelos Django óptimos utilizando patrones de ORM, implementar vistas escalables con FBV, CBV y conjuntos de vistas de DRF, y desarrollar API de REST de alto rendimiento con Django REST Framework, siguiendo las mejores prácticas oficiales de Django y convenciones de Python modernas","fr":"Permet aux agents de concevoir des modèles Django optimaux en utilisant des modèles de ORM, de mettre en œuvre des vues escalables avec FBV, CBV et des ensembles de vues de DRF, et de développer des API REST haute performance avec Django REST Framework, en suivant les meilleures pratiques officielles de Django et les conventions Python modernes","de":"Ermächtigt Agents, optimale Django-Modelle unter Verwendung von ORM-Mustern zu entwerfen, skalierbare Ansichten mit FBV, CBV und DRF-Viewsets zu implementieren und High-Performance-REST-APIs mit Django REST Framework zu entwickeln, indem sie offizielle Django-Best-Practices und moderne Python-Konventionen befolgen","pt":"Habilita os agentes a projetar modelos Django ótimos usando padrões de ORM, implementar visualizações escaláveis com FBV, CBV e coleções de visualizações DRF e desenvolver APIs REST de alto desempenho com Django REST Framework, seguindo as melhores práticas oficiais do Django e convenções Python modernas","ru":"Предоставляет агентам возможность проектировать оптимальные модели Django с использованием шаблонов ORM, реализовывать масштабируемые представления с FBV, CBV и наборами представлений DRF, а также разрабатывать высокопроизводительные REST API с использованием Django REST Framework, следуя официальным лучшим практикам Django и современным соглашениям Python","ar":"تمكّن الوكيل من تصميم نماذج دجنجو أمثلة باستخدام أنماط ORM، وتنفيذ مناظير قابلة للتوسعة مع FBV وCBV ووحدات مناظير DRF، وتصميم واجهات برمجة تطبيقات REST عالية الأداء مع إطار دجنجو REST، اتباعًا لأفضل الممارسات الرسمية لدجنجو والاتفاقيات البايثونية الحديثة"},"useCases":{"en":["Building maintainable Django applications with robust model design","Implementing scalable and secure Django REST Framework APIs","Optimizing Django application performance using official best practices"],"zh":["构建可维护的Django应用程序，具有强大的模型设计","实现可扩展和安全的Django REST Framework API","使用官方最佳实践优化Django应用程序性能"],"ja":["強力なモデル設計を持つメンテナンス可能なDjangoアプリケーションを構築する","拡張可能でセキュアなDjango REST Framework APIを実装する","公式のベストプラクティスを使用してDjangoアプリケーションのパフォーマンスを最適化する"],"ko":["강력한 모델 디자인을 갖춘 유지 보수 가능한 Django 애플리케이션을 구축","확장 가능하고 보안이 강화된 Django REST Framework API를 구현","공식 최고 실践을 사용하여 Django 애플리케이션의 성능을 최적화"],"es":["Construir aplicaciones Django mantenibles con un diseño de modelo robusto","Implementar API de Django REST Framework escalables y seguras","Optimizar el rendimiento de la aplicación Django usando las mejores prácticas oficiales"],"fr":["Construire des applications Django maintenables avec une conception de modèle robuste","Mettre en œuvre des API de Django REST Framework escalables et sécurisées","Optimiser les performances de l''application Django en utilisant les meilleures pratiques officielles"],"de":["Erstellen von wartbaren Django-Anwendungen mit robustem Modell-Design","Implementierung von skalierbaren und sicheren Django-REST-Framework-APIs","Optimierung der Django-Anwendungsleistung unter Verwendung offizieller Best-Practices"],"pt":["Construir aplicações Django mantenedoras com design de modelo robusto","Implementar APIs Django REST Framework escaláveis e seguras","Otimizar o desempenho da aplicação Django usando as melhores práticas oficiais"],"ru":["Построение поддерживаемых приложений Django с прочным дизайном модели","Реализация масштабируемых и безопасных API Django REST Framework","Оптимизация производительности приложения Django с использованием официальных лучших практиках"],"ar":["بناء تطبيقات دجنجو قابلة للصيانة مع تصميم نموذج قوي","تنفيذ واجهات برمجة تطبيقات دجنجو REST Framework قابلة للتوسعة وأمنة","تحسين أداء تطبيق دجنجو باستخدام أفضل الممارسات الرسمية"]},"limitations":{"en":["Requires Python and Django installation","Limited to Django backend development","Follows official Django best practices, which may not be compatible with older Django versions"],"zh":["需要Python和Django安装","仅限Django后端开发","遵循官方Django最佳实践，可能与旧版本的Django不兼容"],"ja":["PythonとDjangoのインストールが必要","Djangoバックエンド開発のみ","公式のDjangoベストプラクティスに従うが、古いバージョンのDjangoと互換性がない可能性がある"],"ko":["Python 및 Django 설치가 필요","Django 백엔드 개발만 해당","공식 Django 최고 실践을 따르지만 이전 버전의 Django와 호환되지 않을 수 있음"],"es":["Requiere instalación de Python y Django","Limitado al desarrollo de backend de Django","Sigue las mejores prácticas oficiales de Django, que pueden no ser compatibles con versiones anteriores de Django"],"fr":["Nécessite l''installation de Python et de Django","Limité au développement de backend de Django","Suit les meilleures pratiques officielles de Django, qui peuvent ne pas être compatibles avec les anciennes versions de Django"],"de":["Benötigt Python- und Django-Installation","Begrenzt auf Django-Backend-Entwicklung","Befolgt offizielle Django-Best-Practices, die möglicherweise nicht mit älteren Django-Versionen kompatibel sind"],"pt":["Exige instalação do Python e do Django","Limitado ao desenvolvimento de backend do Django","Sigue as melhores práticas oficiais do Django, que podem não ser compatíveis com versões mais antigas do Django"],"ru":["Требует установки Python и Django","Ограничен разработкой бэкенда Django","Следует официальным лучшим практикам Django, которые могут быть несовместимы с более старыми версиями Django"],"ar":["يتطلب تثبيت بايثون ودجنجو","محدود بتطوير خلفية دجنجو","ياتي بموجب أفضل الممارسات الرسمية لدجنجو، والتي قد لا تكون متوافقة مع الإصدارات الأقدم من دجنجو"]},"version":4},"contentHash":"a4919acb26157e182b2d5da524f85efa8c837eaeff3596cbeadf8ec6b61702bb","qualityScore":50}');
