INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('emlopezr/TrackWatch/django-expert', 'django-expert', 'emlopezr', 'TrackWatch', 'community', 'django-expert emlopezr TrackWatch community The django-expert skill provides comprehensive guidance for Django backend development, covering models, views, Django REST Framework, and performance optimization. It helps developers build maintainable applications following official Django best practices. Django Expert 提供了 Django 后端开发的全面指导，包括模型、视图、Django REST Framework、表单、身份验证、测试和性能优化 Django Expert は、モデル、ビュー、Django REST Framework、フォーム、認証、テスト、パフォーマンス最適化を含む Django バックエンド開発の総合ガイドを提供する Django Expert는 모델, 뷰, Django REST Framework, 폼, 인증, 테스트 및 성능 최적화를 포함하는 Django 백엔드 개발에 대한 종합 가이드를 제공 Django Expert es una herramienta para desarrollo backend que proporciona orientación experta en modelos, vistas, Django REST Framework y autenticación Django Expert est un outil de développement backend qui offre une guidance experte sur les modèles, vues, Django REST Framework et l''authentification Django Expert ist ein Tool für die Backend-Entwicklung, das umfassende Anleitung zu Modellen, Views, Django REST Framework und Authentifizierung bietet O Django Expert é uma ferramenta para desenvolvedores que fornece orientação especializada para desenvolvimento de backend com Django, incluindo modelos, views e otimização de desempenho Django Expert - это инструмент для разработчиков, который предоставляет экспертные рекомендации по разработке бэкенда на Django, включая модели, представления и оптимизацию производительности خبير Django هو أداة لل مطورين توفر إرشادات متخصصة لتحسين تطوير الخلفية مع Django ، بما في ذلك النماذج والوجهات وتحسين الأداء how to use django-expert django-expert setup guide django-expert alternative django-expert vs flask django-expert install django-expert tutorial what is django-expert django-expert best practices django-expert documentation Django 后端开发 Django Expert AI 工具 模型设计 视图实现 Django REST Framework 表单处理 身份验证 测试与性能优化 Model design with optimal ORM patterns View implementation using FBV, CBV, and DRF viewsets Django REST Framework API development Testing and performance optimization Implementation of authentication and forms django-expert is a skill that provides expert guidance for Django backend development with comprehensive coverage of models, views, and Django REST Framework.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('olavocarvalho/engrain/biome', 'community', 'olavocarvalho', 'engrain', 'olavocarvalho/engrain', 'biome', 0, 0, 50, '2026-03-08T01:57:15.339Z', '2026-03-08T02:03:24.159Z', '9c1ebccf003c106d060a43d19ac819a0cece9badc9b7e5cb8354dc6e47b7f59f', '{"id":"olavocarvalho/engrain/biome","name":"biome","description":{"en":"Biome is a fast, all-in-one toolchain for web projects written in Rust, replacing ESLint and Prettier. It benefits developers by providing zero-config defaults and 100x faster performance.","zh":"Biome 是一个快速的、全面的工具链，用于 web 项目，提供零配置默认值和 100x 更快的性能","ja":"Biome は、Web プロジェクト用の高速なオールインワントゥールチェーンで、ゼロコンフィグのデフォルト値と 100x高速なパフォーマンスを提供します","ko":"Biome는 웹 프로젝트를 위한 빠른 모든 툴체인으로, 기본값이 설정되어 있지 않으며 100x 빠른 성능을 제공합니다","es":"Biome es una herramienta de desarrollo web de Rust que combina linting y formateo en una sola herramienta","fr":"Biome est un outil de développement web Rust qui combine linting et formateo en un seul outil","de":"Biome ist ein Webentwicklungstool in Rust, das Linting und Formateo in einem Tool kombiniert","pt":"O Biome é uma ferramenta de desenvolvimento rápida e versátil para projetos web, escrita em Rust, que substitui ESLint e Prettier","ru":"Biome - быстрый и универсальный инструмент для веб-проектов, написанный на Rust, заменяющий ESLint и Prettier","ar":"بيوم هي أداة سريعة ومرنة لتطوير الويب، مكتوبة بلغة روست، تحل مكان ESLint و Prettier"},"seo":{"title":{"en":"Biome: Fast All-in-One Toolchain Setup Guide | AI Agent S...","zh":"Biome 快速集成工具链设置指南","ja":"Biome AIエージェントの最適な設定方法","ko":"Biome 빠른 통합 툴체인 설치 가이드","es":"Guía de configuración de Biome: Herramienta de desarrollo...","fr":"Guide de mise en place de Biome : Outil de développement ...","de":"Biome-Setup-Anleitung: Schnellste Toolchain für Webprojekte","pt":"Guia de Configuração do Biome: Ferramenta de Desenvolvime...","ru":"Настройка Biome: Быстрый Инструмент для Веб-проектов","ar":"إعداد بيوم: أداة سريعة للويب"},"description":{"en":"Discover how Biome replaces ESLint and Prettier with a 100x faster tool. Learn how to install and use Biome for your web projects today!","zh":"Biome 是一个快速的、全面的工具链，用于替代 ESLint 和 Prettier，提供零配置默认值和 100x 更快的性能","ja":"Biome は、ESLint と Prettier を置き換える高速なオールインワントゥールチェーンで、ゼロコンフィグのデフォルト値と 100x高速なパフォーマンスを提供します","ko":"Biome는 ESLint와 Prettier를 대체하는 빠른 모든 툴체인으로, 기본값이 설정되어 있지 않으며 100x 빠른 성능을 제공합니다","es":"Descubre cómo Biome reemplaza ESLint y Prettier con una herramienta 100x más rápida y con configuración cero","fr":"Découvrez comment Biome remplace ESLint et Prettier avec un outil 100x plus rapide et sans configuration","de":"Erfahren Sie, wie Biome ESLint und Prettier mit einem 100x schnelleren Tool und null Konfiguration ersetzt","pt":"Aprenda a configurar o Biome, uma ferramenta de desenvolvimento rápida e versátil para projetos web, substituindo ESLint e Prettier","ru":"Узнайте, как настроить Biome, быстрый и универсальный инструмент для веб-проектов, заменяющий ESLint и Prettier","ar":"تعلم كيفية إعداد بيوم، أداة سريعة ومرنة لتطوير الويب، تحل مكان ESLint و Prettier"},"definition":{"en":"Biome is a fast, all-in-one toolchain for web projects written in Rust, providing linting and formatting capabilities with zero-config defaults.","zh":"Biome 是一个基于 Rust 的快速工具链，用于 web 项目，提供 linting 和 formatting 功能","ja":"Biome は、Rust で構築された Web プロジェクト用の高速ツールチェーンで、linting と formatting 機能を提供します","ko":"Biome는 Rust 기반의 빠른 툴체인으로, 웹 프로젝트를 위한 린팅과 포매팅 기능을 제공합니다","es":"Biome es una herramienta de desarrollo web de Rust que proporciona linting y formateo con configuración cero","fr":"Biome est un outil de développement web Rust qui fournit linting et formateo avec configuration zéro","de":"Biome ist ein Webentwicklungstool in Rust, das Linting und Formateo mit null Konfiguration bietet","pt":"O que é Biome? É uma ferramenta de desenvolvimento rápida e versátil para projetos web, escrita em Rust","ru":"Что такое Biome? Это быстрый и универсальный инструмент для веб-проектов, написанный на Rust","ar":"ما هو بيوم؟ هي أداة سريعة ومرنة لتطوير الويب، مكتوبة بلغة روست"},"features":{"en":["Single tool for linting and formatting","100x faster than ESLint","Zero configuration by default","Built-in import sorting","Native monorepo support","VS Code integration"],"zh":["单一工具用于 linting 和 formatting","100x 更快的性能","零配置默认值","内置导入排序","TypeScript 首选设计","部分 Prettier 兼容性"],"ja":["linting と formatting 用の単一ツール","100x高速なパフォーマンス","ゼロコンフィグのデフォルト値","内蔵のインポートソート","TypeScript 最適化設計","一部 Prettier 互換性"],"ko":["린팅과 포매팅을 위한 단일 툴","100x 빠른 성능","기본값이 설정되어 있지 않음","내장된 IMPORT 정렬","타입스크립트 최적화 설계","일부 Prettier 호환성"],"es":["Herramienta única para linting y formateo","100x más rápida que ESLint","Configuración cero por defecto","Compatibilidad parcial con Prettier","Soporte nativo para monorepos","Integración con VS Code"],"fr":["Outil unique pour linting et formateo","100x plus rapide que ESLint","Configuration zéro par défaut","Compatibilité partielle avec Prettier","Support natif pour les monorepos","Intégration avec VS Code"],"de":["Einziges Tool für Linting und Formateo","100x schneller als ESLint","Null Konfiguration standardmäßig","Teilweise Kompatibilität mit Prettier","Native Unterstützung für Monorepos","Integration mit VS Code"],"pt":["Ferramenta única para linting e formatação","100x mais rápido que ESLint","Compatibilidade parcial com Prettier","Suporte nativo a monorepo","Integração com VS Code"],"ru":["Единый инструмент для проверки и форматирования кода","В 100 раз быстрее, чем ESLint","Частичная совместимость с Prettier","Нативная поддержка монорепозитория","Интеграция с VS Code"],"ar":["أداة واحدة للتحقق والتنسيق","100 مرة أسرع من ESLint","توافق جزئي مع Prettier","دعم مدمج ل monorepo","التكامل مع VS Code"]},"keywords":{"en":["how to use biome","biome alternative","biome install","biome vs eslint","biome setup guide","what is biome","biome rust","biome toolchain","biome web development"],"zh":["Biome","Rust","web 项目","linting","formatting","ESLint","Prettier","TypeScript","零配置默认值","100x 更快的性能"],"ja":["Biome","Rust","Web プロジェクト","linting","formatting","ESLint","Prettier","TypeScript","ゼロコンフィグのデフォルト値","100x高速なパフォーマンス","AIエージェント"],"ko":["Biome","Rust","웹 프로젝트","린팅","포매팅","ESLint","Prettier","타입스크립트","기본값이 설정되어 있지 않음","100x 빠른 성능","AI 툴"],"es":["Biome","Herramienta de desarrollo web","Rust","Linting","Formateo","ESLint","Prettier","Configuración cero","Monorepos","VS Code"],"fr":["Biome","Outil de développement web","Rust","Linting","Formateo","ESLint","Prettier","Configuration zéro","Monorepos","VS Code"],"de":["Biome","Webentwicklungstool","Rust","Linting","Formateo","ESLint","Prettier","Null Konfiguration","Monorepos","VS Code"],"pt":["Biome","Ferramenta de desenvolvimento","Rust","ESLint","Prettier","Desenvolvimento web","Linting","Formatação","Monorepo","VS Code"],"ru":["Biome","Инструмент для разработки","Rust","ESLint","Prettier","Веб-разработка","Проверка кода","Форматирование","Монорепозиторий","VS Code","ИИ Агенты"],"ar":["بيوم","أداة تطوير","روست","ESLint","Prettier","تطوير الويب","التحقق","التنسيق","monorepo","VS Code","أدوات الذكاء الاصطناعي"]}},"owner":"olavocarvalho","repo":"engrain","repoPath":"olavocarvalho/engrain","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.339Z","topics":[],"category":"community","skillMd":{"name":"biome","description":"Biome - Fast all-in-one toolchain for web projects (linter + formatter in Rust, 100x faster than ESLint)","version":"1.0.0","tags":"","bodyPreview":"# Biome - Fast All-in-One Toolchain\n\n## Overview\n\nBiome is a fast, all-in-one toolchain for web projects written in Rust. It replaces both ESLint and Prettier with a single tool that''s 100x faster and provides zero-config defaults.\n\n**Key Features**:\n- Single tool for linting and formatting\n- 100x faster than ESLint\n- Zero configuration by default\n- Built-in import sorting\n- TypeScript-first design\n- Partial Prettier compatibility\n- Native monorepo support\n- VS Code integration\n\n**Installation**","body":"# Biome - Fast All-in-One Toolchain\n\n## Overview\n\nBiome is a fast, all-in-one toolchain for web projects written in Rust. It replaces both ESLint and Prettier with a single tool that''s 100x faster and provides zero-config defaults.\n\n**Key Features**:\n- Single tool for linting and formatting\n- 100x faster than ESLint\n- Zero configuration by default\n- Built-in import sorting\n- TypeScript-first design\n- Partial Prettier compatibility\n- Native monorepo support\n- VS Code integration\n\n**Installation**:\n```bash\nnpm install --save-dev @biomejs/biome\n```\n\n## Quick Start\n\n### 1. Initialize Biome\n\n```bash\n# Create biome.json configuration\nnpx @biomejs/biome init\n\n# Check your project\nnpx @biomejs/biome check .\n\n# Fix issues automatically\nnpx @biomejs/biome check --write .\n\n# Format only\nnpx @biomejs/biome format --write .\n\n# Lint only\nnpx @biomejs/biome lint .\n```\n\n### 2. Package.json Scripts\n\n```json\n{\n  \"scripts\": {\n    \"check\": \"biome check .\",\n    \"check:write\": \"biome check --write .\",\n    \"format\": \"biome format --write .\",\n    \"lint\": \"biome lint .\",\n    \"lint:fix\": \"biome lint --write .\"\n  }\n}\n```\n\n### 3. Basic Configuration\n\n```json\n{\n  \"$schema\": \"https://biomejs.dev/schemas/1.9.4/schema.json\",\n  \"vcs\": {\n    \"enabled\": true,\n    \"clientKind\": \"git\",\n    \"useIgnoreFile\": true\n  },\n  \"files\": {\n    \"ignoreUnknown\": false,\n    \"ignore\": [\"node_modules\", \"dist\", \"build\", \".next\"]\n  },\n  \"formatter\": {\n    \"enabled\": true,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2,\n    \"lineWidth\": 100\n  },\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true\n    }\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"quoteStyle\": \"single\",\n      \"semicolons\": \"asNeeded\",\n      \"trailingCommas\": \"all\"\n    }\n  }\n}\n```\n\n## Core Commands\n\n### Check Command (Recommended)\n\nThe `check` command runs both linting and formatting:\n\n```bash\n# Check all files\nbiome check .\n\n# Fix issues automatically\nbiome check --write .\n\n# Unsafe fixes (may change behavior)\nbiome check --write --unsafe .\n\n# Apply suggested fixes\nbiome check --write --unsafe --apply-suggested\n\n# Check specific files\nbiome check src/**/*.ts\n\n# CI mode (exit with error on issues)\nbiome ci .\n```\n\n### Format Command\n\nFormat code without linting:\n\n```bash\n# Format all files\nbiome format --write .\n\n# Check formatting without changing files\nbiome format .\n\n# Format specific files\nbiome format --write src/**/*.{ts,tsx,js,jsx}\n\n# Format stdin\necho \"const x={a:1}\" | biome format --stdin-file-path=file.js\n```\n\n### Lint Command\n\nLint code without formatting:\n\n```bash\n# Lint all files\nbiome lint .\n\n# Fix linting issues\nbiome lint --write .\n\n# Show rule names\nbiome lint --verbose .\n\n# Apply unsafe fixes\nbiome lint --write --unsafe .\n```\n\n## Configuration Deep Dive\n\n### Formatter Configuration\n\n```json\n{\n  \"formatter\": {\n    \"enabled\": true,\n    \"formatWithErrors\": false,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2,\n    \"lineEnding\": \"lf\",\n    \"lineWidth\": 80,\n    \"attributePosition\": \"auto\"\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"quoteStyle\": \"single\",\n      \"jsxQuoteStyle\": \"double\",\n      \"quoteProperties\": \"asNeeded\",\n      \"trailingCommas\": \"all\",\n      \"semicolons\": \"asNeeded\",\n      \"arrowParentheses\": \"always\",\n      \"bracketSpacing\": true,\n      \"bracketSameLine\": false\n    }\n  },\n  \"json\": {\n    \"formatter\": {\n      \"trailingCommas\": \"none\"\n    }\n  }\n}\n```\n\n### Linter Configuration\n\n```json\n{\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true,\n      \"a11y\": {\n        \"recommended\": true,\n        \"noAutofocus\": \"error\",\n        \"useKeyWithClickEvents\": \"warn\"\n      },\n      \"complexity\": {\n        \"recommended\": true,\n        \"noForEach\": \"off\",\n        \"useLiteralKeys\": \"error\"\n      },\n      \"correctness\": {\n        \"recommended\": true,\n        \"noUnusedVariables\": \"error\",\n        \"useExhaustiveDependencies\": \"warn\"\n      },\n      \"performance\": {\n        \"recommended\": true,\n        \"noAccumulatingSpread\": \"warn\"\n      },\n      \"security\": {\n        \"recommended\": true,\n        \"noDangerouslySetInnerHtml\": \"error\"\n      },\n      \"style\": {\n        \"recommended\": true,\n        \"noNonNullAssertion\": \"warn\",\n        \"useConst\": \"error\",\n        \"useTemplate\": \"warn\"\n      },\n      \"suspicious\": {\n        \"recommended\": true,\n        \"noExplicitAny\": \"warn\",\n        \"noArrayIndexKey\": \"error\"\n      }\n    }\n  }\n}\n```\n\n### File Ignore Patterns\n\n```json\n{\n  \"files\": {\n    \"ignore\": [\n      \"node_modules\",\n      \"dist\",\n      \"build\",\n      \".next\",\n      \"coverage\",\n      \"*.min.js\",\n      \"public/assets/**\"\n    ],\n    \"ignoreUnknown\": false,\n    \"include\": [\"src/**/*.ts\", \"src/**/*.tsx\"]\n  }\n}\n```\n\n### Override Configuration for Specific Files\n\n```json\n{\n  \"overrides\": [\n    {\n      \"include\": [\"**/*.test.ts\", \"**/*.spec.ts\"],\n      \"linter\": {\n        \"rules\": {\n          \"suspicious\": {\n            \"noExplicitAny\": \"off\"\n          }\n        }\n      }\n    },\n    {\n      \"include\": [\"scripts/**/*.js\"],\n      \"formatter\": {\n        \"lineWidth\": 120\n      }\n    }\n  ]\n}\n```\n\n## VS Code Integration\n\n### 1. Install Biome Extension\n\n```bash\n# Install from VS Code marketplace\ncode --install-extension biomejs.biome\n```\n\n### 2. VS Code Settings (`.vscode/settings.json`)\n\n```json\n{\n  \"[javascript]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true,\n    \"editor.codeActionsOnSave\": {\n      \"quickfix.biome\": \"explicit\",\n      \"source.organizeImports.biome\": \"explicit\"\n    }\n  },\n  \"[typescript]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true,\n    \"editor.codeActionsOnSave\": {\n      \"quickfix.biome\": \"explicit\",\n      \"source.organizeImports.biome\": \"explicit\"\n    }\n  },\n  \"[typescriptreact]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true\n  },\n  \"[json]\": {\n    \"editor.defaultFormatter\": \"biomejs.biome\",\n    \"editor.formatOnSave\": true\n  },\n  \"biome.lspBin\": \"./node_modules/@biomejs/biome/bin/biome\"\n}\n```\n\n### 3. Workspace Settings\n\n```json\n{\n  \"editor.formatOnSave\": true,\n  \"editor.formatOnPaste\": true,\n  \"editor.defaultFormatter\": \"biomejs.biome\",\n  \"biome.rename\": true,\n  \"files.autoSave\": \"onFocusChange\"\n}\n```\n\n## Migration from ESLint and Prettier\n\n### 1. Remove Old Tools\n\n```bash\n# Remove ESLint and Prettier\nnpm uninstall eslint prettier eslint-config-prettier \\\n  eslint-plugin-react eslint-plugin-import \\\n  @typescript-eslint/parser @typescript-eslint/eslint-plugin\n\n# Remove configuration files\nrm .eslintrc.js .eslintrc.json .prettierrc .prettierignore\n```\n\n### 2. Migrate Configuration\n\nUse Biome''s migration tool:\n\n```bash\n# Migrate from Prettier config\nbiome migrate prettier --write\n\n# Migrate from ESLint config\nbiome migrate eslint --write\n```\n\n### 3. Manual Migration\n\n**Prettier → Biome Formatter**:\n\n```json\n// .prettierrc (old)\n{\n  \"semi\": false,\n  \"singleQuote\": true,\n  \"trailingComma\": \"all\",\n  \"printWidth\": 100\n}\n\n// biome.json (new)\n{\n  \"formatter\": {\n    \"lineWidth\": 100\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"semicolons\": \"asNeeded\",\n      \"quoteStyle\": \"single\",\n      \"trailingCommas\": \"all\"\n    }\n  }\n}\n```\n\n**ESLint → Biome Linter**:\n\n```json\n// .eslintrc.json (old)\n{\n  \"rules\": {\n    \"no-unused-vars\": \"error\",\n    \"prefer-const\": \"warn\"\n  }\n}\n\n// biome.json (new)\n{\n  \"linter\": {\n    \"rules\": {\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\"\n      },\n      \"style\": {\n        \"useConst\": \"warn\"\n      }\n    }\n  }\n}\n```\n\n### 4. Update Scripts\n\n```json\n{\n  \"scripts\": {\n    \"lint\": \"biome lint .\",\n    \"lint:fix\": \"biome lint --write .\",\n    \"format\": \"biome format --write .\",\n    \"check\": \"biome check --write .\"\n  }\n}\n```\n\n## Git Hooks Integration\n\n### Using Husky + lint-staged\n\n```bash\n# Install dependencies\nnpm install --save-dev husky lint-staged\nnpx husky init\n```\n\n**`.husky/pre-commit`**:\n```bash\n#!/usr/bin/env sh\n. \"$(dirname -- \"$0\")/_/husky.sh\"\n\nnpx lint-staged\n```\n\n**`package.json`**:\n```json\n{\n  \"lint-staged\": {\n    \"*.{js,ts,jsx,tsx,json}\": [\n      \"biome check --write --no-errors-on-unmatched\"\n    ]\n  }\n}\n```\n\n### Using Lefthook\n\n**`lefthook.yml`**:\n```yaml\npre-commit:\n  commands:\n    lint:\n      glob: \"*.{js,ts,jsx,tsx,json}\"\n      run: biome check --write --no-errors-on-unmatched {staged_files}\n```\n\n### Simple Git Hook (no dependencies)\n\n**`.git/hooks/pre-commit`**:\n```bash\n#!/bin/bash\n\n# Get staged files\nSTAGED_FILES=$(git diff --cached --name-only --diff-filter=ACM | grep -E ''\\.(js|ts|jsx|tsx|json)$'')\n\nif [ -n \"$STAGED_FILES\" ]; then\n  echo \"Running Biome on staged files...\"\n  npx @biomejs/biome check --write --no-errors-on-unmatched $STAGED_FILES\n\n  # Add formatted files back to staging\n  git add $STAGED_FILES\nfi\n```\n\n## CI/CD Integration\n\n### GitHub Actions\n\n```yaml\nname: Biome CI\n\non:\n  push:\n    branches: [main, develop]\n  pull_request:\n    branches: [main]\n\njobs:\n  biome:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Setup Node.js\n        uses: actions/setup-node@v4\n        with:\n          node-version: ''20''\n          cache: ''npm''\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Run Biome CI\n        run: npx @biomejs/biome ci .\n\n      - name: Check formatting\n        run: npx @biomejs/biome format .\n\n      - name: Lint\n        run: npx @biomejs/biome lint .\n```\n\n### GitLab CI\n\n```yaml\nbiome:\n  image: node:20-alpine\n  stage: test\n  script:\n    - npm ci\n    - npx @biomejs/biome ci .\n  cache:\n    paths:\n      - node_modules/\n  only:\n    - merge_requests\n    - main\n```\n\n### CircleCI\n\n```yaml\nversion: 2.1\n\njobs:\n  biome:\n    docker:\n      - image: cimg/node:20.11\n    steps:\n      - checkout\n      - restore_cache:\n          keys:\n            - deps-{{ checksum \"package-lock.json\" }}\n      - run: npm ci\n      - save_cache:\n          paths:\n            - node_modules\n          key: deps-{{ checksum \"package-lock.json\" }}\n      - run: npx @biomejs/biome ci .\n\nworkflows:\n  test:\n    jobs:\n      - biome\n```\n\n## Import Sorting\n\nBiome includes built-in import sorting:\n\n```bash\n# Organize imports\nbiome check --write --organize-imports-enabled=true .\n```\n\n**Configuration**:\n```json\n{\n  \"organizeImports\": {\n    \"enabled\": true\n  }\n}\n```\n\n**Example**:\n```typescript\n// Before\nimport { useState } from ''react'';\nimport axios from ''axios'';\nimport { Button } from ''./components/Button'';\nimport type { User } from ''./types'';\nimport ''./styles.css'';\n\n// After (sorted)\nimport type { User } from ''./types'';\n\nimport axios from ''axios'';\nimport { useState } from ''react'';\n\nimport { Button } from ''./components/Button'';\n\nimport ''./styles.css'';\n```\n\n## TypeScript Support\n\nBiome has first-class TypeScript support:\n\n```json\n{\n  \"linter\": {\n    \"rules\": {\n      \"suspicious\": {\n        \"noExplicitAny\": \"warn\",\n        \"noUnsafeDeclarationMerging\": \"error\"\n      },\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\"\n      },\n      \"style\": {\n        \"useImportType\": \"error\",\n        \"useExportType\": \"error\"\n      }\n    }\n  }\n}\n```\n\n**Type-aware linting**:\n```typescript\n// Biome detects unused variables\nconst unused = 123; // ❌ Error\n\n// Enforces type imports\nimport { User } from ''./types''; // ❌ Error\nimport type { User } from ''./types''; // ✅ Correct\n\n// Detects unsafe type assertions\nconst num = \"123\" as any as number; // ⚠️ Warning\n```\n\n## Monorepo Support\n\nBiome works great in monorepos:\n\n### Project Structure\n```\nmy-monorepo/\n├── biome.json (root config)\n├── packages/\n│   ├── web/\n│   │   └── biome.json (extends root)\n│   ├── api/\n│   │   └── biome.json\n│   └── shared/\n│       └── biome.json\n```\n\n### Root Configuration\n```json\n{\n  \"$schema\": \"https://biomejs.dev/schemas/1.9.4/schema.json\",\n  \"extends\": [],\n  \"formatter\": {\n    \"enabled\": true,\n    \"indentStyle\": \"space\",\n    \"indentWidth\": 2\n  },\n  \"linter\": {\n    \"enabled\": true,\n    \"rules\": {\n      \"recommended\": true\n    }\n  }\n}\n```\n\n### Package Override\n```json\n{\n  \"extends\": [\"../../biome.json\"],\n  \"formatter\": {\n    \"lineWidth\": 100\n  },\n  \"linter\": {\n    \"rules\": {\n      \"style\": {\n        \"noNonNullAssertion\": \"off\"\n      }\n    }\n  }\n}\n```\n\n### Monorepo Scripts\n```json\n{\n  \"scripts\": {\n    \"check\": \"biome check .\",\n    \"check:packages\": \"biome check packages/*\",\n    \"format\": \"biome format --write .\",\n    \"lint\": \"biome lint packages/*\"\n  }\n}\n```\n\n## Performance Benefits\n\n### Speed Comparison\n\n| Tool | Time (10,000 files) |\n|------|---------------------|\n| ESLint + Prettier | ~60s |\n| Biome | ~0.6s |\n\n**100x faster** on average workloads.\n\n### Caching\n\nBiome includes intelligent caching:\n\n```bash\n# First run (no cache)\nbiome check .  # 1.2s\n\n# Second run (with cache)\nbiome check .  # 0.1s\n\n# Clear cache\nrm -rf node_modules/.cache/biome\n```\n\n### Parallel Processing\n\nBiome uses all CPU cores by default:\n\n```bash\n# Limit CPU cores\nbiome check --max-diagnostics=50 .\n\n# Verbose output\nbiome check --verbose .\n```\n\n## Common Patterns\n\n### React Projects\n\n```json\n{\n  \"linter\": {\n    \"rules\": {\n      \"a11y\": {\n        \"recommended\": true,\n        \"useButtonType\": \"error\",\n        \"useKeyWithClickEvents\": \"error\"\n      },\n      \"correctness\": {\n        \"useExhaustiveDependencies\": \"warn\",\n        \"useHookAtTopLevel\": \"error\"\n      },\n      \"suspicious\": {\n        \"noArrayIndexKey\": \"error\"\n      }\n    }\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"jsxQuoteStyle\": \"double\"\n    }\n  }\n}\n```\n\n### Next.js Projects\n\n```json\n{\n  \"files\": {\n    \"ignore\": [\".next\", \"out\", \"node_modules\"]\n  },\n  \"overrides\": [\n    {\n      \"include\": [\"app/**/*.tsx\", \"pages/**/*.tsx\"],\n      \"linter\": {\n        \"rules\": {\n          \"a11y\": {\n            \"recommended\": true\n          }\n        }\n      }\n    }\n  ]\n}\n```\n\n### Node.js Backend\n\n```json\n{\n  \"linter\": {\n    \"rules\": {\n      \"security\": {\n        \"recommended\": true,\n        \"noGlobalEval\": \"error\"\n      },\n      \"correctness\": {\n        \"noUnusedVariables\": \"error\"\n      }\n    }\n  },\n  \"javascript\": {\n    \"formatter\": {\n      \"semicolons\": \"always\"\n    }\n  }\n}\n```\n\n## Best Practices\n\n1. **Use `biome check`** instead of separate format/lint commands\n2. **Enable `--write`** flag for automatic fixes\n3. **Configure VS Code** for format-on-save\n4. **Add git hooks** to enforce quality before commits\n5. **Use CI mode** (`biome ci`) in continuous integration\n6. **Start with recommended rules** then customize\n7. **Leverage import sorting** to organize imports automatically\n8. **Use overrides** for different file types or directories\n9. **Enable VCS integration** to respect .gitignore\n10. **Keep configuration minimal** - Biome has smart defaults\n\n## Troubleshooting\n\n### Biome Not Formatting\n\n```bash\n# Check if formatter is enabled\nbiome rage\n\n# Verify file is not ignored\nbiome check --verbose src/file.ts\n\n# Check VS Code extension logs\n# View → Output → Biome\n```\n\n### Conflicts with Prettier\n\n```bash\n# Disable Prettier in VS Code settings\n\"[javascript]\": {\n  \"editor.defaultFormatter\": \"biomejs.biome\"\n}\n\n# Remove Prettier dependencies\nnpm uninstall prettier\n```\n\n### Performance Issues\n\n```bash\n# Check cache location\nbiome rage\n\n# Clear cache\nrm -rf node_modules/.cache/biome\n\n# Reduce max diagnostics\nbiome check --max-diagnostics=20 .\n```\n\n### Rule Configuration Not Working\n\n```json\n// Ensure correct category\n{\n  \"linter\": {\n    \"rules\": {\n      \"correctness\": {  // Category name matters\n        \"noUnusedVariables\": \"error\"\n      }\n    }\n  }\n}\n```\n\n## Local Biome Configs (Your Repos)\n\nPatterns from active projects:\n\n- `ai-code-review/biome.json`: `files.includes` targets `src/**/*.ts` and excludes tests, `lineWidth: 100`, single quotes, semicolons always, and `noExplicitAny: warn`.\n- `itinerizer-ts/biome.json`: `files.ignore` includes `node_modules`, `dist`, `.claude`, and data directories; `organizeImports.enabled = true`.\n- `matsuoka-com` and `diogenes` use similar formatting defaults (2-space indent, lineWidth 100).\n\nCommon scripts:\n\n```json\n{\n  \"lint\": \"biome check src/ --diagnostic-level=error\",\n  \"lint:fix\": \"biome check src/ --write\",\n  \"format\": \"biome format src/ --write\"\n}\n```\n\n## Resources\n\n- **Official Docs**: https://biomejs.dev\n- **VS Code Extension**: https://marketplace.visualstudio.com/items?itemName=biomejs.biome\n- **GitHub**: https://github.com/biomejs/biome\n- **Rules Reference**: https://biomejs.dev/linter/rules/\n- **Migration Guide**: https://biomejs.dev/guides/migrate-eslint-prettier/\n\n## Summary\n\n- **Biome** is a fast all-in-one linter and formatter\n- **100x faster** than ESLint + Prettier\n- **Zero config** by default with smart defaults\n- **Built in Rust** for maximum performance\n- **TypeScript-first** with excellent type support\n- **Import sorting** included out of the box\n- **VS Code integration** with official extension\n- **Perfect for** modern web projects, monorepos, CI/CD\n- **Easy migration** from ESLint and Prettier\n"},"lastSynced":"2026-03-08T02:03:24.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing fast and streamlined code linting and formatting with Rust and TypeScript support.","zh":"非常适合需要快速、简化代码linting和格式化的Web开发代理，支持Rust和TypeScript。","ja":"Web開発エージェントが高速でストリームライン化されたコードのlintingとフォーマットが必要な場合に最適です。RustとTypeScriptをサポートしています。","ko":"빠르고 간결한 코드 linting 및 형식 지정이 필요한 웹 개발 에이전트에게 완벽합니다. Rust 및 TypeScript를 지원합니다.","es":"Ideal para Agentes de Desarrollo Web que necesitan linting y formateo de código rápido y optimizado con soporte para Rust y TypeScript.","fr":"Idéal pour les Agents de Développement Web ayant besoin d''un linting et d''un formatage de code rapide et rationalisé avec prise en charge de Rust et TypeScript.","de":"Perfekt für Webentwicklungs-Agents, die schnelles und optimiertes Code-Linting und -Formatierung mit Unterstützung für Rust und TypeScript benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que precisam de linting e formatação de código rápido e otimizado com suporte a Rust e TypeScript.","ru":"Идеально подходит для веб-агентов, которым требуется быстрая и оптимизированная проверка и форматирование кода с поддержкой Rust и TypeScript.","ar":"مثالي للوكلاء التطوير الوب الذين يحتاجون إلى تنسيق وتنسيق رمز سريع وخالي من العيوب مع دعم Rust وTypeScript."},"recommendation":{"en":"Empowers agents to lint and format web project code 100x faster than ESLint, with zero-config defaults, built-in import sorting, and native monorepo support using Rust and TypeScript-first design.","zh":"赋予代理快速linting和格式化网页项目代码的能力，速度比ESLint快100倍，具有零配置默认值、内置导入排序和使用Rust和TypeScript第一设计的原生monorepo支持。","ja":"エージェントに、ESLintよりも100倍高速で、ゼロコンフィグのデフォルト値、ビルトインのインポート整理、RustとTypeScript第一のデザインを使用したネイティブのモノリポサポートを備えた、Webプロジェクトコードのlintingとフォーマットを実行する能力を与えます。","ko":"에이전트에게 ESLint보다 100배 빠른 속도로 웹 프로젝트 코드를 linting 및 형식 지정할 수 있는 능력을 부여하며, 영구 구성 기본값, 내장 가져오기 정렬 및 Rust 및 TypeScript 우선 디자인을 사용하는 네이티브 모노 리포 지원을 제공합니다.","es":"Permite a los agentes realizar linting y formateo del código de proyectos web 100 veces más rápido que ESLint, con configuraciones predeterminadas de cero configuración, ordenamiento de importaciones incorporado y soporte nativo para monorepos utilizando un diseño basado en Rust y centrado en TypeScript.","fr":"Permet aux agents d''effectuer le linting et le formatage du code des projets web 100 fois plus vite qu''ESLint, avec des paramètres par défaut sans configuration, un tri d''importations intégré et une prise en charge native des monorepos grâce à une conception basée sur Rust et axée sur TypeScript.","de":"Ermöglicht Agents, Code von Webprojekten 100-mal schneller als ESLint zu linten und zu formatieren, mit Zero-Config-Standardeinstellungen, integriertem Import-Sorting und nativer Monorepo-Unterstützung durch Rust-basiertes und TypeScript-first Design.","pt":"Habilita os agentes a verificar e formatar o código do projeto da web 100x mais rápido do que o ESLint, com configurações padrão sem configuração, classificação de importação incorporada e suporte nativo a monorepo usando design Rust e TypeScript-first.","ru":"Наделяет агентов возможностью проверять и форматировать код веб-проектов в 100 раз быстрее, чем ESLint, с нулевой настройкой по умолчанию, встроенной сортировкой импорта и родной поддержкой монорепозитория, используя дизайн, ориентированный на Rust и TypeScript.","ar":"يمكّن الوكلاء من فحص وتنسيق رمز مشروع الويب 100x أسرع من ESLint، مع إعدادات افتراضية بدون إعداد، وترتيب الاستيراد المدمج، ودعم مونوريبوزيتوري أصلي باستخدام تصميم Rust و TypeScript-first."},"useCases":{"en":["Replacing ESLint and Prettier with a single, faster tool","Formatting code with partial Prettier compatibility","Integrating with VS Code for seamless development workflows","Optimizing web project performance with zero-config defaults"],"zh":["用单一、更快的工具替换ESLint和Prettier","具有部分Prettier兼容性的代码格式化","与VS Code集成以实现无缝的开发工作流程","使用零配置默认值优化Web项目性能"],"ja":["ESLintとPrettierを1つのより高速なツールに置き換える","一部のPrettier互換性を備えたコードのフォーマット","VS Codeと統合してシームレスな開発ワークフローを実現する","ゼロコンフィグのデフォルト値を使用してWebプロジェクトのパフォーマンスを最適化する"],"ko":["ESLint와 Prettier를 단일하며 더 빠른 도구로 대체","일부 Prettier 호환성을 갖춘 코드 형식 지정","VS Code와 통합하여 무결점 개발 워크플로우를 구현","영구 구성 기본값을 사용하여 웹 프로젝트 성능 최적화"],"es":["Reemplazar ESLint y Prettier con una única herramienta más rápida","Formatear código con compatibilidad parcial de Prettier","Integrar con VS Code para flujos de trabajo de desarrollo perfectos","Optimizar el rendimiento de proyectos web con configuraciones predeterminadas de cero configuración"],"fr":["Remplacer ESLint et Prettier par un outil unique et plus rapide","Formater le code avec une compatibilité partielle de Prettier","Intégration avec VS Code pour des workflows de développement transparents","Optimiser les performances des projets web avec des paramètres par défaut sans configuration"],"de":["Ersetzen von ESLint und Prettier durch ein einziges, schnelleres Tool","Formatieren von Code mit teilweiser Prettier-Kompatibilität","Integration in VS Code für nahtlose Entwicklungsworkflows","Optimieren der Webprojektleistung mit Zero-Config-Standardeinstellungen"],"pt":["Substituir ESLint e Prettier por uma ferramenta única e mais rápida","Formatar código com compatibilidade parcial com Prettier","Integrar com o VS Code para fluxos de trabalho de desenvolvimento transparentes","Otimizar o desempenho do projeto da web com configurações padrão sem configuração"],"ru":["Заменить ESLint и Prettier на один, более быстрый инструмент","Форматировать код с частичной совместимостью с Prettier","Интегрировать с VS Code для бесшовных рабочих процессов разработки","Оптимизировать производительность веб-проекта с нулевой настройкой по умолчанию"],"ar":["استبدال ESLint و Prettier بأداة واحدة وأسرع","تنسيق الرمز مع توافق جزئي مع Prettier","التكامل مع VS Code من أجل سلاسل عمل تطوير متواصلة","تحسين أداء مشروع الويب مع إعدادات افتراضية بدون إعداد"]},"limitations":{"en":["Requires Rust installation","Limited to web projects","Partial Prettier compatibility may require additional configuration"],"zh":["需要Rust安装","仅限于Web项目","部分Prettier兼容性可能需要额外的配置"],"ja":["Rustのインストールが必要","Webプロジェクトのみ","一部のPrettier互換性は、追加のコンフィグが必要になる場合がある"],"ko":["Rust 설치가 필요","웹 프로젝트만 해당","일부 Prettier 호환성은 추가 구성이 필요할 수 있음"],"es":["Requiere la instalación de Rust","Limitado a proyectos web","La compatibilidad parcial con Prettier puede requerir configuración adicional"],"fr":["Nécessite l''installation de Rust","Limité aux projets web","La compatibilité partielle avec Prettier peut nécessiter une configuration supplémentaire"],"de":["Erfordert eine Rust-Installation","Beschränkt auf Webprojekte","Partielle Prettier-Kompatibilität kann zusätzliche Konfiguration erfordern"],"pt":["Requer instalação do Rust","Limitado a projetos da web","A compatibilidade parcial com Prettier pode exigir configuração adicional"],"ru":["Требует установки Rust","Ограничен для веб-проектов","Частичная совместимость с Prettier может потребовать дополнительной настройки"],"ar":["يتطلب تثبيت Rust","محدود لمشاريع الويب","التوافق الجزئي مع Prettier قد يتطلب إعدادات إضافية"]},"version":4},"contentHash":"9c1ebccf003c106d060a43d19ac819a0cece9badc9b7e5cb8354dc6e47b7f59f","qualityScore":50}');
