INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('olavocarvalho/engrain/biome', 'biome', 'olavocarvalho', 'engrain', 'community', 'biome olavocarvalho engrain community Biome is a fast, all-in-one toolchain for web projects written in Rust, replacing ESLint and Prettier. It benefits developers by providing zero-config defaults and 100x faster performance. Biome 是一个快速的、全面的工具链，用于 web 项目，提供零配置默认值和 100x 更快的性能 Biome は、Web プロジェクト用の高速なオールインワントゥールチェーンで、ゼロコンフィグのデフォルト値と 100x高速なパフォーマンスを提供します Biome는 웹 프로젝트를 위한 빠른 모든 툴체인으로, 기본값이 설정되어 있지 않으며 100x 빠른 성능을 제공합니다 Biome es una herramienta de desarrollo web de Rust que combina linting y formateo en una sola herramienta Biome est un outil de développement web Rust qui combine linting et formateo en un seul outil Biome ist ein Webentwicklungstool in Rust, das Linting und Formateo in einem Tool kombiniert O Biome é uma ferramenta de desenvolvimento rápida e versátil para projetos web, escrita em Rust, que substitui ESLint e Prettier Biome - быстрый и универсальный инструмент для веб-проектов, написанный на Rust, заменяющий ESLint и Prettier بيوم هي أداة سريعة ومرنة لتطوير الويب، مكتوبة بلغة روست، تحل مكان ESLint و Prettier how to use biome biome alternative biome install biome vs eslint biome setup guide what is biome biome rust biome toolchain biome web development Biome Rust web 项目 linting formatting ESLint Prettier TypeScript 零配置默认值 100x 更快的性能 Single tool for linting and formatting 100x faster than ESLint Zero configuration by default Built-in import sorting Native monorepo support VS Code integration Biome is a fast, all-in-one toolchain for web projects written in Rust, providing linting and formatting capabilities with zero-config defaults.');
