INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wtyang/basic-antd-vite/ant-design', 'ant-design', 'wtyang', 'basic-antd-vite', 'community', 'ant-design wtyang basic-antd-vite community ant-design is a foundational framework for React-based admin projects, utilizing antd v6 and Vite. It benefits developers seeking efficient UI component management. Ant Design 是一个基于 React 的后台管理项目基础架构，使用 Vite 作为构建工具 Ant Design は React を使用した後台管理プロジェクトの基本構成で、Vite をビルドツールとして使用 Ant Design는 React 기반의 백오피스 관리 프로젝트 기본 구조로 Vite를 빌드 도구로 사용합니다 ant-design es una infraestructura básica para proyectos de administración de backend con React y Vite. Incluye componentes core, theming y tokens ant-design est une infrastructure de base pour les projets de gestion de backend avec React et Vite. Il comprend des composants core, theming et tokens ant-design ist eine Basisinfrastruktur für Backend-Verwaltungsprojekte mit React und Vite. Enthält Core-Komponenten, Theming und Token Ant Design é uma infraestrutura de projeto de administração baseada em React e Antd v6 com Vite Ant Design - это базовая инфраструктура проекта администрирования на основе React и Antd v6 с Vite Ant Design هو مشروع إدارة أساسي مبني على React و Antd v6 مع Vite how to use ant-design with React 18-19 ant-design vs material-ui ant-design setup guide for Vite what is ant-design and its benefits ant-design alternative for admin interfaces installing ant-design for scalable UI components ant-design documentation and tutorials ant-design pro components and their usage ant-design and accessibility best practices Ant Design React Vite 后台管理项目 UI 组件库 antd ant-design-pro CSS-in-JS SSR A11Y 性能优化 Supports core components and theming/tokens with antd@^6 Utilizes CSS-in-JS for styling with tokens Enables Server-Side Rendering (SSR) for improved performance Provides accessibility (a11y) features for compliant UI Integrates with ant-design-pro@^5 for advanced layouts and routing Includes X (AI/chat UI) patterns for enhanced user experience ant-design is a React-based framework providing core components, theming, and CSS-in-JS capabilities for building scalable admin interfaces.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danieledelgiudice/shiny-disco/laravel-specialist', 'community', 'danieledelgiudice', 'shiny-disco', 'danieledelgiudice/shiny-disco', 'laravel-specialist', 0, 0, 50, '2026-03-08T01:57:15.341Z', '2026-03-08T02:03:28.018Z', '5e85c1de4e904e51d620eb680c7069b4041fc3321c3c5c4d9122007877d930e9', '{"id":"danieledelgiudice/shiny-disco/laravel-specialist","name":"laravel-specialist","description":{"en":"The Laravel Specialist skill enables senior PHP engineers to build scalable Laravel 10+ applications with Eloquent ORM and modern PHP 8.2+ development. Ideal for experienced developers and legal consulting firms.","zh":"Laravel Specialist 是一名高级 Laravel 工程师，具有 10+ 年的 Laravel 经验，专门从事 Laravel 10+、Eloquent ORM 和现代 PHP 8.2+ 开发","ja":"Laravel Specialist は、10 年以上の Laravel 経験を持つシニア Laravel エンジニアで、Laravel 10+、Eloquent ORM、modern PHP 8.2+ 開発を専門としています","ko":"Laravel Specialist는 10년 이상의 Laravel 경험을 가진 시니어 Laravel 엔지니어로, Laravel 10+, Eloquent ORM 및 현대적인 PHP 8.2+ 개발을 전문으로 합니다","es":"El especialista en Laravel es un ingeniero senior con experiencia en Laravel 10+, Eloquent ORM y desarrollo de PHP 8.2+","fr":"Le spécialiste Laravel est un ingénieur senior avec une expérience approfondie en Laravel 10+, Eloquent ORM et développement PHP 8.2+","de":"Der Laravel-Spezialist ist ein Senior-Ingenieur mit Erfahrung in Laravel 10+, Eloquent ORM und moderner PHP-Entwicklung","pt":"O Laravel Specialist é um especialista sênior em Laravel com experiência em Eloquent ORM e PHP 8.2+ para gerenciar aplicações legais.","ru":"ИИ Агент Laravel Specialist - это старший специалист по Laravel с опытом работы с Eloquent ORM и PHP 8.2+ для управления юридическими приложениями.","ar":"Laravel Specialist هو محترف أول في Laravel ذو خبرة في Eloquent ORM و PHP 8.2+ لتدبير التطبيقات القانونية."},"seo":{"title":{"en":"Laravel Specialist: Expert Laravel 10+ Devel