INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danieledelgiudice/shiny-disco/laravel-specialist', 'laravel-specialist', 'danieledelgiudice', 'shiny-disco', 'community', 'laravel-specialist danieledelgiudice shiny-disco community The Laravel Specialist skill enables senior PHP engineers to build scalable Laravel 10+ applications with Eloquent ORM and modern PHP 8.2+ development. Ideal for experienced developers and legal consulting firms. Laravel Specialist 是一名高级 Laravel 工程师，具有 10+ 年的 Laravel 经验，专门从事 Laravel 10+、Eloquent ORM 和现代 PHP 8.2+ 开发 Laravel Specialist は、10 年以上の Laravel 経験を持つシニア Laravel エンジニアで、Laravel 10+、Eloquent ORM、modern PHP 8.2+ 開発を専門としています Laravel Specialist는 10년 이상의 Laravel 경험을 가진 시니어 Laravel 엔지니어로, Laravel 10+, Eloquent ORM 및 현대적인 PHP 8.2+ 개발을 전문으로 합니다 El especialista en Laravel es un ingeniero senior con experiencia en Laravel 10+, Eloquent ORM y desarrollo de PHP 8.2+ Le spécialiste Laravel est un ingénieur senior avec une expérience approfondie en Laravel 10+, Eloquent ORM et développement PHP 8.2+ Der Laravel-Spezialist ist ein Senior-Ingenieur mit Erfahrung in Laravel 10+, Eloquent ORM und moderner PHP-Entwicklung O Laravel Specialist é um especialista sênior em Laravel com experiência em Eloquent ORM e PHP 8.2+ para gerenciar aplicações legais. ИИ Агент Laravel Specialist - это старший специалист по Laravel с опытом работы с Eloquent ORM и PHP 8.2+ для управления юридическими приложениями. Laravel Specialist هو محترف أول في Laravel ذو خبرة في Eloquent ORM و PHP 8.2+ لتدبير التطبيقات القانونية. how to use laravel-specialist what is laravel-specialist laravel-specialist alternative laravel-specialist vs lumen laravel-specialist install guide laravel-specialist setup for legal consulting firms expert laravel 10+ development eloquent orm tutorial php 8.2+ development best practices Laravel Specialist Laravel 10+ Eloquent ORM 现代 PHP 8.2+ API 资源 队列系统 AIエージェント Builds elegant, scalable Laravel 10+ applications Implements Eloquent models and API resources Utilizes queue systems for efficient task management Develops with modern PHP 8.2+ and Laravel patterns Creates powerful features for administrative and commercial management Laravel-specialist is a senior PHP engineer skill with deep expertise in Laravel 10+, Eloquent ORM, and modern PHP 8.2+ development for administrative and commercial management applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MetaCubeX/metacubexd/openspec-bulk-archive-change', 'community', 'MetaCubeX', 'metacubexd', 'MetaCubeX/metacubexd', 'openspec-bulk-archive-change', 0, 0, 50, '2026-03-08T01:57:15.346Z', '2026-03-08T02:03:36.794Z', 'f42ab9c99f56c5646d109e7fe94407c25e847ea12c8b43facc8ea42ddc488c72', '{"id":"MetaCubeX/metacubexd/openspec-bulk-archive-change","name":"openspec-bulk-archive-change","description":{"en":"The openspec-bulk-archive-change skill enables developers to archive multiple completed changes in a single operation, handling spec conflicts by checking the codebase. This skill benefits developers working with the Mihomo Dashboard.","zh":"openspec-bulk-archive-change允许您批量存档已完成的更改，并智能处理Spec冲突","ja":"openspec-bulk-archive-changeは、Specのコンフリクトをスマートに処理し、複数の変更を一括でアーカイブする機能を提供します","ko":"openspec-bulk-archive-change는 Spec 충돌을智能하게 처리하고 여러 변경 사항을 일괄적으로 보관할 수 있는 기능을 제공합니다","es":"openspec-bulk-archive-change es una habilidad que permite archivar múltiples cambios en una sola operación, manejando conflictos de especificaciones de forma inteligente","fr":"openspec-bulk-archive-change est une compétence qui permet d''archiver plusieurs changements en une seule opération, en gérant de manière intelligente les conflits de spécifications","de":"openspec-bulk-archive-change ist eine Fähigkeit, die das Archivieren mehrerer Änderungen in einer einzigen Operation ermöglicht, indem sie Spezifikationskonflikte intelligent handhabt","pt":"O openspec-bulk-archive-change é uma habilidade que permite arquivar múltiplas alterações em uma operação, lidando com conflitos de especificações de forma inteligente.","ru":"openspec-bulk-archive-change - это навык, который позволяет архивировать несколько изменений в одну операцию, обрабатывая конфликты спецификаций интеллектуально.","ar":"openspec-bulk-archive-change هو مهارة يسمح بارشفة العديد من التغييرات في عملية واحدة، ويتعامل مع تضارب المواصفات بذكاء."},"seo":{"title":{"en":"openspec-bulk-archive-change: Bulk Archive Setup Guide | ...","zh":"openspec-bulk-archive-change_SETUP GUIDE","ja":"openspec-bulk-archive-change_BEST PRACTICES","ko":"openspec-bulk-archive-change_SETUP TUTORIAL","es":"Guía de configuración de openspec-bulk-archive-change par...","fr":"Guide d''installation d''openspec-bulk-archive-change pour ...","de":"Einrichtungsleitfaden für openspec-bulk-archive-change fü...","pt":"Guia de Configuração do openspec-bulk-archive-change: Arq...","ru":"ИИ Агенты: Настройка openspec-bulk-archive-change для Арх...","ar":"إعداد openspec-bulk-archive-change: دليل ارشفة التغييرات ..."},"description":{"en":"Discover how openspec-bulk-archive-change streamlines batch archiving with intelligent spec conflict resolution - learn how to get started today!","zh":"使用openspec-bulk-archive-change智能处理Spec冲突，批量存档已完成的更改","ja":"openspec-bulk-archive-changeを使用してSpecのコンフリクトをスマートに処理し、複数の変更を一括でアーカイブする","ko":"openspec-bulk-archive-change를 사용하여 Spec 충돌을智能하게 처리하고 여러 변경 사항을 일괄적으로 보관합니다","es":"Aprende a archivar cambios múltiples con openspec-bulk-archive-change, una herramienta de inteligencia artificial para desarrolladores","fr":"Découvrez comment archiver plusieurs changements avec openspec-bulk-archive-change, un outil d''intelligence artificielle pour les développeurs","de":"Erfahren Sie, wie Sie mehrere Änderungen mit openspec-bulk-archive-change archivieren, einem KI-Tool für Entwickler","pt":"Aprenda a configurar o openspec-bulk-archive-change para arquivar múltiplas alterações em uma operação. Veja como automatizar o processo com a ferramenta Ask...","ru":"Узнайте, как настроить openspec-bulk-archive-change для архивации нескольких изменений в одну операцию. Автоматизируйте процесс с помощью инструмента AskUser...","ar":"تعلم كيفية إعداد openspec-bulk-archive-change لارشفة العديد من التغييرات في عملية واحدة. شاهد كيفية تلقين العملية باستخدام أداة AskUserQuestion."},"definition":{"en":"openspec-bulk-archive-change is a skill that allows batch archiving of completed changes, intelligently resolving spec conflicts by analyzing the codebase.","zh":"openspec-bulk-archive-change是一种AI工具，用于批量存档已完成的更改并处理Spec冲突","ja":"openspec-bulk-archive-changeは、AIエージェントの一種で、複数の変更を一括でアーカイブし、Specのコンフリクトを処理する","ko":"openspec-bulk-archive-change는 AI 에이전트의 일종으로 여러 변경 사항을 일괄적으로 보관하고 Spec 충돌을 처리합니다","es":"openspec-bulk-archive-change es una herramienta de inteligencia artificial que archiva cambios múltiples de forma inteligente","fr":"openspec-bulk-archive-change est un outil d''intelligence artificielle qui archive plusieurs changements de manière intelligente","de":"openspec-bulk-archive-change ist ein KI-Tool, das mehrere Änderungen intelligent archiviert","pt":"O que é openspec-bulk-archive-change? É uma habilidade de arquivamento em lote que lida com conflitos de especificações.","ru":"Что такое openspec-bulk-archive-change? Это навык архивации пакетов, обрабатывающий конфликты спецификаций.","ar":"ما هو openspec-bulk-archive-change? هو مهارة أرشفة بالجملة التي تتعامل مع تضارب المواصفات."},"features":{"en":["Runs `openspec list --json` to retrieve all active changes","Utilizes the AskUserQuestion tool for multi-select change selection","Promptly informs users when no active changes exist","Handles spec conflicts by checking the codebase","Supports batch archiving of multiple completed changes in a single operation"],"zh":["批量存档已完成的更改","智能处理Spec冲突","使用openspec list --json获取所有活动更改","使用AskUserQuestion工具进行多选提示","支持CLI命令"],"ja":["複数の変更を一括でアーカイブする","Specのコンフリクトをスマートに処理する","openspec list --jsonを使用してすべてのアクティブな変更を取得する","AskUserQuestionツールを使用してマルチセレクト提示を行う","CLIコマンドをサポートする"],"ko":["여러 변경 사항을 일괄적으로 보관한다","Spec 충돌을智能하게 처리한다","openspec list --json을 사용하여 모든 활성 변경 사항을 가져온다","AskUserQuestion 툴을 사용하여 멀티 선택提示을 한다","CLI 명령어를 지원한다"],"es":["Archivado múltiple de cambios en una sola operación","Manejo inteligente de conflictos de especificaciones","Uso de la herramienta AskUserQuestion para selección de cambios","Compatibilidad con el comando openspec list --json","Detección automática de cambios activos","Soporte para selección múltiple de cambios"],"fr":["Archivage multiple de changements en une seule opération","Gestion intelligente des conflits de spécifications","Utilisation de l''outil AskUserQuestion pour la sélection de changements","Compatibilité avec la commande openspec list --json","Détection automatique des changements actifs","Prise en charge de la sélection multiple de changements"],"de":["Mehrere Änderungen in einer einzigen Operation archivieren","Intelligente Handhabung von Spezifikationskonflikten","Verwendung der AskUserQuestion-Tool für die Auswahl von Änderungen","Kompatibilität mit dem Befehl openspec list --json","Automatische Erkennung von aktiven Änderungen","Unterstützung für die Auswahl von mehreren Änderungen"],"pt":["Arquivamento em lote de alterações","Lidando com conflitos de especificações de forma inteligente","Utiliza a ferramenta AskUserQuestion para seleção de alterações","Executa o comando `openspec list --json` para obter alterações ativas","Verifica a implementação no código para resolver conflitos","Permite a automação do processo de arquivamento"],"ru":["Пакетная архивация изменений","Обработка конфликтов спецификаций интеллектуально","Использует инструмент AskUserQuestion для выбора изменений","Выполняет команду `openspec list --json` для получения активных изменений","Проверяет реализацию в коде для решения конфликтов","Позволяет автоматизировать процесс архивации"],"ar":["أرشفة التغييرات بالجملة","التعامل مع تضارب المواصفات بذكاء","استخدام أداة AskUserQuestion لتحديد التغييرات","تنفيذ الأمر `openspec list --json` للحصول على التغييرات النشطة","التحقق من التنفيذ في الكود لحل تضارب","السماح بتلقين عملية الأرشفة"]},"keywords":{"en":["how to use openspec-bulk-archive-change","openspec-bulk-archive-change setup guide","what is openspec-bulk-archive-change","openspec-bulk-archive-change alternative","openspec-bulk-archive-change vs competing tools","openspec-bulk-archive-change install"],"zh":["openspec-bulk-archive-change","AI工具","批量存档","Spec冲突","CLI命令","openspec list --json","AskUserQuestion工具"],"ja":["openspec-bulk-archive-change","AIエージェント","一括アーカイブ","Specコンフリクト","CLIコマンド","openspec list --json","AskUserQuestionツール"],"ko":["openspec-bulk-archive-change","AI 에이전트","일괄 보관","Spec 충돌","CLI 명령어","openspec list --json","AskUserQuestion 툴"],"es":["openspec-bulk-archive-change","herramientas de inteligencia artificial para desarrolladores","archivado de cambios","manejo de conflictos de especificaciones","AskUserQuestion","openspec list --json","desarrollo de software","productividad para desarrolladores"],"fr":["openspec-bulk-archive-change","outils d''intelligence artificielle pour les développeurs","archivage de changements","gestion de conflits de spécifications","AskUserQuestion","openspec list --json","développement de logiciels","productivité pour les développeurs"],"de":["openspec-bulk-archive-change","KI-Tools für Entwickler","Archivierung von Änderungen","Handhabung von Spezifikationskonflikten","AskUserQuestion","openspec list --json","Software-Entwicklung","Produktivität für Entwickler"],"pt":["openspec-bulk-archive-change","arquivamento em lote","conflitos de especificações","AskUserQuestion","CLI","automatização de processos","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["openspec-bulk-archive-change","пакетная архивация","конфликты спецификаций","AskUserQuestion","CLI","автоматизация процессов","разработка программного обеспечения","инструменты разработки"],"ar":["openspec-bulk-archive-change","أرشفة بالجملة","تضارب المواصفات","AskUserQuestion","CLI","تلقين العمليات","تطوير البرمجيات","أدوات التطوير"]}},"owner":"MetaCubeX","repo":"metacubexd","repoPath":"MetaCubeX/metacubexd","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.346Z","topics":[],"category":"community","skillMd":{"name":"openspec-bulk-archive-change","description":"Archive multiple completed changes at once. Use when archiving several parallel changes.","version":"1.0","bodyPreview":"Archive multiple completed changes in a single operation.\n\nThis skill allows you to batch-archive changes, handling spec conflicts intelligently by checking the codebase to determine what''s actually implemented.\n\n**Input**: None required (prompts for selection)\n\n**Steps**\n\n1. **Get active changes**\n\n   Run `openspec list --json` to get all active changes.\n\n   If no active changes exist, inform user and stop.\n\n2. **Prompt for change selection**\n\n   Use **AskUserQuestion tool** with multi-select t","body":"Archive multiple completed changes in a single operation.\n\nThis skill allows you to batch-archive changes, handling spec conflicts intelligently by checking the codebase to determine what''s actually implemented.\n\n**Input**: None required (prompts for selection)\n\n**Steps**\n\n1. **Get active changes**\n\n   Run `openspec list --json` to get all active changes.\n\n   If no active changes exist, inform user and stop.\n\n2. **Prompt for change selection**\n\n   Use **AskUserQuestion tool** with multi-select to let user choose changes:\n   - Show each change with its schema\n   - Include an option for \"All changes\"\n   - Allow any number of selections (1+ works, 2+ is the typical use case)\n\n   **IMPORTANT**: Do NOT auto-select. Always let the user choose.\n\n3. **Batch validation - gather status for all selected changes**\n\n   For each selected change, collect:\n\n   a. **Artifact status** - Run `openspec status --change \"<name>\" --json`\n   - Parse `schemaName` and `artifacts` list\n   - Note which artifacts are `done` vs other states\n\n   b. **Task completion** - Read `openspec/changes/<name>/tasks.md`\n   - Count `- [ ]` (incomplete) vs `- [x]` (complete)\n   - If no tasks file exists, note as \"No tasks\"\n\n   c. **Delta specs** - Check `openspec/changes/<name>/specs/` directory\n   - List which capability specs exist\n   - For each, extract requirement names (lines matching `### Requirement: <name>`)\n\n4. **Detect spec conflicts**\n\n   Build a map of `capability -> [changes that touch it]`:\n\n   ```\n   auth -> [change-a, change-b]  <- CONFLICT (2+ changes)\n   api  -> [change-c]            <- OK (only 1 change)\n   ```\n\n   A conflict exists when 2+ selected changes have delta specs for the same capability.\n\n5. **Resolve conflicts agentically**\n\n   **For each conflict**, investigate the codebase:\n\n   a. **Read the delta specs** from each conflicting change to understand what each claims to add/modify\n\n   b. **Search the codebase** for implementation evidence:\n   - Look for code implementing requirements from each delta spec\n   - Check for related files, functions, or tests\n\n   c. **Determine resolution**:\n   - If only one change is actually implemented -> sync that one''s specs\n   - If both implemented -> apply in chronological order (older first, newer overwrites)\n   - If neither implemented -> skip spec sync, warn user\n\n   d. **Record resolution** for each conflict:\n   - Which change''s specs to apply\n   - In what order (if both)\n   - Rationale (what was found in codebase)\n\n6. **Show consolidated status table**\n\n   Display a table summarizing all changes:\n\n   ```\n   | Change               | Artifacts | Tasks | Specs   | Conflicts | Status |\n   |---------------------|-----------|-------|---------|-----------|--------|\n   | schema-management   | Done      | 5/5   | 2 delta | None      | Ready  |\n   | project-config      | Done      | 3/3   | 1 delta | None      | Ready  |\n   | add-oauth           | Done      | 4/4   | 1 delta | auth (!)  | Ready* |\n   | add-verify-skill    | 1 left    | 2/5   | None    | None      | Warn   |\n   ```\n\n   For conflicts, show the resolution:\n\n   ```\n   * Conflict resolution:\n     - auth spec: Will apply add-oauth then add-jwt (both implemented, chronological order)\n   ```\n\n   For incomplete changes, show warnings:\n\n   ```\n   Warnings:\n   - add-verify-skill: 1 incomplete artifact, 3 incomplete tasks\n   ```\n\n7. **Confirm batch operation**\n\n   Use **AskUserQuestion tool** with a single confirmation:\n   - \"Archive N changes?\" with options based on status\n   - Options might include:\n     - \"Archive all N changes\"\n     - \"Archive only N ready changes (skip incomplete)\"\n     - \"Cancel\"\n\n   If there are incomplete changes, make clear they''ll be archived with warnings.\n\n8. **Execute archive for each confirmed change**\n\n   Process changes in the determined order (respecting conflict resolution):\n\n   a. **Sync specs** if delta specs exist:\n   - Use the openspec-sync-specs approach (agent-driven intelligent merge)\n   - For conflicts, apply in resolved order\n   - Track if sync was done\n\n   b. **Perform the archive**:\n\n   ```bash\n   mkdir -p openspec/changes/archive\n   mv openspec/changes/<name> openspec/changes/archive/YYYY-MM-DD-<name>\n   ```\n\n   c. **Track outcome** for each change:\n   - Success: archived successfully\n   - Failed: error during archive (record error)\n   - Skipped: user chose not to archive (if applicable)\n\n9. **Display summary**\n\n   Show final results:\n\n   ```\n   ## Bulk Archive Complete\n\n   Archived 3 changes:\n   - schema-management-cli -> archive/2026-01-19-schema-management-cli/\n   - project-config -> archive/2026-01-19-project-config/\n   - add-oauth -> archive/2026-01-19-add-oauth/\n\n   Skipped 1 change:\n   - add-verify-skill (user chose not to archive incomplete)\n\n   Spec sync summary:\n   - 4 delta specs synced to main specs\n   - 1 conflict resolved (auth: applied both in chronological order)\n   ```\n\n   If any failures:\n\n   ```\n   Failed 1 change:\n   - some-change: Archive directory already exists\n   ```\n\n**Conflict Resolution Examples**\n\nExample 1: Only one implemented\n\n```\nConflict: specs/auth/spec.md touched by [add-oauth, add-jwt]\n\nChecking add-oauth:\n- Delta adds \"OAuth Provider Integration\" requirement\n- Searching codebase... found src/auth/oauth.ts implementing OAuth flow\n\nChecking add-jwt:\n- Delta adds \"JWT Token Handling\" requirement\n- Searching codebase... no JWT implementation found\n\nResolution: Only add-oauth is implemented. Will sync add-oauth specs only.\n```\n\nExample 2: Both implemented\n\n```\nConflict: specs/api/spec.md touched by [add-rest-api, add-graphql]\n\nChecking add-rest-api (created 2026-01-10):\n- Delta adds \"REST Endpoints\" requirement\n- Searching codebase... found src/api/rest.ts\n\nChecking add-graphql (created 2026-01-15):\n- Delta adds \"GraphQL Schema\" requirement\n- Searching codebase... found src/api/graphql.ts\n\nResolution: Both implemented. Will apply add-rest-api specs first,\nthen add-graphql specs (chronological order, newer takes precedence).\n```\n\n**Output On Success**\n\n```\n## Bulk Archive Complete\n\nArchived N changes:\n- <change-1> -> archive/YYYY-MM-DD-<change-1>/\n- <change-2> -> archive/YYYY-MM-DD-<change-2>/\n\nSpec sync summary:\n- N delta specs synced to main specs\n- No conflicts (or: M conflicts resolved)\n```\n\n**Output On Partial Success**\n\n```\n## Bulk Archive Complete (partial)\n\nArchived N changes:\n- <change-1> -> archive/YYYY-MM-DD-<change-1>/\n\nSkipped M changes:\n- <change-2> (user chose not to archive incomplete)\n\nFailed K changes:\n- <change-3>: Archive directory already exists\n```\n\n**Output When No Changes**\n\n```\n## No Changes to Archive\n\nNo active changes found. Use `/opsx:new` to create a new change.\n```\n\n**Guardrails**\n\n- Allow any number of changes (1+ is fine, 2+ is the typical use case)\n- Always prompt for selection, never auto-select\n- Detect spec conflicts early and resolve by checking codebase\n- When both changes are implemented, apply specs in chronological order\n- Skip spec sync only when implementation is missing (warn user)\n- Show clear per-change status before confirming\n- Use single confirmation for entire batch\n- Track and report all outcomes (success/skip/fail)\n- Preserve .openspec.yaml when moving to archive\n- Archive directory target uses current date: YYYY-MM-DD-<name>\n- If archive target exists, fail that change but continue with others\n"},"lastSynced":"2026-03-08T02:03:36.794Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient change management and archiving capabilities in Mihomo Dashboard environments.","zh":"非常适合需要在 Mihomo Dashboard 环境中高效进行变更管理和存档的开发代理。","ja":"Mihomo Dashboard 環境で効率的な変更管理とアーカイブ機能が必要な開発エージェントに最適です。","ko":"Mihomo Dashboard 환경에서 효율적인 변경 관리와 아카이브 기능이 필요한 개발 에이전트에게 완벽한 솔루션입니다.","es":"Perfecto para agentes de desarrollo que necesitan un manejo de cambios eficiente y capacidades de archivado en entornos de Mihomo Dashboard.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de changements efficace et de capacités d''archivage dans les environnements Mihomo Dashboard.","de":"Perfekt für Entwicklungssagenten, die ein effizientes Change-Management und Archivierungsfähigkeiten in Mihomo Dashboard-Umgebungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de alterações eficiente e capacidades de arquivamento em ambientes do Mihomo Dashboard.","ru":"Идеально подходит для агентов разработки, которым необходим эффективный менеджмент изменений и возможности архивации в средах Mihomo Dashboard.","ar":"مثالي لعمليات التطوير التي تحتاج إلى إدارة تغييرات فعالة وقدرات أرشفة في بيئات لوحة تحكم Mihomo."},"recommendation":{"en":"Empowers agents to batch-archive completed changes, handling spec conflicts by intelligently checking the codebase, utilizing the `openspec list --json` command for seamless integration and automated conflict resolution through codebase analysis.","zh":"赋予代理批量存档已完成的更改的能力，通过智能检查代码库，利用 `openspec list --json` 命令实现无缝集成和自动化冲突解决。","ja":"エージェントが完了した変更をバッチでアーカイブできるようにし、コードベースを智能的にチェックして `openspec list --json` コマンドを利用してシームレスに統合し、自動的にコンフリクトを解決します。","ko":"에이전트가 완료된 변경을 일괄 아카이브할 수 있는 능력을 부여하며, 코드베이스를智能的に 확인하고 `openspec list --json` 명령을 사용하여 무중단 통합 및 자동화된 충돌 해결을 제공합니다.","es":"Habilita a los agentes a archivar por lotes los cambios completados, manejando conflictos de especificaciones mediante la verificación inteligente del código base, utilizando el comando `openspec list --json` para una integración sin problemas y una resolución automática de conflictos a través del análisis del código base.","fr":"Autonomise les agents pour archiver par lots les changements terminés, gérant les conflits de spécifications en vérifiant de manière intelligente la base de code, en utilisant la commande `openspec list --json` pour une intégration transparente et une résolution automatisée des conflits via l''analyse de la base de code.","de":"Ermächtigt Agenten, abgeschlossene Änderungen in Batches zu archivieren, Spezifikationskonflikte durch intelligente Überprüfung des Codebases zu bearbeiten, unter Verwendung des Befehls `openspec list --json` für eine nahtlose Integration und automatisierte Konfliktlösung durch Codebase-Analyse.","pt":"Permite que os agentes arquivem em lote alterações concluídas, lidando com conflitos de especificação ao verificar inteligentemente a base de código, utilizando o comando `openspec list --json` para integração transparente e resolução automática de conflitos por meio da análise da base de código.","ru":"Позволяет агентам архивировать завершенные изменения пакетно, обрабатывая конфликты спецификаций путем интеллектуальной проверки кодовой базы, используя команду `openspec list --json` для бесшовной интеграции и автоматического разрешения конфликтов посредством анализа кодовой базы.","ar":"تمكن الوكلاء من أرشفة التغييرات المكتملة بشكل.mousePosition، ومعالجة تضارب المواصفات عن طريق الفحص الذكي للقاعدة البرمجية، واستخدام الأمر `openspec list --json` من أجل التكامل السلس والتصالح التلقائي للتضارب من خلال تحليل القاعدة البرمجية."},"useCases":{"en":["Batch-archiving multiple completed changes","Automating spec conflict resolution","Streamlining Mihomo Dashboard workflows"],"zh":["批量存档多个已完成的更改","自动化规格冲突解决","简化 Mihomo Dashboard 工作流"],"ja":["複数の完了した変更をバッチでアーカイブする","仕様のコンフリクトを自動化して解決する","Mihomo Dashboard のワークフローを最適化する"],"ko":["여러 개의 완료된 변경을 일괄 아카이브하는 것","명세의 충돌을 자동화하여 해결하는 것","Mihomo Dashboard 워크플로우를 최적화하는 것"],"es":["Archivado por lotes de varios cambios completados","Automatización de la resolución de conflictos de especificaciones","Optimización de los flujos de trabajo de Mihomo Dashboard"],"fr":["Archivage par lots de plusieurs changements terminés","Automatisation de la résolution de conflits de spécifications","Optimisation des flux de travail de Mihomo Dashboard"],"de":["Batch-Archivierung mehrerer abgeschlossener Änderungen","Automatisierung der Konfliktlösung von Spezifikationen","Optimierung der Mihomo Dashboard-Arbeitsabläufe"],"pt":["Arquivamento em lote de várias alterações concluídas","Automatização da resolução de conflitos de especificação","Otimização dos fluxos de trabalho do Mihomo Dashboard"],"ru":["Пакетное архивирование нескольких завершенных изменений","Автоматизация разрешения конфликтов спецификаций","Оптимизация рабочих процессов Mihomo Dashboard"],"ar":["أرشفة تغييرات متعددة مكتملة بشكل.mousePosition","تأليف حل تضارب المواصفات","تبسيط سير عمل لوحة تحكم Mihomo"]},"limitations":{"en":["Requires access to Mihomo Dashboard","Dependent on `openspec list --json` command functionality"],"zh":["需要访问 Mihomo Dashboard","依赖于 `openspec list --json` 命令的功能"],"ja":["Mihomo Dashboard にアクセスする必要がある","`openspec list --json` コマンドの機能に依存する"],"ko":["Mihomo Dashboard에 접근할 수 있어야 함","`openspec list --json` 명령의 기능에 의존함"],"es":["Requiere acceso a Mihomo Dashboard","Dependiente de la funcionalidad del comando `openspec list --json`"],"fr":["Nécessite un accès à Mihomo Dashboard","Dépend de la fonctionnalité de la commande `openspec list --json`"],"de":["Erfordert Zugriff auf Mihomo Dashboard","Abhängig von der Funktionalität des Befehls `openspec list --json`"],"pt":["Requer acesso ao Mihomo Dashboard","Dependente da funcionalidade do comando `openspec list --json`"],"ru":["Требует доступа к Mihomo Dashboard","Зависит от функциональности команды `openspec list --json`"],"ar":["يتطلب الوصول إلى لوحة تحكم Mihomo","يعتمد على وظيفة الأمر `openspec list --json`"]},"version":4},"contentHash":"f42ab9c99f56c5646d109e7fe94407c25e847ea12c8b43facc8ea42ddc488c72","qualityScore":50}');
