INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MetaCubeX/metacubexd/openspec-bulk-archive-change', 'openspec-bulk-archive-change', 'MetaCubeX', 'metacubexd', 'community', 'openspec-bulk-archive-change MetaCubeX metacubexd community The openspec-bulk-archive-change skill enables developers to archive multiple completed changes in a single operation, handling spec conflicts by checking the codebase. This skill benefits developers working with the Mihomo Dashboard. openspec-bulk-archive-change允许您批量存档已完成的更改，并智能处理Spec冲突 openspec-bulk-archive-changeは、Specのコンフリクトをスマートに処理し、複数の変更を一括でアーカイブする機能を提供します openspec-bulk-archive-change는 Spec 충돌을智能하게 처리하고 여러 변경 사항을 일괄적으로 보관할 수 있는 기능을 제공합니다 openspec-bulk-archive-change es una habilidad que permite archivar múltiples cambios en una sola operación, manejando conflictos de especificaciones de forma inteligente openspec-bulk-archive-change est une compétence qui permet d''archiver plusieurs changements en une seule opération, en gérant de manière intelligente les conflits de spécifications openspec-bulk-archive-change ist eine Fähigkeit, die das Archivieren mehrerer Änderungen in einer einzigen Operation ermöglicht, indem sie Spezifikationskonflikte intelligent handhabt O openspec-bulk-archive-change é uma habilidade que permite arquivar múltiplas alterações em uma operação, lidando com conflitos de especificações de forma inteligente. openspec-bulk-archive-change - это навык, который позволяет архивировать несколько изменений в одну операцию, обрабатывая конфликты спецификаций интеллектуально. openspec-bulk-archive-change هو مهارة يسمح بارشفة العديد من التغييرات في عملية واحدة، ويتعامل مع تضارب المواصفات بذكاء. how to use openspec-bulk-archive-change openspec-bulk-archive-change setup guide what is openspec-bulk-archive-change openspec-bulk-archive-change alternative openspec-bulk-archive-change vs competing tools openspec-bulk-archive-change install openspec-bulk-archive-change AI工具 批量存档 Spec冲突 CLI命令 openspec list --json AskUserQuestion工具 Runs `openspec list --json` to retrieve all active changes Utilizes the AskUserQuestion tool for multi-select change selection Promptly informs users when no active changes exist Handles spec conflicts by checking the codebase Supports batch archiving of multiple completed changes in a single operation openspec-bulk-archive-change is a skill that allows batch archiving of completed changes, intelligently resolving spec conflicts by analyzing the codebase.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('altrr2/yandex-tools-mcp/yandex-competitive-analysis', 'community', 'altrr2', 'yandex-tools-mcp', 'altrr2/yandex-tools-mcp', 'yandex-competitive-analysis', 0, 0, 50, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:55.636Z', '8ead333bfc775b7d85983849fecb28e0586a1e1faf9de803f12ffea735ab3f40', '{"id":"altrr2/yandex-tools-mcp/yandex-competitive-analysis","name":"yandex-competitive-analysis","description":{"en":"yandex-competitive-analysis helps developers analyze competitors and find opportunities in Russian and CIS search markets by utilizing tools like mcp__yandex-search__search and mcp__yandex-wordstat__top-requests.","zh":"Yandex 竞争分析工具帮助开发者分析俄罗斯和 CIS 搜索市场，找到商业机会。利用 mcp__yandex-search__search 等工具","ja":"Yandex 競合分析ツールは、開発者がロシアとCISの検索市場を分析し、ビジネスチャンスを発見するのに役立ちます。mcp__yandex-search__search 等のツールを使用","ko":"Yandex 경쟁 분석 도구는 개발자가 러시아 및 CIS 검색 시장 분석하고 비즈니스 기회를 찾는 것을 도와줍니다. mcp__yandex-search__search 등","es":"Análisis competitivo de Yandex para identificar oportunidades en los mercados de búsqueda de Rusia y la CEI. Utiliza herramientas como mcp__yandex-search__search y mcp__yandex-wordstat__top-requests.","fr":"Analyse concurrentielle Yandex pour identifier les opportunités sur les marchés de recherche russes et de la CEI. Utilisez des outils tels que mcp__yandex-search__search et mcp__yandex-wordstat__top-requests.","de":"Wettbewerbsanalyse von Yandex, um Chancen in den russischen und GUS-Suchmärkten zu identifizieren. Verwenden Sie Tools wie mcp__yandex-search__search und mcp__yandex-wordstat__top-requests.","pt":"O Yandex Competitive Analysis é uma ferramenta para analisar concorrentes e encontrar oportunidades no mercado de busca russo e CIS.","ru":"ИИ Агенты: Yandex Competitive Analysis - это инструмент для анализа конкурентов и нахождения возможностей на российском и СНГ рынках поиска.","ar":"تحليل المنافس يان