INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wade56754/AI_ad_spend02/ai-ad-spec-governor', 'ai-ad-spec-governor', 'wade56754', 'AI_ad_spend02', 'community', 'ai-ad-spec-governor wade56754 AI_ad_spend02 community The ai-ad-spec-governor skill executes Spec-Driven governance and SoT alignment across document systems, benefiting AI_ad_spend02 project developers. It automates document auditing, repair, validation, and Freeze compliance checks. ai-ad-spec-governor是AI_ad_spend02项目的元规范总控Architect，负责规范治理闭环和SoT对齐 ai-ad-spec-governorはAI_ad_spend02プロジェクトのメタ規範総括アーキテクトであり、規範ガバナンスの閉じ込めとSoTの統一を担当します ai-ad-spec-governor는 AI_ad_spend02 프로젝트의 메타 규范 총괄 아키텍트로서 규范 총괄 및 SoT 통일을 담당합니다 ai-ad-spec-governor es un skill que gestiona la gobernanza de especificaciones y la alineación de fuentes de verdad en documentos ai-ad-spec-governor est une compétence qui gère la gouvernance des spécifications et l''alignement des sources de vérité dans les documents ai-ad-spec-governor ist ein Skill, der die Spezifikationsgovernance und die Ausrichtung von Wahrheitsquellen in Dokumenten verwaltet O ai-ad-spec-governor é um skill de AI que executa governança de especificações e alinhamento SoT em documentos. Ele é responsável por auditoria, reparo, verificação e congelamento de documentos ИИ Агент ai-ad-spec-governor выполняет управление спецификациями и выравнивание SoT в документах. Он отвечает за аудит, ремонт, проверку и заморозку документов المهارة الإصطناعية ai-ad-spec-governor تنفذ حوكمة المواصفات والتناغم مع SoT في الوثائق. وهي مسؤولة عن التدقيق والإصلاح والتحقق وتجميد الوثائق ai-ad-spec-governor setup guide Spec-Driven governance in AI_ad_spend02 SoT alignment tools ai-ad-spec-governor vs traditional governance methods how to use ai-ad-spec-governor for document validation ai-ad-spec-governor install and configuration AI智能代理 规范治理 SoT对齐 文档管理 Spec-Driven AI_ad_spend02 元规范总控Architect 文档审计 文档修复 Executes specification-driven governance across the document ecosystem Ensures SoT alignment with the docs/sot/ truth source Coordinates document auditing, repair, validation, and Freeze compliance checks Acts as a meta-specification architect for AI_ad_spend02 projects Schedules sub-skill tasks for efficient document governance ai-ad-spec-governor is a skill that acts as a Spec Governor, responsible for governing and aligning documents with the SoT truth source in AI_ad_spend02 projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcoodignoti/couple-diary/cicd-workflows', 'community', 'marcoodignoti', 'couple-diary', 'marcoodignoti/couple-diary', 'cicd-workflows', 0, 0, 50, '2026-03-08T01:57:15.388Z', '2026-03-08T02:05:57.315Z', '69e285601df4076a914557aa604037a750baad85588dd4712c9ce3b7523b99ca', '{"id":"marcoodignoti/couple-diary/cicd-workflows","name":"cicd-workflows","description":{"en":"The cicd-workflows skill helps developers write and edit EAS CI/CD workflow YAML files, utilizing Node.js scripts and JSON schema for efficient workflow management. This skill benefits developers working with EAS workflows.","zh":"EAS Workflows Skill 帮助开发者编写和编辑 EAS CI/CD 工作流 YAML 文件，提高开发效率","ja":"EAS Workflows Skill は、開発者が EAS CI/CD ワークフロー YAML ファイルを書き込むおよび編集するのを支援し、開発効率を向上させます","ko":"EAS Workflows Skill은 개발자가 EAS CI/CD 워크플ロー YAML 파일을 작성하고 편집하는 것을 도와줌으로써 개발 효율성을 향상시킵니다","es":"El skill de flujos de trabajo CI/CD ayuda a los desarrolladores a escribir y editar archivos YAML de flujo de trabajo de EAS CI/CD. Utiliza el script de recuperación implementado con Node.js para obtener recursos.","fr":"Le skill de flux de travail CI/CD aide les développeurs à écrire et à modifier des fichiers YAML de flux de travail EAS CI/CD. Il utilise le script de récupération implementé avec Node.js pour obtenir des ressources.","de":"Das Skill für CI/CD-Workflows hilft Entwicklern, EAS CI/CD-Workflow-YAML-Dateien zu schreiben und zu bearbeiten. Es verwendet das mit Node.js implementierte Fetch-Skript, um Ressourcen abzurufen.","pt":"O skill de workflows CI/CD ajuda desenvolvedores a escrever e editar arquivos YAML de workflow EAS CI/CD","ru":"Навык рабочих процессов CI/CD помогает разработчикам создавать и редактировать файлы YAML рабочих процессов EAS CI/CD","ar":"مهارة سير عمل CI/CD تساعد المطورين على كتابة وتحرير ملفات YAML لسير عمل EAS CI/CD"},"seo":{"title":{"en":"cicd-workflows: EAS CI/CD Workflow YAML Setup Guide | AI ...","zh":"CI/CD 工作流设置指南 - EAS Workflows Skill","ja":"CI/CD ワークフロー設定ガイド - EAS Workflows Skill AIエージェント","ko":"CI/CD 워크플ロー 설정 가이드 - EAS Workflows Skill AI 도구","es":"Guía de configuración de flujos de trabajo CI/CD con herr...","fr":"Guide de configuration des flux de travail CI/CD avec out...","de":"Einrichtungsleitfaden für CI/CD-Workflows mit KI-Tools un...","pt":"Guia de Configuração de Workflows CI/CD com Ferramentas d...","ru":"Настройка Работы CI/CD с Помощью ИИ Агентов","ar":"دليل إعداد سير عمل CI/CD باستخدام أدوات ذكاء اصطناعي"},"description":{"en":"Discover how to write and edit EAS CI/CD workflow YAML files with the cicd-workflows skill. Learn how to fetch JSON schema and use Node.js scripts for effici...","zh":"使用 EAS Workflows Skill 设置和管理 CI/CD 工作流，提高开发效率。了解更多关于 JSON Schema 和 Node.js 脚本的信息","ja":"EAS Workflows Skill を使用して CI/CD ワークフローを設定して管理し、開発効率を向上させます。JSON Schema と Node.js スクリプトの詳細を確認してください","ko":"EAS Workflows Skill을 사용하여 CI/CD 워크플ロー 설정 및 관리를 자동화하고 개발 효율성을 향상시키세요. JSON Schema 및 Node.js 스크립트에 대한 자세한 정보를 확인하세요","es":"Aprende a configurar flujos de trabajo CI/CD con nuestra guía paso a paso y mejora la eficiencia de tu equipo de desarrollo con herramientas de agente de int...","fr":"Découvrez comment configurer des flux de travail CI/CD avec notre guide étape par étape et améliorez l''efficacité de votre équipe de développement avec des o...","de":"Erfahren Sie, wie Sie CI/CD-Workflows mit unserem Schritt-für-Schritt-Leitfaden konfigurieren und die Effizienz Ihres Entwicklungsteams mit KI-Tools und -Age...","pt":"Aprenda a configurar workflows CI/CD com Node.js e JSON Schema para melhorar a eficiência do desenvolvimento","ru":"Узнайте, как настроить рабочие процессы CI/CD с помощью Node.js и JSON Schema для повышения эффективности разработки","ar":"تعرف على كيفية إعداد سير عمل CI/CD باستخدام Node.js و JSON Schema لتحسين كفاءة التطوير"},"definition":{"en":"cicd-workflows is a skill that assists developers in creating and editing EAS CI/CD workflow YAML files using Node.js scripts and JSON schema.","zh":"EAS Workflows Skill 是一种帮助开发者设置和管理 CI/CD 工作流的工具","ja":"EAS Workflows Skill は、開発者が CI/CD ワークフローを設定して管理するのを支援するツールです","ko":"EAS Workflows Skill은 개발자가 CI/CD 워크플ロー 설정 및 관리를 도와주는 도구입니다","es":"Un flujo de trabajo CI/CD es un proceso automatizado que ayuda a los desarrolladores a integrar y entregar software de manera eficiente","fr":"Un flux de travail CI/CD est un processus automatisé qui aide les développeurs à intégrer et à livrer des logiciels de manière efficace","de":"Ein CI/CD-Workflow ist ein automatisierter Prozess, der Entwicklern hilft, Software effizient zu integrieren und auszuliefern","pt":"Workflows CI/CD são processos automatizados que integram desenvolvimento e implantação de software","ru":"Рабочие процессы CI/CD - это автоматизированные процессы, которые интегрируют разработку и развертывание программного обеспечения","ar":"سير عمل CI/CD هي عمليات آلية تدمج تطوير وتنفيذ البرمجيات"},"features":{"en":["Fetches JSON schema from https://api.expo.dev/v2/workflows/schema for workflow validation","Utilizes Node.js scripts for efficient workflow file generation and validation","Caches responses using ETags for improved performance","Supports workflow file editing and writing using YAML files","Provides a fetch script for fetching resources and caching responses"],"zh":["支持 JSON Schema","使用 Node.js 脚本缓存响应","提供 EAS CI/CD 工作流 YAML 文件编辑功能","提高开发效率","支持 ETags 缓存","提供 fetch 脚本实现资源获取"],"ja":["JSON Schema をサポート","Node.js スクリプトを使用してレスポンスをキャッシュ","EAS CI/CD ワークフロー YAML ファイルの編集機能を提供","開発効率を向上","ETags キャッシュをサポート","fetch スクリプトを使用してリソースを取得"],"ko":["JSON Schema 지원","Node.js 스크립트를 사용하여 응답을 캐싱","EAS CI/CD 워크플ロー YAML 파일 편집 기능 제공","개발 효율성 향상","ETags 캐싱 지원","fetch 스크립트를 사용하여 리소스 가져오기"],"es":["Generación de archivos YAML de flujo de trabajo de EAS CI/CD","Uso de Node.js para implementar el script de recuperación","Obtención de recursos con el script de recuperación","Caché de respuestas con ETags para mejorar la eficiencia","Compatibilidad con JSON Schema para validar archivos YAML"],"fr":["Génération de fichiers YAML de flux de travail EAS CI/CD","Utilisation de Node.js pour implémenter le script de récupération","Obtention de ressources avec le script de récupération","Mise en cache des réponses avec ETags pour améliorer l''efficacité","Compatibilité avec JSON Schema pour valider les fichiers YAML"],"de":["Generierung von EAS CI/CD-Workflow-YAML-Dateien","Verwendung von Node.js zur Implementierung des Fetch-Skripts","Abruf von Ressourcen mit dem Fetch-Skript","Cachening von Antworten mit ETags zur Effizienzsteigerung","Unterstützung von JSON Schema zur Validierung von YAML-Dateien"],"pt":["Suporte a Node.js para fetch de recursos","Uso de JSON Schema para validação de workflows","Cache de respostas com ETags para eficiência","Edição de arquivos YAML de workflow EAS CI/CD","Integração com a API do Expo"],"ru":["Поддержка Node.js для получения ресурсов","Использование JSON Schema для проверки рабочих процессов","Кэширование ответов с помощью ETags для эффективности","Редактирование файлов YAML рабочих процессов EAS CI/CD","Интеграция с API Expo"],"ar":["دعم Node.js لاسترجاع الموارد","استخدام JSON Schema للتحقق من سير العمل","مخزن الإجابات باستخدام ETags لتحسين الكفاءة","تحرير ملفات YAML لسير عمل EAS CI/CD","التكامل مع واجهة برمجة تطبيقات Expo"]},"keywords":{"en":["how to use cicd-workflows","cicd-workflows setup guide","EAS CI/CD workflow YAML files","cicd-workflows vs other workflow tools","cicd-workflows install","what is cicd-workflows","cicd-workflows alternative","cicd-workflows Node.js scripts","cicd-workflows JSON schema"],"zh":["CI/CD 工作流","EAS Workflows Skill","JSON Schema","Node.js 脚本","YAML 文件编辑","开发效率","ETags 缓存","fetch 脚本"],"ja":["CI/CD ワークフロー","EAS Workflows Skill","JSON Schema","Node.js スクリプト","YAML ファイル編集","開発効率","ETags キャッシュ","fetch スクリプト","AIエージェント"],"ko":["CI/CD 워크플ロー","EAS Workflows Skill","JSON Schema","Node.js 스크립트","YAML 파일 편집","개발 효율성","ETags 캐싱","fetch 스크립트","AI 도구"],"es":["flujos de trabajo CI/CD","herramientas de agente de inteligencia artificial","configuración de flujos de trabajo","desarrollo de software","automatización de procesos","EAS CI/CD","YAML","Node.js","JSON Schema"],"fr":["flux de travail CI/CD","outils d''agent d''intelligence artificielle","configuration de flux de travail","développement de logiciels","automatisation de processus","EAS CI/CD","YAML","Node.js","JSON Schema"],"de":["CI/CD-Workflows","KI-Tools und -Agenten","Konfiguration von Workflows","Software-Entwicklung","Automatisierung von Prozessen","EAS CI/CD","YAML","Node.js","JSON Schema"],"pt":["workflows CI/CD","ferramentas de IA","desenvolvimento de software","Node.js","JSON Schema","EAS CI/CD","Expo API","automatização de processos"],"ru":["рабочие процессы CI/CD","ИИ агенты","разработка программного обеспечения","Node.js","JSON Schema","EAS CI/CD","API Expo","автоматизация процессов"],"ar":["سير عمل CI/CD","أدوات ذكاء اصطناعي","تطوير البرمجيات","Node.js","JSON Schema","EAS CI/CD","واجهة برمجة تطبيقات Expo","آليّة العمليات"]}},"owner":"marcoodignoti","repo":"couple-diary","repoPath":"marcoodignoti/couple-diary","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.388Z","topics":[],"category":"community","skillMd":{"name":"cicd-workflows","description":"Helps understand and write EAS workflow YAML files for Expo projects. Use this skill when the user asks about CI/CD or workflows in an Expo or EAS context, mentions .eas/workflows/, or wants help with EAS build pipelines or deployment automation.","version":"1.0.0","bodyPreview":"# EAS Workflows Skill\n\nHelp developers write and edit EAS CI/CD workflow YAML files.\n\n## Reference Documentation\n\nFetch these resources before generating or validating workflow files. Use the fetch script (implemented using Node.js) in this skill''s `scripts/` directory; it caches responses using ETags for efficiency:\n\n```bash\n# Fetch resources\nnode {baseDir}/scripts/fetch.js <url>\n```\n\n1. **JSON Schema** — https://api.expo.dev/v2/workflows/schema\n   - It is NECESSARY to fetch this schema\n   - So","body":"# EAS Workflows Skill\n\nHelp developers write and edit EAS CI/CD workflow YAML files.\n\n## Reference Documentation\n\nFetch these resources before generating or validating workflow files. Use the fetch script (implemented using Node.js) in this skill''s `scripts/` directory; it caches responses using ETags for efficiency:\n\n```bash\n# Fetch resources\nnode {baseDir}/scripts/fetch.js <url>\n```\n\n1. **JSON Schema** — https://api.expo.dev/v2/workflows/schema\n   - It is NECESSARY to fetch this schema\n   - Source of truth for validation\n   - All job types and their required/optional parameters\n   - Trigger types and configurations\n   - Runner types, VM images, and all enums\n\n2. **Syntax Documentation** — https://raw.githubusercontent.com/expo/expo/refs/heads/main/docs/pages/eas/workflows/syntax.mdx\n   - Overview of workflow YAML syntax\n   - Examples and English explanations\n   - Expression syntax and contexts\n\n3. **Pre-packaged Jobs** — https://raw.githubusercontent.com/expo/expo/refs/heads/main/docs/pages/eas/workflows/pre-packaged-jobs.mdx\n   - Documentation for supported pre-packaged job types\n   - Job-specific parameters and outputs\n\nDo not rely on memorized values; these resources evolve as new features are added.\n\n## Workflow File Location\n\nWorkflows live in `.eas/workflows/*.yml` (or `.yaml`).\n\n## Top-Level Structure\n\nA workflow file has these top-level keys:\n\n- `name` — Display name for the workflow\n- `on` — Triggers that start the workflow (at least one required)\n- `jobs` — Job definitions (required)\n- `defaults` — Shared defaults for all jobs\n- `concurrency` — Control parallel workflow runs\n\nConsult the schema for the full specification of each section.\n\n## Expressions\n\nUse `${{ }}` syntax for dynamic values. The schema defines available contexts:\n\n- `github.*` — GitHub repository and event information\n- `inputs.*` — Values from `workflow_dispatch` inputs\n- `needs.*` — Outputs and status from dependent jobs\n- `jobs.*` — Job outputs (alternative syntax)\n- `steps.*` — Step outputs within custom jobs\n- `workflow.*` — Workflow metadata\n\n## Generating Workflows\n\nWhen generating or editing workflows:\n\n1. Fetch the schema to get current job types, parameters, and allowed values\n2. Validate that required fields are present for each job type\n3. Verify job references in `needs` and `after` exist in the workflow\n4. Check that expressions reference valid contexts and outputs\n5. Ensure `if` conditions respect the schema''s length constraints\n\n## Validation\n\nAfter generating or editing a workflow file, validate it against the schema:\n\n```sh\n# Install dependencies if missing\n[ -d \"{baseDir}/scripts/node_modules\" ] || npm install --prefix {baseDir}/scripts\n\nnode {baseDir}/scripts/validate.js <workflow.yml> [workflow2.yml ...]\n```\n\nThe validator fetches the latest schema and checks the YAML structure. Fix any reported errors before considering the workflow complete.\n\n## Answering Questions\n\nWhen users ask about available options (job types, triggers, runner types, etc.), fetch the schema and derive the answer from it rather than relying on potentially outdated information.\n"},"lastSynced":"2026-03-08T02:05:57.315Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring efficient EAS CI/CD workflow management and YAML file editing capabilities.","zh":"适合需要高效EAS CI/CD工作流管理和YAML文件编辑功能的DevOps代理。","ja":"DevOpsエージェントが効率的なEAS CI/CDワークフローマネジメントとYAMLファイルの編集機能を必要とする場合に適しています。","ko":"효율적인 EAS CI/CD 워크플로우 관리 및 YAML 파일 편집 기능이 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren una gestión de flujo de trabajo de EAS CI/CD eficiente y capacidades de edición de archivos YAML.","fr":"Idéal pour les agents DevOps nécessitant une gestion de workflow EAS CI/CD efficace et des capacités d''édition de fichiers YAML.","de":"Ideal für DevOps-Agents, die eine effiziente Verwaltung von EAS CI/CD-Workflows und YAML-Dateibearbeitungsfunktionen erfordern.","pt":"Ideal para Agentes DevOps que exigem gerenciamento eficiente de fluxo de trabalho EAS CI/CD e capacidades de edição de arquivos YAML.","ru":"Идеально для агентов DevOps, требующих эффективного управления рабочим процессом EAS CI/CD и возможностей редактирования файлов YAML.","ar":"مثالي لعميل DevOps الذي يتطلب إدارة فعالة لتدفق عمل EAS CI/CD وقدرات تحرير ملفات YAML."},"recommendation":{"en":"Empowers agents to write and edit EAS CI/CD workflow YAML files utilizing Node.js scripts and JSON schema for efficient workflow management, leveraging ETags for caching and workflow validation against the Expo API JSON schema.","zh":"赋予代理写入和编辑EAS CI/CD工作流YAML文件的能力，利用Node.js脚本和JSON模式实现高效的工作流管理，利用ETags进行缓存和工作流验证，验证工作流是否符合Expo API JSON模式。","ja":"エージェントにEAS CI/CDワークフローのYAMLファイルを書き込み、編集する能力を付与し、Node.jsスクリプトとJSONスキーマを使用して効率的なワークフローマネジメントを行い、ETagsを使用してキャッシングとワークフローの検証を行い、Expo APIのJSONスキーマに基づいてワークフローの検証を行う。","ko":"에이전트가 EAS CI/CD 워크플로우의 YAML 파일을 작성하고 편집할 수 있는 능력을 부여하여 Node.js 스크립트와 JSON 스키마를 사용하여 효율적인 워크플로우 관리를 thực現하고 ETags를 사용하여 캐싱과 워크플로우 검증을 수행하며 Expo API의 JSON 스키마에 따라 워크플로우를 검증합니다.","es":"Habilita a los agentes a escribir y editar archivos YAML de flujo de trabajo de EAS CI/CD utilizando scripts de Node.js y esquema JSON para una gestión de flujo de trabajo eficiente, aprovechando ETags para caché y validación de flujo de trabajo contra el esquema JSON de la API de Expo.","fr":"Permet aux agents d''écrire et de modifier des fichiers YAML de workflow EAS CI/CD en utilisant des scripts Node.js et un schéma JSON pour une gestion de workflow efficace, en exploitant les ETags pour le cache et la validation du workflow contre le schéma JSON de l''API Expo.","de":"Ermöglicht es den Agenten, EAS CI/CD-Workflow-YAML-Dateien mithilfe von Node.js-Skripten und JSON-Schema für eine effiziente Workflow-Verwaltung zu schreiben und zu bearbeiten, indem ETags für Caching und Workflow-Validierung gegen das JSON-Schema der Expo-API genutzt werden.","pt":"Habilita os agentes a escrever e editar arquivos YAML de fluxo de trabalho EAS CI/CD utilizando scripts Node.js e esquema JSON para gerenciamento de fluxo de trabalho eficiente, utilizando ETags para cache e validação de fluxo de trabalho contra o esquema JSON da API Expo.","ru":"Наделяет агентов возможностью писать и редактировать файлы YAML рабочего процесса EAS CI/CD, используя скрипты Node.js и схему JSON для эффективного управления рабочим процессом, используя ETags для кэширования и проверки рабочего процесса против схемы JSON API Expo.","ar":"يتمكّن الوكلاء من كتابة وتحرير ملفات YAML لتدفق العمل EAS CI/CD باستخدام سكريبتات Node.js و مخطط JSON من أجل إدارة تدفق العمل بشكل فعال، واستخدام ETags للแคش وتحقق تدفق العمل ضد مخطط JSON API Expo."},"useCases":{"en":["Automating EAS workflow deployments using Node.js scripts","Editing and validating EAS CI/CD workflow YAML files against the Expo API JSON schema","Generating EAS workflows with efficient caching using ETags"],"zh":["使用Node.js脚本自动化EAS工作流部署","编辑和验证EAS CI/CD工作流YAML文件，验证文件是否符合Expo API JSON模式","使用ETags实现缓存，生成EAS工作流"],"ja":["Node.jsスクリプトを使用してEASワークフローのデプロイを自動化する","EAS CI/CDワークフローのYAMLファイルを編集、検証し、Expo APIのJSONスキーマに基づいて検証する","ETagsを使用してキャッシングを行い、EASワークフローを生成する"],"ko":["Node.js 스크립트를 사용하여 EAS 워크플로우 배포를 자동화하는 것","EAS CI/CD 워크플로우의 YAML 파일을 편집하고 검증하며 Expo API의 JSON 스키마에 따라 검증하는 것","ETags를 사용하여 캐싱을 thực現하고 EAS 워크플로우를 생성하는 것"],"es":["Automatización de implementaciones de flujo de trabajo de EAS utilizando scripts de Node.js","Edición y validación de archivos YAML de flujo de trabajo de EAS CI/CD contra el esquema JSON de la API de Expo","Generación de flujos de trabajo de EAS con caché eficiente utilizando ETags"],"fr":["Automatisation des déploiements de workflow EAS à l''aide de scripts Node.js","Édition et validation de fichiers YAML de workflow EAS CI/CD contre le schéma JSON de l''API Expo","Génération de workflows EAS avec un cache efficace en utilisant les ETags"],"de":["Automatisierung von EAS-Workflow-Bereitstellungen mithilfe von Node.js-Skripten","Bearbeitung und Validierung von EAS CI/CD-Workflow-YAML-Dateien gegen das JSON-Schema der Expo-API","Generierung von EAS-Workflows mit effizientem Caching unter Verwendung von ETags"],"pt":["Automatizar implantações de fluxo de trabalho EAS usando scripts Node.js","Editar e validar arquivos YAML de fluxo de trabalho EAS CI/CD contra o esquema JSON da API Expo","Gerar fluxos de trabalho EAS com cache eficiente usando ETags"],"ru":["Автоматизировать развертывания рабочего процесса EAS с помощью скриптов Node.js","Редактировать и проверять файлы YAML рабочего процесса EAS CI/CD против схемы JSON API Expo","Генерировать рабочие процессы EAS с эффективным кэшированием, используя ETags"],"ar":["تأتمة عمليات نشر تدفق العمل EAS باستخدام سكريبتات Node.js","تحرير وتحقق ملفات YAML لتدفق العمل EAS CI/CD ضد مخطط JSON API Expo","توليد تدفقات العمل EAS مع ذاكرة مؤقتة فعالة باستخدام ETags"]},"limitations":{"en":["Requires Node.js for script execution","Dependent on Expo API for JSON schema and workflow validation","Specific to EAS workflows and YAML file format"],"zh":["需要Node.js来执行脚本","依赖Expo API来获取JSON模式和工作流验证","仅适用于EAS工作流和YAML文件格式"],"ja":["スクリプトの実行にはNode.jsが必要","JSONスキーマとワークフローの検証にはExpo APIに依存する","EASワークフローとYAMLファイル形式に特化している"],"ko":["스크립트 실행을 위해 Node.js가 필요합니다.","JSON 스키마 및 워크플로우 검증을 위해 Expo API에 의존합니다.","EAS 워크플로우 및 YAML 파일 형식에만 적합합니다."],"es":["Requiere Node.js para la ejecución de scripts","Depende de la API de Expo para el esquema JSON y la validación de flujo de trabajo","Específico para flujos de trabajo de EAS y formato de archivo YAML"],"fr":["Nécessite Node.js pour l''exécution de scripts","Dépend de l''API Expo pour le schéma JSON et la validation du workflow","Spécifique aux workflows EAS et au format de fichier YAML"],"de":["Benötigt Node.js für die Skriptausführung","Hängt von der Expo-API für das JSON-Schema und die Workflow-Validierung ab","Spezifisch für EAS-Workflows und YAML-Dateiformat"],"pt":["Exige Node.js para execução de scripts","Dependente da API Expo para esquema JSON e validação de fluxo de trabalho","Específico para fluxos de trabalho EAS e formato de arquivo YAML"],"ru":["Требует Node.js для выполнения скриптов","Зависит от API Expo для схемы JSON и проверки рабочего процесса","Конкретно для рабочих процессов EAS и формата файла YAML"],"ar":["يتطلب Node.js لتنفيذ السكريبتات","يعتمد على API Expo لمخطط JSON وتحقق تدفق العمل","محدد لتدفقات العمل EAS وتنسيق ملف YAML"]},"version":4},"contentHash":"69e285601df4076a914557aa604037a750baad85588dd4712c9ce3b7523b99ca","qualityScore":50}');
