INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('marcoodignoti/couple-diary/cicd-workflows', 'cicd-workflows', 'marcoodignoti', 'couple-diary', 'community', 'cicd-workflows marcoodignoti couple-diary community The cicd-workflows skill helps developers write and edit EAS CI/CD workflow YAML files, utilizing Node.js scripts and JSON schema for efficient workflow management. This skill benefits developers working with EAS workflows. EAS Workflows Skill 帮助开发者编写和编辑 EAS CI/CD 工作流 YAML 文件，提高开发效率 EAS Workflows Skill は、開発者が EAS CI/CD ワークフロー YAML ファイルを書き込むおよび編集するのを支援し、開発効率を向上させます EAS Workflows Skill은 개발자가 EAS CI/CD 워크플ロー YAML 파일을 작성하고 편집하는 것을 도와줌으로써 개발 효율성을 향상시킵니다 El skill de flujos de trabajo CI/CD ayuda a los desarrolladores a escribir y editar archivos YAML de flujo de trabajo de EAS CI/CD. Utiliza el script de recuperación implementado con Node.js para obtener recursos. Le skill de flux de travail CI/CD aide les développeurs à écrire et à modifier des fichiers YAML de flux de travail EAS CI/CD. Il utilise le script de récupération implementé avec Node.js pour obtenir des ressources. Das Skill für CI/CD-Workflows hilft Entwicklern, EAS CI/CD-Workflow-YAML-Dateien zu schreiben und zu bearbeiten. Es verwendet das mit Node.js implementierte Fetch-Skript, um Ressourcen abzurufen. O skill de workflows CI/CD ajuda desenvolvedores a escrever e editar arquivos YAML de workflow EAS CI/CD Навык рабочих процессов CI/CD помогает разработчикам создавать и редактировать файлы YAML рабочих процессов EAS CI/CD مهارة سير عمل CI/CD تساعد المطورين على كتابة وتحرير ملفات YAML لسير عمل EAS CI/CD how to use cicd-workflows cicd-workflows setup guide EAS CI/CD workflow YAML files cicd-workflows vs other workflow tools cicd-workflows install what is cicd-workflows cicd-workflows alternative cicd-workflows Node.js scripts cicd-workflows JSON schema CI/CD 工作流 EAS Workflows Skill JSON Schema Node.js 脚本 YAML 文件编辑 开发效率 ETags 缓存 fetch 脚本 Fetches JSON schema from https://api.expo.dev/v2/workflows/schema for workflow validation Utilizes Node.js scripts for efficient workflow file generation and validation Caches responses using ETags for improved performance Supports workflow file editing and writing using YAML files Provides a fetch script for fetching resources and caching responses cicd-workflows is a skill that assists developers in creating and editing EAS CI/CD workflow YAML files using Node.js scripts and JSON schema.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jiangzhuizzz/MyMoltbot/copywriting', 'community', 'jiangzhuizzz', 'MyMoltbot', 'jiangzhuizzz/MyMoltbot', 'copywriting', 0, 0, 50, '2026-03-08T01:57:15.406Z', '2026-03-08T02:06:56.151Z', '5b3ea76961e8de82f00083569f4ef275058afb70bb301a9153dd80f73837b18e', '{"id":"jiangzhuizzz/MyMoltbot/copywriting","name":"copywriting","description":{"en":"The copywriting skill generates clear and compelling marketing copy that drives action. It benefits developers and marketers seeking to optimize their page content for conversions.","zh":"AIエージェント的copywriting功能可以帮助开发者创建清晰、引人入胜的营销文案","ja":"AIエージェントによるcopywriting機能は、開発者が明確で魅力的なマーケティングコピーを作成するのに役立ちます","ko":"AI 에이전트의 copywriting 기능은 개발자가 명확하고 매력적인 마케팅 복사를 생성하는 데 도움이 됩니다","es":"El copywriting es el proceso de escribir copias de marketing claras y convincentes que impulsan la conversión y el compromiso del usuario.","fr":"La réécriture de contenu est le processus d''écriture de copies de marketing claires et convaincantes qui favorisent la conversion et l''engagement des utilisateurs.","de":"Copywriting ist der Prozess des Erstellens klarer und überzeugender Marketing-Kopien, die die Konversion und die Benutzerbeteiligung fördern.","pt":"Nossa ferramenta de redação publicitária ajuda a criar marketing copy claro e convincente, impulsionando ações eficazes.","ru":"Наша технология копирайтинга помогает создавать маркетинговый копи, который преобразует, стимулируя действия.","ar":"أداة الكتابة الإعلانية تساعد على إنشاء نسخ إعلانية واضحة ومقنعة، تدفع الإجراءات الفعالة."},"seo":{"title":{"en":"Copywriting: Conversion-Optimized Content Generation | AI...","zh":"AIエージェント_copywriting最佳实践","ja":"AIエージェントによるcopywritingセットアップガイド","ko":"AI 에이전트를 위한 copywriting 기술 가이드","es":"Guía de Configuración de Copywriting para Agentes de IA","fr":"Guide de Configuration de la Réécriture de Contenu pour l...","de":"Einrichtungsleitfaden für Copywriting mit KI-Tools","pt":"Guia de Configuração de Redação Publicitária para Desenvo...","ru":"ИИ Агенты: Руководство по Настройке Копирайтинга","ar":"دليل ضبط الكتابة الإعلانية للأجهزة الذكية"},"description":{"en":"Unlock the power of persuasive copy with our AI agent''s copywriting skill. Learn how to drive action and convert visitors into customers - get started now!","zh":"了解如何使用AIエージェント实现高效的copywriting，驱动转化和行动","ja":"AIエージェントを使用して効果的なcopywritingを実現し、コンバージョンを促進する","ko":"AI 에이전트를 활용하여 copywriting을 최적화하고 변환률을 높이는 방법에 대해 알아보세요","es":"Aprende a escribir copias de marketing claras y convincentes con nuestra guía de copywriting para agentes de IA. Mejora la conversión y el compromiso del usu...","fr":"Découvrez comment écrire des copies de marketing claires et convaincantes avec notre guide de réécriture de contenu pour les outils d''IA. Améliorez la conver...","de":"Erfahren Sie, wie Sie mit unserem Einrichtungsleitfaden für Copywriting mit KI-Tools klare und überzeugende Marketing-Kopien erstellen. Verbessern Sie die Ko...","pt":"Aprenda a escrever marketing copy claro e convincente com nossa ferramenta de redação publicitária. Descubra como impulsionar ações com copywriting eficaz.","ru":"Изучите, как писать маркетинговый копи, который преобразует с помощью нашей технологии копирайтинга. Узнайте, как стимулировать действия с помощью эффективно...","ar":"تعلم كيف تكتب نسخة إعلانية واضحة ومقنعة مع أداة الكتابة الإعلانية. اكتشف كيف تدفع الإجراءات بنسخ إعلانية فعالة."},"definition":{"en":"Copywriting is the process of crafting marketing copy that is clear, compelling, and drives action, typically for homepage, landing page, pricing, feature, or about pages.","zh":"copywriting是AIエージェント的一种功能，用于创建驱动行动的营销文案","ja":"copywritingは、AIエージェントの機能の1つで、行動を促進するマーケティングコピーを作成するために使用されます","ko":"copywriting은 AI 에이전트의 기능 중 하나로 행동을 유도하는 마케팅 복스를 생성하는 데 사용됩니다","es":"El copywriting es la técnica de escritura de contenido de marketing que busca impulsar la acción del usuario.","fr":"La réécriture de contenu est la technique d''écriture de contenu de marketing qui vise à inciter l''utilisateur à agir.","de":"Copywriting ist die Technik des Schreibens von Marketing-Inhalten, die darauf abzielt, die Benutzerhandlung zu fördern.","pt":"Redação publicitária é a arte de criar marketing copy que converte, utilizando técnicas de copywriting para impulsionar ações.","ru":"Копирайтинг - это искусство создания маркетингового копи, который преобразует, используя техники копирайтинга для стимулирования действий.","ar":"الكتابة الإعلانية هي فن إنشاء نسخ إعلانية التي تحول، باستخدام تقنيات الكتابة الإعلانية لتحفيز الإجراءات."},"features":{"en":["Gathers context on page purpose, including primary and secondary actions","Identifies ideal customer and their problem to solve","Writes marketing copy for various page types, such as homepage and landing pages","Optimizes copy for conversion, driving visitors to take specific actions","Considers audience and their needs when crafting compelling copy"],"zh":["页面目的分析","受众分析和理解","行动驱动的营销文案创建","次要行动的定义","清晰和引人入胜的文案编写"],"ja":["ページ目的の分析","対象オーディエンスの分析と理解","アクションを促進するマーケティングコピーの作成","二次的なアクションの定義","明確で魅力的なコピーの作成"],"ko":["페이지 목적 분석","대상 오디언스의 분석과 이해","행동을 유도하는 마케팅 복스의 생성","이차적인 행동의 정의","명확하고 매력적인 복스의 작성"],"es":["Escribir copias de marketing claras y convincentes","Definir el propósito de la página y la acción principal","Identificar la audiencia objetivo y sus necesidades","Crear contenido que impulse la conversión y el compromiso del usuario","Optimizar el contenido para mejorar la experiencia del usuario"],"fr":["Écrire des copies de marketing claires et convaincantes","Définir le but de la page et l''action principale","Identifier le public cible et ses besoins","Créer du contenu qui favorise la conversion et l''engagement des utilisateurs","Optimiser le contenu pour améliorer l''expérience utilisateur"],"de":["Klare und überzeugende Marketing-Kopien erstellen","Den Zweck der Seite und die primäre Aktion definieren","Die Zielgruppe und ihre Bedürfnisse identifizieren","Inhalte erstellen, die die Konversion und die Benutzerbeteiligung fördern","Inhalte optimieren, um die Benutzererfahrung zu verbessern"],"pt":["Definição de propósito de página para marketing copy eficaz","Identificação do público-alvo para copywriting personalizado","Criação de ações primárias e secundárias para direcionar o tráfego","Uso de técnicas de copywriting para impulsionar conversões","Análise de resultados para otimizar o marketing copy"],"ru":["Определение цели страницы для эффективного маркетингового копи","Идентификация целевой аудитории для персонализированного копирайтинга","Создание первичных и вторичных действий для направления трафика","Использование техник копирайтинга для стимулирования конверсий","Анализ результатов для оптимизации маркетингового копи"],"ar":["تحديد هدف الصفحة لنص إعلاني فعال","تحديد الجمهور المستهدف للكتابة الإعلانية المخصصة","إنشاء إجراءات أولية وثانوية لتوجيه حركة المرور","استخدام تقنيات الكتابة الإعلانية لتحفيز التحويلات","تحليل النتائج لتحسين نص الإعلان"]},"keywords":{"en":["how to use copywriting for landing pages","what is conversion copywriting","copywriting vs content writing","copywriting setup guide for AI agents","best practices for copywriting","copywriting for homepage optimization"],"zh":["AIエージェント_copywriting","copywriting技术","营销文案创建","行动驱动的copywriting","页面目的分析","受众分析"],"ja":["AIエージェントによるcopywriting","copywriting技術","マーケティングコピーの作成","アクションを促進するcopywriting","ページ目的の分析","対象オーディエンスの分析"],"ko":["AI 에이전트를 위한 copywriting","copywriting 기술","마케팅 복스의 생성","행동을 유도하는 copywriting","페이지 목적 분석","대상 오디언스의 분석"],"es":["copywriting para agentes de IA","guía de copywriting","mejora de la conversión","compromiso del usuario","contenido de marketing","optimización de contenido"],"fr":["réécriture de contenu pour les outils d''IA","guide de réécriture de contenu","amélioration de la conversion","engagement des utilisateurs","contenu de marketing","optimisation de contenu"],"de":["Copywriting mit KI-Tools","Einrichtungsleitfaden für Copywriting","Verbesserung der Konversion","Benutzerbeteiligung","Marketing-Inhalte","Inhalts-Optimierung"],"pt":["redação publicitária","copywriting","marketing copy","conversão de leads","otimização de tráfego","análise de resultados","técnicas de copywriting","público-alvo","propósito de página"],"ru":["копирайтинг","маркетинговый копи","ИИ Агенты","преобразование лидов","оптимизация трафика","анализ результатов","техники копирайтинга","целевая аудитория","цель страницы"],"ar":["الكتابة الإعلانية","نص إعلاني","أداة الكتابة الإعلانية","تحويل الرصيد","تحسين حركة المرور","تحليل النتائج","تقنيات الكتابة الإعلانية","الجمهور المستهدف","هدف الصفحة"]}},"owner":"jiangzhuizzz","repo":"MyMoltbot","repoPath":"jiangzhuizzz/MyMoltbot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.406Z","topics":[],"category":"community","skillMd":{"name":"copywriting","description":"When the user wants to write, rewrite, or improve marketing copy for any page — including homepage, landing pages, pricing pages, feature pages, about pages, or product pages. Also use when the user says write copy for, improve this copy, rewrite this page, marketing copy, headline help, or CTA copy. For email copy, see email-sequence. For popup copy, see popup-cro.","bodyPreview":"# Copywriting\n\nYou are an expert conversion copywriter. Your goal is to write marketing copy that is clear, compelling, and drives action.\n\n## Before Writing\n\nGather this context (ask if not provided):\n\n### 1. Page Purpose\n- What type of page is this? (homepage, landing page, pricing, feature, about)\n- What is the ONE primary action you want visitors to take?\n- What''s the secondary action (if any)?\n\n### 2. Audience\n- Who is the ideal customer for this page?\n- What problem are they trying to solv","body":"# Copywriting\n\nYou are an expert conversion copywriter. Your goal is to write marketing copy that is clear, compelling, and drives action.\n\n## Before Writing\n\nGather this context (ask if not provided):\n\n### 1. Page Purpose\n- What type of page is this? (homepage, landing page, pricing, feature, about)\n- What is the ONE primary action you want visitors to take?\n- What''s the secondary action (if any)?\n\n### 2. Audience\n- Who is the ideal customer for this page?\n- What problem are they trying to solve?\n- What have they already tried?\n- What objections or hesitations do they have?\n- What language do they use to describe their problem?\n\n### 3. Product/Offer\n- What are you selling or offering?\n- What makes it different from alternatives?\n- What''s the key transformation or outcome?\n- Any proof points (numbers, testimonials, case studies)?\n\n### 4. Context\n- Where is traffic coming from? (ads, organic, email)\n- What do visitors already know before arriving?\n- What messaging are they seeing before this page?\n\n---\n\n## Copywriting Principles\n\n### Clarity Over Cleverness\n- If you have to choose between clear and creative, choose clear\n- Every sentence should have one job\n- Remove words that don''t add meaning\n\n### Benefits Over Features\n- Features: What it does\n- Benefits: What that means for the customer\n- Always connect features to outcomes\n\n### Specificity Over Vagueness\n- Vague: \"Save time on your workflow\"\n- Specific: \"Cut your weekly reporting from 4 hours to 15 minutes\"\n\n### Customer Language Over Company Language\n- Use words your customers use\n- Avoid jargon unless your audience uses it\n- Mirror voice-of-customer from reviews, interviews, support tickets\n\n### One Idea Per Section\n- Don''t try to say everything everywhere\n- Each section should advance one argument\n- Build a logical flow down the page\n\n---\n\n## Writing Style Rules\n\nFollow these core principles. For detailed editing checks and word-by-word polish, use the **copy-editing** skill after your initial draft.\n\n### Core Style Principles\n\n1. **Simple over complex** — Use everyday words. \"Use\" instead of \"utilize,\" \"help\" instead of \"facilitate.\"\n\n2. **Specific over vague** — Avoid words like \"streamline,\" \"optimize,\" \"innovative\" that sound good but mean nothing.\n\n3. **Active over passive** — \"We generate reports\" not \"Reports are generated.\"\n\n4. **Confident over qualified** — Remove hedging words like \"almost,\" \"very,\" \"really.\"\n\n5. **Show over tell** — Describe the outcome instead of using adverbs like \"instantly\" or \"easily.\"\n\n6. **Honest over sensational** — Never fabricate statistics, claims, or testimonials.\n\n### Quick Quality Check\n\nBefore finalizing, scan for:\n- Jargon that could confuse outsiders\n- Sentences trying to do too much (max 3 conjunctions)\n- Passive voice constructions\n- Exclamation points (remove them)\n- Marketing buzzwords without substance\n\nFor a thorough line-by-line review, run the copy through the **copy-editing** skill''s Seven Sweeps framework.\n\n---\n\n## Best Practices\n\n### Be Direct\nGet to the point. Don''t bury the value in qualifications.\n\n❌ Slack lets you share files instantly, from documents to images, directly in your conversations\n\n✅ Need to share a screenshot? Send as many documents, images, and audio files as your heart desires.\n\n### Use Rhetorical Questions\nQuestions engage readers and make them think about their own situation.\n\n✅ Hate returning stuff to Amazon?\n\n✅ Need to share a screenshot?\n\n✅ Tired of chasing approvals?\n\n### Use Analogies and Metaphors\nWhen appropriate, analogies make abstract concepts concrete and memorable.\n\n❌ Slack lets you share files instantly, from documents to images, directly in your conversations\n\n✅ Imagine Slack''s file-sharing as a digital whiteboard where everyone can post files, images, and updates in real time.\n\n### Pepper in Humor (When Appropriate)\nPuns, wit, and humor make copy memorable—but only if it fits the brand and doesn''t undermine clarity.\n\n---\n\n## Page Structure Framework\n\n### Above the Fold (First Screen)\n\n**Headline**\n- Your single most important message\n- Should communicate core value proposition\n- Specific > generic\n\n**Headline Formulas:**\n\n**{Achieve desirable outcome} without {pain point}**\n*Example: Understand how users are really experiencing your site without drowning in numbers*\n\n**The {opposite of usual process} way to {achieve desirable outcome}**\n*Example: The easiest way to turn your passion into income*\n\n**Never {unpleasant event} again**\n*Example: Never miss a sales opportunity again*\n\n**{Key feature/product type} for {target audience}**\n*Example: Advanced analytics for Shopify e-commerce*\n\n**{Key feature/product type} for {target audience} to {what it''s used for}**\n*Example: An online whiteboard for teams to ideate and brainstorm together*\n\n**You don''t have to {skills or resources} to {achieve desirable outcome}**\n*Example: With Ahrefs, you don''t have to be an SEO pro to rank higher and get more traffic*\n\n**{Achieve desirable outcome} by {how product makes it possible}**\n*Example: Generate more leads by seeing which companies visit your site*\n\n**{Key benefit of your product}**\n*Example: Sound clear in online meetings*\n\n**{Question highlighting the main pain point}**\n*Example: Hate returning stuff to Amazon?*\n\n**Turn {input} into {outcome}**\n*Example: Turn your hard-earned sales into repeat customers*\n\n**Additional formulas:**\n- \"[Achieve outcome] in [timeframe]\"\n- \"The [category] that [key differentiator]\"\n- \"Stop [pain]. Start [pleasure].\"\n- \"[Number] [people] use [product] to [outcome]\"\n\n**Subheadline**\n- Expands on the headline\n- Adds specificity or addresses secondary concern\n- 1-2 sentences max\n\n**Primary CTA**\n- Action-oriented button text\n- Communicate what they get, not what they do\n- \"Start Free Trial\" > \"Sign Up\"\n- \"Get Your Report\" > \"Submit\"\n\n**Supporting Visual**\n- Product screenshot, demo, or hero image\n- Should reinforce the message, not distract\n\n### Social Proof Section\n\nOptions (use 1-2):\n- Customer logos (recognizable > many)\n- Key metric (\"10,000+ teams\")\n- Short testimonial with attribution\n- Star rating with review count\n\n### Problem/Pain Section\n\n- Articulate the problem better than they can\n- Show you understand their situation\n- Create recognition (\"that''s exactly my problem\")\n\nStructure:\n- \"You know the feeling...\" or \"If you''re like most [role]...\"\n- Describe the specific frustrations\n- Hint at the cost of not solving it\n\n### Solution/Benefits Section\n\n- Bridge from problem to your solution\n- Focus on 3-5 key benefits (not 10)\n- Each benefit: headline + short explanation + proof point if available\n\nFormat options:\n- Benefit blocks with icons\n- Before/after comparison\n- Feature → Benefit → Proof structure\n\n### How It Works Section\n\n- Reduce perceived complexity\n- 3-4 step process\n- Each step: simple action + outcome\n\nExample:\n1. \"Connect your tools (2 minutes)\"\n2. \"Set your preferences\"\n3. \"Get automated reports every Monday\"\n\n### Social Proof (Detailed)\n\n- Full testimonials with:\n  - Specific results\n  - Customer name, role, company\n  - Photo if possible\n- Case study snippets\n- Logos section (if not above)\n\n### Objection Handling\n\nCommon objections to address:\n- \"Is this right for my situation?\"\n- \"What if it doesn''t work?\"\n- \"Is it hard to set up?\"\n- \"How is this different from X?\"\n\nFormats:\n- FAQ section\n- Comparison table\n- Guarantee/promise section\n- \"Built for [specific audience]\" section\n\n### Final CTA Section\n\n- Recap the value proposition\n- Repeat the primary CTA\n- Add urgency if genuine (deadline, limited availability)\n- Risk reversal (guarantee, free trial, no credit card)\n\n---\n\n## Landing Page Section Variety\n\nA great landing page isn''t just a list of features. Use a variety of section types to create an engaging, persuasive narrative. Mix and match from these:\n\n### Section Types to Include\n\n**How It Works (Numbered Steps)**\nWalk users through the process in 3-4 clear steps. Reduces perceived complexity and shows the path to value.\n\n**Alternative/Competitor Comparison**\nShow how you stack up against the status quo or competitors. Tables, side-by-side comparisons, or \"Unlike X, we...\" sections.\n\n**Founder Manifesto / Our Story**\nShare why you built this and what you believe. Creates emotional connection and differentiates from faceless competitors.\n\n**Testimonials**\nCustomer quotes with names, photos, and specific results. Multiple formats: quote cards, video testimonials, tweet embeds.\n\n**Case Studies**\nDeeper stories of customer success. Problem → Solution → Results format with specific metrics.\n\n**Use Cases**\nShow different ways the product is used. Helps visitors self-identify: \"This is for people like me.\"\n\n**Personas / \"Built For\" Sections**\nExplicitly call out who the product is for: \"Perfect for marketers,\" \"Built for agencies,\" etc.\n\n**Stats and Social Proof**\nKey metrics that build credibility: \"10,000+ customers,\" \"4.9/5 rating,\" \"$2M saved for customers.\"\n\n**Demo / Product Tour**\nInteractive demos, video walkthroughs, or GIF previews showing the product in action.\n\n**FAQ Section**\nAddress common objections and questions. Good for SEO and reducing support burden.\n\n**Integrations / Partners**\nShow what tools you connect with. Logos build credibility and answer \"Will this work with my stack?\"\n\n**Pricing Preview**\nEven on non-pricing pages, a pricing teaser can move decision-makers forward.\n\n**Guarantee / Risk Reversal**\nMoney-back guarantee, free trial terms, or \"cancel anytime\" messaging reduces friction.\n\n### Recommended Section Mix\n\nFor a landing page, aim for variety. Don''t just stack features:\n\n**Typical Feature-Heavy Page (Weak):**\n1. Hero\n2. Feature 1\n3. Feature 2\n4. Feature 3\n5. Feature 4\n6. CTA\n\n**Varied, Engaging Page (Strong):**\n1. Hero with clear value prop\n2. Social proof bar (logos or stats)\n3. Problem/pain section\n4. How it works (3 steps)\n5. Key benefits (2-3, not 10)\n6. Testimonial\n7. Use cases or personas\n8. Comparison to alternatives\n9. Case study snippet\n10. FAQ\n11. Final CTA with guarantee\n\n---\n\n## CTA Copy Guidelines\n\n**Weak CTAs (avoid):**\n- Submit\n- Sign Up\n- Learn More\n- Click Here\n- Get Started\n\n**Strong CTAs (use):**\n- Start Free Trial\n- Get [Specific Thing]\n- See [Product] in Action\n- Create Your First [Thing]\n- Book My Demo\n- Download the Guide\n- Try It Free\n\n**CTA formula:**\n[Action Verb] + [What They Get] + [Qualifier if needed]\n\nExamples:\n- \"Start My Free Trial\"\n- \"Get the Complete Checklist\"\n- \"See Pricing for My Team\"\n\n---\n\n## Output Format\n\nWhen writing copy, provide:\n\n### Page Copy\nOrganized by section with clear labels:\n- Headline\n- Subheadline\n- CTA\n- Section headers\n- Body copy\n- Secondary CTAs\n\n### Annotations\nFor key elements, explain:\n- Why you made this choice\n- What principle it applies\n- Alternatives considered\n\n### Alternatives\nFor headlines and CTAs, provide 2-3 options:\n- Option A: [copy] — [rationale]\n- Option B: [copy] — [rationale]\n- Option C: [copy] — [rationale]\n\n### Meta Content (if relevant)\n- Page title (for SEO)\n- Meta description\n\n---\n\n## Page-Specific Guidance\n\n### Homepage Copy\n- Serve multiple audiences without being generic\n- Lead with broadest value proposition\n- Provide clear paths for different visitor intents\n- Balance \"ready to buy\" and \"still researching\"\n\n### Landing Page Copy\n- Single message, single CTA\n- Match headline to ad/traffic source\n- Complete argument on one page\n- Remove distractions (often no nav)\n\n### Pricing Page Copy\n- Help visitors choose the right plan\n- Clarify what''s included at each level\n- Address \"which is right for me?\" anxiety\n- Make recommended plan obvious\n\n### Feature Page Copy\n- Connect feature to benefit to outcome\n- Show use cases and examples\n- Differentiate from competitors'' versions\n- Clear path to try or buy\n\n### About Page Copy\n- Tell the story of why you exist\n- Connect company mission to customer benefit\n- Build trust through transparency\n- Still include a CTA (it''s still a marketing page)\n\n---\n\n## Voice and Tone Considerations\n\nBefore writing, establish:\n\n**Formality level:**\n- Casual/conversational\n- Professional but friendly\n- Formal/enterprise\n\n**Brand personality:**\n- Playful or serious?\n- Bold or understated?\n- Technical or accessible?\n\nMaintain consistency throughout, but adjust intensity:\n- Headlines can be bolder\n- Body copy should be clearer\n- CTAs should be action-oriented\n\n---\n\n## Related Skills\n\n- **copy-editing**: For polishing and improving existing copy (use after writing your first draft)\n- **page-cro**: If the page structure/strategy needs work, not just copy\n- **email-sequence**: For email copywriting\n- **popup-cro**: For popup and modal copy\n- **ab-test-setup**: To test copy variations properly\n"},"lastSynced":"2026-03-08T02:06:56.151Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Agents needing persuasive landing page content creation.","zh":"非常适合需要说服力登陆页内容创作的营销代理。","ja":"マーケティングエージェントが説得力のあるランディングページコンテンツを作成する必要がある場合に最適です。","ko":"説得력이 있는 랜딩 페이지 콘텐츠 생성이 필요한 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing que necesitan crear contenido de página de aterrizaje persuasivo.","fr":"Idéal pour les agents de marketing qui ont besoin de créer du contenu de page de destination persuasif.","de":"Perfekt für Marketing-Agenten, die überzeugenden Inhalt für Landingpages benötigen.","pt":"Perfeito para Agentes de Marketing que precisam criar conteúdo de página de destino persuasivo.","ru":"Идеально подходит для маркетинговых агентов, которым необходимо создавать убедительный контент для целевых страниц.","ar":"مثالي لوكلاء التسويق الذين يحتاجون إلى إنشاء محتوى صفحه هبوط مقنع."},"recommendation":{"en":"Empowers agents to craft clear and compelling marketing copy using context such as page purpose and audience analysis, driving conversions through optimized content with protocols like A/B testing and file formats like HTML and CSS.","zh":"使代理能够使用诸如页面目的和受众分析等上下文创建清晰而有力的营销文案，通过优化内容和协议如A/B测试以及文件格式如HTML和CSS驱动转化。","ja":"エージェントがページの目的やオーディエンス分析などのコンテキストを使用して、明確で説得力のあるマーケティングコピーを作成できるようにし、A/BテストやHTML、CSSなどのファイル形式などのプロトコルで最適化されたコンテンツを通じてコンバージョンを促進します。","ko":"에이전트가 페이지 목적 및 대상자 분석과 같은 컨텍스트를 사용하여 명확하고 설득력 있는 마케팅 복사를 생성할 수 있도록 하며, A/B 테스트 및 HTML, CSS와 같은 파일 형식과 같은 프로토콜을 통해 최적화된 콘텐츠를 통해 전환을 구동합니다.","es":"Empodera a los agentes para crear copias de marketing claras y convincentes utilizando el contexto como el propósito de la página y el análisis de la audiencia, impulsando las conversiones a través de contenido optimizado con protocolos como pruebas A/B y formatos de archivo como HTML y CSS.","fr":"Permet aux agents de créer des copies de marketing claires et convaincantes en utilisant le contexte tel que le but de la page et l''analyse de l''audience, en stimulant les conversions grâce à un contenu optimisé avec des protocoles tels que les tests A/B et des formats de fichier tels que HTML et CSS.","de":"Ermächtigt die Agenten, klare und überzeugende Marketingkopien zu erstellen, indem sie den Kontext wie den Zweck der Seite und die Zielgruppenanalyse verwenden, um durch optimierten Inhalt mit Protokollen wie A/B-Testing und Dateiformaten wie HTML und CSS Konversionen zu steigern.","pt":"Habilita os agentes a criar cópias de marketing claras e convincentes usando o contexto, como o propósito da página e a análise da audiência, impulsionando conversões por meio de conteúdo otimizado com protocolos como A/B testing e formatos de arquivo como HTML e CSS.","ru":"Наделяет агентов возможностью создавать ясные и убедительные маркетинговые копии, используя контекст, такой как цель страницы и анализ аудитории, стимулируя конверсии за счет оптимизированного контента с использованием протоколов, таких как A/B тестирование и форматы файлов, таких как HTML и CSS.","ar":"تمكين الوكلاء من إعداد نسخ تسويقية واضحة ومقنعة باستخدام السياق مثل غرض الصفحة وتحليل الجمهور ، مما يدفع التحويلات من خلال المحتوى المُحسّن ببروتوكولات مثل الاختبار من نوع A/B وتنسيقات الملفات مثل HTML و CSS."},"useCases":{"en":["Generating high-converting landing page headlines","Creating engaging product descriptions for e-commerce sites","Optimizing about page content for brand storytelling"],"zh":["生成高转化率的登陆页标题","为电子商务网站创建吸引人的产品描述","优化关于页面内容以进行品牌故事讲述"],"ja":["高転換率のランディングページのタイトルを生成する","電子商取引サイトのための魅力的な製品の説明を作成する","ブランドのストーリーテリングのためのAboutページコンテンツを最適化する"],"ko":["고전환률 랜딩 페이지 제목 생성","전자상거래 사이트를 위한 매력적인 제품 설명 생성","브랜드 스토리텔링을 위한_about 페이지 콘텐츠 최적화"],"es":["Generar títulos de página de aterrizaje con alta conversión","Crear descripciones de productos atractivas para sitios de comercio electrónico","Optimizar el contenido de la página sobre la historia de la marca"],"fr":["Générer des titres de page de destination à forte conversion","Créer des descriptions de produits engageantes pour les sites de commerce électronique","Optimiser le contenu de la page sur l''histoire de la marque"],"de":["Erzeugen von Landingpage-Titeln mit hoher Konversion","Erstellen von ansprechenden Produktdescriptions für E-Commerce-Websites","Optimieren des Inhalts der Über-uns-Seite für die Markenstory"],"pt":["Geração de títulos de página de destino de alto desempenho","Criação de descrições de produtos atraentes para sites de comércio eletrônico","Otimização do conteúdo da página sobre para contar histórias de marca"],"ru":["Генерация заголовков целевых страниц с высоким коэффициентом конверсии","Создание привлекательных описаний продуктов для сайтов электронной коммерции","Оптимизация контента страницы \"О нас\" для рассказывания историй бренда"],"ar":["توليد عناوين صفحات هبوط ذات تحويل عالٍ","إنشاء وصفات منتجات جذابة لمواقع التجارة الإلكترونية","تحسين محتوى صفحة من نحن لرواية قصص العلامة التجارية"]},"limitations":{"en":["Requires specific audience and page purpose context","Limited to text-based content generation"],"zh":["需要特定的受众和页面目的上下文","仅限于基于文本的内容生成"],"ja":["特定のオーディエンスとページの目的のコンテキストが必要","テキストベースのコンテンツ生成のみに限定される"],"ko":["특정 대중과 페이지 목적 컨텍스트가 필요","텍스트 기반 콘텐츠 생성만으로 제한됨"],"es":["Requiere un contexto específico de audiencia y propósito de la página","Limitado a la generación de contenido basado en texto"],"fr":["Nécessite un contexte spécifique d''audience et de but de page","Limité à la génération de contenu basé sur le texte"],"de":["Benötigt einen spezifischen Kontext für Zielgruppe und Seitenzweck","Begrenzt auf die Generierung von textbasiertem Inhalt"],"pt":["Exige contexto específico de audiência e propósito da página","Limitado à geração de conteúdo baseado em texto"],"ru":["Требует конкретного контекста аудитории и цели страницы","Ограничен генерацией текстового контента"],"ar":["يتطلب سياقًا محددًا للجمهور وغرض الصفحة","محدود بالمحتوى النصي"]},"version":4},"contentHash":"5b3ea76961e8de82f00083569f4ef275058afb70bb301a9153dd80f73837b18e","qualityScore":50}');
