INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jiangzhuizzz/MyMoltbot/copywriting', 'copywriting', 'jiangzhuizzz', 'MyMoltbot', 'community', 'copywriting jiangzhuizzz MyMoltbot community The copywriting skill generates clear and compelling marketing copy that drives action. It benefits developers and marketers seeking to optimize their page content for conversions. AIエージェント的copywriting功能可以帮助开发者创建清晰、引人入胜的营销文案 AIエージェントによるcopywriting機能は、開発者が明確で魅力的なマーケティングコピーを作成するのに役立ちます AI 에이전트의 copywriting 기능은 개발자가 명확하고 매력적인 마케팅 복사를 생성하는 데 도움이 됩니다 El copywriting es el proceso de escribir copias de marketing claras y convincentes que impulsan la conversión y el compromiso del usuario. La réécriture de contenu est le processus d''écriture de copies de marketing claires et convaincantes qui favorisent la conversion et l''engagement des utilisateurs. Copywriting ist der Prozess des Erstellens klarer und überzeugender Marketing-Kopien, die die Konversion und die Benutzerbeteiligung fördern. Nossa ferramenta de redação publicitária ajuda a criar marketing copy claro e convincente, impulsionando ações eficazes. Наша технология копирайтинга помогает создавать маркетинговый копи, который преобразует, стимулируя действия. أداة الكتابة الإعلانية تساعد على إنشاء نسخ إعلانية واضحة ومقنعة، تدفع الإجراءات الفعالة. how to use copywriting for landing pages what is conversion copywriting copywriting vs content writing copywriting setup guide for AI agents best practices for copywriting copywriting for homepage optimization AIエージェント_copywriting copywriting技术 营销文案创建 行动驱动的copywriting 页面目的分析 受众分析 Gathers context on page purpose, including primary and secondary actions Identifies ideal customer and their problem to solve Writes marketing copy for various page types, such as homepage and landing pages Optimizes copy for conversion, driving visitors to take specific actions Considers audience and their needs when crafting compelling copy Copywriting is the process of crafting marketing copy that is clear, compelling, and drives action, typically for homepage, landing page, pricing, feature, or about pages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jmreicha/lazycfg/findings', 'community', 'jmreicha', 'lazycfg', 'jmreicha/lazycfg', 'findings', 0, 0, 50, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:11.568Z', '3a50c67de7cff3f52064efe06f9e3718a909be9e86adb40da935ca73349a5666', '{"id":"jmreicha/lazycfg/findings","name":"findings","description":{"en":"Findings is a tool for managing per-repo markdown files, tracking mistakes, corrections, and patterns. It benefits developers by providing a centralized knowledge base for each project.","zh":"Findings是一种用于管理配置文件的工具，通过维护一个per-repo markdown文件来记录错误、更正和模式。","ja":"Findingsは、設定ファイルを管理するためのツールで、per-repo markdownファイルを維持してエラー、修正、パターンを記録します。","ko":"Findings는 구성 파일을 관리하는 도구로 per-repo markdown 파일을 유지하여 오류, 수정 및 패턴을 기록합니다.","es":"Findings es una herramienta para gestionar archivos de configuración, que ayuda a los desarrolladores a mantener un registro de errores, correcciones y patrones","fr":"Findings est un outil pour gérer les fichiers de configuration, qui aide les développeurs à maintenir un registre des erreurs, des corrections et des modèles","de":"Findings ist ein Tool zur Verwaltung von Konfigurationsdateien, das Entwicklern hilft, eine Aufzeichnung von Fehlern, Korrekturen und Mustern zu führen","pt":"O Findings é uma ferramenta para gerenciar arquivos de configuração, permitindo que os desenvolvedores mantenham um registro de erros, correções e padrões","ru":"ИИ Агент Findings - это инструмент для управления конфигурационными файлами, позволяющий разработчикам вести учет ошибок, исправлений и шаблонов","ar":"أداة العثور على هي أداة لإدارة ملفات التهيئة، تمكن المطورين من الحفاظ على سجل للأخطاء والتصحيحات والأنماط"},"seo":{"title":{"en":"Findings: Per-Repo Markdown Management Setup Guide | AI A...","zh":"Findings配置文件管理工具Setup Guide","ja":"Findings設定ファイル管理ツールベストプラクティス","ko":"Findings 구성 파일 관리 도구 사용법","es":"Guía de configuración de findings para desarrolladores","fr":"Configurer findings pour les développeurs : meilleures pr...","de":"Findings-Setup-Anleitung für Entwickler: Effiziente Konfi...","pt":"Guia de Configuração do Findings: Gerenciamento de Arquiv...","ru":"Настройка ИИ Агента Findings: Управление конфигурационным...","ar":"دليل إعداد العثور على أداة إدارة ملفات التهيئة"},"description":{"en":"Discover how to optimize your development workflow with Findings, a tool for managing configuration files. Learn how to get started and maximize its potentia...","zh":"使用Findings工具管理配置文件，提高开发效率，减少错误。了解Findings的工作原理和使用方法。","ja":"Findingsツールを使用して設定ファイルを管理し、開発効率を向上させ、エラーを減らします。Findingsのしくみと使い方を学びましょう。","ko":"Findings 도구를 사용하여 구성 파일을 관리하고 개발 효율성을 높이며 오류를 줄입니다. Findings의 작동 원리와 사용 방법을 알아보세요.","es":"Descubre cómo utilizar findings para gestionar archivos de configuración de manera efectiva y mejorar tu productividad como desarrollador","fr":"Découvrez comment configurer findings pour gérer vos fichiers de configuration de manière efficace et améliorer votre productivité","de":"Erfahren Sie, wie Sie findings einrichten, um Konfigurationsdateien effizient zu verwalten und Ihre Produktivität zu steigern","pt":"Aprenda a configurar o Findings, uma ferramenta para gerenciar arquivos de configuração de forma eficaz, melhorando a produtividade do desenvolvedor","ru":"Узнайте, как настроить ИИ Агент Findings, инструмент для управления конфигурационными файлами, повышающий производительность разработчика","ar":"تعلم كيفية إعداد أداة العثور على إدارة ملفات التهيئة بشكل فعال، وتحسين إنتاجية المطور"},"definition":{"en":"Findings is a skill for maintaining a per-repo markdown file that tracks mistakes, corrections, and patterns, allowing developers to internalize and apply knowledge silently.","zh":"Findings是一种配置文件管理工具，用于记录和跟踪开发过程中的错误和更正。","ja":"Findingsは、設定ファイルを管理するためのツールで、開発プロセス中的のエラーと修正を記録して追跡します。","ko":"Findings는 구성 파일 관리 도구로 개발 과정中的 오류와 수정을 기록 및 추적합니다.","es":"Findings es una herramienta de gestión de configuración que utiliza un archivo markdown para registrar errores y patrones","fr":"Findings est un outil de gestion de configuration qui utilise un fichier markdown pour enregistrer les erreurs et les modèles","de":"Findings ist ein Konfigurationsverwaltungstool, das eine Markdown-Datei verwendet, um Fehler und Muster zu erfassen","pt":"O que é Findings? É uma ferramenta para gerenciar arquivos de configuração de forma centralizada","ru":"Что такое ИИ Агент Findings? Это инструмент для централизованного управления конфигурационными файлами","ar":"ما هي أداة العثور على؟ هي أداة لإدارة ملفات التهيئة بشكل مركزي"},"features":{"en":["Maintains a per-repo markdown file for tracking mistakes, corrections, and patterns","Reads ./context/findings.md before each session to internalize knowledge","Updates findings.md continuously as new knowledge is gained","Operates silently, without requiring manual triggers or announcements","Supports continuous learning and improvement through iterative updates"],"zh":["维护per-repo markdown文件","记录错误、更正和模式","每次会话开始时读取配置文件","持续更新配置文件","支持CLI命令"],"ja":["per-repo markdownファイルの維持","エラー、修正、パターンの記録","各セッション開始時に設定ファイルの読み込み","設定ファイルの継続的な更新","CLIコマンドのサポート"],"ko":["per-repo markdown 파일 유지","오류, 수정, 패턴 기록","각 세션 시작 시 구성 파일 읽기","구성 파일의 지속적인 업데이트","CLI 명령어 지원"],"es":["Gestión de archivos de configuración mediante un archivo markdown","Registro de errores y correcciones","Identificación de patrones y mejoras","Actualización continua del archivo de configuración","Compatibilidad con repositorios de código"],"fr":["Gestion des fichiers de configuration via un fichier markdown","Enregistrement des erreurs et des corrections","Identification des modèles et des améliorations","Mise à jour continue du fichier de configuration","Compatibilité avec les référentiels de code"],"de":["Verwaltung von Konfigurationsdateien mittels einer Markdown-Datei","Erfassung von Fehlern und Korrekturen","Identifizierung von Mustern und Verbesserungen","Kontinuierliche Aktualisierung der Konfigurationsdatei","Kompatibilität mit Code-Repositorys"],"pt":["Leitura automática do arquivo de configuração","Atualização contínua do arquivo de configuração","Gerenciamento de erros e correções","Manutenção de padrões de configuração","Integração com Markdown"],"ru":["Автоматическое чтение конфигурационного файла","Постоянное обновление конфигурационного файла","Управление ошибками и исправлениями","Ведение учета шаблонов конфигурации","Интеграция с Markdown"],"ar":["قراءة автомاتیکیة لملف التهيئة","تحديث مستمر لملف التهيئة","إدارة الأخطاء والتصحيحات","الحفاظ على أنماط التهيئة","التكامل مع Markdown"]},"keywords":{"en":["how to use findings","findings alternative","findings setup guide","what is findings","findings vs markdown managers","findings install","per-repo markdown management","configuration file tracking","development workflow optimization"],"zh":["Findings工具","配置文件管理","开发效率","错误减少","markdown文件","CLI命令","AIエージェント工具","开发辅助工具"],"ja":["Findingsツール","設定ファイル管理","開発効率","エラー減少","markdownファイル","CLIコマンド","AIエージェントツール","開発支援ツール"],"ko":["Findings 도구","구성 파일 관리","개발 효율성","오류 감소","markdown 파일","CLI 명령어","AI 에이전트 도구","개발 지원 도구"],"es":["herramientas de configuración","gestión de configuración","findings para desarrolladores","configuración de repositorios","mejores prácticas de configuración","tools de configuración para desarrolladores"],"fr":["outils de configuration","gestion de configuration","findings pour les développeurs","configuration de référentiels","meilleures pratiques de configuration","tools de configuration pour les développeurs"],"de":["Konfigurationswerkzeuge","Konfigurationsverwaltung","Findings für Entwickler","Konfiguration von Repositorys","Best Practices für Konfiguration","Entwicklertools für Konfiguration"],"pt":["gerenciamento de arquivos de configuração","ferramenta de configuração","desenvolvedor de software","produtividade do desenvolvedor","gerenciamento de erros","configuração de projeto","markdown"],"ru":["управление конфигурационными файлами","инструмент конфигурации","разработчик программного обеспечения","производительность разработчика","управление ошибками","конфигурация проекта","markdown"],"ar":["إدارة ملفات التهيئة","أداة التهيئة","مطور البرمجيات","إنتاجية المطور","إدارة الأخطاء","تهيئة المشروع","markdown"]}},"owner":"jmreicha","repo":"lazycfg","repoPath":"jmreicha/lazycfg","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.414Z","topics":[],"category":"community","skillMd":{"name":"findings","description":"|","version":"1.0.0","bodyPreview":"# Finding\n\nYou maintain a per-repo markdown file that tracks mistakes, corrections, and\npatterns that work or don''t. You read it before doing anything and update it\ncontinuously as you work — whenever you learn something worth recording.\n\n**This skill is always active. Every session. No trigger required.**\n\n## Session Start: Read Your Notes\n\nFirst thing, every session — read `./context/findings.md` before doing anything\nelse. Internalize what''s there and apply it silently. Don''t announce that yo","body":"# Finding\n\nYou maintain a per-repo markdown file that tracks mistakes, corrections, and\npatterns that work or don''t. You read it before doing anything and update it\ncontinuously as you work — whenever you learn something worth recording.\n\n**This skill is always active. Every session. No trigger required.**\n\n## Session Start: Read Your Notes\n\nFirst thing, every session — read `./context/findings.md` before doing anything\nelse. Internalize what''s there and apply it silently. Don''t announce that you\nread it. Just apply what you know.\n\nIf no finding exists yet, create one at `./context/findings.md`:\n\n```markdown\n# Finding\n\n## Corrections\n\n| Date | Source | What Went Wrong | What To Do Instead |\n| ---- | ------ | --------------- | ------------------ |\n\n## User Preferences\n\n- (accumulate here as you learn them)\n\n## Patterns That Work\n\n- (approaches that succeeded)\n\n## Patterns That Don''t Work\n\n- (approaches that failed and why)\n\n## Domain Notes\n\n- (project/domain context that matters)\n```\n\nAdapt the sections to fit the repo''s domain. Design something you can usefully\nconsume.\n\n## Continuous Updates\n\nUpdate the finding as you work, not just at session start and end. Write to\nit whenever you learn something worth recording:\n\n- **You hit an error and figure out why.** Log it immediately. Don''t wait.\n- **The user corrects you.** Log what you did and what they wanted instead.\n- **You catch your own mistake.** Log it. Your mistakes count the same as\n  user corrections — maybe more, because you''re the one who knows what went\n  wrong internally.\n- **You try something and it fails.** Log the approach and why it didn''t work\n  so you don''t repeat it.\n- **You try something and it works well.** Log the pattern.\n- **You re-read the napkin mid-task** because you''re about to do something\n  you''ve gotten wrong before. Good. Do this.\n\nThe finding is a living document. Treat it like working memory that persists\nacross sessions, not a journal you write in once.\n\n## What to Log\n\nLog anything that would change your behavior if you read it next session:\n\n- **Your own mistakes**: wrong assumptions, bad approaches, misread code,\n  failed commands, incorrect fixes you had to redo.\n- **User corrections**: anything the user told you to do differently.\n- **Tool/environment surprises**: things about this repo, its tooling, or its\n  patterns that you didn''t expect.\n- **Preferences**: how the user likes things done — style, structure, process.\n- **What worked**: approaches that succeeded, especially non-obvious ones.\n\nBe specific. \"Made an error\" is useless. \"Assumed the API returns a list but\nit returns a paginated object with `.items`\" is actionable.\n\n## Finding Maintenance\n\nEvery 5-10 sessions, or when the file exceeds ~150 lines, consolidate:\n\n- Merge redundant entries into a single rule.\n- Promote repeated corrections to User Preferences.\n- Remove entries that are now captured as top-level rules.\n- Archive resolved or outdated notes.\n- Keep total length under 200 lines of high-signal content.\n\nA 50-line napkin of hard-won rules beats a 500-line log of raw entries.\n\n## Example\n\n**Early in a session** — you misread a function signature and pass args in the\nwrong order. You catch it yourself. Log it:\n\n```markdown\n| 2026-02-06 | self | Passed (name, id) to createUser but signature is (id, name) | Check function signatures before calling, this codebase doesn''t follow conventional arg ordering |\n```\n\n**Mid-session** — user corrects your import style. Log it:\n\n```markdown\n| 2026-02-06 | user | Used relative imports | This repo uses absolute imports from `src/` — always |\n```\n\n**Later** — you re-read the finding before editing another file and use\nabsolute imports without being told. That''s the loop working.\n"},"lastSynced":"2026-03-08T02:07:11.568Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing centralized knowledge base management for per-repo markdown files.","zh":"非常适合需要集中式知识库管理的开发代理，用于管理每个仓库的markdown文件。","ja":"開発エージェントがリポジトリごとのMarkdownファイルを集中管理する必要がある開発に最適です。","ko":"리포지토리별 마크다운 파일을 중앙 集中管理할 필요가 있는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de base de conocimientos centralizada para archivos markdown por repositorio.","fr":"Parfait pour les agents de développement qui ont besoin d''une gestion de base de connaissances centralisée pour les fichiers markdown par référentiel.","de":"Perfekt für Entwicklungsmittel, die eine zentrale Wissensbasisverwaltung für pro-Repository-Markdown-Dateien benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de base de conhecimento centralizada para arquivos markdown por repositório.","ru":"Идеально подходит для агентов разработки, которым необходима централизованная система управления базой знаний для файлов markdown в каждом репозитории.","ar":"مثالي لعمال التطوير الذين يحتاجون إلى إدارة قاعدة معرفة مركزية لملفات markdown لكل مستودع."},"recommendation":{"en":"Empowers agents to silently internalize and apply project-specific findings, utilizing markdown files to track mistakes, corrections, and patterns, thereby enhancing their development workflow with continuous learning and improvement through ./context/findings.md updates.","zh":"赋予代理silently内部化和应用项目特定发现，利用markdown文件跟踪错误、更正和模式，从而通过./context/findings.md更新增强其开发工作流程，实现持续学习和改进。","ja":"エージェントが静かに内部化してプロジェクト固有の発見を適用できるようにし、Markdownファイルを使用してエラー、修正、パターンを追跡し、./context/findings.mdの更新を通じて開発ワークフローを継続的に学習して改善します。","ko":"에이전트가 프로젝트 특정 발견을 무음으로 내부화하고 적용할 수 있도록 하며, 마크다운 파일을 사용하여 오류, 수정 및 패턴을 추적하고 ./context/findings.md 업데이트를 통해 개발 워크플로우를 지속적으로 학습하고 개선합니다.","es":"Habilita a los agentes a internalizar y aplicar silenciosamente hallazgos específicos del proyecto, utilizando archivos markdown para rastrear errores, correcciones y patrones, mejorando así su flujo de trabajo de desarrollo con aprendizaje y mejora continuos a través de actualizaciones de ./context/findings.md.","fr":"Permet aux agents d''internaliser et d''appliquer en silence des résultats spécifiques au projet, en utilisant des fichiers markdown pour suivre les erreurs, les corrections et les modèles, améliorant ainsi leur flux de travail de développement avec un apprentissage et une amélioration continus via des mises à jour de ./context/findings.md.","de":"Ermöglicht es den Agenten, Projektergebnisse stumm zu internalisieren und anzuwenden, indem sie Markdown-Dateien verwenden, um Fehler, Korrekturen und Muster zu verfolgen, und verbessert so ihren Entwicklungsworkflow mit kontinuierlichem Lernen und Verbesserung durch ./context/findings.md-Updates.","pt":"Habilita os agentes a internalizar e aplicar silenciosamente descobertas específicas do projeto, utilizando arquivos markdown para rastrear erros, correções e padrões, melhorando assim seu fluxo de trabalho de desenvolvimento com aprendizado e melhoria contínua por meio de atualizações do ./context/findings.md.","ru":"Наделяет агентов возможностью默но внутренне усваивать и применять результаты проекта, используя файлы markdown для отслеживания ошибок, исправлений и закономерностей, тем самым повышая эффективность их рабочего процесса разработки за счет непрерывного обучения и совершенствования посредством обновлений ./context/findings.md.","ar":"يمنح الوكلاء القدرة على استيعاب وتنفيذ النتائج الخاصة بالمشروع بصمت، باستخدام ملفات markdown لتتبع الأخطاء والتصحيحات والأنماط، وبالتالي تحسين تدفق عملهم التطويعي مع التعلم المستمر والتحسين من خلال تحديثات ./context/findings.md."},"useCases":{"en":["Updating project knowledge bases with corrections and patterns","Automating the review of per-repo markdown files for informed development decisions","Debugging project issues by referencing historical mistakes and corrections"],"zh":["使用更正和模式更新项目知识库","自动审查每个仓库的markdown文件以进行明智的开发决策","通过引用历史错误和更正来调试项目问题"],"ja":["修正とパターンを使用してプロジェクトのナレッジベースを更新する","リポジトリごとのMarkdownファイルを自動的にレビューして、情報に基づいた開発決定を行う","歴史的なエラーと修正を参照して、プロジェクトの問題をデバッグする"],"ko":["수정 및 패턴을 사용하여 프로젝트 지식베이스를 업데이트함","리포지토리별 마크다운 파일을 자동으로 검토하여 정보에 근거한 개발 결정을 내림","과거의 오류 및 수정을 참조하여 프로젝트 문제를 디버깅함"],"es":["Actualización de bases de conocimiento de proyectos con correcciones y patrones","Automatización de la revisión de archivos markdown por repositorio para tomar decisiones de desarrollo informadas","Depuración de problemas de proyecto haciendo referencia a errores y correcciones históricos"],"fr":["Mise à jour des bases de connaissances de projet avec des corrections et des modèles","Automatisation de l''examen des fichiers markdown par référentiel pour prendre des décisions de développement éclairées","Débogage des problèmes de projet en référençant les erreurs et les corrections historiques"],"de":["Aktualisierung von Projektwissensbasen mit Korrekturen und Mustern","Automatisierung der Überprüfung von pro-Repository-Markdown-Dateien für fundierte Entwicklungsentscheidungen","Fehlerbehebung bei Projekten durch Verweis auf historische Fehler und Korrekturen"],"pt":["Atualizar bases de conhecimento de projeto com correções e padrões","Automatizar a revisão de arquivos markdown por repositório para tomar decisões de desenvolvimento informadas","Depurar problemas de projeto referenciando erros e correções históricos"],"ru":["Обновление баз знаний проекта с исправлениями и закономерностями","Автоматизация проверки файлов markdown в каждом репозитории для принятия обоснованных решений по разработке","Отладка проблем проекта с ссылкой на исторические ошибки и исправления"],"ar":["تحديث قواعد المعرفة للمشروع مع التصحيحات والأنماط","تأتمتة عملية مراجعة ملفات markdown لكل مستودع لاتخاذ قرارات تطويرية مستنيرة","تصحيح مشاكل المشروع بالاطلاع على الأخطاء والتصحيحات التاريخية"]},"limitations":{"en":["Requires access to per-repo markdown files","Limited to projects with ./context/findings.md files"],"zh":["需要访问每个仓库的markdown文件","仅限于具有./context/findings.md文件的项目"],"ja":["リポジトリごとのMarkdownファイルにアクセスする必要があります"," ./context/findings.mdファイルを持つプロジェクトのみに限定されます"],"ko":["각 리포지토리의 마크다운 파일에 접근할 수 있어야 함"," ./context/findings.md 파일을 가지고 있는 프로젝트에만 제한됨"],"es":["Requiere acceso a archivos markdown por repositorio","Limitado a proyectos con archivos ./context/findings.md"],"fr":["Nécessite l''accès aux fichiers markdown par référentiel","Limité aux projets avec des fichiers ./context/findings.md"],"de":["Benötigt Zugriff auf pro-Repository-Markdown-Dateien","Begrenzt auf Projekte mit ./context/findings.md-Dateien"],"pt":["Requer acesso a arquivos markdown por repositório","Limitado a projetos com arquivos ./context/findings.md"],"ru":["Требует доступа к файлам markdown в каждом репозитории","Ограничен проектами с файлами ./context/findings.md"],"ar":["يتطلب الوصول إلى ملفات markdown لكل مستودع","محدود بمشاريع ملفات ./context/findings.md"]},"version":4},"contentHash":"3a50c67de7cff3f52064efe06f9e3718a909be9e86adb40da935ca73349a5666","