INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jmreicha/lazycfg/findings', 'findings', 'jmreicha', 'lazycfg', 'community', 'findings jmreicha lazycfg community Findings is a tool for managing per-repo markdown files, tracking mistakes, corrections, and patterns. It benefits developers by providing a centralized knowledge base for each project. Findings是一种用于管理配置文件的工具，通过维护一个per-repo markdown文件来记录错误、更正和模式。 Findingsは、設定ファイルを管理するためのツールで、per-repo markdownファイルを維持してエラー、修正、パターンを記録します。 Findings는 구성 파일을 관리하는 도구로 per-repo markdown 파일을 유지하여 오류, 수정 및 패턴을 기록합니다. Findings es una herramienta para gestionar archivos de configuración, que ayuda a los desarrolladores a mantener un registro de errores, correcciones y patrones Findings est un outil pour gérer les fichiers de configuration, qui aide les développeurs à maintenir un registre des erreurs, des corrections et des modèles Findings ist ein Tool zur Verwaltung von Konfigurationsdateien, das Entwicklern hilft, eine Aufzeichnung von Fehlern, Korrekturen und Mustern zu führen O Findings é uma ferramenta para gerenciar arquivos de configuração, permitindo que os desenvolvedores mantenham um registro de erros, correções e padrões ИИ Агент Findings - это инструмент для управления конфигурационными файлами, позволяющий разработчикам вести учет ошибок, исправлений и шаблонов أداة العثور على هي أداة لإدارة ملفات التهيئة، تمكن المطورين من الحفاظ على سجل للأخطاء والتصحيحات والأنماط how to use findings findings alternative findings setup guide what is findings findings vs markdown managers findings install per-repo markdown management configuration file tracking development workflow optimization Findings工具 配置文件管理 开发效率 错误减少 markdown文件 CLI命令 AIエージェント工具 开发辅助工具 Maintains a per-repo markdown file for tracking mistakes, corrections, and patterns Reads ./context/findings.md before each session to internalize knowledge Updates findings.md continuously as new knowledge is gained Operates silently, without requiring manual triggers or announcements Supports continuous learning and improvement through iterative updates Findings is a skill for maintaining a per-repo markdown file that tracks mistakes, corrections, and patterns, allowing developers to internalize and apply knowledge silently.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sayeedjoy/seucampusmate-web/core-web-vitals', 'community', 'sayeedjoy', 'seucampusmate-web', 'sayeedjoy/seucampusmate-web', 'core-web-vitals', 0, 0, 50, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:13.078Z', 'b03396c9bd7a41950bbaf5964bc8f1cf60a3c81830a6171614d6413c8bff308c', '{"id":"sayeedjoy/seucampusmate-web/core-web-vitals","name":"core-web-vitals","description":{"en":"The core-web-vitals skill optimizes web performance for Southeast University students, focusing on three key metrics: LCP, INP, and CLS, to enhance user experience and Google Search ranking.","zh":"Core Web Vitals 优化是为了提高网页性能和用户体验，包括加载时间、交互性和视觉稳定性","ja":"Core Web Vitals 最適化は、Web ページのパフォーマンスとユーザーエクスペリエンスを向上させるために、ロード時間、インタラクティビティ、視覚的安定性を最適化する","ko":"Core Web Vitals 최적화는 웹 페이지 성능과 사용자 경험을 개선하기 위해 로딩 시간, 상호 작용성, 시각적 안정성을 최적화하는 것","es":"Optimiza los tres métricos de Core Web Vitals: LCP, INP y CLS para mejorar la experiencia del usuario y el ranking en Google. Aprende a configurar y optimizar tus sitios web para una mejor experiencia del usuario","fr":"Optimisez les trois métriques de Core Web Vitals : LCP, INP et CLS pour améliorer l''expérience utilisateur et le référencement Google. Découvrez comment configurer et optimiser vos sites web pour une meilleure expérience utilisateur","de":"Optimieren Sie die drei Core Web Vitals-Metriken: LCP, INP und CLS, um die Benutzererfahrung und die Google-Suche zu verbessern. Erfahren Sie, wie Sie Ihre Websites konfigurieren und optimieren, um eine bessere Benutzererfahrung zu bieten","pt":"Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranking no Google. Aprenda a configurar e otimizar os três principais métricas: LCP, INP e CLS.","ru":"ИИ Агенты для оптимизации Core Web Vitals. Узнайте, как настроить и оптимизировать три основных метрики: LCP, INP и CLS, чтобы улучшить пользовательский опыт и рейтинг в Google.","ar":"اداة الذكاء الاصطناعي لتحسين Core Web Vitals. تعرف على كيفية إعداد وتحسين ثلاثة مقاييس أساسية: LCP، INP و CLS لتحسين تجربة المستخدم وترتيب گوگل"},"seo":{"title":{"en":"core-web-vitals: Optimization Setup Guide | AI Agent Skill","zh":"Core Web Vitals 优化设置指南","ja":"Core Web Vitals 最適化セットアップガイド","ko":"Core Web Vitals 최적화 설정 가이드","es":"Optimización de Core Web Vitals: Guía de configuración","fr":"Guide de configuration des Core Web Vitals","de":"Core Web Vitals-Optimierung: Einrichtungsleitfaden","pt":"Otimização de Core Web Vitals: Guia de Configuração","ru":"ИИ Агенты для оптимизации Core Web Vitals: Настройка и лу...","ar":"اداة الذكاء الاصطناعي لتحسين Core Web Vitals: دليل الإعداد"},"description":{"en":"Unlock better Google Search rankings and user experience with core-web-vitals optimization - learn how to improve LCP, INP, and CLS metrics today!","zh":"了解 Core Web Vitals 的三大指标：LCP、INP 和 CLS，优化网页性能和用户体验","ja":"Core Web Vitals の 3 つの指標：LCP、INP、CLS を最適化して、Web ページのパフォーマンスとユーザーエクスペリエンスを向上させる","ko":"Core Web Vitals의 3가지 지표: LCP, INP, CLS를 최적화하여 웹 페이지 성능과 사용자 경험을 개선하는 방법","es":"Aprende a optimizar los tres métricos de Core Web Vitals: LCP, INP y CLS para mejorar la experiencia del usuario y el ranking en Google","fr":"Découvrez comment optimiser les trois métriques de Core Web Vitals : LCP, INP et CLS pour améliorer l''expérience utilisateur et le référencement Google","de":"Erfahren Sie, wie Sie die drei Core Web Vitals-Metriken: LCP, INP und CLS optimieren, um die Benutzererfahrung und die Google-Suche zu verbessern","pt":"Aprenda a otimizar os três principais métricas de Core Web Vitals para melhorar a experiência do usuário e o ranking no Google","ru":"Узнайте, как оптимизировать три основных метрики Core Web Vitals, чтобы улучшить пользовательский опыт и рейтинг в Google с помощью ИИ Агентов","ar":"تعرف على كيفية تحسين ثلاثة مقاييس Core Web Vitals الأساسية لتحسين تجربة المستخدم وترتيب گوگل باستخدام أداة الذكاء الاصطناعي"},"definition":{"en":"core-web-vitals is a set of metrics that measure web performance, including Largest Contentful Paint (LCP), Interactivity (INP), and Cumulative Layout Shift (CLS), to improve user experience and search engine ranking.","zh":"Core Web Vitals 是一种用于衡量网页性能和用户体验的指标，包括 LCP、INP 和 CLS","ja":"Core Web Vitals は、Web ページのパフォーマンスとユーザーエクスペリエンスを測定する指標で、LCP、INP、CLS の 3 つで構成される","ko":"Core Web Vitals은 웹 페이지 성능과 사용자 경험을 측정하는 지표로, LCP, INP, CLS의 3가지로 구성","es":"Core Web Vitals son métricas que miden la experiencia del usuario en un sitio web, incluyendo la velocidad de carga, la interactividad y la estabilidad visual","fr":"Les Core Web Vitals sont des métriques qui mesurent l''expérience utilisateur sur un site web, notamment la vitesse de chargement, l''interactivité et la stabilité visuelle","de":"Core Web Vitals sind Metriken, die die Benutzererfahrung auf einer Website messen, einschließlich Ladezeit, Interaktivität und visueller Stabilität","pt":"Core Web Vitals é um conjunto de métricas que medem a experiência do usuário em um site, incluindo LCP, INP e CLS.","ru":"Core Web Vitals - это набор метрик, измеряющих пользовательский опыт на сайте, включая LCP, INP и CLS.","ar":"Core Web Vitals هي مجموعة من المقاييس التي تقيس تجربة المستخدم على موقع الويب، بما في ذلك LCP و INP و CLS."},"features":{"en":["Optimizes Largest Contentful Paint (LCP) for faster loading times","Improves Interactivity (INP) with targeted optimization for better user engagement","Enhances Cumulative Layout Shift (CLS) for improved visual stability","Provides 75th percentile measurement for accurate performance assessment","Supports Google Search ranking improvement through optimized web performance"],"zh":["加载时间（LCP）优化","交互性（INP）优化","视觉稳定性（CLS）优化","75th 百分位数测量","Google 搜索排名优化","用户体验改善"],"ja":["ロード時間（LCP）最適化","インタラクティビティ（INP）最適化","視覚的安定性（CLS）最適化","75th パーセンタイル測定","Google 検索ランキング最適化","ユーザーエクスペリエンスの改善"],"ko":["로딩 시간（LCP）최적화","상호 작용성（INP）최적화","시각적 안정성（CLS）최적화","75th 백분위 수 측정","Google 검색 순위 최적화","사용자 경험 개선"],"es":["Optimización de LCP (Loading) para una carga más rápida","Mejora de la interactividad con INP (Interactivity)","Optimización de CLS (Visual Stability) para una experiencia del usuario más estable","Análisis de las métricas de Core Web Vitals para identificar áreas de mejora","Configuración de sitios web para una mejor experiencia del usuario","Integración con herramientas de desarrollo para una optimización más efectiva"],"fr":["Optimisation de LCP (Loading) pour un chargement plus rapide","Amélioration de l''interactivité avec INP (Interactivity)","Optimisation de CLS (Visual Stability) pour une expérience utilisateur plus stable","Analyse des métriques de Core Web Vitals pour identifier les domaines d''amélioration","Configuration de sites web pour une meilleure expérience utilisateur","Intégration avec des outils de développement pour une optimisation plus efficace"],"de":["Optimierung von LCP (Loading) für eine schnellere Ladezeit","Verbesserung der Interaktivität mit INP (Interactivity)","Optimierung von CLS (Visual Stability) für eine stabilere Benutzererfahrung","Analyse der Core Web Vitals-Metriken, um Bereiche für Verbesserungen zu identifizieren","Konfiguration von Websites für eine bessere Benutzererfahrung","Integration mit Entwicklungstools für eine effektivere Optimierung"],"pt":["Otimização de LCP (Loading Performance) para carregamento rápido de páginas","Melhoria de INP (Interactivity) para interação rápida com o usuário","Otimização de CLS (Visual Stability) para estabilidade visual da página","Análise de desempenho no 75º percentil para garantir a experiência do usuário","Configuração de métricas personalizadas para atender às necessidades do site","Integração com ferramentas de desenvolvimento para simplificar a otimização"],"ru":["Оптимизация LCP (Loading Performance) для быстрой загрузки страниц","Улучшение INP (Interactivity) для быстрого взаимодействия с пользователем","Оптимизация CLS (Visual Stability) для визуальной стабильности страницы","Анализ производительности в 75-м процентиле для обеспечения пользовательского опыта","Настройка пользовательских метрик для удовлетворения потребностей сайта","Интеграция с инструментами разработки для упрощения оптимизации"],"ar":["تحسين LCP (أداء التحميل) لتحميل الصفحات بسرعة","تحسين INP (التفاعل) للتفاعل السريع مع المستخدم","تحسين CLS (الاستقرار البصري) لاستقرار الصفحة بصريا","تحليل الأداء في Percentil 75 لضمان تجربة المستخدم","تكوين مقاييس مخصصة لتلبي احتياجات الموقع","تكامل مع أدوات التطوير لتبسيط التحسين"]},"keywords":{"en":["how to use core-web-vitals","what is core-web-vitals","core-web-vitals optimization guide","core-web-vitals vs web performance optimization","core-web-vitals setup tutorial","improve LCP and INP metrics","optimize CLS for better user experience","core-web-vitals install and setup","core-web-vitals alternative solutions"],"zh":["Core Web Vitals","网页性能优化","用户体验改善","LCP 优化","INP 优化","CLS 优化","Google 搜索排名","AI 工具","Web 优化"],"ja":["Core Web Vitals","Web ページのパフォーマンス最適化","ユーザーエクスペリエンスの改善","LCP 最適化","INP 最適化","CLS 最適化","Google 検索ランキング","AI エージェント","Web 最適化"],"ko":["Core Web Vitals","웹 페이지 성능 최적화","사용자 경험 개선","LCP 최적화","INP 최적화","CLS 최적화","Google 검색 순위","AI 도구","웹 최적화"],"es":["Core Web Vitals","Optimización de sitios web","Experiencia del usuario","LCP","INP","CLS","Mejora de la velocidad de carga","Interactividad","Estabilidad visual","Herramientas de desarrollo"],"fr":["Core Web Vitals","Optimisation de sites web","Expérience utilisateur","LCP","INP","CLS","Amélioration de la vitesse de chargement","Interactivité","Stabilité visuelle","Outils de développement"],"de":["Core Web Vitals","Optimierung von Websites","Benutzererfahrung","LCP","INP","CLS","Verbesserung der Ladezeit","Interaktivität","Visuelle Stabilität","Entwicklungstools"],"pt":["Core Web Vitals","Otimização de site","Experiência do usuário","Ranking no Google","LCP","INP","CLS","Desempenho de carregamento","Interação rápida","Estabilidade visual"],"ru":["Core Web Vitals","ИИ Агенты","Оптимизация сайта","Пользовательский опыт","Рейтинг в Google","LCP","INP","CLS","Производительность загрузки","Быстрое взаимодействие","Визуальная стабильность"],"ar":["Core Web Vitals","اداة الذكاء الاصطناعي","تحسين موقع الويب","تجربة المستخدم","ترتيب گوگل","LCP","INP","CLS","أداء التحميل","التفاعل السريع","الاستقرار البصري"]}},"owner":"sayeedjoy","repo":"seucampusmate-web","repoPath":"sayeedjoy/seucampusmate-web","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"core-web-vitals","description":"Optimize Core Web Vitals (LCP, INP, CLS) for better page experience and search ranking. Use when asked to improve Core Web Vitals, fix LCP, reduce CLS, optimize INP, page experience optimization, or fix layout shifts.","version":"1.0","bodyPreview":"# Core Web Vitals optimization\n\nTargeted optimization for the three Core Web Vitals metrics that affect Google Search ranking and user experience.\n\n## The three metrics\n\n| Metric | Measures | Good | Needs work | Poor |\n|--------|----------|------|------------|------|\n| **LCP** | Loading | ≤ 2.5s | 2.5s – 4s | > 4s |\n| **INP** | Interactivity | ≤ 200ms | 200ms – 500ms | > 500ms |\n| **CLS** | Visual Stability | ≤ 0.1 | 0.1 – 0.25 | > 0.25 |\n\nGoogle measures at the **75th percentile** — 75% of page","body":"# Core Web Vitals optimization\n\nTargeted optimization for the three Core Web Vitals metrics that affect Google Search ranking and user experience.\n\n## The three metrics\n\n| Metric | Measures | Good | Needs work | Poor |\n|--------|----------|------|------------|------|\n| **LCP** | Loading | ≤ 2.5s | 2.5s – 4s | > 4s |\n| **INP** | Interactivity | ≤ 200ms | 200ms – 500ms | > 500ms |\n| **CLS** | Visual Stability | ≤ 0.1 | 0.1 – 0.25 | > 0.25 |\n\nGoogle measures at the **75th percentile** — 75% of page visits must meet \"Good\" thresholds.\n\n---\n\n## LCP: Largest Contentful Paint\n\nLCP measures when the largest visible content element renders. Usually this is:\n- Hero image or video\n- Large text block\n- Background image\n- `<svg>` element\n\n### Common LCP issues\n\n**1. Slow server response (TTFB > 800ms)**\n```\nFix: CDN, caching, optimized backend, edge rendering\n```\n\n**2. Render-blocking resources**\n```html\n<!-- ❌ Blocks rendering -->\n<link rel=\"stylesheet\" href=\"/all-styles.css\">\n\n<!-- ✅ Critical CSS inlined, rest deferred -->\n<style>/* Critical above-fold CSS */</style>\n<link rel=\"preload\" href=\"/styles.css\" as=\"style\" \n      onload=\"this.onload=null;this.rel=''stylesheet''\">\n```\n\n**3. Slow resource load times**\n```html\n<!-- ❌ No hints, discovered late -->\n<img src=\"/hero.jpg\" alt=\"Hero\">\n\n<!-- ✅ Preloaded with high priority -->\n<link rel=\"preload\" href=\"/hero.webp\" as=\"image\" fetchpriority=\"high\">\n<img src=\"/hero.webp\" alt=\"Hero\" fetchpriority=\"high\">\n```\n\n**4. Client-side rendering delays**\n```javascript\n// ❌ Content loads after JavaScript\nuseEffect(() => {\n  fetch(''/api/hero-text'').then(r => r.json()).then(setHeroText);\n}, []);\n\n// ✅ Server-side or static rendering\n// Use SSR, SSG, or streaming to send HTML with content\nexport async function getServerSideProps() {\n  const heroText = await fetchHeroText();\n  return { props: { heroText } };\n}\n```\n\n### LCP optimization checklist\n\n```markdown\n- [ ] TTFB < 800ms (use CDN, edge caching)\n- [ ] LCP image preloaded with fetchpriority=\"high\"\n- [ ] LCP image optimized (WebP/AVIF, correct size)\n- [ ] Critical CSS inlined (< 14KB)\n- [ ] No render-blocking JavaScript in <head>\n- [ ] Fonts don''t block text rendering (font-display: swap)\n- [ ] LCP element in initial HTML (not JS-rendered)\n```\n\n### LCP element identification\n```javascript\n// Find your LCP element\nnew PerformanceObserver((list) => {\n  const entries = list.getEntries();\n  const lastEntry = entries[entries.length - 1];\n  console.log(''LCP element:'', lastEntry.element);\n  console.log(''LCP time:'', lastEntry.startTime);\n}).observe({ type: ''largest-contentful-paint'', buffered: true });\n```\n\n---\n\n## INP: Interaction to Next Paint\n\nINP measures responsiveness across ALL interactions (clicks, taps, key presses) during a page visit. It reports the worst interaction (at 98th percentile for high-traffic pages).\n\n### INP breakdown\n\nTotal INP = **Input Delay** + **Processing Time** + **Presentation Delay**\n\n| Phase | Target | Optimization |\n|-------|--------|--------------|\n| Input Delay | < 50ms | Reduce main thread blocking |\n| Processing | < 100ms | Optimize event handlers |\n| Presentation | < 50ms | Minimize rendering work |\n\n### Common INP issues\n\n**1. Long tasks blocking main thread**\n```javascript\n// ❌ Long synchronous task\nfunction processLargeArray(items) {\n  items.forEach(item => expensiveOperation(item));\n}\n\n// ✅ Break into chunks with yielding\nasync function processLargeArray(items) {\n  const CHUNK_SIZE = 100;\n  for (let i = 0; i < items.length; i += CHUNK_SIZE) {\n    const chunk = items.slice(i, i + CHUNK_SIZE);\n    chunk.forEach(item => expensiveOperation(item));\n    \n    // Yield to main thread\n    await new Promise(r => setTimeout(r, 0));\n    // Or use scheduler.yield() when available\n  }\n}\n```\n\n**2. Heavy event handlers**\n```javascript\n// ❌ All work in handler\nbutton.addEventListener(''click'', () => {\n  // Heavy computation\n  const result = calculateComplexThing();\n  // DOM updates\n  updateUI(result);\n  // Analytics\n  trackEvent(''click'');\n});\n\n// ✅ Prioritize visual feedback\nbutton.addEventListener(''click'', () => {\n  // Immediate visual feedback\n  button.classList.add(''loading'');\n  \n  // Defer non-critical work\n  requestAnimationFrame(() => {\n    const result = calculateComplexThing();\n    updateUI(result);\n  });\n  \n  // Use requestIdleCallback for analytics\n  requestIdleCallback(() => trackEvent(''click''));\n});\n```\n\n**3. Third-party scripts**\n```javascript\n// ❌ Eagerly loaded, blocks interactions\n<script src=\"https://heavy-widget.com/widget.js\"></script>\n\n// ✅ Lazy loaded on interaction or visibility\nconst loadWidget = () => {\n  import(''https://heavy-widget.com/widget.js'')\n    .then(widget => widget.init());\n};\nbutton.addEventListener(''click'', loadWidget, { once: true });\n```\n\n**4. Excessive re-renders (React/Vue)**\n```javascript\n// ❌ Re-renders entire tree\nfunction App() {\n  const [count, setCount] = useState(0);\n  return (\n    <div>\n      <Counter count={count} />\n      <ExpensiveComponent /> {/* Re-renders on every count change */}\n    </div>\n  );\n}\n\n// ✅ Memoized expensive components\nconst MemoizedExpensive = React.memo(ExpensiveComponent);\n\nfunction App() {\n  const [count, setCount] = useState(0);\n  return (\n    <div>\n      <Counter count={count} />\n      <MemoizedExpensive />\n    </div>\n  );\n}\n```\n\n### INP optimization checklist\n\n```markdown\n- [ ] No tasks > 50ms on main thread\n- [ ] Event handlers complete quickly (< 100ms)\n- [ ] Visual feedback provided immediately\n- [ ] Heavy work deferred with requestIdleCallback\n- [ ] Third-party scripts don''t block interactions\n- [ ] Debounced input handlers where appropriate\n- [ ] Web Workers for CPU-intensive operations\n```\n\n### INP debugging\n```javascript\n// Identify slow interactions\nnew PerformanceObserver((list) => {\n  for (const entry of list.getEntries()) {\n    if (entry.duration > 200) {\n      console.warn(''Slow interaction:'', {\n        type: entry.name,\n        duration: entry.duration,\n        processingStart: entry.processingStart,\n        processingEnd: entry.processingEnd,\n        target: entry.target\n      });\n    }\n  }\n}).observe({ type: ''event'', buffered: true, durationThreshold: 16 });\n```\n\n---\n\n## CLS: Cumulative Layout Shift\n\nCLS measures unexpected layout shifts. A shift occurs when a visible element changes position between frames without user interaction.\n\n**CLS Formula:** `impact fraction × distance fraction`\n\n### Common CLS causes\n\n**1. Images without dimensions**\n```html\n<!-- ❌ Causes layout shift when loaded -->\n<img src=\"photo.jpg\" alt=\"Photo\">\n\n<!-- ✅ Space reserved -->\n<img src=\"photo.jpg\" alt=\"Photo\" width=\"800\" height=\"600\">\n\n<!-- ✅ Or use aspect-ratio -->\n<img src=\"photo.jpg\" alt=\"Photo\" style=\"aspect-ratio: 4/3; width: 100%;\">\n```\n\n**2. Ads, embeds, and iframes**\n```html\n<!-- ❌ Unknown size until loaded -->\n<iframe src=\"https://ad-network.com/ad\"></iframe>\n\n<!-- ✅ Reserve space with min-height -->\n<div style=\"min-height: 250px;\">\n  <iframe src=\"https://ad-network.com/ad\" height=\"250\"></iframe>\n</div>\n\n<!-- ✅ Or use aspect-ratio container -->\n<div style=\"aspect-ratio: 16/9;\">\n  <iframe src=\"https://youtube.com/embed/...\" \n          style=\"width: 100%; height: 100%;\"></iframe>\n</div>\n```\n\n**3. Dynamically injected content**\n```javascript\n// ❌ Inserts content above viewport\nnotifications.prepend(newNotification);\n\n// ✅ Insert below viewport or use transform\nconst insertBelow = viewport.bottom < newNotification.top;\nif (insertBelow) {\n  notifications.prepend(newNotification);\n} else {\n  // Animate in without shifting\n  newNotification.style.transform = ''translateY(-100%)'';\n  notifications.prepend(newNotification);\n  requestAnimationFrame(() => {\n    newNotification.style.transform = '''';\n  });\n}\n```\n\n**4. Web fonts causing FOUT**\n```css\n/* ❌ Font swap shifts text */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n}\n\n/* ✅ Optional font (no shift if slow) */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n  font-display: optional;\n}\n\n/* ✅ Or match fallback metrics */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n  font-display: swap;\n  size-adjust: 105%; /* Match fallback size */\n  ascent-override: 95%;\n  descent-override: 20%;\n}\n```\n\n**5. Animations triggering layout**\n```css\n/* ❌ Animates layout properties */\n.animate {\n  transition: height 0.3s, width 0.3s;\n}\n\n/* ✅ Use transform instead */\n.animate {\n  transition: transform 0.3s;\n}\n.animate.expanded {\n  transform: scale(1.2);\n}\n```\n\n### CLS optimization checklist\n\n```markdown\n- [ ] All images have width/height or aspect-ratio\n- [ ] All videos/embeds have reserved space\n- [ ] Ads have min-height containers\n- [ ] Fonts use font-display: optional or matched metrics\n- [ ] Dynamic content inserted below viewport\n- [ ] Animations use transform/opacity only\n- [ ] No content injected above existing content\n```\n\n### CLS debugging\n```javascript\n// Track layout shifts\nnew PerformanceObserver((list) => {\n  for (const entry of list.getEntries()) {\n    if (!entry.hadRecentInput) {\n      console.log(''Layout shift:'', entry.value);\n      entry.sources?.forEach(source => {\n        console.log(''  Shifted element:'', source.node);\n        console.log(''  Previous rect:'', source.previousRect);\n        console.log(''  Current rect:'', source.currentRect);\n      });\n    }\n  }\n}).observe({ type: ''layout-shift'', buffered: true });\n```\n\n---\n\n## Measurement tools\n\n### Lab testing\n- **Chrome DevTools** → Performance panel, Lighthouse\n- **WebPageTest** → Detailed waterfall, filmstrip\n- **Lighthouse CLI** → `npx lighthouse <url>`\n\n### Field data (real users)\n- **Chrome User Experience Report (CrUX)** → BigQuery or API\n- **Search Console** → Core Web Vitals report\n- **web-vitals library** → Send to your analytics\n\n```javascript\nimport {onLCP, onINP, onCLS} from ''web-vitals'';\n\nfunction sendToAnalytics({name, value, rating}) {\n  gtag(''event'', name, {\n    event_category: ''Web Vitals'',\n    value: Math.round(name === ''CLS'' ? value * 1000 : value),\n    event_label: rating\n  });\n}\n\nonLCP(sendToAnalytics);\nonINP(sendToAnalytics);\nonCLS(sendToAnalytics);\n```\n\n---\n\n## Framework quick fixes\n\n### Next.js\n```jsx\n// LCP: Use next/image with priority\nimport Image from ''next/image'';\n<Image src=\"/hero.jpg\" priority fill alt=\"Hero\" />\n\n// INP: Use dynamic imports\nconst HeavyComponent = dynamic(() => import(''./Heavy''), { ssr: false });\n\n// CLS: Image component handles dimensions automatically\n```\n\n### React\n```jsx\n// LCP: Preload in head\n<link rel=\"preload\" href=\"/hero.jpg\" as=\"image\" fetchpriority=\"high\" />\n\n// INP: Memoize and useTransition\nconst [isPending, startTransition] = useTransition();\nstartTransition(() => setExpensiveState(newValue));\n\n// CLS: Always specify dimensions in img tags\n```\n\n### Vue/Nuxt\n```vue\n<!-- LCP: Use nuxt/image with preload -->\n<NuxtImg src=\"/hero.jpg\" preload loading=\"eager\" />\n\n<!-- INP: Use async components -->\n<component :is=\"() => import(''./Heavy.vue'')\" />\n\n<!-- CLS: Use aspect-ratio CSS -->\n<img :style=\"{ aspectRatio: ''16/9'' }\" />\n```\n\n## References\n\n- [web.dev LCP](https://web.dev/articles/lcp)\n- [web.dev INP](https://web.dev/articles/inp)\n- [web.dev CLS](https://web.dev/articles/cls)\n- [Performance skill](../performance/SKILL.md)\n"},"lastSynced":"2026-03-08T02:07:13.078Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Optimization Agents needing advanced metrics analysis for LCP, INP, and CLS","zh":"非常适合需要高级指标分析的Web优化代理，用于LCP、INP和CLS","ja":"Web最適化エージェントがLCP、INP、CLSの高度な指標分析を必要とする場合に最適","ko":"LCP, INP, CLS의 고급 메트릭 분석이 필요한 웹 최적화 에이전트에게 적합","es":"Perfecto para agentes de optimización web que necesitan un análisis de métricas avanzado para LCP, INP y CLS","fr":"Parfait pour les agents d''optimisation web ayant besoin d''une analyse de métriques avancée pour LCP, INP et CLS","de":"Perfekt für Web-Optimierungsagenten, die eine erweiterte Metrikanalyse für LCP, INP und CLS benötigen","pt":"Perfeito para Agentes de Otimização da Web que precisam de análise de métricas avançadas para LCP, INP e CLS","ru":"Идеально подходит для агентов по оптимизации веб-страниц, которым требуется продвинутый анализ метрик LCP, INP и CLS","ar":"مثالي لعمليات وكالات تحسين الويب التي تتطلب تحليلات متقدمة لأداء LCP و INP و CLS"},"recommendation":{"en":"Empowers agents to optimize web performance using Core Web Vitals metrics, enhancing user experience and Google Search ranking through targeted optimization of Loading, Interactivity, and Visual Stability","zh":"赋予代理优化网页性能的能力，使用核心网页生命指标来增强用户体验和Google搜索排名，通过有针对性的优化加载、交互性和视觉稳定性","ja":"エージェントがCore Web Vitalsメトリクスを使用してWebパフォーマンスを最適化することを可能にし、ロード、インタラクティビティ、視覚的安定性のターゲット最適化によってユーザーエクスペリエンスとGoogle検索ランキングを向上させる","ko":"에이전트가 Core Web Vitals 메트릭스를 사용하여 웹 성능을 최적화할 수 있도록 하며, 로딩, 상호작용, 시각적 안정성의 표적 최적화를 통해 사용자 경험과 구글 검색 순위를 향상시킴","es":"Habilita a los agentes a optimizar el rendimiento web utilizando las métricas de Core Web Vitals, mejorando la experiencia del usuario y el posicionamiento en Google Search a través de la optimización dirigida de Carga, Interactividad y Estabilidad Visual","fr":"Permet aux agents d''optimiser les performances web en utilisant les métriques de Core Web Vitals, améliorant l''expérience utilisateur et le référencement Google Search grâce à l''optimisation ciblée du Chargement, de l''Interactivité et de la Stabilité Visuelle","de":"Ermöglicht es den Agenten, die Webleistung mithilfe der Core Web Vitals-Metriken zu optimieren, um die Benutzererfahrung und die Google-Suchmaschinen-Positionierung durch gezielte Optimierung von Ladezeit, Interaktivität und visueller Stabilität zu verbessern","pt":"Habilita os agentes a otimizar o desempenho da web usando métricas Core Web Vitals, melhorando a experiência do usuário e o ranqueamento do Google Search por meio da otimização direcionada de Carregamento, Interatividade e Estabilidade Visual","ru":"Позволяет агентам оптимизировать производительность веб-страниц, используя метрики Core Web Vitals, повышая уровень пользовательского опыта и рейтинг поиска Google посредством нацеливания на оптимизацию Загрузки, Интерактивности и Визуальной Стабильности","ar":"تمكّن الوكالات من تحسين أداء الويب باستخدام مقاييس Core Web Vitals، مما يحسن تجربة المستخدم وتصنيف محركات البحث جوجل من خلال تحسين الاستجابة والتفاعل والاستقرار البصري"},"useCases":{"en":["Analyzing LCP metrics to improve page loading times","Optimizing INP for enhanced interactivity and responsiveness","Debugging CLS issues to ensure visual stability and improve user experience"],"zh":["分析LCP指标以改善页面加载时间","优化INP以提高交互性和响应性","调试CLS问题以确保视觉稳定性和改善用户体验"],"ja":["LCPメトリクスを分析してページロード時間を改善する","INPを最適化してインタラクティビティとレスポンスを高める","CLSの問題をデバッグして視覚的安定性を確保し、ユーザーエクスペリエンスを向上させる"],"ko":["LCP 메트릭스를 분석하여 페이지 로딩 시간을 개선함","INP를 최적화하여 상호작용과 반응성을 향상함","CLS 문제를 디버깅하여 시각적 안정성을 확보하고 사용자 경험을 개선함"],"es":["Analizar las métricas de LCP para mejorar los tiempos de carga de la página","Optimizar INP para mejorar la interactividad y la respuesta","Depurar problemas de CLS para garantizar la estabilidad visual y mejorar la experiencia del usuario"],"fr":["Analyser les métriques de LCP pour améliorer les temps de chargement de page","Optimiser INP pour améliorer l''interactivité et la réactivité","Déboguer les problèmes de CLS pour assurer la stabilité visuelle et améliorer l''expérience utilisateur"],"de":["Analysieren von LCP-Metriken, um die Ladezeiten von Seiten zu verbessern","Optimieren von INP für verbesserte Interaktivität und Reaktionsfähigkeit","Beheben von CLS-Problemen, um die visuelle Stabilität sicherzustellen und die Benutzererfahrung zu verbessern"],"pt":["Analisar métricas LCP para melhorar os tempos de carregamento de página","Otimizar INP para melhorar a interatividade e a responsividade","Depurar problemas CLS para garantir a estabilidade visual e melhorar a experiência do usuário"],"ru":["Анализ метрик LCP для улучшения времени загрузки страницы","Оптимизация INP для повышения интерактивности и отзывчивости","Отладка проблем CLS для обеспечения визуальной стабильности и улучшения пользовательского опыта"],"ar":["تحليل مقاييس LCP لتحسين أوقات تحميل الصفحة","تحسين INP لتعزيز التفاعل والاستجابة","تصحيح أخطاء CLS لضمان الاستقرار البصري وتحسين تجربة المستخدم"]},"limitations":{"en":["Requires understanding of Google Search ranking algorithms","Metrics analysis limited to 75th percentile measurement","Optimization targets specific to LCP, INP, and CLS metrics only"],"zh":["需要理解Google搜索排名算法","指标分析仅限于75百分位测量","优化目标仅限于LCP、INP和CLS指标"],"ja":["Google検索ランキングアルゴリズムの理解が必要","メトリクス分析は75パーセンタイル測定に限定される","最適化ターゲットはLCP、INP、CLSメトリクスのみに特定される"],"ko":["구글 검색 순위 알고리즘의 이해가 필요함","메트릭스 분석은 75 백분위 측정으로 제한됨","최적화 대상은 LCP, INP, CLS 메트릭스만으로 특정됨"],"es":["Requiere comprensión de los algoritmos de posicionamiento de Google Search","El análisis de métricas está limitado a la medición del percentil 75","Los objetivos de optimización son específicos de las métricas LCP, INP y CLS solo"],"fr":["Nécessite une compréhension des algorithmes de référencement Google Search","L''analyse des métriques est limitée à la mesure du 75e percentile","Les objectifs d''optimisation sont spécifiques aux métriques LCP, INP et CLS uniquement"],"de":["Erfordert Verständnis der Google-Suchmaschinen-Positionierungs-Algorithmen","Die Metrikanalyse ist auf die Messung des 75. Perzentils beschränkt","Die Optimierungsziele sind spezifisch für die Metriken LCP, INP und CLS"],"pt":["Exige compreensão dos algoritmos de ranqueamento do Google Search","Análise de métricas limitada à medição do percentil 75","Metas de otimização específicas apenas para métricas LCP, INP e CLS"],"ru":["Требует понимания алгоритмов ранжирования поиска Google","Анализ метрик ограничен измерением 75-го процентиля","Цели оптимизации специфичны только для метрик LCP, INP и CLS"],"ar":["يتطلب فهم خوارزميات تصنيف جوجل للبحث","تحليل المقاييس مقيد بقياس النسبة المئوية 75","أهداف التحسين محددة لمقاييس LCP و INP و CLS فقط"]},"version":4},"contentHash":"b03396c9bd7a41950bbaf5964bc8f1cf60a3c81830a6171614d6413c8bff308c","qualityScore":50}');
