INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sayeedjoy/seucampusmate-web/core-web-vitals', 'core-web-vitals', 'sayeedjoy', 'seucampusmate-web', 'community', 'core-web-vitals sayeedjoy seucampusmate-web community The core-web-vitals skill optimizes web performance for Southeast University students, focusing on three key metrics: LCP, INP, and CLS, to enhance user experience and Google Search ranking. Core Web Vitals 优化是为了提高网页性能和用户体验，包括加载时间、交互性和视觉稳定性 Core Web Vitals 最適化は、Web ページのパフォーマンスとユーザーエクスペリエンスを向上させるために、ロード時間、インタラクティビティ、視覚的安定性を最適化する Core Web Vitals 최적화는 웹 페이지 성능과 사용자 경험을 개선하기 위해 로딩 시간, 상호 작용성, 시각적 안정성을 최적화하는 것 Optimiza los tres métricos de Core Web Vitals: LCP, INP y CLS para mejorar la experiencia del usuario y el ranking en Google. Aprende a configurar y optimizar tus sitios web para una mejor experiencia del usuario Optimisez les trois métriques de Core Web Vitals : LCP, INP et CLS pour améliorer l''expérience utilisateur et le référencement Google. Découvrez comment configurer et optimiser vos sites web pour une meilleure expérience utilisateur Optimieren Sie die drei Core Web Vitals-Metriken: LCP, INP und CLS, um die Benutzererfahrung und die Google-Suche zu verbessern. Erfahren Sie, wie Sie Ihre Websites konfigurieren und optimieren, um eine bessere Benutzererfahrung zu bieten Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranking no Google. Aprenda a configurar e otimizar os três principais métricas: LCP, INP e CLS. ИИ Агенты для оптимизации Core Web Vitals. Узнайте, как настроить и оптимизировать три основных метрики: LCP, INP и CLS, чтобы улучшить пользовательский опыт и рейтинг в Google. اداة الذكاء الاصطناعي لتحسين Core Web Vitals. تعرف على كيفية إعداد وتحسين ثلاثة مقاييس أساسية: LCP، INP و CLS لتحسين تجربة المستخدم وترتيب گوگل how to use core-web-vitals what is core-web-vitals core-web-vitals optimization guide core-web-vitals vs web performance optimization core-web-vitals setup tutorial improve LCP and INP metrics optimize CLS for better user experience core-web-vitals install and setup core-web-vitals alternative solutions Core Web Vitals 网页性能优化 用户体验改善 LCP 优化 INP 优化 CLS 优化 Google 搜索排名 AI 工具 Web 优化 Optimizes Largest Contentful Paint (LCP) for faster loading times Improves Interactivity (INP) with targeted optimization for better user engagement Enhances Cumulative Layout Shift (CLS) for improved visual stability Provides 75th percentile measurement for accurate performance assessment Supports Google Search ranking improvement through optimized web performance core-web-vitals is a set of metrics that measure web performance, including Largest Contentful Paint (LCP), Interactivity (INP), and Cumulative Layout Shift (CLS), to improve user experience and search engine ranking.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alexey1312/ExFig/openspec-apply-change', 'community', 'alexey1312', 'ExFig', 'alexey1312/ExFig', 'openspec-apply-change', 0, 0, 50, '2026-03-08T01:57:15.423Z', '2026-03-08T02:07:25.641Z', '89b5aea2c575f407ff96a22f53f2fbfc94a7e7779148d8fe6276feddf83f5b2f', '{"id":"alexey1312/ExFig/openspec-apply-change","name":"openspec-apply-change","description":{"en":"The openspec-apply-change skill implements tasks from OpenSpec changes, allowing developers to optionally specify a change name or infer from conversation context. This skill benefits developers working with OpenSpec changes.","zh":"openspec-apply-change是一个实现OpenSpec变更的AI工具，支持Figma CLI的并行导出、批处理和智能缓存","ja":"openspec-apply-changeは、OpenSpecの変更を実装するAIエージェントで、Figma CLIの並列エクスポート、バッチ処理、スマートキャッシュをサポート","ko":"openspec-apply-change는 오픈스펙 변경을 구현하는 AI 에이전트로, 피그마 CLI의 병렬 내보내기, 일괄 처리, 스마트 캐싱을 지원","es":"openspec-apply-change es una herramienta de línea de comandos que implementa tareas de OpenSpec para iOS, Android y Flutter","fr":"openspec-apply-change est un outil en ligne de commande qui applique des changements OpenSpec pour iOS, Android et Flutter","de":"openspec-apply-change ist ein Kommandozeilen-Tool, das Aufgaben von OpenSpec für iOS, Android und Flutter implementiert","pt":"O openspec-apply-change é uma ferramenta para implementar tarefas do OpenSpec, com recursos como processamento em lote e cache inteligente para Figma CLI.","ru":"openspec-apply-change - это инструмент для реализации задач OpenSpec, с функциями параллельного экспорта и умной кэширования для ИИ Агентов.","ar":"openspec-apply-change هو أداة لتطبيق التعديلات على منصة Figma CLI، مع ميزات مثل المعالجة الدفعية وتخزين الذاكرة التخزين المرن"},"seo":{"title":{"en":"openspec-apply-change: Implement OpenSpec Changes with Ea...","zh":"openspec-apply-change Setup Guide: 优化Figma CLI工作流","ja":"openspec-apply-change のベストプラクティス: AIエージェントを活用したFigma CLI最適化","ko":"openspec-apply-change 설정 가이드: 빠른 Figma CLI 작업을 위한 팁","es":"Guía de configuración de openspec-apply-change para imple...","fr":"Guide d''installation d''openspec-apply-change pour appliqu...","de":"Einrichtungsanleitung für openspec-apply-change zur Ausfü...","pt":"Guia de Configuração do openspec-apply-change para Desenv...","ru":"Настройка openspec-apply-change: Руководство для Разработ...","ar":"دليل إعداد openspec-apply-change لمنصة Figma CLI"},"description":{"en":"Discover how openspec-apply-change streamlines task implementation from OpenSpec changes. Learn how to infer changes, auto-select, and prompt for available c...","zh":"了解openspec-apply-change的功能和特点，优化Figma CLI工作流，提高开发效率","ja":"openspec-apply-changeを使用してFigma CLIのパフォーマンスを向上させ、開発効率を高める方法を紹介","ko":"openspec-apply-change를 사용하여 Figma CLI 작업을 최적화하고 개발 속도를 높이는 방법을 알아보세요","es":"Aprende a implementar tareas de OpenSpec con openspec-apply-change, una herramienta de línea de comandos para iOS, Android y Flutter","fr":"Découvrez comment appliquer des changements avec openspec-apply-change, un outil en ligne de commande pour iOS, Android et Flutter","de":"Erfahren Sie, wie Sie Aufgaben mit openspec-apply-change implementieren, einem Kommandozeilen-Tool für iOS, Android und Flutter","pt":"Aprenda a implementar tarefas do OpenSpec com o openspec-apply-change, incluindo processamento em lote e cache inteligente","ru":"Узнайте, как реализовать задачи OpenSpec с помощью openspec-apply-change, включая параллельный экспорт и умную кэширование для ИИ Агентов","ar":"استكشف كيفية تطبيق التعديلات على منصة Figma CLI باستخدام openspec-apply-change، بما في ذلك المعالجة الدفعية وتخزين الذاكرة التخزين المرن"},"definition":{"en":"openspec-apply-change is a skill that implements tasks from OpenSpec changes, using commands like openspec list --json to get available changes.","zh":"openspec-apply-change是一个AI工具，用于实现OpenSpec变更，支持Figma CLI的高效开发","ja":"openspec-apply-changeは、OpenSpecの変更を実装するAIエージェントで、Figma CLIの高性能開発をサポート","ko":"openspec-apply-change는 오픈스펙 변경을 구현하는 AI 에이전트로, 피그마 CLI의 효율적인 개발을 지원","es":"openspec-apply-change es una herramienta de línea de comandos que implementa tareas de OpenSpec","fr":"openspec-apply-change est un outil en ligne de commande qui applique des changements OpenSpec","de":"openspec-apply-change ist ein Kommandozeilen-Tool, das Aufgaben von OpenSpec implementiert","pt":"O openspec-apply-change é uma ferramenta de linha de comando para aplicar alterações do OpenSpec em projetos Figma CLI.","ru":"openspec-apply-change - это консольная утилита для применения изменений OpenSpec в проектах ИИ Агентов.","ar":"openspec-apply-change هو أداة سطر الأوامر لتطبيق التعديلات على منصة Figma CLI"},"features":{"en":["Implements tasks from OpenSpec changes using optional change name specification","Infers changes from conversation context if no name is provided","Auto-selects the change if only one active change exists","Runs openspec list --json to get available changes when ambiguous","Prompts for available changes when vague or ambiguous"],"zh":["支持Figma CLI的并行导出","批处理和智能缓存功能","支持iOS、Android和Flutter开发","自动检测和选择OpenSpec变更","并行导出和批处理提高开发效率"],"ja":["Figma CLIの並列エクスポートをサポート","バッチ処理とスマートキャッシュ機能","iOS、Android、Flutter開発に対応","OpenSpecの変更を自動で検出・選択","並列エクスポートとバッチ処理で開発効率を向上"],"ko":["피그마 CLI의 병렬 내보내기 지원","일괄 처리와 스마트 캐싱 기능","iOS, Android, Flutter 개발 지원","오픈스펙 변경 자동 감지 및 선택","병렬 내보내기와 일괄 처리로 개발 속도 향상"],"es":["Implementación de tareas de OpenSpec","Soporte para iOS, Android y Flutter","Uso de la línea de comandos para la implementación de tareas","Inferencia del contexto de conversación para la selección de cambios","Compatibilidad con la ejecución de comandos en paralelo"],"fr":["Application de changements OpenSpec","Prise en charge d''iOS, Android et Flutter","Utilisation de la ligne de commande pour l''application de changements","Inférence du contexte de conversation pour la sélection de changements","Compatibilité avec l''exécution de commandes en parallèle"],"de":["Implementierung von OpenSpec-Aufgaben","Unterstützung für iOS, Android und Flutter","Verwendung der Kommandozeile für die Implementierung von Aufgaben","Ableitung des Konversationskontexts für die Auswahl von Änderungen","Kompatibilität mit der Ausführung von Befehlen in parallelen"],"pt":["Processamento em lote para tarefas do OpenSpec","Cache inteligente para otimizar o desempenho","Suporte a Figma CLI para iOS, Android e Flutter","Paralelização de exports para melhorar a eficiência","Seleção automática de alterações ativas","Integração com openspec list --json para obter alterações disponíveis"],"ru":["Параллельный экспорт для задач OpenSpec","Умная кэширование для оптимизации производительности","Поддержка Figma CLI для ИИ Агентов","Пакетная обработка для улучшения эффективности","Автоматическая выборка активных изменений","Интеграция с openspec list --json для получения доступных изменений"],"ar":["المعالجة الدفعية لتطبيق التعديلات على منصة Figma CLI","تخزين الذاكرة التخزين المرن لتحسين الأداء","دعم منصة Figma CLI لمنصات iOS و Android و Flutter","التوازي في التصدير لتحسين الكفاءة","الاختيار التلقائي للتعديلات النشطة","التكامل مع openspec list --json للحصول على التعديلات المتاحة"]},"keywords":{"en":["how to use openspec-apply-change","openspec-apply-change alternative","openspec-apply-change setup guide","what is openspec-apply-change","openspec-apply-change vs ExFig","openspec-apply-change install","openspec list --json command","OpenSpec change implementation"],"zh":["openspec-apply-change","Figma CLI","OpenSpec","AI工具","并行导出","批处理","智能缓存","iOS开发","Android开发","Flutter开发"],"ja":["openspec-apply-change","Figma CLI","OpenSpec","AIエージェント","並列エクスポート","バッチ処理","スマートキャッシュ","iOS開発","Android開発","Flutter開発"],"ko":["openspec-apply-change","피그마 CLI","오픈스펙","AI 에이전트","병렬 내보내기","일괄 처리","스마트 캐싱","iOS 개발","Android 개발","Flutter 개발"],"es":["openspec-apply-change","herramienta de línea de comandos","implementación de tareas","OpenSpec","iOS","Android","Flutter","desarrollo de aplicaciones","herramientas de desarrollo"],"fr":["openspec-apply-change","outil en ligne de commande","application de changements","OpenSpec","iOS","Android","Flutter","développement d''applications","outils de développement"],"de":["openspec-apply-change","Kommandozeilen-Tool","Implementierung von Aufgaben","OpenSpec","iOS","Android","Flutter","App-Entwicklung","Entwicklungstools"],"pt":["openspec-apply-change","Figma CLI","OpenSpec","processamento em lote","cache inteligente","desenvolvimento de software","ferramentas de desenvolvimento","otimização de desempenho","paralelização de exports"],"ru":["openspec-apply-change","ИИ Агенты","OpenSpec","параллельный экспорт","умная кэширование","разработка программного обеспечения","инструменты разработки","оптимизация производительности","пакетная обработка"],"ar":["openspec-apply-change","منصة Figma CLI","OpenSpec","المعالجة الدفعية","تخزين الذاكرة التخزين المرن","تطوير البرمجيات","أدوات التطوير","تحسين الأداء","التوازي في التصدير"]}},"owner":"alexey1312","repo":"ExFig","repoPath":"alexey1312/ExFig","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.423Z","topics":[],"category":"community","skillMd":{"name":"openspec-apply-change","description":"Implement tasks from an OpenSpec change. Use when the user wants to start implementing, continue implementation, or work through tasks.","version":"1.0","bodyPreview":"Implement tasks from an OpenSpec change.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **Select the change**\n\n   If a name is provided, use it. Otherwise:\n   - Infer from conversation context if the user mentioned a change\n   - Auto-select if only one active change exists\n   - If ambiguous, run `openspec list --json` to get available changes and use the *","body":"Implement tasks from an OpenSpec change.\n\n**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.\n\n**Steps**\n\n1. **Select the change**\n\n   If a name is provided, use it. Otherwise:\n   - Infer from conversation context if the user mentioned a change\n   - Auto-select if only one active change exists\n   - If ambiguous, run `openspec list --json` to get available changes and use the **AskUserQuestion tool** to let the user select\n\n   Always announce: \"Using change: <name>\" and how to override (e.g., `/opsx:apply <other>`).\n\n2. **Check status to understand the schema**\n   ```bash\n   openspec status --change \"<name>\" --json\n   ```\n   Parse the JSON to understand:\n   - `schemaName`: The workflow being used (e.g., \"spec-driven\")\n   - Which artifact contains the tasks (typically \"tasks\" for spec-driven, check status for others)\n\n3. **Get apply instructions**\n\n   ```bash\n   openspec instructions apply --change \"<name>\" --json\n   ```\n\n   This returns:\n   - Context file paths (varies by schema - could be proposal/specs/design/tasks or spec/tests/implementation/docs)\n   - Progress (total, complete, remaining)\n   - Task list with status\n   - Dynamic instruction based on current state\n\n   **Handle states:**\n   - If `state: \"blocked\"` (missing artifacts): show message, suggest using openspec-continue-change\n   - If `state: \"all_done\"`: congratulate, suggest archive\n   - Otherwise: proceed to implementation\n\n4. **Read context files**\n\n   Read the files listed in `contextFiles` from the apply instructions output.\n   The files depend on the schema being used:\n   - **spec-driven**: proposal, specs, design, tasks\n   - Other schemas: follow the contextFiles from CLI output\n\n5. **Show current progress**\n\n   Display:\n   - Schema being used\n   - Progress: \"N/M tasks complete\"\n   - Remaining tasks overview\n   - Dynamic instruction from CLI\n\n6. **Implement tasks (loop until done or blocked)**\n\n   For each pending task:\n   - Show which task is being worked on\n   - Make the code changes required\n   - Keep changes minimal and focused\n   - Mark task complete in the tasks file: `- [ ]` → `- [x]`\n   - Continue to next task\n\n   **Pause if:**\n   - Task is unclear → ask for clarification\n   - Implementation reveals a design issue → suggest updating artifacts\n   - Error or blocker encountered → report and wait for guidance\n   - User interrupts\n\n7. **On completion or pause, show status**\n\n   Display:\n   - Tasks completed this session\n   - Overall progress: \"N/M tasks complete\"\n   - If all done: suggest archive\n   - If paused: explain why and wait for guidance\n\n**Output During Implementation**\n\n```\n## Implementing: <change-name> (schema: <schema-name>)\n\nWorking on task 3/7: <task description>\n[...implementation happening...]\n✓ Task complete\n\nWorking on task 4/7: <task description>\n[...implementation happening...]\n✓ Task complete\n```\n\n**Output On Completion**\n\n```\n## Implementation Complete\n\n**Change:** <change-name>\n**Schema:** <schema-name>\n**Progress:** 7/7 tasks complete ✓\n\n### Completed This Session\n- [x] Task 1\n- [x] Task 2\n...\n\nAll tasks complete! Ready to archive this change.\n```\n\n**Output On Pause (Issue Encountered)**\n\n```\n## Implementation Paused\n\n**Change:** <change-name>\n**Schema:** <schema-name>\n**Progress:** 4/7 tasks complete\n\n### Issue Encountered\n<description of the issue>\n\n**Options:**\n1. <option 1>\n2. <option 2>\n3. Other approach\n\nWhat would you like to do?\n```\n\n**Guardrails**\n\n- Keep going through tasks until done or blocked\n- Always read context files before starting (from the apply instructions output)\n- If task is ambiguous, pause and ask before implementing\n- If implementation reveals issues, pause and suggest artifact updates\n- Keep code changes minimal and scoped to each task\n- Update task checkbox immediately after completing each task\n- Pause on errors, blockers, or unclear requirements - don''t guess\n- Use contextFiles from CLI output, don''t assume specific file names\n\n**Fluid Workflow Integration**\n\nThis skill supports the \"actions on a change\" model:\n\n- **Can be invoked anytime**: Before all artifacts are done (if tasks exist), after partial implementation, interleaved with other actions\n- **Allows artifact updates**: If implementation reveals design issues, suggest updating artifacts - not phase-locked, work fluidly\n"},"lastSynced":"2026-03-08T02:07:25.641Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents working with OpenSpec changes, needing automated task implementation from change specifications.","zh":"适用于需要从 OpenSpec 变更规格自动实现任务的开发代理，特别是处理 OpenSpec 变更时。","ja":"OpenSpec の変更から自動タスク実装が必要な開発エージェントに最適です。","ko":"OpenSpec 변경 규격에서 자동화된 태스크 구현이 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo que trabajan con cambios de OpenSpec, necesitando implementación de tareas automatizada a partir de especificaciones de cambios.","fr":"Idéal pour les agents de développement travaillant avec des modifications OpenSpec, nécessitant une mise en œuvre de tâches automatisée à partir de spécifications de modifications.","de":"Ideal für Entwicklungsmittel, die mit OpenSpec-Änderungen arbeiten und eine automatisierte Aufgabenimplementierung aus Änderungsspezifikationen benötigen.","pt":"Ideal para Agentes de Desenvolvimento que trabalham com alterações do OpenSpec, necessitando de implementação automática de tarefas a partir de especificações de alterações.","ru":"Идеально для агентов разработки, работающих с изменениями OpenSpec, требующих автоматизированной реализации задач из спецификаций изменений.","ar":"مثالي لوسائل التطوير العاملة مع التغييرات المفتوحة، بحاجة إلى تنفيذ مهام آلي من مواصفات التغيير."},"recommendation":{"en":"Empowers agents to implement tasks from OpenSpec changes, utilizing conversation context and the `openspec list --json` command to handle ambiguous change names, and supports optional change name specification for precise control.","zh":"赋予代理从 OpenSpec 变更中实现任务的能力，利用对话上下文和 `openspec list --json` 命令来处理模糊的变更名称，并支持可选的变更名称指定以实现精确控制。","ja":"エージェントが OpenSpec の変更からタスクを実装する能力を提供し、会話のコンテキストと `openspec list --json` コマンドを使用して曖昧な変更名を処理し、正確な制御のために変更名の指定をオプションでサポートします。","ko":"에이전트가 OpenSpec 변경에서 태스크를 구현할 수 있는 능력을 제공하며 대화 문맥과 `openspec list --json` 명령을 사용하여 모호한 변경 이름을 처리하며, 정밀한 제어를 위해 변경 이름 지정 옵션을 지원합니다.","es":"Permite a los agentes implementar tareas a partir de cambios de OpenSpec, utilizando el contexto de la conversación y el comando `openspec list --json` para manejar nombres de cambios ambigüos, y admite la especificación opcional del nombre de cambio para un control preciso.","fr":"Permet aux agents de mettre en œuvre des tâches à partir de modifications OpenSpec, en utilisant le contexte de la conversation et la commande `openspec list --json` pour gérer les noms de modifications ambigus, et prend en charge la spécification facultative du nom de modification pour un contrôle précis.","de":"Ermöglicht es den Agenten, Aufgaben aus OpenSpec-Änderungen umzusetzen, indem sie den Konversationskontext und den Befehl `openspec list --json` zur Handhabung mehrdeutiger Änderungsnamen verwenden, und unterstützt die optionale Angabe des Änderungsnamens für eine präzise Kontrolle.","pt":"Habilite os agentes a implementar tarefas a partir de alterações do OpenSpec, utilizando o contexto de conversa e o comando `openspec list --json` para lidar com nomes de alterações ambíguos, e suporta especificação opcional de nome de alteração para controle preciso.","ru":"Наделяет агентов возможностью реализовывать задачи из изменений OpenSpec, используя контекст разговора и команду `openspec list --json` для обработки неоднозначных имен изменений, и поддерживает необязательное указание имени изменения для точного контроля.","ar":"تمكين الوكلاء من تنفيذ المهام من التغييرات المفتوحة، باستخدام سياق المحادثة وأمر `openspec list --json` لمعالجة أسماء التغييرات الغامضة، ودعم تحديد اسم التغيير الإختياري للسيطرة الدقيقة."},"useCases":{"en":["Automating OpenSpec change implementations based on conversation context","Inferring and applying changes when names are omitted or vague","Selecting and implementing tasks from a list of available OpenSpec changes using `openspec list --json`"],"zh":["基于对话上下文自动实现 OpenSpec 变更","当名称省略或模糊时推断和应用变更","使用 `openspec list --json` 命令从可用的 OpenSpec 变更列表中选择和实现任务"],"ja":["会話のコンテキストに基づいて OpenSpec の変更を自動実装する","名前が省略または曖昧な場合に変更を推論して適用する","`openspec list --json` コマンドを使用して利用可能な OpenSpec の変更一覧からタスクを選択して実装する"],"ko":["대화 문맥에 기반하여 OpenSpec 변경을 자동으로 구현하는 것","이름이 생략되거나 모호한 경우에 변경을 추론하여 적용하는 것","`openspec list --json` 명령을 사용하여 사용 가능한 OpenSpec 변경 목록에서 태스크를 선택하여 구현하는 것"],"es":["Automatización de implementaciones de cambios de OpenSpec en función del contexto de la conversación","Inferencia y aplicación de cambios cuando los nombres se omiten o son vagos","Selección e implementación de tareas a partir de una lista de cambios de OpenSpec disponibles utilizando `openspec list --json`"],"fr":["Automatisation de la mise en œuvre de modifications OpenSpec en fonction du contexte de la conversation","Inférence et application de modifications lorsque les noms sont omis ou vagues","Sélection et mise en œuvre de tâches à partir d''une liste de modifications OpenSpec disponibles en utilisant `openspec list --json`"],"de":["Automatisierung von OpenSpec-Änderungsimplementierungen basierend auf dem Konversationskontext","Ableitung und Anwendung von Änderungen, wenn Namen ausgelassen oder mehrdeutig sind","Auswahl und Implementierung von Aufgaben aus einer Liste verfügbarer OpenSpec-Änderungen unter Verwendung von `openspec list --json`"],"pt":["Automatizar implementações de alterações do OpenSpec com base no contexto de conversa","Inferir e aplicar alterações quando os nomes são omitidos ou vagos","Selecionar e implementar tarefas a partir de uma lista de alterações do OpenSpec disponíveis usando `openspec list --json`"],"ru":["Автоматизировать реализацию изменений OpenSpec на основе контекста разговора","Выявлять и применять изменения, когда имена опущены или неоднозначны","Выбирать и реализовывать задачи из списка доступных изменений OpenSpec, используя `openspec list --json`"],"ar":["تحقيق آلي لتنفيذ التغييرات المفتوحة بناءً على سياق المحادثة","استنتاج وتطبيق التغييرات عند حذف أو غموض الأسماء","اختيار وتنفيذ المهام من قائمة التغييرات المفتوحة المتاحة باستخدام `openspec list --json`"]},"limitations":{"en":["Requires OpenSpec changes to be available and configured","May prompt for clarification if change name is ambiguous or vague","Dependent on the availability of a single active change for auto-selection"],"zh":["需要 OpenSpec 变更可用并配置","如果变更名称模糊或不明确，可能会提示要求澄清","依赖于单个活动变更的可用性以进行自动选择"],"ja":["OpenSpec の変更が利用可能で構成されている必要がある","変更名が曖昧または不明確な場合、明確化を求めるプロンプトが表示される可能性がある","自動選択のために単一のアクティブな変更の可用性に依存する"],"ko":["OpenSpec 변경이 사용 가능하고 구성되어야 함","변경 이름이 모호하거나 불명확한 경우 澄清을 요구하는 프롬프트가 표시될 수 있음","자동 선택을 위해 단일 활성 변경의 가용성에 의존함"],"es":["Requiere que los cambios de OpenSpec estén disponibles y configurados","Puede solicitar aclaraciones si el nombre del cambio es ambiguo o vago","Depende de la disponibilidad de un solo cambio activo para la autoselección"],"fr":["Nécessite que les modifications OpenSpec soient disponibles et configurées","Peut demander des éclaircissements si le nom de la modification est ambigü ou vague","Dépend de la disponibilité d''un seul changement actif pour la sélection automatique"],"de":["Benötigt, dass OpenSpec-Änderungen verfügbar und konfiguriert sind","Kann um Klarstellung bitten, wenn der Änderungsname mehrdeutig oder ungenau ist","Hängt von der Verfügbarkeit einer einzelnen aktiven Änderung für die Automatisierung ab"],"pt":["Requer que as alterações do OpenSpec estejam disponíveis e configuradas","Pode solicitar esclarecimento se o nome da alteração for ambíguo ou vago","Depende da disponibilidade de uma única alteração ativa para seleção automática"],"ru":["Требует, чтобы изменения OpenSpec были доступны и настроены","Может запросить уточнение, если имя изменения неоднозначно или двусмысленно","Зависит от наличия единственной активной изменения для автоматического выбора"],"ar":["يتطلب أن تكون التغييرات المفتوحة متاحة ومُضبوطة","يمكن أن يطلب توضيحًا إذا كان اسم التغيير غامضًا أو غير واضح","يعتمد على توافر تغيير واحد نشط للاختيار الآلي"]},"version":4},"contentHash":"89b5aea2c575f407ff96a22f53f2fbfc94a7e7779148d8fe6276feddf83f5b2f","qualityScore":50}');
