INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alexey1312/ExFig/openspec-apply-change', 'openspec-apply-change', 'alexey1312', 'ExFig', 'community', 'openspec-apply-change alexey1312 ExFig community The openspec-apply-change skill implements tasks from OpenSpec changes, allowing developers to optionally specify a change name or infer from conversation context. This skill benefits developers working with OpenSpec changes. openspec-apply-change是一个实现OpenSpec变更的AI工具，支持Figma CLI的并行导出、批处理和智能缓存 openspec-apply-changeは、OpenSpecの変更を実装するAIエージェントで、Figma CLIの並列エクスポート、バッチ処理、スマートキャッシュをサポート openspec-apply-change는 오픈스펙 변경을 구현하는 AI 에이전트로, 피그마 CLI의 병렬 내보내기, 일괄 처리, 스마트 캐싱을 지원 openspec-apply-change es una herramienta de línea de comandos que implementa tareas de OpenSpec para iOS, Android y Flutter openspec-apply-change est un outil en ligne de commande qui applique des changements OpenSpec pour iOS, Android et Flutter openspec-apply-change ist ein Kommandozeilen-Tool, das Aufgaben von OpenSpec für iOS, Android und Flutter implementiert O openspec-apply-change é uma ferramenta para implementar tarefas do OpenSpec, com recursos como processamento em lote e cache inteligente para Figma CLI. openspec-apply-change - это инструмент для реализации задач OpenSpec, с функциями параллельного экспорта и умной кэширования для ИИ Агентов. openspec-apply-change هو أداة لتطبيق التعديلات على منصة Figma CLI، مع ميزات مثل المعالجة الدفعية وتخزين الذاكرة التخزين المرن how to use openspec-apply-change openspec-apply-change alternative openspec-apply-change setup guide what is openspec-apply-change openspec-apply-change vs ExFig openspec-apply-change install openspec list --json command OpenSpec change implementation openspec-apply-change Figma CLI OpenSpec AI工具 并行导出 批处理 智能缓存 iOS开发 Android开发 Flutter开发 Implements tasks from OpenSpec changes using optional change name specification Infers changes from conversation context if no name is provided Auto-selects the change if only one active change exists Runs openspec list --json to get available changes when ambiguous Prompts for available changes when vague or ambiguous openspec-apply-change is a skill that implements tasks from OpenSpec changes, using commands like openspec list --json to get available changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('avivsinai/langfuse-mcp/langfuse', 'community', 'avivsinai', 'langfuse-mcp', 'avivsinai/langfuse-mcp', 'langfuse', 0, 0, 50, '2026-03-08T01:57:15.431Z', '2026-03-08T02:07:32.370Z', '01be3566e99305c2ea1bd4b21e364d4c07e74bf2e9c19c276d7d5e37b0008756', '{"id":"avivsinai/langfuse-mcp/langfuse","name":"langfuse","description":{"en":"The langfuse skill enables AI agents to query Langfuse trace data for enhanced debugging and observability. It benefits developers working with AI systems.","zh":"Langfuse是一种MCP服务器，允许AI代理查询Langfuse跟踪数据以增强调试和可观察性","ja":"LangfuseはMCPサーバーであり、AIエージェントがLangfuseのトレースデータを照会してデバッグと可観測性を強化できるようにする","ko":"Langfuse는 MCP 서버로서 AI 에이전트가 Langfuse 추적 데이터를 쿼리하여 디버깅 및 관찰 가능성을 강화할 수 있습니다","es":"Langfuse es un protocolo de contexto de modelo que permite a los agentes de IA consultar datos de trazas para una mejor depuración y observabilidad","fr":"Langfuse est un protocole de contexte de modèle qui permet aux agents d''IA d''interroger des données de traces pour une meilleure débogage et observabilité","de":"Langfuse ist ein Modellkontextprotokoll, das es KI-Agents ermöglicht, Trace-Daten abzufragen, um die Fehlersuche und Überwachung zu verbessern","pt":"O Langfuse é um protocolo de contexto de modelo que permite aos agentes de IA consultar dados de rastreamento para depuração e observabilidade aprimoradas","ru":"Langfuse — это протокол контекста модели, который позволяет ИИ агентам запрашивать данные трассировки для улучшенной отладки и наблюдаемости","ar":"Langfuse هو بروتوكول سياق النموذج الذي يسمح للأدوات الذكاء الاصطناعي بالاستعلام عن بيانات التتبع لتصحيح وأمكانيات مراقبة محسنة"},"seo":{"title":{"en":"langfuse: Setup Guide for AI Agents | MCP Server","zh":"Langfuse Setup Guide - AIエージェント调试工具","ja":"Langfuse Setup Guide - AIエージェントのデバッグツール","ko":"Langfuse 설정 가이드 - AI 에이전트 디버깅 도구","es":"Guía de configuración de Langfuse para depuración de sist...","fr":"Guide de configuration de Langfuse pour le débogage des s...","de":"Langfuse-Konfigurationsleitfaden für die Fehlersuche in K...","pt":"Guia de Configuração do Langfuse para Ferramentas de IA","ru":"Настройка Langfuse для ИИ Агентов: Руководство","ar":"دليل إعداد Langfuse لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock Langfuse observability for your AI systems. Learn how to set up the MCP server and debug with ease. Get started now!","zh":"使用Langfuse调试AI系统，通过Langfuse可观察性增强异常检测和性能优化","ja":"Langfuseを使用してAIシステムをデバッグし、Langfuseの可観測性で例外検出とパフォーマンスの最適化を強化する","ko":"Langfuse를 사용하여 AI 시스템을 디버깅하고 Langfuse의 관찰 가능성으로 예외 감지 및 성능 최적화를 강화합니다","es":"Aprende a configurar Langfuse para mejorar la depuración y la observabilidad de tus sistemas de IA. Obtén credenciales y configura el servidor MCP","fr":"Découvrez comment configurer Langfuse pour améliorer le débogage et l''observabilité de vos systèmes d''IA. Obtenez des informations d''identification et config...","de":"Erfahren Sie, wie Sie Langfuse konfigurieren, um die Fehlersuche und Überwachung Ihrer KI-Systeme zu verbessern. Erhalten Sie Zugangsdaten und konfigurieren ...","pt":"Aprenda a configurar o Langfuse para melhorar a depuração e observabilidade dos seus sistemas de IA","ru":"Узнайте, как настроить Langfuse для повышения отладки и наблюдаемости ваших ИИ систем","ar":"تعرف على كيفية إعداد Langfuse لتحسين إمكانيات التصحيح ومراقبة أنظمة الذكاء الاصطناعي"},"definition":{"en":"langfuse is a Model Context Protocol (MCP) server enabling AI agents to query Langfuse trace data for debugging and observability","zh":"Langfuse是一种用于AI系统调试的MCP服务器","ja":"LangfuseはAIシステムのデバッグに使用されるMCPサーバーです","ko":"Langfuse는 AI 시스템 디버깅을 위한 MCP 서버입니다","es":"Langfuse es un servidor MCP que permite la depuración y observabilidad de sistemas de IA","fr":"Langfuse est un serveur MCP qui permet le débogage et l''observabilité des systèmes d''IA","de":"Langfuse ist ein MCP-Server, der die Fehlersuche und Überwachung von KI-Systemen ermöglicht","pt":"O que é Langfuse? Um servidor de protocolo de contexto de modelo para depuração e observabilidade de sistemas de IA","ru":"Что такое Langfuse? Сервер протокола контекста модели для отладки и наблюдаемости ИИ систем","ar":"ما هو Langfuse؟ خادم بروتوكول سياق النموذج للتصحيح ومراقبة أنظمة الذكاء الاصطناعي"},"features":{"en":["Installs MCP using claude mcp add command","Supports setup via API Keys from https://cloud.langfuse.com","Enables tracing and debugging of AI systems","Allows self-hosted instances with custom LANGFUSE_HOST","Generates credentials for secure access"],"zh":["支持Langfuse跟踪数据查询","增强AI系统调试和可观察性","支持多种安装方式，包括Claude Code","提供API密钥管理功能","支持自托管和云端部署"],"ja":["Langfuseのトレースデータの照会をサポート","AIシステムのデバッグと可観測性を強化","複数のインストール方法をサポート，Claude Codeを含む","APIキー管理機能を提供","セルフホスティングとクラウドデプロイをサポート"],"ko":["Langfuse 추적 데이터 쿼리를 지원","AI 시스템 디버깅 및 관찰 가능성을 강화","다양한 설치 방법을 지원, Claude Code 포함","API 키 관리 기능을 제공","셀프 호스팅 및 클라우드 배포를 지원"],"es":["Soporte para depuración de sistemas de IA","Consulta de datos de trazas para mejorar la observabilidad","Configuración de servidor MCP para Langfuse","Obtención de credenciales de API en https://cloud.langfuse.com","Integración con Claude Code para la configuración de MCP"],"fr":["Prise en charge du débogage des systèmes d''IA","Interrogation des données de traces pour améliorer l''observabilité","Configuration du serveur MCP pour Langfuse","Obtention des informations d''identification de l''API sur https://cloud.langfuse.com","Intégration avec Claude Code pour la configuration de MCP"],"de":["Unterstützung für die Fehlersuche in KI-Systemen","Abfrage von Trace-Daten zur Verbesserung der Überwachung","Konfiguration des MCP-Servers für Langfuse","Erhalt von API-Zugangsdaten auf https://cloud.langfuse.com","Integration mit Claude Code für die MCP-Konfiguration"],"pt":["Suporte à depuração e observabilidade de sistemas de IA","Consulta de dados de rastreamento via protocolo de contexto de modelo","Integração com MCP (Model Context Protocol) para melhorias de desempenho","Configuração simplificada com credenciais de API e instalação de MCP","Compatibilidade com instâncias auto-hospedadas e na nuvem"],"ru":["Поддержка отладки и наблюдаемости ИИ систем","Запрос данных трассировки через протокол контекста модели","Интеграция с MCP (протокол контекста модели) для улучшения производительности","Упрощенная настройка с помощью ключей API и установки MCP","Совместимость с自охозяйственными и облачными экземплярами"],"ar":["دعم التصحيح ومراقبة أنظمة الذكاء الاصطناعي","الاستعلام عن بيانات التتبع عبر بروتوكول سياق النموذج","التكامل مع MCP (بروتوكول سياق النموذج) لتحسين الأداء","إعداد مبسط باستخدام مفتاح API وتثبيت MCP","توافق مع الحالات المضيفة الذاتية والسحابية"]},"keywords":{"en":["how to use langfuse","langfuse setup guide","langfuse alternative","langfuse vs competitors","langfuse install","what is langfuse","langfuse debugging","MCP server setup","AI system observability"],"zh":["Langfuse","AIエージェント","MCP服务器","AI系统调试","可观察性","跟踪数据","Claude Code","API密钥","自托管","云端部署"],"ja":["Langfuse","AIエージェント","MCPサーバー","AIシステムのデバッグ","可観測性","トレースデータ","Claude Code","APIキー","セルフホスティング","クラウドデプロイ"],"ko":["Langfuse","AI 에이전트","MCP 서버","AI 시스템 디버깅","관찰 가능성","추적 데이터","Claude Code","API 키","셀프 호스팅","클라우드 배포"],"es":["Langfuse","depuración de sistemas de IA","observabilidad de IA","servidor MCP","credenciales de API","Claude Code","configuración de Langfuse","herramientas de IA","Agentes de IA"],"fr":["Langfuse","débogage des systèmes d''IA","observabilité des systèmes d''IA","serveur MCP","informations d''identification de l''API","Claude Code","configuration de Langfuse","outils d''IA","Agents d''IA"],"de":["Langfuse","Fehlersuche in KI-Systemen","Überwachung von KI-Systemen","MCP-Server","API-Zugangsdaten","Claude Code","Konfiguration von Langfuse","KI-Tools","KI-Agents"],"pt":["Langfuse","depuração de IA","observabilidade de sistemas de IA","protocolo de contexto de modelo","MCP","credenciais de API","instalação de MCP","configuração de Langfuse"],"ru":["Langfuse","отладка ИИ","наблюдаемость ИИ систем","протокол контекста модели","MCP","ключи API","установка MCP","настройка Langfuse"],"ar":["Langfuse","تصحيح الذكاء الاصطناعي","مراقبة أنظمة الذكاء الاصطناعي","بروتوكول سياق النموذج","MCP","مفتاح API","تثبيت MCP","إعداد Langfuse"]}},"owner":"avivsinai","repo":"langfuse-mcp","repoPath":"avivsinai/langfuse-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.431Z","topics":[],"category":"community","skillMd":{"name":"langfuse","description":"Debug AI traces, find exceptions, analyze sessions, and manage prompts via Langfuse MCP. Also handles MCP setup and configuration.","version":"1.0.2","bodyPreview":"# Langfuse Skill\n\nDebug your AI systems through Langfuse observability.\n\n**Triggers:** langfuse, traces, debug AI, find exceptions, set up langfuse, what went wrong, why is it slow, datasets, evaluation sets\n\n## Setup\n\n**Step 1:** Get credentials from https://cloud.langfuse.com → Settings → API Keys\n\nIf self-hosted, use your instance URL for `LANGFUSE_HOST` and create keys there.\n\n**Step 2:** Install MCP (pick one):\n\n```bash\n# Claude Code (project-scoped, shared via .mcp.json)\nclaude mcp add \\","body":"# Langfuse Skill\n\nDebug your AI systems through Langfuse observability.\n\n**Triggers:** langfuse, traces, debug AI, find exceptions, set up langfuse, what went wrong, why is it slow, datasets, evaluation sets\n\n## Setup\n\n**Step 1:** Get credentials from https://cloud.langfuse.com → Settings → API Keys\n\nIf self-hosted, use your instance URL for `LANGFUSE_HOST` and create keys there.\n\n**Step 2:** Install MCP (pick one):\n\n```bash\n# Claude Code (project-scoped, shared via .mcp.json)\nclaude mcp add \\\n  --scope project \\\n  --env LANGFUSE_PUBLIC_KEY=pk-... \\\n  --env LANGFUSE_SECRET_KEY=sk-... \\\n  --env LANGFUSE_HOST=https://cloud.langfuse.com \\\n  langfuse -- uvx --python 3.11 langfuse-mcp\n\n# Codex CLI (user-scoped, stored in ~/.codex/config.toml)\ncodex mcp add langfuse \\\n  --env LANGFUSE_PUBLIC_KEY=pk-... \\\n  --env LANGFUSE_SECRET_KEY=sk-... \\\n  --env LANGFUSE_HOST=https://cloud.langfuse.com \\\n  -- uvx --python 3.11 langfuse-mcp\n```\n\n**Step 3:** Restart CLI, verify with `/mcp` (Claude) or `codex mcp list` (Codex)\n\n**Step 4:** Test: `fetch_traces(age=60)`\n\n### Read-Only Mode\n\nFor safer observability without risk of modifying prompts or datasets, enable read-only mode:\n\n```bash\n# CLI flag\nlangfuse-mcp --read-only\n\n# Or environment variable\nLANGFUSE_MCP_READ_ONLY=true\n```\n\nThis disables write tools: `create_text_prompt`, `create_chat_prompt`, `update_prompt_labels`, `create_dataset`, `create_dataset_item`, `delete_dataset_item`.\n\nFor manual `.mcp.json` setup or troubleshooting, see `references/setup.md`.\n\n---\n\n## Playbooks\n\n### \"Where are the errors?\"\n\n```\nfind_exceptions(age=1440, group_by=\"file\")\n```\n→ Shows error counts by file. Pick the worst offender.\n\n```\nfind_exceptions_in_file(filepath=\"src/ai/chat.py\", age=1440)\n```\n→ Lists specific exceptions. Grab a trace_id.\n\n```\nget_exception_details(trace_id=\"...\")\n```\n→ Full stacktrace and context.\n\n---\n\n### \"What happened in this interaction?\"\n\n```\nfetch_traces(age=60, user_id=\"...\")\n```\n→ Find the trace. Note the trace_id.\n\nIf you don''t know the user_id, start with:\n```\nfetch_traces(age=60)\n```\n\n```\nfetch_trace(trace_id=\"...\", include_observations=true)\n```\n→ See all LLM calls in the trace.\n\n```\nfetch_observation(observation_id=\"...\")\n```\n→ Inspect a specific generation''s input/output.\n\n---\n\n### \"Why is it slow?\"\n\n```\nfetch_observations(age=60, type=\"GENERATION\")\n```\n→ Find recent LLM calls. Look for high latency.\n\n```\nfetch_observation(observation_id=\"...\")\n```\n→ Check token counts, model, timing.\n\n---\n\n### \"What''s this user experiencing?\"\n\n```\nget_user_sessions(user_id=\"...\", age=1440)\n```\n→ List their sessions.\n\n```\nget_session_details(session_id=\"...\")\n```\n→ See all traces in the session.\n\n---\n\n### \"Manage datasets\"\n\n```\nlist_datasets()\n```\n→ See all datasets.\n\n```\nget_dataset(name=\"evaluation-set-v1\")\n```\n→ Get dataset details.\n\n```\nlist_dataset_items(dataset_name=\"evaluation-set-v1\", page=1, limit=10)\n```\n→ Browse items in the dataset.\n\n```\ncreate_dataset(name=\"qa-test-cases\", description=\"QA evaluation set\")\n```\n→ Create a new dataset.\n\n```\ncreate_dataset_item(\n  dataset_name=\"qa-test-cases\",\n  input={\"question\": \"What is 2+2?\"},\n  expected_output={\"answer\": \"4\"}\n)\n```\n→ Add test cases.\n\n```\ncreate_dataset_item(\n  dataset_name=\"qa-test-cases\",\n  item_id=\"item_123\",\n  input={\"question\": \"What is 3+3?\"},\n  expected_output={\"answer\": \"6\"}\n)\n```\n→ Upsert: updates existing item by id or creates if missing.\n\n---\n\n### \"Manage prompts\"\n\n```\nlist_prompts()\n```\n→ See all prompts with labels.\n\n```\nget_prompt(name=\"...\", label=\"production\")\n```\n→ Fetch current production version.\n\n```\ncreate_text_prompt(name=\"...\", prompt=\"...\", labels=[\"staging\"])\n```\n→ Create new version in staging.\n\n```\nupdate_prompt_labels(name=\"...\", version=N, labels=[\"production\"])\n```\n→ Promote to production. (Rollback = re-apply label to older version)\n\n---\n\n## Quick Reference\n\n| Task | Tool |\n|------|------|\n| List traces | `fetch_traces(age=N)` |\n| Get trace details | `fetch_trace(trace_id=\"...\", include_observations=true)` |\n| List LLM calls | `fetch_observations(age=N, type=\"GENERATION\")` |\n| Get observation | `fetch_observation(observation_id=\"...\")` |\n| Error count | `get_error_count(age=N)` |\n| Find exceptions | `find_exceptions(age=N, group_by=\"file\")` |\n| List sessions | `fetch_sessions(age=N)` |\n| User sessions | `get_user_sessions(user_id=\"...\", age=N)` |\n| List prompts | `list_prompts()` |\n| Get prompt | `get_prompt(name=\"...\", label=\"production\")` |\n| List datasets | `list_datasets()` |\n| Get dataset | `get_dataset(name=\"...\")` |\n| List dataset items | `list_dataset_items(dataset_name=\"...\", limit=N)` |\n| Create/update dataset item | `create_dataset_item(dataset_name=\"...\", item_id=\"...\")` |\n\n`age` = minutes to look back (max 10080 = 7 days)\n\n---\n\n## References\n\n- `references/tool-reference.md` — Full parameter docs, filter semantics, response schemas\n- `references/setup.md` — Manual setup, troubleshooting, advanced configuration\n"},"lastSynced":"2026-03-08T02:07:32.370Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Debugging Agents needing enhanced observability and tracing capabilities through Langfuse integration.","zh":"适合需要通过Langfuse集成增强可观察性和跟踪功能的AI调试代理。","ja":"Langfuseの統合を通じて観察可能性とトレーシング機能を強化する必要があるAIデバッグエージェントに最適です。","ko":"Langfuse 통합을 통해 관찰 가능성과 추적 기능을 강화해야 하는 AI 디버깅 에이전트에 적합합니다.","es":"Perfecto para agentes de depuración de IA que necesitan funcionalidades de observabilidad y trazabilidad mejoradas a través de la integración de Langfuse.","fr":"Parfait pour les agents de débogage d''IA nécessitant des fonctionnalités d''observabilité et de traçabilité améliorées via l''intégration de Langfuse.","de":"Perfekt für AI-Debugging-Agents, die erweiterte Observierbarkeits- und Nachverfolgungsfunktionen durch Langfuse-Integration benötigen.","pt":"Perfeito para Agentes de Depuração de IA que necessitam de observabilidade e capacidades de rastreio aprimoradas por meio da integração com Langfuse.","ru":"Идеально подходит для агентов отладки ИИ, которым требуются расширенные возможности наблюдаемости и отслеживания через интеграцию с Langfuse.","ar":"مثالي لعمليات تصحيح أخطاء وكيل الإصطناع الاصطناعي التي تحتاج إلى القدرات المعززة للرصد والتتبع من خلال التكامل مع Langfuse."},"recommendation":{"en":"Empowers agents to query Langfuse trace data for advanced debugging, leveraging API keys and instance URLs for seamless integration with langfuse.com or self-hosted setups, facilitating comprehensive analysis of AI system performance and exceptions.","zh":"使代理能够查询Langfuse跟踪数据以进行高级调试，利用API密钥和实例URL实现与langfuse.com或自托管设置的无缝集成，从而实现对AI系统性能和异常的综合分析。","ja":"エージェントがLangfuseのトレースデータを照会して高度なデバッグを行えるようにし、APIキーとインスタンスURLを使用してlangfuse.comまたはセルフホステッド設定とのシームレスな統合を実現し、AIシステムのパフォーマンスと例外の包括的な分析を可能にします。","ko":"에이전트가 Langfuse 추적 데이터를 쿼리하여 고급 디버깅을 수행할 수 있도록 하며, API 키와 인스턴스 URL을 사용하여 langfuse.com 또는 자체 호스팅 설정과 무결점 통합을 제공하여 AI 시스템의 성능과 예외에 대한 포괄적인 분석을 가능하게 합니다.","es":"Habilita a los agentes a consultar datos de trazas de Langfuse para un depuración avanzada, aprovechando claves de API y URL de instancias para una integración fluida con langfuse.com o configuraciones autohospedadas, facilitando un análisis integral del rendimiento y las excepciones del sistema de IA.","fr":"Permet aux agents d''interroger les données de traçage de Langfuse pour un débogage avancé, en exploitant les clés d''API et les URL d''instances pour une intégration transparente avec langfuse.com ou des configurations auto-hébergées, facilitant une analyse complète des performances et des exceptions du système d''IA.","de":"Ermöglicht es Agenten, Langfuse-Trace-Daten für erweitertes Debugging abzufragen, indem API-Schlüssel und Instanz-URLs für eine nahtlose Integration mit langfuse.com oder selbstgehosteten Einrichtungen genutzt werden, wodurch eine umfassende Analyse der Leistung und Ausnahmen des KI-Systems erleichtert wird.","pt":"Habilita os agentes a consultar dados de rastreio do Langfuse para depuração avançada, utilizando chaves de API e URLs de instância para integração sem interrupções com langfuse.com ou configurações de hospedagem própria, facilitando a análise abrangente do desempenho e exceções do sistema de IA.","ru":"Наделяет агентов возможностью запроса данных о трассировке Langfuse для расширенной отладки, используя ключи API и URL-адреса экземпляров для бесшовной интеграции с langfuse.com или自охозяйственных настроек, облегчая комплексный анализ производительности и исключений системы ИИ.","ar":"تمكين الوكلاء من استفسار بيانات التتبع من Langfuse للتصحيح المتقدم ، باستخدام مفاتيح API و URL للمثيلات من أجل التكامل السلس مع langfuse.com أو الإعدادات المضيفة الخاصة ، مما يسهل التحليل الشامل لأداء واستثناءات نظام الإصطناع الاصطناعي."},"useCases":{"en":["Debugging AI model exceptions","Analyzing dataset performance","Setting up Langfuse observability for AI systems"],"zh":["调试AI模型异常","分析数据集性能","为AI系统设置Langfuse可观察性"],"ja":["AIモデルの例外のデバッグ","データセットのパフォーマンスの分析","AIシステムのLangfuseの可観測性の設定"],"ko":["AI 모델 예외 디버깅","데이터셋 성능 분석","AI 시스템의 Langfuse 관찰 가능성 설정"],"es":["Depuración de excepciones de modelos de IA","Análisis del rendimiento de conjuntos de datos","Configuración de la observabilidad de Langfuse para sistemas de IA"],"fr":["Débogage des exceptions de modèles d''IA","Analyse des performances de jeux de données","Configuration de l''observabilité de Langfuse pour les systèmes d''IA"],"de":["Debugging von Ausnahmen von KI-Modellen","Analyse der Leistung von Datensätzen","Einrichtung der Langfuse-Observierbarkeit für KI-Systeme"],"pt":["Depuração de exceções de modelo de IA","Análise de desempenho de conjunto de dados","Configuração da observabilidade do Langfuse para sistemas de IA"],"ru":["Отладка исключений модели ИИ","Анализ производительности набора данных","Настройка наблюдаемости Langfuse для систем ИИ"],"ar":["تصحيح أخطاء استثناءات نموذج الإصطناع الاصطناعي","تحليل أداء مجموعة البيانات","تكوين ملاحظة Langfuse لأنظمة الإصطناع الاصطناعي"]},"limitations":{"en":["Requires Langfuse API key or self-hosted instance credentials","Dependent on Langfuse trace data availability"],"zh":["需要Langfuse API密钥或自托管实例凭证","依赖于Langfuse跟踪数据的可用性"],"ja":["Langfuse APIキーまたはセルフホステッドインスタンスの資格情報が必要","Langfuseのトレースデータの可用性に依存"],"ko":["Langfuse API 키 또는 자체 호스팅 인스턴스 자격 증명이 필요","Langfuse 추적 데이터의 가용성에 종속"],"es":["Requiere clave de API de Langfuse o credenciales de instancia autohospedada","Dependiente de la disponibilidad de datos de trazas de Langfuse"],"fr":["Nécessite une clé d''API Langfuse ou des informations d''identification d''instance auto-hébergée","Dépend de la disponibilité des données de traçage de Langfuse"],"de":["Erfordert Langfuse-API-Schlüssel oder selbstgehostete Instanz-Anmeldeinformationen","Abhängig von der Verfügbarkeit von Langfuse-Trace-Daten"],"pt":["Requer chave de API do Langfuse ou credenciais de instância hospedada","Dependente da disponibilidade de dados de rastreio do Langfuse"],"ru":["Требуется ключ API Langfuse или учетные данные自охозяйственного экземпляра","Зависит от наличия данных о трассировке Langfuse"],"ar":["يتطلب مفتاح API من Langfuse أو أوراق اعتماد المثيل المضيف","يعتمد على توافر بيانات التتبع من Langfuse"]},"version":4},"contentHash":"01be3566e99305c2ea1bd4b21e364d4c07e74bf2e9c19c276d7d5e37b0008756","qualityScore":50}');
