INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('avivsinai/langfuse-mcp/langfuse', 'langfuse', 'avivsinai', 'langfuse-mcp', 'community', 'langfuse avivsinai langfuse-mcp community The langfuse skill enables AI agents to query Langfuse trace data for enhanced debugging and observability. It benefits developers working with AI systems. Langfuse是一种MCP服务器，允许AI代理查询Langfuse跟踪数据以增强调试和可观察性 LangfuseはMCPサーバーであり、AIエージェントがLangfuseのトレースデータを照会してデバッグと可観測性を強化できるようにする Langfuse는 MCP 서버로서 AI 에이전트가 Langfuse 추적 데이터를 쿼리하여 디버깅 및 관찰 가능성을 강화할 수 있습니다 Langfuse es un protocolo de contexto de modelo que permite a los agentes de IA consultar datos de trazas para una mejor depuración y observabilidad Langfuse est un protocole de contexte de modèle qui permet aux agents d''IA d''interroger des données de traces pour une meilleure débogage et observabilité Langfuse ist ein Modellkontextprotokoll, das es KI-Agents ermöglicht, Trace-Daten abzufragen, um die Fehlersuche und Überwachung zu verbessern O Langfuse é um protocolo de contexto de modelo que permite aos agentes de IA consultar dados de rastreamento para depuração e observabilidade aprimoradas Langfuse — это протокол контекста модели, который позволяет ИИ агентам запрашивать данные трассировки для улучшенной отладки и наблюдаемости Langfuse هو بروتوكول سياق النموذج الذي يسمح للأدوات الذكاء الاصطناعي بالاستعلام عن بيانات التتبع لتصحيح وأمكانيات مراقبة محسنة how to use langfuse langfuse setup guide langfuse alternative langfuse vs competitors langfuse install what is langfuse langfuse debugging MCP server setup AI system observability Langfuse AIエージェント MCP服务器 AI系统调试 可观察性 跟踪数据 Claude Code API密钥 自托管 云端部署 Installs MCP using claude mcp add command Supports setup via API Keys from https://cloud.langfuse.com Enables tracing and debugging of AI systems Allows self-hosted instances with custom LANGFUSE_HOST Generates credentials for secure access langfuse is a Model Context Protocol (MCP) server enabling AI agents to query Langfuse trace data for debugging and observability');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('oyjt/uniapp-vue3-template/antfu', 'community', 'oyjt', 'uniapp-vue3-template', 'oyjt/uniapp-vue3-template', 'antfu', 0, 0, 50, '2026-03-08T01:57:15.452Z', '2026-03-08T02:09:00.721Z', 'd759c9396ff2c4ba8eae05fb141c0090f67f15c1592b89bb2bca3055afc3117a', '{"id":"oyjt/uniapp-vue3-template/antfu","name":"antfu","description":{"en":"antfu is a web development skill that utilizes uniapp, vite, vue3, typescript, uview-plus, and unocss for fast team collaboration. It benefits developers seeking efficient project setup and management.","zh":"antfu快速开发模版使用uniapp、vite、vue3、typescript、uview-plus和unocss搭建，适合团队协作","ja":"antfuの推奨ツールと設定を使用したウェブ開発環境構築方法、チームコラボレーションに適した迅速な開発テンプレート","ko":"antfu 빠른 개발 템플릿은 uniapp, vite, vue3, typescript, uview-plus, unocss를 사용하여 구축되어 팀 협업에 적합","es":"antfu es un conjunto de herramientas y configuraciones para desarrolladores que busca agilizar el desarrollo web con tecnologías como uniapp, vite y vue3","fr":"antfu est un ensemble d''outils et de configurations pour les développeurs qui vise à accélérer le développement web avec des technologies comme uniapp, vite et vue3","de":"antfu ist eine Sammlung von Tools und Konfigurationen für Entwickler, die darauf abzielt, die Webentwicklung mit Technologien wie uniapp, vite und vue3 zu beschleunigen","pt":"O antfu é um modelo de desenvolvimento rápido para equipes, utilizando uniapp, Vite, Vue 3, TypeScript e uview-plus","ru":"antfu - это шаблон быстрой разработки для команд, использующий uniapp, Vite, Vue 3, TypeScript и uview-plus","ar":"antfu هو قالب لتطوير سريع للفرق، يستخدم uniapp و Vite و Vue 3 و TypeScript و uview-plus"},"seo":{"title":{"en":"antfu: Setup Guide for AI Agents with Vite and Vue3 | AI ...","zh":"antfu 快速开发模版搭建指南","ja":"antfu AIエージェントを使用したウェブ開発環境構築ガイド","ko":"antfu 빠른 개발 템플릿 설정 가이드","es":"Guía de configuración de antfu para desarrolladores","fr":"Guide de configuration d''antfu pour les développeurs","de":"Einrichtungsleitfaden für antfu-Entwickler","pt":"Guia de Configuração antfu: Melhores Práticas para Desenv...","ru":"ИИ Агент antfu: Руководство по Настройке и Лучшим Практикам","ar":"دليل إعداد antfu: أفضل الممارسات لتنمية الويب"},"description":{"en":"Unlock efficient web development with antfu! Learn how to leverage uniapp, vite, and vue3 for rapid team collaboration - get started now!","zh":"使用uniapp、vite、vue3、typescript、uview-plus和unocss搭建的快速开发模版，了解antfu的最佳实践","ja":"antfuの推奨ツールと設定を使用したウェブ開発環境構築方法、Vite、Vue3、TypeScriptなどの技術を活用","ko":"antfu의 빠른 개발 템플릿을 사용하여 효율적인 웹 개발 환경을 구축하는 방법, uniapp, vite, vue3, typescript 등","es":"Aprende a configurar antfu con tecnologías como uniapp, vite, vue3, typescript y uview-plus para un desarrollo rápido y en equipo","fr":"Découvrez comment configurer antfu avec des technologies comme uniapp, vite, vue3, typescript et uview-plus pour un développement rapide et en équipe","de":"Erfahren Sie, wie Sie antfu mit Technologien wie uniapp, vite, vue3, typescript und uview-plus für eine schnelle und teambasierte Entwicklung konfigurieren","pt":"Aprenda a configurar o antfu com as melhores práticas para desenvolvimento web, incluindo TypeScript, Vite e Vue 3","ru":"Узнайте, как настроить antfu с лучшими практиками для веб-разработки, включая TypeScript, Vite и Vue 3","ar":"تعلم كيفية إعداد antfu مع أفضل الممارسات لتنمية الويب، بما في ذلك TypeScript و Vite و Vue 3"},"definition":{"en":"antfu is a preferred tooling and configuration for web development, utilizing pnpm, TypeScript, ESM, and Vitest for optimized project workflow.","zh":"antfu是Anthony Fu的首选工具和配置，用于快速开发模版搭建","ja":"antfuはAnthony Fuの推奨ツールと設定を使用したウェブ開発環境構築方法","ko":"antfu는 앤서니 푸의 추천 도구 및 설정을 사용하여 빠른 개발 템플릿을 구축","es":"antfu es un conjunto de preferencias y configuraciones de Anthony Fu para el desarrollo web","fr":"antfu est un ensemble de préférences et de configurations d''Anthony Fu pour le développement web","de":"antfu ist eine Sammlung von Vorlieben und Konfigurationen von Anthony Fu für die Webentwicklung","pt":"antfu é um conjunto de ferramentas e práticas recomendadas para desenvolvimento web, criado por Anthony Fu","ru":"antfu - это набор инструментов и рекомендуемых практик для веб-разработки, созданный Энтони Фу","ar":"antfu هو مجموعة من الأدوات والممارسات الموصى بها لتنمية الويب، تم إنشاؤها بواسطة أنتوني فو"},"features":{"en":["Utilizes pnpm as the package manager for efficient dependency management","Employs TypeScript in strict mode for robust code quality","Leverages ESM (\"type\": \"module\") for modern module system handling","Integrates @antfu/eslint-config for opinionated linting and formatting","Supports Vitest for fast and efficient testing","Includes simple-git-hooks and lint-staged for streamlined git workflow"],"zh":["使用pnpm作为包管理器","支持TypeScript（严格模式）","使用ESM（\"type\": \"module\"）作为模块系统","集成@antfu/eslint-config进行linting和格式化","使用Vitest进行测试","支持simple-git-hooks和lint-staged的Git Hooks"],"ja":["pnpmをパッケージマネージャーとして使用","TypeScript（厳格モード）をサポート","ESM（\"type\": \"module\"）をモジュールシステムとして使用","@antfu/eslint-configを使用したlintingとフォーマット","Vitestを使用したテスト","simple-git-hooksとlint-stagedのGit Hooksをサポート"],"ko":["pnpm을 패키지 매니저로 사용","TypeScript(严格 모드)를 지원","ESM(\"type\": \"module\")을 모듈 시스템으로 사용","@antfu/eslint-config를 사용한 린팅 및 포맷팅","Vitest를 사용한 테스트","simple-git-hooks와 lint-staged의 Git Hooks를 지원"],"es":["Soporte para uniapp y vite","Integración con vue3 y typescript","Uso de uview-plus para componentes de interfaz de usuario","Configuración de eslint con @antfu/eslint-config","Soporte para testing con Vitest","Integración con simple-git-hooks y lint-staged para hooks de git"],"fr":["Prise en charge de uniapp et vite","Intégration avec vue3 et typescript","Utilisation de uview-plus pour les composants d''interface utilisateur","Configuration de eslint avec @antfu/eslint-config","Prise en charge du testing avec Vitest","Intégration avec simple-git-hooks et lint-staged pour les hooks de git"],"de":["Unterstützung für uniapp und vite","Integration mit vue3 und typescript","Verwendung von uview-plus für Benutzeroberflächenkomponenten","Konfiguration von eslint mit @antfu/eslint-config","Unterstützung für Testing mit Vitest","Integration mit simple-git-hooks und lint-staged für Git-Hooks"],"pt":["Utilização de pnpm como gerenciador de pacotes","Suporte a TypeScript com modo estrito","Utilização de ESM com tipo de módulo","Integração com @antfu/eslint-config para linting e formatação","Suporte a Vitest para testes","Integração com simple-git-hooks e lint-staged para hooks de git"],"ru":["Использование pnpm в качестве менеджера пакетов","Поддержка TypeScript в строгом режиме","Использование ESM с типом модуля","Интеграция с @antfu/eslint-config для проверки и форматирования кода","Поддержка Vitest для тестирования","Интеграция с simple-git-hooks и lint-staged для хуков git"],"ar":["استخدام pnpm كمدير حزم","دعم TypeScript مع الوضع الصارم","استخدام ESM مع نوع الوحدة","التكامل مع @antfu/eslint-config لتحقق وتنسيق الشفرة","دعم Vitest للاختبارات","التكامل مع simple-git-hooks و lint-staged ل_hooks git"]},"keywords":{"en":["how to use antfu","antfu setup guide","antfu vs vite","what is antfu","antfu install","antfu alternative","uniapp development with antfu","vite and vue3 with antfu","antfu for team collaboration","antfu web development best practices"],"zh":["antfu快速开发模版","uniapp开发","vite开发","vue3开发","typescript开发","uview-plus开发","unocss开发","pnpm包管理","TypeScript严格模式","ESM模块系统"],"ja":["antfu AIエージェント","ウェブ開発環境構築","Vite開発","Vue3開発","TypeScript開発","pnpmパッケージマネージャー","ESMモジュールシステム","Vitestテスト","simple-git-hooks","lint-staged"],"ko":["antfu 빠른 개발 템플릿","웹 개발 환경 구축","vite 개발","vue3 개발","typescrypt 개발","pnpm 패키지 매니저","ESM 모듈 시스템","Vitest 테스트","simple-git-hooks","lint-staged"],"es":["antfu","desarrollo web","uniapp","vite","vue3","typescript","uview-plus","eslint","Vitest","simple-git-hooks","lint-staged"],"fr":["antfu","développement web","uniapp","vite","vue3","typescript","uview-plus","eslint","Vitest","simple-git-hooks","lint-staged"],"de":["antfu","Webentwicklung","uniapp","vite","vue3","typescript","uview-plus","eslint","Vitest","simple-git-hooks","lint-staged"],"pt":["antfu","desenvolvimento web","TypeScript","Vite","Vue 3","uniapp","uview-plus","pnpm","ESM","Vitest","simple-git-hooks","lint-staged"],"ru":["antfu","веб-разработка","TypeScript","Vite","Vue 3","uniapp","uview-plus","pnpm","ESM","Vitest","simple-git-hooks","lint-staged"],"ar":["antfu","تنمية الويب","TypeScript","Vite","Vue 3","uniapp","uview-plus","pnpm","ESM","Vitest","simple-git-hooks","lint-staged"]}},"owner":"oyjt","repo":"uniapp-vue3-template","repoPath":"oyjt/uniapp-vue3-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.452Z","topics":[],"category":"community","skillMd":{"name":"antfu","description":"Anthony Fus {Opinionated} preferences and best practices for web development","version":"2026.1.28","bodyPreview":"# Anthony Fu''s Preferences\n\nThis skill covers Anthony Fu''s preferred tooling, configurations, and best practices for web development. This skill is opinionated.\n\n## Quick Summary\n\n| Category | Preference |\n|----------|------------|\n| Package Manager | pnpm |\n| Language | TypeScript (strict mode) |\n| Module System | ESM (`\"type\": \"module\"`) |\n| Linting & Formatting | @antfu/eslint-config (no Prettier) |\n| Testing | Vitest |\n| Git Hooks | simple-git-hooks + lint-staged |\n| Documentation | VitePres","body":"# Anthony Fu''s Preferences\n\nThis skill covers Anthony Fu''s preferred tooling, configurations, and best practices for web development. This skill is opinionated.\n\n## Quick Summary\n\n| Category | Preference |\n|----------|------------|\n| Package Manager | pnpm |\n| Language | TypeScript (strict mode) |\n| Module System | ESM (`\"type\": \"module\"`) |\n| Linting & Formatting | @antfu/eslint-config (no Prettier) |\n| Testing | Vitest |\n| Git Hooks | simple-git-hooks + lint-staged |\n| Documentation | VitePress (in `docs/`) |\n\n---\n\n## Core Stack\n\n### Package Manager (pnpm)\n\nUse pnpm as the package manager.\n\nFor monorepo setups, use pnpm workspaces:\n\n```yaml\n# pnpm-workspace.yaml\npackages:\n  - ''packages/*''\n```\n\n\nUse pnpm named catalogs in `pnpm-workspace.yaml` to manage dependency versions:\n\n| Catalog | Purpose |\n|---------|---------|\n| `prod` | Production dependencies |\n| `inlined` | Dependencies inlined by bundler |\n| `dev` | Development tools (linter, bundler, testing, dev-server) |\n| `frontend` | Frontend libraries bundled into frontend |\n\nCatalog names are not limited to the above and can be adjusted based on needs. Avoid using default catalog.\n\n#### @antfu/ni\n\nUse `@antfu/ni` for unified package manager commands. It auto-detects the package manager (pnpm/npm/yarn/bun) based on lockfile.\n\n| Command | Description |\n|---------|-------------|\n| `ni` | Install dependencies |\n| `ni <pkg>` | Add dependency |\n| `ni -D <pkg>` | Add dev dependency |\n| `nr <script>` | Run script |\n| `nu` | Upgrade dependencies |\n| `nun <pkg>` | Uninstall dependency |\n| `nci` | Clean install (like `pnpm i --frozen-lockfile`) |\n| `nlx <pkg>` | Execute package (like `npx`) |\n\nInstall globally with `pnpm i -g @antfu/ni` if the commands are not found.\n\n### TypeScript (Strict Mode)\n\nAlways use TypeScript with strict mode enabled.\n\n```json\n{\n  \"compilerOptions\": {\n    \"target\": \"ESNext\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true\n  }\n}\n```\n\n### ESM (ECMAScript Modules)\n\nAlways work in ESM mode. Set `\"type\": \"module\"` in `package.json`.\n\n---\n\n## Code Quality\n\n### ESLint (@antfu/eslint-config)\n\nUse `@antfu/eslint-config` for both formatting and linting. This eliminates the need for Prettier.\n\nCreate `eslint.config.js` with `// @ts-check` comment:\n\n```js\n// @ts-check\nimport antfu from ''@antfu/eslint-config''\n\nexport default antfu()\n```\n\nAdd script to `package.json`:\n\n```json\n{\n  \"scripts\": {\n    \"lint\": \"eslint .\"\n  }\n}\n```\n\nWhen getting linting errors, try to fix them with `nr lint --fix`. Don''t add `lint:fix` script.\n\n### Git Hooks (simple-git-hooks + lint-staged)\n\nUse `simple-git-hooks` with `lint-staged` for pre-commit linting:\n\n```json\n{\n  \"simple-git-hooks\": {\n    \"pre-commit\": \"pnpm i --frozen-lockfile --ignore-scripts --offline && npx lint-staged\"\n  },\n  \"lint-staged\": {\n    \"*\": \"eslint --fix\"\n  },\n  \"scripts\": {\n    \"prepare\": \"npx simple-git-hooks\"\n  }\n}\n```\n\n### Unit Testing (Vitest)\n\nUse Vitest for unit testing.\n\n```json\n{\n  \"scripts\": {\n    \"test\": \"vitest\"\n  }\n}\n```\n\n**Conventions:**\n\n- Place test files next to source files: `foo.ts` → `foo.test.ts` (same directory)\n- High-level tests go in `tests/` directory in each package\n- Use `describe` and `it` API (not `test`)\n- Use `expect` API for assertions\n- Use `assert` only for TypeScript null assertions\n- Use `toMatchSnapshot` for complex output assertions\n- Use `toMatchFileSnapshot` with explicit file path and extension for language-specific output (exclude those files from linting)\n\n---\n\n## Project Setup\n\n### Publishing (Library Projects)\n\nFor library projects, publish through GitHub Releases triggered by `bumpp`:\n\n```json\n{\n  \"scripts\": {\n    \"release\": \"bumpp -r\"\n  }\n}\n```\n\n### Documentation (VitePress)\n\nUse VitePress for documentation. Place docs under `docs/` directory.\n\n```\ndocs/\n├── .vitepress/\n│   └── config.ts\n├── index.md\n└── guide/\n    └── getting-started.md\n```\n\nAdd script to `package.json`:\n\n```json\n{\n  \"scripts\": {\n    \"docs:dev\": \"vitepress dev docs\",\n    \"docs:build\": \"vitepress build docs\"\n  }\n}\n```\n\n---\n\n## References\n\n### Project Setup\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| @antfu/eslint-config | ESLint flat config for formatting and linting | [antfu-eslint-config](references/antfu-eslint-config.md) |\n| GitHub Actions | Preferred workflows using sxzz/workflows | [github-actions](references/github-actions.md) |\n| .gitignore | Preferred .gitignore for JS/TS projects | [gitignore](references/gitignore.md) |\n| VS Code Extensions | Recommended extensions for development | [vscode-extensions](references/vscode-extensions.md) |\n\n### Development\n\n| Topic | Description | Reference |\n|-------|-------------|-----------|\n| App Development | Preferences for Vue/Vite/Nuxt/UnoCSS web applications | [app-development](references/app-development.md) |\n| Library Development | Preferences for bundling and publishing TypeScript libraries | [library-development](references/library-development.md) |\n| Monorepo | pnpm workspaces, centralized alias, Turborepo | [monorepo](references/monorepo.md) |\n"},"lastSynced":"2026-03-08T02:09:00.721Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Development Agents requiring streamlined project setup with uniapp, vite, vue3, typescript, uview-plus, and unocss.","zh":"适合需要使用uniapp、vite、vue3、typescript、uview-plus和unocss进行流线化项目设置的Web开发代理。","ja":"Uniapp、Vite、Vue3、TypeScript、Uview-plus、Unocssを使用してプロジェクト設定をストリームライン化する必要があるWeb開発エージェントに適しています。","ko":"uniapp, vite, vue3, typescript, uview-plus, unocss를 사용하여 프로젝트 설정을 스트림 라인화하는 웹 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo web que requieren una configuración de proyecto simplificada con uniapp, vite, vue3, typescript, uview-plus y unocss.","fr":"Idéal pour les agents de développement web nécessitant une configuration de projet simplifiée avec uniapp, vite, vue3, typescript, uview-plus et unocss.","de":"Ideal für Webentwicklungsagenten, die eine vereinfachte Projektsetup mit uniapp, vite, vue3, typescript, uview-plus und unocss benötigen.","pt":"Ideal para Agentes de Desenvolvimento Web que exigem configuração de projeto simplificada com uniapp, vite, vue3, typescript, uview-plus e unocss.","ru":"Идеально для агентов веб-разработки, требующих упрощенной настройки проекта с помощью uniapp, vite, vue3, typescript, uview-plus и unocss.","ar":"المثالي لوكلاء تطوير الويب الذين يتطلبون إعداد مشروع مبسط مع uniapp، vite، vue3، typescript، uview-plus و unocss."},"recommendation":{"en":"Empowers agents to leverage pnpm for package management, TypeScript in strict mode for robust coding, and Vitest for efficient testing, all while adhering to Anthony Fu''s preferred configurations and best practices, including @antfu/eslint-config for linting and simple-git-hooks for git management.","zh":"赋予代理使用pnpm进行包管理、严格模式下的TypeScript进行强大的编码以及Vitest进行高效测试的能力，同时遵循Anthony Fu的首选配置和最佳实践，包括使用@antfu/eslint-config进行linting和simple-git-hooks进行git管理。","ja":"pnpmを使用したパッケージ管理、厳格モードのTypeScriptを使用したロバストなコーディング、Vitestを使用した効率的なテストを行う能力をエージェントに与え、Anthony Fuの推奨構成とベストプラクティスに従い、@antfu/eslint-configを使用したlintingとsimple-git-hooksを使用したGit管理を行います。","ko":"pnpm을 사용한 패키지 관리, 엄格 모드下的 TypeScript를 사용한 강력한 코딩, Vitest를 사용한 효율적인 테스트를 수행할 수 있는 능력을 에이전트에게 부여하며, Anthony Fu의 선호하는 구성 및 최선의 관행을 따르며, @antfu/eslint-config를 사용한 린팅 및 simple-git-hooks를 사용한 깃 관리를 수행합니다.","es":"Habilita a los agentes a aprovechar pnpm para la gestión de paquetes, TypeScript en modo estricto para codificación robusta y Vitest para pruebas eficientes, todo mientras se adhiere a las configuraciones y mejores prácticas preferidas por Anthony Fu, incluyendo @antfu/eslint-config para la verificación y simple-git-hooks para la gestión de git.","fr":"Permet aux agents d''utiliser pnpm pour la gestion de packages, TypeScript en mode strict pour une codification robuste et Vitest pour des tests efficaces, tout en respectant les configurations et les meilleures pratiques préférées par Anthony Fu, y compris @antfu/eslint-config pour la vérification et simple-git-hooks pour la gestion de git.","de":"Ermächtigt die Agenten, pnpm für das Paketmanagement, TypeScript im Strict-Modus für robuste Kodierung und Vitest für effizientes Testen zu nutzen, und hält sich dabei an die von Anthony Fu bevorzugten Konfigurationen und Best Practices, einschließlich @antfu/eslint-config für die Überprüfung und simple-git-hooks für die Git-Verwaltung.","pt":"Habilita os agentes a aproveitar o pnpm para gerenciamento de pacotes, TypeScript no modo estrito para codificação robusta e Vitest para testes eficientes, tudo isso seguindo as configurações preferidas de Anthony Fu e as melhores práticas, incluindo @antfu/eslint-config para análise de código e simple-git-hooks para gerenciamento de git.","ru":"Наделяет агентов возможностью использовать pnpm для управления пакетами, TypeScript в строгом режиме для прочного кодирования и Vitest для эффективного тестирования, все это при соблюдении предпочитаемых конфигураций Anthony Fu и лучших практик, включая @antfu/eslint-config для проверки кода и simple-git-hooks для управления git.","ar":"تمكّن الوكلاء من استغلال pnpm لإدارة الحزم وTypeScript في الوضع الصارم للترميز القوي وVitest للاختبارات الفعالة، كل ذلك مع اتباع التكوينات المفضلة لأنتوني فو وأفضل الممارسات، بما في ذلك @antfu/eslint-config لتحليل الشفرة وsimple-git-hooks لإدارة جيت."},"useCases":{"en":["Streamlining web project setup with vite and uniapp","Implementing robust testing with Vitest","Enforcing coding standards with @antfu/eslint-config and TypeScript strict mode"],"zh":["使用vite和uniapp进行Web项目设置的流线化","使用Vitest进行强大的测试の実装","使用@antfu/eslint-config和TypeScript严格模式进行编码标准の実施"],"ja":["ViteとUniappを使用したWebプロジェクト設定のストリームライン化","Vitestを使用したロバストなテストの実装","@antfu/eslint-configとTypeScript厳格モードを使用したコーディング規約の実施"],"ko":["vite와 uniapp를 사용한 웹 프로젝트 설정의 스트림 라인화","Vitest를 사용한 강력한 테스트의 구현","@antfu/eslint-config와 TypeScript 엄格 모드를 사용한 코딩 표준의 구현"],"es":["Simplificar la configuración de proyectos web con vite y uniapp","Implementar pruebas robustas con Vitest","Hacer cumplir los estándares de codificación con @antfu/eslint-config y TypeScript en modo estricto"],"fr":["Simplifier la configuration de projets web avec vite et uniapp","Mettre en œuvre des tests robustes avec Vitest","Faire respecter les normes de codage avec @antfu/eslint-config et TypeScript en mode strict"],"de":["Die Konfiguration von Webprojekten mit vite und uniapp zu vereinfachen","Robuste Tests mit Vitest umzusetzen","Die Kodierungsstandards mit @antfu/eslint-config und TypeScript im Strict-Modus durchzusetzen"],"pt":["Simplificar a configuração do projeto web com vite e uniapp","Implementar testes robustos com Vitest","Impor padrões de codificação com @antfu/eslint-config e TypeScript no modo estrito"],"ru":["Упрощение настройки веб-проекта с помощью vite и uniapp","Реализация прочных тестов с помощью Vitest","Внедрение стандартов кодирования с помощью @antfu/eslint-config и TypeScript в строгом режиме"],"ar":["تبسيط إعداد مشروع الويب مع vite و uniapp","تنفيذ اختبارات قوية مع Vitest","تطبيق معايير الترميز مع @antfu/eslint-config وTypeScript في الوضع الصارم"]},"limitations":{"en":["Requires pnpm as the package manager","Specific to Anthony Fu''s preferred tooling and configurations","Opinionated, which may not fit all development teams'' preferences"],"zh":["需要pnpm作为包管理器","特定于Anthony Fu的首选工具和配置","有意见且可能不符合所有开发团队的偏好"],"ja":["pnpmをパッケージマネージャーとして必要とする","Anthony Fuの推奨ツールと構成に特化する","意見を持っているため、すべての開発チームの好みに合わない可能性がある"],"ko":["pnpm을 패키지 관리자로 필요로 함","Anthony Fu의 선호하는 도구 및 구성에 특화됨","의견을 가지고 있으므로 모든 개발 팀의 선호도에 맞지 않을 수 있음"],"es":["Requiere pnpm como gestor de paquetes","Específico para las herramientas y configuraciones preferidas por Anthony Fu","Opinado, lo que puede no adaptarse a las preferencias de todos los equipos de desarrollo"],"fr":["Nécessite pnpm comme gestionnaire de packages","Spécifique aux outils et configurations préférés par Anthony Fu","Opinionné, ce qui peut ne pas convenir aux préférences de tous les équipes de développement"],"de":["Erfordert pnpm als Paketmanager","Spezifisch für die bevorzugten Werkzeuge und Konfigurationen von Anthony Fu","Meinungsbildend, was möglicherweise nicht den Vorlieben aller Entwicklerteams entspricht"],"pt":["Exige pnpm como gerenciador de pacotes","Específico para as ferramentas e configurações preferidas de Anthony Fu","Opinionado, o que pode não atender às preferências de todos os times de desenvolvimento"],"ru":["Требует pnpm в качестве менеджера пакетов","Спецефичен для предпочитаемых инструментов и конфигураций Anthony Fu","Оpinionated, что может не соответствовать предпочтениям всех команд разработки"],"ar":["يتطلب pnpm كمدير لحزم","محدد لأدوات وتكوينات أنتوني فو المفضلة","مبتكر، مما قد لا يلبي تفضيلات جميع فرق التطوير"]},"version":4},"contentHash":"d759c9396ff2c4ba8eae05fb141c0090f67f15c1592b89bb2bca3055afc3117a","qualityScore":50}');
