INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('oyjt/uniapp-vue3-template/antfu', 'antfu', 'oyjt', 'uniapp-vue3-template', 'community', 'antfu oyjt uniapp-vue3-template community antfu is a web development skill that utilizes uniapp, vite, vue3, typescript, uview-plus, and unocss for fast team collaboration. It benefits developers seeking efficient project setup and management. antfu快速开发模版使用uniapp、vite、vue3、typescript、uview-plus和unocss搭建，适合团队协作 antfuの推奨ツールと設定を使用したウェブ開発環境構築方法、チームコラボレーションに適した迅速な開発テンプレート antfu 빠른 개발 템플릿은 uniapp, vite, vue3, typescript, uview-plus, unocss를 사용하여 구축되어 팀 협업에 적합 antfu es un conjunto de herramientas y configuraciones para desarrolladores que busca agilizar el desarrollo web con tecnologías como uniapp, vite y vue3 antfu est un ensemble d''outils et de configurations pour les développeurs qui vise à accélérer le développement web avec des technologies comme uniapp, vite et vue3 antfu ist eine Sammlung von Tools und Konfigurationen für Entwickler, die darauf abzielt, die Webentwicklung mit Technologien wie uniapp, vite und vue3 zu beschleunigen O antfu é um modelo de desenvolvimento rápido para equipes, utilizando uniapp, Vite, Vue 3, TypeScript e uview-plus antfu - это шаблон быстрой разработки для команд, использующий uniapp, Vite, Vue 3, TypeScript и uview-plus antfu هو قالب لتطوير سريع للفرق، يستخدم uniapp و Vite و Vue 3 و TypeScript و uview-plus how to use antfu antfu setup guide antfu vs vite what is antfu antfu install antfu alternative uniapp development with antfu vite and vue3 with antfu antfu for team collaboration antfu web development best practices antfu快速开发模版 uniapp开发 vite开发 vue3开发 typescript开发 uview-plus开发 unocss开发 pnpm包管理 TypeScript严格模式 ESM模块系统 Utilizes pnpm as the package manager for efficient dependency management Employs TypeScript in strict mode for robust code quality Leverages ESM ("type": "module") for modern module system handling Integrates @antfu/eslint-config for opinionated linting and formatting Supports Vitest for fast and efficient testing Includes simple-git-hooks and lint-staged for streamlined git workflow antfu is a preferred tooling and configuration for web development, utilizing pnpm, TypeScript, ESM, and Vitest for optimized project workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('warpdotdev/oz-skills/seo-aeo-audit', 'community', 'warpdotdev', 'oz-skills', 'warpdotdev/oz-skills', 'seo-aeo-audit', 0, 0, 50, '2026-03-08T01:57:15.456Z', '2026-03-08T02:09:05.952Z', '6e157f9dfc2edcaa465df672b9b5468392a769cfd0a5b187eb137fa365c56e44', '{"id":"warpdotdev/oz-skills/seo-aeo-audit","name":"seo-aeo-audit","description":{"en":"The seo-aeo-audit skill provides technical SEO optimization based on Lighthouse SEO audits and Google Search guidelines, benefiting developers and SEO specialists. It focuses on crawlability, on-page optimization, and structured data.","zh":"seo-aeo-audit工具提供了基于Lighthouse SEO审计和Google搜索指南的技术SEO优化，包括爬行性、页面优化和结构化数据","ja":"seo-aeo-auditツールは、Lighthouse SEO監査とGoogle検索ガイドラインに基づいた技術SEO最適化を提供し、クロール性、ページ最適化、構造化データなどを含みます","ko":"seo-aeo-audit 도구는 Lighthouse SEO 감사 및 Google 검색 지침을 기반으로 하는 기술 SEO 최적화를 제공하며, 크롤링, 페이지 최적화, 구조화된 데이터 등을 포함합니다","es":"El skill seo-aeo-audit ofrece una guía técnica para la optimización de motores de búsqueda basada en auditorías de Lighthouse SEO y directrices de Google Search","fr":"Le skill seo-aeo-audit propose un guide technique pour l''optimisation des moteurs de recherche basée sur les audits de Lighthouse SEO et les directives de Google Search","de":"Der Skill seo-aeo-audit bietet einen technischen Leitfaden für die Suchmaschinenoptimierung basierend auf Lighthouse-SEO-Audits und Google-Suchrichtlinien","pt":"O SEO-AEO-Audit é uma ferramenta de otimização técnica que ajuda a melhorar a visibilidade do seu site com base em auditorias do Lighthouse e diretrizes do Google Search","ru":"ИИ Агент SEO-AEO-Audit - это инструмент технической оптимизации, который помогает улучшить видимость вашего сайта на основе аудитов Lighthouse и руководств Google Search","ar":"SEO-AEO-Audit هي أداة لتحسين فني تساعد على تحسين وضوح موقعك على الويب بناءً على عمليات التدقيق لبرنامج Lighthouse وإرشادات البحث من جوجل"},"seo":{"title":{"en":"seo-aeo-audit: Lighthouse SEO Audit Setup Guide | AI Agen...","zh":"SEO优化工具：seo-aeo-audit_SETUP指南","ja":"AIエージェントを使用したSEO最適化：seo-aeo-audit_BESTプラクティス","ko":"SEO 최적화 도구: seo-aeo-audit 설정 가이드","es":"Guía de configuración de seo-aeo-audit para optimización ...","fr":"Guide de configuration de seo-aeo-audit pour l''optimisati...","de":"Einrichtungsleitfaden für seo-aeo-audit zur Suchmaschinen...","pt":"SEO-AEO-Audit: Guia de Configuração para Otimização Técnica","ru":"ИИ Агент SEO-AEO-Audit: Настройка для Технической Оптимиз...","ar":"SEO-AEO-Audit: دليل إعداد للتحسين الفني"},"description":{"en":"Unlock technical SEO optimization with seo-aeo-audit. Learn how to configure robots.txt, meta robots, and structured data for better search engine rankings. ...","zh":"学习如何使用seo-aeo-audit工具优化您的网站SEO，提高搜索引擎排名和用户体验","ja":"AIエージェントを使用してSEOを最適化する方法を学び、検索エンジンのランキングとユーザーエクスペリエンスを向上させます","ko":"seo-aeo-audit 도구를 사용하여 웹 사이트의 SEO를 최적화하고 검색 엔진 순위 및 사용자 경험을 향상시키는 방법을 배우세요","es":"Aprende a configurar seo-aeo-audit para mejorar la visibilidad en los resultados de búsqueda con nuestra guía técnica","fr":"Découvrez comment configurer seo-aeo-audit pour améliorer la visibilité dans les résultats de recherche avec notre guide technique","de":"Erfahren Sie, wie Sie seo-aeo-audit konfigurieren, um die Sichtbarkeit in den Suchergebnissen zu verbessern, mit unserem technischen Leitfaden","pt":"Aprenda a configurar o SEO-AEO-Audit para melhorar a visibilidade do seu site com técnicas de otimização técnica e on-page","ru":"Узнайте, как настроить ИИ Агент SEO-AEO-Audit для улучшения видимости вашего сайта с помощью технической оптимизации и настроек на странице","ar":"تعلم كيفية تهيئة SEO-AEO-Audit لتحسين وضوح موقعك على الويب باستخدام تقنيات التحسين الفني وعلى الصفحة"},"definition":{"en":"seo-aeo-audit is a technical SEO optimization skill that uses Lighthouse SEO audits and Google Search guidelines to improve website crawlability, on-page optimization, and structured data.","zh":"seo-aeo-audit是一种用于优化网站SEO的工具，通过技术SEO、页面优化和结构化数据来提高搜索引擎排名","ja":"seo-aeo-auditは、検索エンジンのランキングを向上させるために技術SEO、ページ最適化、構造化データを使用するウェブサイトのSEOを最適化するツールです","ko":"seo-aeo-audit는 검색 엔진 순위를 향상시키기 위해 기술 SEO, 페이지 최적화, 구조화된 데이터를 사용하여 웹 사이트의 SEO를 최적화하는 도구입니다","es":"seo-aeo-audit es una herramienta de optimización de motores de búsqueda que utiliza auditorías de Lighthouse SEO y directrices de Google Search","fr":"seo-aeo-audit est un outil d''optimisation des moteurs de recherche qui utilise des audits de Lighthouse SEO et des directives de Google Search","de":"seo-aeo-audit ist ein Tool für die Suchmaschinenoptimierung, das Lighthouse-SEO-Audits und Google-Suchrichtlinien verwendet","pt":"O que é SEO-AEO-Audit? É uma ferramenta de otimização técnica para melhorar a visibilidade do site","ru":"Что такое ИИ Агент SEO-AEO-Audit? Это инструмент технической оптимизации для улучшения видимости сайта","ar":"ما هو SEO-AEO-Audit؟ إنه أداة لتحسين فني لتحسين وضوح موقعك على الويب"},"features":{"en":["Configures robots.txt for controlled crawling","Optimizes meta robots for improved search engine indexing","Utilizes structured data for enhanced search engine results","Supports sitemap.xml generation for efficient site mapping","Blocks admin and private areas from search engine crawling","Allows rendering of necessary resources with selective disallow rules"],"zh":["基于Lighthouse SEO审计的技术SEO优化","页面优化，包括Meta标签和结构化数据","爬行性优化，包括robots.txt和sitemap.xml","Google搜索指南的遵守","提高搜索引擎排名和用户体验"],"ja":["Lighthouse SEO監査に基づいた技術SEO最適化","ページ最適化，Metaタグと構造化データを含む","クロール性の最適化，robots.txtとsitemap.xmlを含む","Google検索ガイドラインの遵守","検索エンジンのランキングとユーザーエクスペリエンスの向上"],"ko":["Lighthouse SEO 감사 기반의 기술 SEO 최적화","페이지 최적화, 메타 태그 및 구조화된 데이터 포함","크롤링 최적화, robots.txt 및 sitemap.xml 포함","Google 검색 지침 준수","검색 엔진 순위 및 사용자 경험 향상"],"es":["Análisis de crawlabilidad con robots.txt","Optimización de meta robots","Implementación de estructuras de datos","Seguimiento de las directrices de Google Search","Análisis de rendimiento con Lighthouse SEO"],"fr":["Analyse de la crawlabilité avec robots.txt","Optimisation des meta robots","Mise en œuvre de structures de données","Suivi des directives de Google Search","Analyse des performances avec Lighthouse SEO"],"de":["Analyse der Crawlbility mit robots.txt","Optimierung von Meta-Robots","Implementierung von Datenstrukturen","Verfolgung der Google-Suchrichtlinien","Leistungsanalyse mit Lighthouse SEO"],"pt":["Análise de crawlability com robots.txt","Otimização de meta robots","Implementação de sitemap.xml","Otimização técnica com base em auditorias do Lighthouse","Ajustes de estrutura de dados para melhorar a visibilidade"],"ru":["Анализ crawlability с помощью robots.txt","Оптимизация meta robots","Реализация sitemap.xml","Техническая оптимизация на основе аудитов Lighthouse","Настройка структуры данных для улучшения видимости"],"ar":["تحليل crawlability باستخدام robots.txt","تحسين meta robots","تنفيذ sitemap.xml","تحسين فني بناءً على عمليات التدقيق لبرنامج Lighthouse","ضبط هيكل البيانات لتحسين وضوح الموقع"]},"keywords":{"en":["how to use seo-aeo-audit","seo-aeo-audit setup guide","seo-aeo-audit vs lighthouse","seo-aeo-audit install","what is seo-aeo-audit","seo-aeo-audit alternative","technical seo optimization","lighthouse seo audit","google search guidelines","structured data optimization"],"zh":["SEO优化工具","技术SEO","页面优化","结构化数据","Lighthouse SEO审计","Google搜索指南","搜索引擎排名","用户体验"],"ja":["AIエージェント","SEO最適化","技術SEO","ページ最適化","構造化データ","Lighthouse SEO監査","Google検索ガイドライン","検索エンジンのランキング","ユーザーエクスペリエンス"],"ko":["SEO 최적화 도구","기술 SEO","페이지 최적화","구조화된 데이터","Lighthouse SEO 감사","Google 검색 지침","검색 엔진 순위","사용자 경험","AI 에이전트"],"es":["seo-aeo-audit","optimización de motores de búsqueda","auditorías de Lighthouse SEO","directrices de Google Search","robots.txt","meta robots","estructuras de datos","herramientas de desarrollo web"],"fr":["seo-aeo-audit","optimisation des moteurs de recherche","audits de Lighthouse SEO","directives de Google Search","robots.txt","meta robots","structures de données","outils de développement web"],"de":["seo-aeo-audit","Suchmaschinenoptimierung","Lighthouse-SEO-Audits","Google-Suchrichtlinien","robots.txt","Meta-Robots","Datenstrukturen","Webentwicklungstools"],"pt":["SEO-AEO-Audit","otimização técnica","Lighthouse","Google Search","robots.txt","meta robots","sitemap.xml","estrutura de dados"],"ru":["ИИ Агент SEO-AEO-Audit","техническая оптимизация","Lighthouse","Google Search","robots.txt","meta robots","sitemap.xml","структура данных"],"ar":["SEO-AEO-Audit","تحسين فني","Lighthouse","بحث جوجل","robots.txt","meta robots","sitemap.xml","هيكل البيانات"]}},"owner":"warpdotdev","repo":"oz-skills","repoPath":"warpdotdev/oz-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.456Z","topics":[],"category":"community","skillMd":{"name":"seo-aeo-audit","description":"Optimize for search engine visibility, ranking, and AI citations. Use when asked to improve SEO, optimize for search, fix meta tags, add structured data, or improve AEO and AI visibility.","version":"2.0","bodyPreview":"# SEO Optimization\n\nSearch engine optimization based on Lighthouse SEO audits and Google Search guidelines. Focus on technical SEO, on-page optimization, and structured data.\n\n## Technical SEO\n\n### Crawlability\n\n**robots.txt:**\n```text\n# /robots.txt\nUser-agent: *\nAllow: /\n\n# Block admin/private areas\nDisallow: /admin/\nDisallow: /api/\nDisallow: /private/\n\n# Don''t block resources needed for rendering\n# ❌ Disallow: /static/\n\nSitemap: https://example.com/sitemap.xml\n```\n\n**Meta robots:**\n```html\n<!-","body":"# SEO Optimization\n\nSearch engine optimization based on Lighthouse SEO audits and Google Search guidelines. Focus on technical SEO, on-page optimization, and structured data.\n\n## Technical SEO\n\n### Crawlability\n\n**robots.txt:**\n```text\n# /robots.txt\nUser-agent: *\nAllow: /\n\n# Block admin/private areas\nDisallow: /admin/\nDisallow: /api/\nDisallow: /private/\n\n# Don''t block resources needed for rendering\n# ❌ Disallow: /static/\n\nSitemap: https://example.com/sitemap.xml\n```\n\n**Meta robots:**\n```html\n<!-- Default: indexable, followable -->\n<meta name=\"robots\" content=\"index, follow\">\n\n<!-- Noindex specific pages -->\n<meta name=\"robots\" content=\"noindex, nofollow\">\n\n<!-- Indexable but don''t follow links -->\n<meta name=\"robots\" content=\"index, nofollow\">\n\n<!-- Control snippets -->\n<meta name=\"robots\" content=\"max-snippet:150, max-image-preview:large\">\n```\n\n**Canonical URLs:**\n```html\n<!-- Prevent duplicate content issues -->\n<link rel=\"canonical\" href=\"https://example.com/page\">\n\n<!-- Self-referencing canonical (recommended) -->\n<link rel=\"canonical\" href=\"https://example.com/current-page\">\n\n<!-- For paginated content -->\n<link rel=\"canonical\" href=\"https://example.com/products\">\n<!-- Or use rel=\"prev\" / rel=\"next\" for explicit pagination -->\n```\n\n### XML sitemap\n\n```xml\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url>\n    <loc>https://example.com/</loc>\n    <lastmod>2024-01-15</lastmod>\n    <changefreq>daily</changefreq>\n    <priority>1.0</priority>\n  </url>\n  <url>\n    <loc>https://example.com/products</loc>\n    <lastmod>2024-01-14</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.8</priority>\n  </url>\n</urlset>\n```\n\n**Sitemap best practices:**\n- Maximum 50,000 URLs or 50MB per sitemap\n- Use sitemap index for larger sites\n- Include only canonical, indexable URLs\n- Update `lastmod` when content changes\n- Submit to Google Search Console\n\n### URL structure\n\n```\n✅ Good URLs:\nhttps://example.com/products/blue-widget\nhttps://example.com/blog/how-to-use-widgets\n\n❌ Poor URLs:\nhttps://example.com/p?id=12345\nhttps://example.com/products/item/category/subcategory/blue-widget-2024-sale-discount\n```\n\n**URL guidelines:**\n- Use hyphens, not underscores\n- Lowercase only\n- Keep short (< 75 characters)\n- Include target keywords naturally\n- Avoid parameters when possible\n- Use HTTPS always\n\n### HTTPS & security\n\n```html\n<!-- Ensure all resources use HTTPS -->\n<img src=\"https://example.com/image.jpg\">\n\n<!-- Not: -->\n<img src=\"http://example.com/image.jpg\">\n```\n\n**Security headers for SEO trust signals:**\n```\nStrict-Transport-Security: max-age=31536000; includeSubDomains\nX-Content-Type-Options: nosniff\nX-Frame-Options: DENY\n```\n\n---\n\n## On-page SEO\n\n### Title tags\n\n```html\n<!-- ❌ Missing or generic -->\n<title>Page</title>\n<title>Home</title>\n\n<!-- ✅ Descriptive with primary keyword -->\n<title>Blue Widgets for Sale | Premium Quality | Example Store</title>\n```\n\n**Title tag guidelines:**\n- 50-60 characters (Google truncates ~60)\n- Primary keyword near the beginning\n- Unique for every page\n- Brand name at end (unless homepage)\n- Action-oriented when appropriate\n\n### Meta descriptions\n\n```html\n<!-- ❌ Missing or duplicate -->\n<meta name=\"description\" content=\"\">\n\n<!-- ✅ Compelling and unique -->\n<meta name=\"description\" content=\"Shop premium blue widgets with free shipping. 30-day returns. Rated 4.9/5 by 10,000+ customers. Order today and save 20%.\">\n```\n\n**Meta description guidelines:**\n- 150-160 characters\n- Include primary keyword naturally\n- Compelling call-to-action\n- Unique for every page\n- Matches page content\n\n### Heading structure\n\n```html\n<!-- ❌ Poor structure -->\n<h2>Welcome to Our Store</h2>\n<h4>Products</h4>\n<h1>Contact Us</h1>\n\n<!-- ✅ Proper hierarchy -->\n<h1>Blue Widgets - Premium Quality</h1>\n  <h2>Product Features</h2>\n    <h3>Durability</h3>\n    <h3>Design</h3>\n  <h2>Customer Reviews</h2>\n  <h2>Pricing</h2>\n```\n\n**Heading guidelines:**\n- Single `<h1>` per page (the main topic)\n- Logical hierarchy (don''t skip levels)\n- Include keywords naturally\n- Descriptive, not generic\n\n### Image SEO\n\n```html\n<!-- ❌ Poor image SEO -->\n<img src=\"IMG_12345.jpg\">\n\n<!-- ✅ Optimized image -->\n<img src=\"blue-widget-product-photo.webp\"\n     alt=\"Blue widget with chrome finish, side view showing control panel\"\n     width=\"800\"\n     height=\"600\"\n     loading=\"lazy\">\n```\n\n**Image guidelines:**\n- Descriptive filenames with keywords\n- Alt text describes the image content\n- Compressed and properly sized\n- WebP/AVIF with fallbacks\n- Lazy load below-fold images\n\n### Internal linking\n\n```html\n<!-- ❌ Non-descriptive -->\n<a href=\"/products\">Click here</a>\n<a href=\"/widgets\">Read more</a>\n\n<!-- ✅ Descriptive anchor text -->\n<a href=\"/products/blue-widgets\">Browse our blue widget collection</a>\n<a href=\"/guides/widget-maintenance\">Learn how to maintain your widgets</a>\n```\n\n**Linking guidelines:**\n- Descriptive anchor text with keywords\n- Link to relevant internal pages\n- Reasonable number of links per page\n- Fix broken links promptly\n- Use breadcrumbs for hierarchy\n\n---\n\n## Structured data (JSON-LD)\n\n### Organization\n\n```html\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Organization\",\n  \"name\": \"Example Company\",\n  \"url\": \"https://example.com\",\n  \"logo\": \"https://example.com/logo.png\",\n  \"sameAs\": [\n    \"https://twitter.com/example\",\n    \"https://linkedin.com/company/example\"\n  ],\n  \"contactPoint\": {\n    \"@type\": \"ContactPoint\",\n    \"telephone\": \"+1-555-123-4567\",\n    \"contactType\": \"customer service\"\n  }\n}\n</script>\n```\n\n### Article\n\n```html\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Article\",\n  \"headline\": \"How to Choose the Right Widget\",\n  \"description\": \"Complete guide to selecting widgets for your needs.\",\n  \"image\": \"https://example.com/article-image.jpg\",\n  \"author\": {\n    \"@type\": \"Person\",\n    \"name\": \"Jane Smith\",\n    \"url\": \"https://example.com/authors/jane-smith\"\n  },\n  \"publisher\": {\n    \"@type\": \"Organization\",\n    \"name\": \"Example Blog\",\n    \"logo\": {\n      \"@type\": \"ImageObject\",\n      \"url\": \"https://example.com/logo.png\"\n    }\n  },\n  \"datePublished\": \"2024-01-15\",\n  \"dateModified\": \"2024-01-20\"\n}\n</script>\n```\n\n### Product\n\n```html\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Product\",\n  \"name\": \"Blue Widget Pro\",\n  \"image\": \"https://example.com/blue-widget.jpg\",\n  \"description\": \"Premium blue widget with advanced features.\",\n  \"brand\": {\n    \"@type\": \"Brand\",\n    \"name\": \"WidgetCo\"\n  },\n  \"offers\": {\n    \"@type\": \"Offer\",\n    \"price\": \"49.99\",\n    \"priceCurrency\": \"USD\",\n    \"availability\": \"https://schema.org/InStock\",\n    \"url\": \"https://example.com/products/blue-widget\"\n  },\n  \"aggregateRating\": {\n    \"@type\": \"AggregateRating\",\n    \"ratingValue\": \"4.8\",\n    \"reviewCount\": \"1250\"\n  }\n}\n</script>\n```\n\n### FAQ\n\n```html\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What colors are available?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Our widgets come in blue, red, and green.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What is the warranty?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"All widgets include a 2-year warranty.\"\n      }\n    }\n  ]\n}\n</script>\n```\n\n### Breadcrumbs\n\n```html\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"BreadcrumbList\",\n  \"itemListElement\": [\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 1,\n      \"name\": \"Home\",\n      \"item\": \"https://example.com\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 2,\n      \"name\": \"Products\",\n      \"item\": \"https://example.com/products\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 3,\n      \"name\": \"Blue Widgets\",\n      \"item\": \"https://example.com/products/blue-widgets\"\n    }\n  ]\n}\n</script>\n```\n\n### Validation\n\nTest structured data at:\n- [Google Rich Results Test](https://search.google.com/test/rich-results)\n- [Schema.org Validator](https://validator.schema.org/)\n\n---\n\n## Mobile SEO\n\n### Responsive design\n\n```html\n<!-- ❌ Not mobile-friendly -->\n<meta name=\"viewport\" content=\"width=1024\">\n\n<!-- ✅ Responsive viewport -->\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n```\n\n### Tap targets\n\n```css\n/* ❌ Too small for mobile */\n.small-link {\n  padding: 4px;\n  font-size: 12px;\n}\n\n/* ✅ Adequate tap target */\n.mobile-friendly-link {\n  padding: 12px;\n  font-size: 16px;\n  min-height: 48px;\n  min-width: 48px;\n}\n```\n\n### Font sizes\n\n```css\n/* ❌ Too small on mobile */\nbody {\n  font-size: 10px;\n}\n\n/* ✅ Readable without zooming */\nbody {\n  font-size: 16px;\n  line-height: 1.5;\n}\n```\n\n---\n\n## International SEO\n\n### Hreflang tags\n\n```html\n<!-- For multi-language sites -->\n<link rel=\"alternate\" hreflang=\"en\" href=\"https://example.com/page\">\n<link rel=\"alternate\" hreflang=\"es\" href=\"https://example.com/es/page\">\n<link rel=\"alternate\" hreflang=\"fr\" href=\"https://example.com/fr/page\">\n<link rel=\"alternate\" hreflang=\"x-default\" href=\"https://example.com/page\">\n```\n\n### Language declaration\n\n```html\n<html lang=\"en\">\n<!-- or -->\n<html lang=\"es-MX\">\n```\n\n---\n\n## SEO audit checklist\n\n### Critical\n- [ ] HTTPS enabled\n- [ ] robots.txt allows crawling\n- [ ] No `noindex` on important pages\n- [ ] Title tags present and unique\n- [ ] Single `<h1>` per page\n\n### High priority\n- [ ] Meta descriptions present\n- [ ] Sitemap submitted\n- [ ] Canonical URLs set\n- [ ] Mobile-responsive\n- [ ] Core Web Vitals passing\n\n### Medium priority\n- [ ] Structured data implemented\n- [ ] Internal linking strategy\n- [ ] Image alt text\n- [ ] Descriptive URLs\n- [ ] Breadcrumb navigation\n\n### Ongoing\n- [ ] Fix crawl errors in Search Console\n- [ ] Update sitemap when content changes\n- [ ] Monitor ranking changes\n- [ ] Check for broken links\n- [ ] Review Search Console insights\n\n---\n\n## Audit workflow\n\n1. Baseline: run Lighthouse and PageSpeed on key templates (home, category, detail, blog).\n2. Crawl: verify indexability, canonicals, and duplicate content (use Search Console + crawler).\n3. Fix blockers: `noindex`, `robots.txt`, canonical mismatches, redirect chains.\n4. On-page: titles, meta descriptions, headings, internal linking, image alt.\n5. Structured data: add JSON-LD and validate rich results.\n6. Re-verify: re-run Lighthouse/PageSpeed and check Search Console coverage.\n\n---\n\n## Common pitfalls\n\n- `noindex` or `X-Robots-Tag` accidentally set on important pages\n- `robots.txt` blocks CSS/JS or critical render resources\n- Canonical points to a different URL than the one indexed\n- Mixed `http`/`https` or `www`/non-`www` causing duplicate content\n- Redirect chains/loops (waste crawl budget and slow page load)\n- Parameterized URLs indexable (filters, sort, UTM) without canonical control\n- JavaScript-rendered content not visible in initial HTML\n- Soft 404s (200 status with \"not found\" content)\n- Sitemap includes non-canonical or `noindex` URLs\n- Hreflang tags missing reciprocal links or using wrong language/region codes\n\n---\n\n## Tools\n\n| Tool | Use |\n|------|-----|\n| Google Search Console | Monitor indexing, fix issues |\n| Google PageSpeed Insights | Performance + Core Web Vitals |\n| Rich Results Test | Validate structured data |\n| Lighthouse | Full SEO audit |\n| Screaming Frog | Crawl analysis |\n\n---\n\n## Scripts (optional)\n\nScripts under `scripts/` for repeatable audits:\n\n- `scripts/lighthouse.sh`: run Lighthouse CLI against a URL or URL list and store JSON reports.\n- `scripts/pagespeed.sh`: call PageSpeed Insights API with `curl` and capture JSON output.\n- `scripts/search-console-export.mjs`: export Search Console Search Analytics data (requires OAuth access token).\n\nExample usage:\n```bash\n# Lighthouse (SEO category only)\nscripts/lighthouse.sh https://example.com\nscripts/lighthouse.sh urls.txt reports/lighthouse\n\n# PageSpeed Insights API (requires PAGESPEED_API_KEY)\nPAGESPEED_API_KEY=... scripts/pagespeed.sh https://example.com\nPAGESPEED_API_KEY=... scripts/pagespeed.sh urls.txt reports/pagespeed\n\n# Search Console API (requires GSC_ACCESS_TOKEN)\nGSC_ACCESS_TOKEN=... scripts/search-console-export.mjs https://example.com 2024-01-01 2024-01-31\n```\n\n---\n\n## AEO / AI Visibility Optimization\n\nAnswer Engine Optimization (AEO) focuses on making content discoverable and citable by AI agents (ChatGPT, Perplexity, Gemini, Google AI Overviews). While SEO targets rankings and clicks, AEO targets citations, mentions, and brand authority within AI-generated responses.\n\n### Key differences from SEO\n\n```\nSEO: Rank high → get clicks → drive traffic\nAEO: Be cited → own the answer → build authority\n\nSEO metric: Position, CTR, impressions\nAEO metric: Citations, mentions, AI visibility score\n\nSEO query: \"best project management software\"\nAEO query: \"What''s the best project management software for a remote team of 15 with budget under $500/month?\"\n```\n\n**Market shift:**\n- Gartner predicts 25% drop in traditional search volume by 2026 due to AI chatbots\n- 400M+ people use OpenAI products weekly\n- 58% of searches are now \"zero-click\" (answered directly in AI interface)\n\n### Content structure for AEO\n\n**Answer-first formatting:**\n\n```markdown\n<!-- ❌ SEO-style (context first) -->\n## What is AEO?\nIn recent years, the rise of AI-powered search has transformed \nhow users discover information. This shift has created new \nopportunities for brands. Answer Engine Optimization is...\n\n<!-- ✅ AEO-style (answer first) -->\n## What is AEO?\nAnswer Engine Optimization (AEO) is the practice of structuring \ncontent so AI systems can directly extract and cite answers. \nIt focuses on citations in AI responses rather than search rankings.\n\nUnlike traditional SEO, AEO optimizes for conversational queries \nand zero-click results where users get answers without visiting \nyour site.\n```\n\n**Guidelines:**\n- Lead with 40-60 word direct answer\n- Self-contained responses (AI extracts without surrounding context)\n- Conversational, natural language\n- Specific data > vague claims\n- Include quantified claims, dates, authoritative citations\n\n**Entity-based optimization:**\n\n```markdown\n<!-- ❌ Keyword-focused -->\n\"Our software helps teams collaborate better with features \nfor project management and communication.\"\n\n<!-- ✅ Entity-focused -->\n\"Acme PM is a project management platform for remote teams. \nFounded in 2020, serves 50,000+ companies. Key features: \nKanban boards, time tracking, Slack integration. Pricing: \n$12/user/month.\"\n```\n\nDefine who you are, what you do, and why AI should trust you.\n\n### Schema for AEO\n\nExpand beyond SEO schema to optimize for AI extraction.\n\n**Critical schema types for AEO:**\n\n1. **FAQPage** (highest AI citation rate)\n   - Template: `references/json-ld-templates.md`\n\n**FAQ answer guidelines for AEO:**\n- 40-60 words ideal (under 30 = lacks substance, over 80 = hard to extract)\n- Match visible H2/H3 headings to schema \"name\" property exactly\n- Include specific numbers, dates, and data\n- Self-contained (makes sense without context)\n- Natural question phrasing (how users actually ask)\n\n2. **Author + Organization** (trust signals)\n   - Template: `references/json-ld-templates.md`\n\n**Why it matters:** AI engines prioritize content from identifiable, authoritative sources. Use `sameAs` links to disambiguate your brand.\n\n3. **Product** (for e-commerce AEO)\n   - Template: `references/json-ld-templates.md`\n\nAllows AI shopping modules to show accurate pricing, availability, reviews.\n\n### Platform-specific optimization\n\nDifferent AI engines have different preferences. Balance all three for maximum citation probability.\n\n**ChatGPT:**\n- Neutral, encyclopedia-style tone\n- Authoritative external citations\n- Specific data and quantified claims\n- Formal structure\n\n```markdown\nExample: \"According to a 2025 Gartner study, 78% of enterprises \nadopted AI-powered search tools. The primary drivers were cost \nreduction (cited by 62% of respondents) and improved accuracy \n(58%). Source: Gartner AI Search Report 2025.\"\n```\n\n**Perplexity:**\n- Conversational, experience-driven\n- Practical examples and case studies\n- Community insights and real-world context\n- Less formal tone\n\n```markdown\nExample: \"Most teams start with the free tier and upgrade after \n2-3 months once they''ve proven ROI. Based on feedback from 500+ \ncustomers, common triggers for upgrading include hitting user \nlimits or needing advanced reporting.\"\n```\n\n**Google AI Overviews:**\n- E-E-A-T signals (Experience, Expertise, Authoritativeness, Trust)\n- Fresh content with recent dates\n- Featured snippet-friendly formatting\n- Mobile-optimized structure\n\n```markdown\nExample: \"Updated February 2026: Current pricing starts at \n$12/user/month (annual billing). Month-to-month adds 20%. \nEducation and nonprofit discounts available. No free tier \nas of Q1 2026.\"\n```\n\n### AEO measurement & tools\n\n**Metrics:**\n- Citation frequency (how often AI mentions your brand)\n- Visibility score (presence across AI platforms)\n- Context quality (positive/neutral/negative sentiment)\n- Source attribution (which URLs AI cites)\n\n**Tracking AI referral traffic:**\n\nIn Google Analytics 4, filter traffic sources:\n- `chat.openai.com` (ChatGPT)\n- `perplexity.ai`\n- `gemini.google.com`\n- `copilot.microsoft.com`\n\nMonitor these as separate acquisition sources.\n\nUse your preferred AEO monitoring tool to track citation frequency, context, and source attribution.\n\n### AEO audit checklist\n\n#### Content audit\n- [ ] All key pages have 40-60 word direct answers upfront\n- [ ] FAQ sections with self-contained answers\n- [ ] Conversational language matching natural queries\n- [ ] Specific data (numbers, dates, sources) not vague claims\n- [ ] Author bios and organization info visible\n- [ ] Content updated with recent dates (freshness)\n\n#### Schema audit\n- [ ] FAQPage schema on FAQ/guide pages\n- [ ] Author schema on all articles/blogs\n- [ ] Organization schema site-wide\n- [ ] Product schema on product pages (if e-commerce)\n- [ ] Article schema with datePublished/dateModified\n- [ ] Schema matches visible content exactly (no hidden markup)\n- [ ] Validate with Google Rich Results Test\n\n#### Technical audit\n- [ ] JSON-LD format (preferred by AI engines)\n- [ ] Schema.org standards compliance\n- [ ] No conflicting or duplicate schema\n- [ ] Fast page load (AI crawlers prefer fast sites)\n- [ ] Clean HTML structure (semantic headings)\n- [ ] Mobile-optimized (especially for Google AI Overviews)\n\n#### Entity & authority signals\n- [ ] Clear brand identity (who you are, what you do)\n- [ ] Consistent NAP (name, address, phone) across web\n- [ ] `sameAs` links to LinkedIn, Twitter, official profiles\n- [ ] External citations and backlinks from authoritative sources\n- [ ] Active presence on review platforms\n- [ ] Google Business Profile optimized (local businesses)\n\n#### AI visibility monitoring\n- [ ] Test top 10-20 commercial queries monthly\n- [ ] Track AI referral traffic in GA4\n- [ ] Monitor brand mentions across AI platforms\n- [ ] Check citation context (positive/neutral/negative)\n- [ ] Verify factual accuracy of AI responses about your brand\n- [ ] Set up alerts for visibility changes (if using paid tools)\n\n\n---\n\n## References\n\n- [Google Search Central](https://developers.google.com/search)\n- [Schema.org](https://schema.org/)\n- [Core Web Vitals](../core-web-vitals/SKILL.md)\n- [Web Quality Audit](../web-quality-audit/SKILL.md)\n"},"lastSynced":"2026-03-08T02:09:05.952Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing advanced technical SEO optimization and Lighthouse audit analysis.","zh":"非常适合需要高级技术SEO优化和Lighthouse审计分析的Web开发代理。","ja":"Web開発エージェントが高度な技術SEO最適化とLighthouse監査分析を必要とする場合に最適です。","ko":"고급 기술 SEO 최적화 및 Lighthouse 감사 분석이 필요한 웹 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo web que necesitan una optimización técnica avanzada de SEO y análisis de auditoría de Lighthouse.","fr":"Parfait pour les agents de développement web ayant besoin d''une optimisation technique avancée du SEO et d''une analyse d''audit de Lighthouse.","de":"Perfekt für Webentwicklungsagenten, die eine erweiterte technische SEO-Optimierung und eine Lighthouse-Audit-Analyse benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que precisam de otimização técnica de SEO avançada e análise de auditoria do Lighthouse.","ru":"Идеально подходит для агентов по разработке веб-сайтов, которым необходима продвинутая техническая оптимизация SEO и анализ аудита Lighthouse.","ar":"مثالي لعميل التطوير الويب الذي يحتاج إلى تحسين تقني متقدم لتحسين محركات البحث والتحليل الشامل للضوء المنور."},"recommendation":{"en":"Empowers agents to analyze and optimize website crawlability, on-page optimization, and structured data using Lighthouse SEO audits and Google Search guidelines, including protocols like robots.txt and meta robots tags.","zh":"赋予代理分析和优化网站爬行能力、页面优化和结构化数据，使用Lighthouse SEO审计和Google搜索指南，包括robots.txt和meta机器人标签等协议。","ja":"Lighthouse SEO監査とGoogle検索ガイドラインを使用して、ウェブサイトのクロール性、ページ内最適化、構造化データを分析および最適化し、robots.txtやmetaロボットタグなどのプロトコルを含むエージェントをEmpowerします。","ko":"Lighthouse SEO 감사 및 Google 검색 가이드ライン을 사용하여 웹 사이트의 크롤링 가능성, 페이지 내 최적화, 구조화된 데이터를 분석 및 최적화하며, robots.txt 및 메타 로봇 태그와 같은 프로토콜을 포함하여 에이전트를 강화합니다.","es":"Habilita a los agentes a analizar y optimizar la accesibilidad del sitio web, la optimización en la página y los datos estructurados utilizando auditorías de SEO de Lighthouse y directrices de Google Search, incluidos protocolos como robots.txt y etiquetas de robots.","fr":"Permet aux agents d''analyser et d''optimiser la crawlabilité du site web, l''optimisation sur page et les données structurées en utilisant des audits SEO Lighthouse et des directives de recherche Google, y compris des protocoles tels que robots.txt et balises de robots.","de":"Ermächtigt Agenten, die Crawlabarkeit von Webseiten, die Onpage-Optimierung und strukturierte Daten mithilfe von Lighthouse-SEO-Audits und Google-Suchrichtlinien zu analysieren und zu optimieren, einschließlich Protokollen wie robots.txt und Meta-Robots-Tags.","pt":"Permite que os agentes analisem e otimizem a capacidade deindexação do site, a otimização na página e os dados estruturados usando auditorias de SEO do Lighthouse e diretrizes do Google Search, incluindo protocolos como robots.txt e meta robots tags.","ru":"Позволяет агентам анализировать и оптимизировать индексацию сайта, оптимизацию на странице и структурированные данные с помощью аудитов SEO Lighthouse и руководств по поиску Google, включая протоколы, такие как robots.txt и теги meta robots.","ar":"تمكّن العميل من تحليل و تحسين قابليّة فهرسة الموقع و تحسين العناصر على الصفحة و البيانات المُنسّقة باستخدام تحليلات SEO لضوء المنور و إرشادات بحث جوجل، بما في ذلك بروتوكولات مثل robots.txt و علامات meta robots."},"useCases":{"en":["Analyzing website crawlability issues","Optimizing on-page elements for search engines","Validating structured data for rich search results"],"zh":["分析网站爬行问题","优化页面元素以适应搜索引擎","验证结构化数据以获得丰富的搜索结果"],"ja":["ウェブサイトのクロール問題を分析する","検索エンジン用にページ要素を最適化する","豊富な検索結果を得るための構造化データを検証する"],"ko":["웹 사이트의 크롤링 문제 분석","검색 엔진을 위한 페이지 요소 최적화","豊富한 검색 결과를 얻기 위한 구조화된 데이터 검증"],"es":["Analizar problemas de crawlabilidad del sitio web","Optimizar elementos en la página para motores de búsqueda","Validar datos estructurados para resultados de búsqueda enriquecidos"],"fr":["Analyser les problèmes de crawlabilité du site web","Optimiser les éléments sur page pour les moteurs de recherche","Valider les données structurées pour des résultats de recherche enrichis"],"de":["Analyse von Crawlabarkeitsproblemen von Webseiten","Optimieren von Onpage-Elementen für Suchmaschinen","Validieren von strukturierten Daten für umfassende Suchergebnisse"],"pt":["Analisar problemas de indexação do site","Otimizar elementos na página para motores de busca","Validar dados estruturados para resultados de pesquisa ricos"],"ru":["Анализ проблем индексации сайта","Оптимизация элементов на странице для поисковых систем","Проверка структурированных данных для богатых результатов поиска"],"ar":["تحليل مشاكل فهرسة الموقع","تحسين العناصر على الصفحة لمحركات البحث","التحقق من البيانات المنسّقة لنتائج بحث غنية"]},"limitations":{"en":["Requires access to website source code","Limited to Lighthouse SEO audits and Google Search guidelines"],"zh":["需要访问网站源代码","仅限Lighthouse SEO审计和Google搜索指南"],"ja":["ウェブサイトのソースコードにアクセスする必要がある","Lighthouse SEO監査とGoogle検索ガイドラインのみ"],"ko":["웹 사이트의 소스 코드에 액세스해야 함","Lighthouse SEO 감사 및 Google 검색 가이드라인만 해당"],"es":["Requiere acceso al código fuente del sitio web","Limitado a auditorías de SEO de Lighthouse y directrices de Google Search"],"fr":["Nécessite un accès au code source du site web","Limité aux audits SEO Lighthouse et aux directives de recherche Google"],"de":["Erfordert Zugriff auf den Quellcode der Webseite","Begrenzt auf Lighthouse-SEO-Audits und Google-Suchrichtlinien"],"pt":["Requer acesso ao código-fonte do site","Limitado a auditorias de SEO do Lighthouse e diretrizes do Google Search"],"ru":["Требует доступа к исходному коду сайта","Ограничен аудитами SEO Lighthouse и руководствами по поиску Google"],"ar":["يتطلب الوصول إلى شفرة المصدر للموقع","محدود بتحليلات SEO لضوء المنور وإرشادات بحث جوجل"]},"version":4},"contentHash":"6e157f9dfc2edcaa465df672b9b5468392a769cfd0a5b187eb137fa365c56e44","qualityScore":50}');
