INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('warpdotdev/oz-skills/seo-aeo-audit', 'seo-aeo-audit', 'warpdotdev', 'oz-skills', 'community', 'seo-aeo-audit warpdotdev oz-skills community The seo-aeo-audit skill provides technical SEO optimization based on Lighthouse SEO audits and Google Search guidelines, benefiting developers and SEO specialists. It focuses on crawlability, on-page optimization, and structured data. seo-aeo-audit工具提供了基于Lighthouse SEO审计和Google搜索指南的技术SEO优化，包括爬行性、页面优化和结构化数据 seo-aeo-auditツールは、Lighthouse SEO監査とGoogle検索ガイドラインに基づいた技術SEO最適化を提供し、クロール性、ページ最適化、構造化データなどを含みます seo-aeo-audit 도구는 Lighthouse SEO 감사 및 Google 검색 지침을 기반으로 하는 기술 SEO 최적화를 제공하며, 크롤링, 페이지 최적화, 구조화된 데이터 등을 포함합니다 El skill seo-aeo-audit ofrece una guía técnica para la optimización de motores de búsqueda basada en auditorías de Lighthouse SEO y directrices de Google Search Le skill seo-aeo-audit propose un guide technique pour l''optimisation des moteurs de recherche basée sur les audits de Lighthouse SEO et les directives de Google Search Der Skill seo-aeo-audit bietet einen technischen Leitfaden für die Suchmaschinenoptimierung basierend auf Lighthouse-SEO-Audits und Google-Suchrichtlinien O SEO-AEO-Audit é uma ferramenta de otimização técnica que ajuda a melhorar a visibilidade do seu site com base em auditorias do Lighthouse e diretrizes do Google Search ИИ Агент SEO-AEO-Audit - это инструмент технической оптимизации, который помогает улучшить видимость вашего сайта на основе аудитов Lighthouse и руководств Google Search SEO-AEO-Audit هي أداة لتحسين فني تساعد على تحسين وضوح موقعك على الويب بناءً على عمليات التدقيق لبرنامج Lighthouse وإرشادات البحث من جوجل how to use seo-aeo-audit seo-aeo-audit setup guide seo-aeo-audit vs lighthouse seo-aeo-audit install what is seo-aeo-audit seo-aeo-audit alternative technical seo optimization lighthouse seo audit google search guidelines structured data optimization SEO优化工具 技术SEO 页面优化 结构化数据 Lighthouse SEO审计 Google搜索指南 搜索引擎排名 用户体验 Configures robots.txt for controlled crawling Optimizes meta robots for improved search engine indexing Utilizes structured data for enhanced search engine results Supports sitemap.xml generation for efficient site mapping Blocks admin and private areas from search engine crawling Allows rendering of necessary resources with selective disallow rules seo-aeo-audit is a technical SEO optimization skill that uses Lighthouse SEO audits and Google Search guidelines to improve website crawlability, on-page optimization, and structured data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gAmUssA/vscode-open-in-marked2/openspec-new-change', 'community', 'gAmUssA', 'vscode-open-in-marked2', 'gAmUssA/vscode-open-in-marked2', 'openspec-new-change', 0, 0, 50, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:26.145Z', '2325ae1019930c6383abd2f1312a8aa41600ac8893d036f3da74530b43df9352', '{"id":"gAmUssA/vscode-open-in-marked2/openspec-new-change","name":"openspec-new-change","description":{"en":"The openspec-new-change skill is a VS Code extension that opens Markdown and AsciiDoc files in Marked 2, benefiting developers who work with these file formats. It uses an experimental artifact-driven approach to start new changes.","zh":"openspec-new-change是一款VS Code扩展，用于打开和编辑Markdown和AsciiDoc文件，支持实验性的artifact-driven方法","ja":"openspec-new-changeは、MarkdownとAsciiDocファイルを開き編集するためのVS Code拡張機能で、実験的なartifact-drivenアプローチをサポートしています","ko":"openspec-new-change는 Markdown와 AsciiDoc 파일을 열고 편집하기 위한 VS Code 확장으로, 실험적인 artifact-driven 방법을 지원합니다","es":"El complemento openspec-new-change para VS Code permite abrir archivos Markdown y AsciiDoc en Marked 2. Utiliza la aproximación experimental basada en artefactos.","fr":"L''extension openspec-new-change pour VS Code permet d''ouvrir des fichiers Markdown et AsciiDoc dans Marked 2. Elle utilise l''approche expérimentale basée sur les artefacts.","de":"Die Erweiterung openspec-new-change für VS Code ermöglicht das Öffnen von Markdown- und AsciiDoc-Dateien in Marked 2. Sie verwendet den experimentellen Ansatz basierend auf Artefakten.","pt":"O openspec-new-change é uma extensão do VS Code que permite abrir arquivos Markdown e AsciiDoc no Marked 2. Ele utiliza uma abordagem experimental baseada em artefatos para iniciar uma nova alteração.","ru":"openspec-new-change - это расширение VS Code, которое позволяет открывать файлы Markdown и AsciiDoc в Marked 2. Оно использует эксперимен